-- =========================================================================
-- EllesmereUI 한글화 가이드라인 (Korean Localization Guidelines)
-- =========================================================================
-- 본 파일은 한글화를 하고자 하는 유저 모두가 함께 유지보수합니다. 
-- (+AI 어시스턴스가 해당 부분을 참고해서 작업할 수 있게 지시해주세요.)
-- 번역 작업 시 일관성과 높은 완성도를 위해 아래 원칙과 표준 용어를 참고해서 작업 부탁드립니다. 
-- 추가할 내용이 있다면 언제든지 추가해주셔도 좋습니다.
--
-- 1. 기본 원칙
--   - 직역보다 실제 와우(WoW) 인터페이스 및 인게임 기능 문맥에 부합하는 자연스러운 의역을 권장합니다.
--   - 파일 인코딩은 반드시 'BOM 없는 UTF-8(UTF-8 without BOM)'을 유지해야 합니다.
--   - 좌측 원문 키(L["..."])는 절대 변경하지 않고, 우측 값("...")만 번역합니다.
--   - 문자열 내 치환자(%s, %d, %1$s 등)와 색상 코드(|cff..., |r)는 원형을 그대로 유지합니다.
--   - [중요] 중국어(zhCN/zhTW) 등 타 언어 로케일 참고 및 한자 혼용 절대 금지:
--     타국어 번역을 무단 참고하여 기계적으로 가져오는 행위를 전면 금지합니다 (한자어/중국식 표현 유입 원천 차단).
--     한국어 번역은 오직 영문 원문(enUS)과 블리자드 공식 한국어 클라이언트 기준만으로 작성해야 합니다.
--
-- 2. 블리자드 공식 명칭 표준 준수
--   - Buff / Debuff: 공식 명칭인 '강화 효과'와 '약화 효과'로 사용합니다.
--   - Secondary / Tertiary Stats : 공식 명칭인 '보조 능력치'(치명/가속/특화/유연) 및 '3차 능력치'로 사용합니다.
--   - Threat: 공식 명칭인 '위협' 또는 '위협 수준' 사용합니다.
--   - Threshold: 자원 바/체력 바 등의 특정 수치에 대한 분기점은 '임계값'으로 사용합니다.
--   - Instance / Instances : 원문에 단독 표기되었거나 인스턴스 구역을 의미할 때는 '인스턴스 던전'으로 사용합니다.
--
-- 3. 유저 직관성을 위한 예외적 의역
--   - 파티 찾기 / 파티 찾기 창 (Premade Groups / Group Finder) : 블리자드 공식 UI 탭 명칭은 '파티 구성하기'이나,
--     실제 유저 실사용 용어 및 직관성을 위해 관련 모듈 전체를 '파티 찾기', 창은 '파티 찾기 창'으로 일괄 통일합니다.
--   - 어그로 (Aggro) : 블리자드 공식 용어는 '위협 수준'이나, 원문이 'Aggro'인 항목(Aggro Lost 등)은
--     원문 Threat(위협)과 명확히 구분하고 인게임 직관성을 위해 '어그로'로 유지합니다.
--   - 크로스헤어 (Crosshair) : 와우 공식 설정에 없는 애드온 기능으로, 커뮤니티 및
--     유저 실사용 용어인 '크로스헤어'로 일괄 통일합니다 ('십자선' 중에 고민중).
--
-- 4. 기계/AI 직번역 주의 항목
--   - Talking Head            -> '말머리' (블리자드 편집 모드 공식 명칭. '말하는 머리', '대화창' 오번역 주의)
--   - Premade Groups          -> '파티 찾기' / '파티 찾기 창' (유저 직관을 위한 예외 통일. '파티 구성하기' 대신 실사용 용어인 '파티 찾기'로 일괄 통일)
--   - Not Declined            -> '거절된 파티 제외' (필터 특성에 맞춘 자연스러운 의역)
--   - Sated / Exhaustion      -> '만족함' / '탈진' (블러드/영웅심 후유증 공식 명칭. '포만감', '배부름' 오번역 주의)
--   - Pandemic                -> '팬데믹' (도트 갱신 30% 보너스 구간 전문 용어. '전염병', '역병' 오번역 주의)
--   - World Markers           -> '지면 징표' (바닥 빛기둥 징표. '월드 마커', '위치 표시기' 직역 주의)
--   - Environment Ping        -> '지형 핑' (바닥에 찍는 핑. '환경 핑' 직역 주의)
--   - Context Menu            -> '우클릭 메뉴' ('문맥 메뉴' 직역 주의)
--   - Pull / Pull Timer       -> '풀링' / '풀링 초읽기' (전투 개시/초읽기. '당기기', '카운트다운' 음차 주의)
--   - Charge vs. Stack        -> '충전' vs '중첩' (스킬 사용 횟수는 '충전', 효과 누적 수는 '중첩'으로 구분)
--
-- 5. 기능 및 UI 조작 표준 표현
--   - Enable / Disable        -> '켜기' / '끄기' 또는 '활성화' / '비활성화' (문맥에 맞추되 한 옵션 내 일관성 유지)
--   - Attach / Detach         -> '부착' / '분리' (UI 프레임 결합 표준 표현)
--   - Reload / Reload UI      -> 'UI 다시 불러오기' / '다시 불러오기' (블리자드 공식 명칭 사용)
-- =========================================================================

-- Korean localization for EllesmereUI. Community-maintained.
-- Encoding: UTF-8 without BOM. See CONTRIBUTING_TRANSLATIONS.md.
-- Seed locale: high-frequency common vocabulary. Run /euiloc dump koKR in-game
-- to generate the full remaining key list. Untranslated keys fall back to English.
-- + bag keystone Korean-cut engine below this header (가방 쐐기돌 한글컷 엔진 포함)

-- Bag keystone dungeon abbreviation overrides (koKR). AbbrevDungeon in
-- EllesmereUIBags cuts the localized dungeon name to first-letters, which in
-- Korean yields awkward 2-char cuts; remap those to cleaner short names. DATA
-- ONLY -- EllesmereUIBags applies it after computing the abbreviation (no
-- global SetText hook, no per-call cost). "마정"/"하늘탑" already correct.
-- (가방 쐐기돌 한글컷 -> 단축명. 순수 한글 키는 본체 L() 불가라 자체 처리)
-- To reuse for another locale, check in-game how that client cuts the localized
-- dungeon names, then add its own guarded override table the same way.
-- The dungeon names follow the client locale, not the display language, so
-- this runs before the catalog's early return.
if GetLocale() == "koKR" and EllesmereUI then
    EllesmereUI._dungeonAbbrevOverride = {
        ["공투"] = "투기장",
        ["세사"] = "세스랄",
        ["송제"] = "송곳니",
        ["눈골"] = "골짜기",
        ["루생웅"] = "루비",
        ["죽골"] = "골목",
        ["날소"] = "날로라크",
        ["왕안"] = "왕안",
    }
end

local L = EllesmereUI.RegisterLocale("koKR")
if not L then return end

