-- == add Core (본체) ========================================================
L["Include Global Settings"] = "전역 설정 포함"
L["Include fonts, custom colours, dark mode and accent colour with this export. Off = only the selected modules' own settings export, keeping the recipient's global look."] = "내보내기에 글꼴, 사용자 지정 색상, 다크 모드, 강조색 등 전역 설정을 포함합니다. 끄면 선택한 모듈의 자체 설정만 내보내므로, 프로필을 받는 사람 기존의 전역 외형 설정이 유지됩니다."
L["Spec Override"] = "전문화 재정의"
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "재정의 그룹 '%s'이(가) 이미 현재 전문화의 사용자 지정 잠금 해제 모드를 제공합니다. 그쪽에서 수정하거나, 이 전문화를 그 그룹에서 제거하세요."
L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "'%s' 재정의의 값을 표시 중입니다. 해당 재정의의 편집 모드에서 수정하세요."
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "이 전문화의 사용자 지정 잠금 해제 모드는 '%s' 소유입니다. 그쪽에서 수정하거나, 그 그룹에서 전문화를 제거하세요."
L[" to be assigned to"] = "을(를) 할당할 전문화를 선택하세요"
L["(Applies on Window Close)"] = "(창 닫을 때 적용)"
L["(minutes)"] = "(분)"
L["*Please enter a profile name"] = "*프로필 이름을 입력하세요"
L["A beautiful visual refresh of Blizzard Bags with intuitive organization."] = "직관적인 정리 기능을 갖춘 블리자드 기본 가방의 세련된 외형 개선."
L["A bright, minimalist layout with a clean aesthetic. Crafted for any role with clear information and a calm but focused feel."] = "깔끔한 디자인의 밝은 미니멀 레이아웃. 명확한 정보와 차분한 구성으로 모든 역할에 맞게 제작."
L["A CDM replacement focused on performance, customizations and alerts."] = "성능, 맞춤 설정, 알림 기능에 집중한 재사용 대기시간 관리자 대체 모듈."
L["A clean minimal setup"] = "깔끔한 미니멀 설정."
L["A clean, updated reskin of Blizzard's Quest Tracker."] = "블리자드 기본 퀘스트 추적기의 깔끔한 최신 외형 개선."
L["A dark, elegant healing setup built around raid frames and a clean display of information to help keep your team alive at a glance."] = "공격대 프레임을 중심으로 구성된 어둡고 세련된 힐러 레이아웃. 깔끔한 정보 표시로 파티원의 생존을 한눈에 관리."
L["A modern friends list with built-in organization tools."] = "정리 도구가 내장된 현대적인 친구 목록."
L["A new age minimap with clean styling and square layout options."] = "깔끔한 스타일과 사각형 배치 옵션을 갖춘 새로운 미니맵."
L["A new Use Modifier option makes the spell and item ID lines on tooltips appear only while you hold Shift, Control, or Alt."] = "새 '보조키 사용' 옵션을 켜면 Shift, Ctrl, Alt 키를 누르고 있을 때만 툴팁에 주문 및 아이템 ID를 표시합니다."
L["A raid control panel with ready check, pull timer and raid markers."] = "전투 준비 확인, 풀링 초읽기, 공격대 징표 기능을 제공하는 공격대 제어 패널."
L["A simple Mythic+ timer with full tracking customizations."] = "다양한 추적 맞춤 설정이 가능한 심플한 신화+ 타이머."
