L["Fill the health bar bottom-to-top instead of left-to-right. Reverse Fill flips it to top-to-bottom."] = "체력 바를 왼쪽에서 오른쪽 대신 아래에서 위로 채웁니다. '반대로 채우기'를 활성화하면 위에서 아래로 방향이 뒤집힙니다."
L["Full mouseover cast binding suite"] = "완전한 마우스오버 시전 단축키"
