L["Remove Override"] = "재정의 제거"
L["Spec Overrides"] = "전문화 재정의"
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "활성화 시 작은 아이콘으로 시작하며, 지정한 단축키를 누르면 아이콘과 전체 창이 전환됩니다. 이 옵션을 끄면 항상 전체 창으로 표시되며 단축키는 창을 숨기거나 띄우는 역할만 합니다."
L["Show the tracker as the Rebirth icon or as a compact text line with charges and time until the next one."] = "추적기를 환생 아이콘으로 표시하거나, 충전 횟수와 다음 충전까지 남은 시간이 표시되는 간결한 텍스트로 나타냅니다."
L["This option requires Display Style to be set to Text"] = "이 옵션을 사용하려면 표시 스타일을 '텍스트'로 설정해야 합니다."
L["One Window combines everything into a single element; the Only choices show just that part."] = "단일 창 모드는 모든 요소를 하나의 프레임으로 통합합니다. '단독' 옵션을 선택하면 해당 부분만 표시됩니다."
L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "전투 중이거나 비전투 상태일 때 공격대 도구 패널을 열고 닫습니다.\n\n좌클릭하여 단축키를 지정합니다.\n우클릭하여 지정을 해제합니다."
L["Vertical Fill"] = "세로로 채우기"
L["Video Guide: Cooldown Manager"] = "영상 가이드: 재사용 대기시간 관리자"
L["Video Guide: Unlock Mode"] = "영상 가이드: 잠금 해제 모드"
L["Which way the windows extend from the collapsed icon when they open."] = "아이콘이 열릴 때, 접혀 있던 창이 어느 방향으로 확장되는지 설정합니다."
L["What's new in EllesmereUI."] = "EllesmereUI의 새로운 기능."
L["|cff888888Click to create|r"] = "|cff888888클릭하여 생성|r"
L["|cff888888Created|r"] = "|cff888888생성됨|r"
L["|cffff4444Delete Macro|r"] = "|cffff4444매크로 삭제|r"
-- patch-notes notice popup shown at login (로그인 시 뜨는 패치노트 안내 팝업)
L["Localization"] = "현지화"
L["Vanilla WoW art joins EllesmereUI Style and Blizzard Style as a third look, keeping EllesmereUI's features. Raid Frames, Chat, Quest Tracker, Friends List and the Character Sheet gain the stock looks too; pick per module or for the whole UI under Global Settings > Style."] = "오리지널 WoW 그림이 EllesmereUI 스타일, 블리자드 스타일에 이어 세 번째 모양으로 추가되었고, EllesmereUI 기능은 그대로입니다. 공격대 프레임, 대화, 퀘스트 추적기, 친구 목록, 캐릭터 창도 기본 모양을 고를 수 있습니다. 전체 설정 > 모양에서 모듈마다 또는 UI 전체로 고르세요."
L["Border Size is now an exact pixel slider across the suite, so Shadow, Glow and Blizzard borders take any size. Width and Height Match now line up by the visible border edge, so an existing match to a textured border may resize slightly."] = "테두리 크기가 모든 모듈에서 정확한 픽셀 단위 슬라이더가 되어 그림자, 반짝임, 블리자드 테두리도 원하는 크기로 조절할 수 있습니다. 너비/높이 맞추기는 이제 보이는 테두리 끝을 기준으로 맞추므로, 텍스처 테두리에 맞춰 둔 것은 크기가 조금 바뀔 수 있습니다."
L["Party frames can show a 2D or 3D portrait or class art in seven sets, attached beside the bars or detached from the frame. Off by default on the Party tab and works with every style; Detached adds seven shapes, and 3D can also sit inside the frame."] = "파티 프레임에 2D, 3D 초상화 또는 직업 그림 7종을 바 옆에 붙이거나 프레임에서 떼어 표시할 수 있습니다. 파티 탭에서 기본으로 꺼져 있고 모든 모양에서 작동합니다. 떼어 내기에는 모양 7종이 있고, 3D는 프레임 안에도 넣을 수 있습니다."
L["A flight path bar that names your destination and counts down the time left, from the route's length, Frequent Flier and a flight speed refined by each flight. Off by default on the new Travel tab, with size, texture, border, fill colour, text and font options plus Unlock Mode placement."] = "비행 경로 바가 목적지 이름과 남은 시간을 보여 줍니다. 시간은 경로 길이, 단골 비행사, 비행할 때마다 다듬어지는 비행 속도로 계산합니다. 새 여행 탭에서 기본으로 꺼져 있고, 크기, 텍스처, 테두리, 채우기 색상, 글자, 글꼴 설정과 잠금 해제 모드 배치를 지원합니다."
L["Unit & Raid Frames"] = "유닛 및 공격대 프레임"
L["Aura Buff Reminders"] = "오라 강화 효과 알림"
L["Swing Timer"] = "자동 공격 타이머"
L["Everything from retail, ported to WoW Forever and tuned for the vanilla client, with a clean base layout the moment you log in. One EllesmereUI: the same install runs on either game."] = "본섭의 모든 것을 WoW 포에버로 옮겨 오리지널 클라이언트에 맞췄고, 접속하는 순간 깔끔한 기본 배치가 준비됩니다. 하나의 EllesmereUI: 같은 설치본이 두 게임에서 모두 돌아갑니다."
L["Give any module the default Blizzard look while keeping EllesmereUI features and customization: Unit Frames, Auras, Nameplates, CDM, Resource Bars, Minimap and Damage Meters all join the Action Bars, each with its own switch under Global Settings > Style."] = "EllesmereUI 기능과 사용자 설정은 그대로 두고 어느 모듈이든 블리자드 기본 모양을 줄 수 있습니다: 유닛 프레임, 오라, 이름표, 재사용 대기시간 관리자, 자원 바, 미니맵, 데미지 미터기가 행동 단축바에 이어 추가되었고, 전체 설정 > 모양에서 각각 켤 수 있습니다."
L["An end-of-key overview of your group with one row per member: spec, item level, score and score gain, loot, damage, damage taken, interrupts and deaths, sortable by column. Off by default; a per-character run history keeps your recent keys, and /ov reopens the panel."] = "쐐기돌이 끝나면 파티원마다 한 줄씩 전문화, 아이템 레벨, 점수와 점수 상승, 전리품, 피해량, 받은 피해, 차단, 죽음을 보여 주는 요약을 띄웁니다. 열마다 정렬할 수 있습니다. 기본으로 꺼져 있고, 캐릭터별 진행 기록에 최근 쐐기돌이 남으며, /ov 로 창을 다시 엽니다."
L["Restyle the chat bubbles over players' and NPCs' heads with your own background, border, font and colors for the channels you pick. Inside instances the game's own bubbles stay, with an option to hide them there; the whole feature is off by default."] = "플레이어와 NPC 머리 위의 대화 말풍선을 고른 채널에 대해 배경, 테두리, 글꼴, 색상을 직접 정해 바꿉니다. 인스턴스 안에서는 게임 기본 말풍선이 유지되고, 거기서 숨기는 설정이 있습니다. 전체 기능이 기본으로 꺼져 있습니다."
L["Shift-clicking a stack in All Items / Category views lets you split it up or even Auto Split to keep splitting into empty slots until only the amount you chose remains. Split stacks in All Items / Category views re-merge once the bags close and reopen (they stay split in OneBag/MultiBag)."] = "모든 아이템 / 분류 보기에서 묶음을 Shift+클릭하면 나눌 수 있고, 자동 나누기로 정한 개수만 남을 때까지 빈 칸으로 계속 나눌 수도 있습니다. 모든 아이템 / 분류 보기에서 나눈 묶음은 가방을 닫았다 열면 다시 합쳐집니다 (통합 가방/다중 가방에서는 나뉜 채로 남음)."
L["A cooldown icon can show a tracked buff in its slot while that buff is active, then return to the cooldown when it ends. Pick the buff from the icon's right-click menu on any cooldown or utility bar."] = "재사용 대기시간 아이콘이 추적 중인 강화 효과가 활성화된 동안 그 칸에 강화 효과를 표시하고, 끝나면 재사용 대기시간으로 돌아갈 수 있습니다. 재사용 대기시간 바나 보조 바에서 아이콘 우클릭 메뉴로 강화 효과를 고르세요."
L["Performance Patch Follow-Up"] = "성능 패치 후속 조치"
L["Debuff filters on Player Aura Bars, Raid Frames and the player frame gain a Less Common Filters section: Cast By Me, Any Player, Magic, Curse, Poison, Disease, Bleed and Can Apply. A new Max Duration dropdown beside Filters keeps long debuffs off Player Aura Bars and Raid Frames."] = "플레이어 오라 바, 공격대 프레임, 플레이어 프레임의 약화 효과 필터에 덜 쓰는 필터 항목이 생겼습니다: 내가 시전함, 모든 플레이어, 마법, 저주, 독, 질병, 출혈, 걸 수 있음. 필터 옆의 새 최대 지속시간 드롭다운으로 긴 약화 효과를 플레이어 오라 바와 공격대 프레임에서 뺄 수 있습니다."
L["Allowed Demons picks which demons count as correct for any Warlock spec, and the Missing Pet reminder now summons on click"] = "허용 악마로 흑마법사 전문화마다 맞는 악마를 고를 수 있고, 소환수 없음 알림을 클릭하면 이제 소환합니다"
L["The Battle.net friend online and offline toast gets a window skin, with its own Friend Notifications card"] = "Battle.net 친구 접속/접속 종료 알림에 창 스킨이 적용되고, 친구 알림 카드가 따로 생겼습니다"
L["Glow at Stacks can now fire Below, At Most, Exactly, At Least or Above the stack count you set, still secret-safe in combat"] = "중첩 시 반짝임을 정한 중첩 수 미만, 이하, 정확히, 이상, 초과 중에서 고를 수 있고, 전투 중에도 비밀 값 규칙을 지킵니다"
L["Raid frame absorbs and health ticks, nameplate health updates, tracking bar pairing and unit frame absorbs all do less work per event"] = "공격대 프레임 흡수와 생명력 틱, 이름표 생명력 갱신, 추적 바 짝짓기, 유닛 프레임 흡수가 모두 이벤트마다 하는 일이 줄었습니다"
L["Opening Myslot again forces every bar visible, including bars using Match Any, Hide with Target or the mounted visibility conditions."] = "Myslot 을 다시 열면 하나라도 일치, 대상 있으면 숨기기, 탈것 표시 조건을 쓰는 바까지 모든 바가 다시 강제로 보입니다."
L["Glow at Stacks no longer shows a faint glow before the buff reaches the set stack count, and the Shape Glow style now respects the threshold."] = "중첩 시 반짝임이 강화 효과가 정한 중첩 수에 도달하기 전에 희미하게 반짝이지 않으며, 모양 반짝임 스타일도 이제 임계값을 정상 반영합니다."
L["Liquid Luster is available as a Custom Buff Bar potion preset alongside Light's Potential and Potion of Recklessness."] = "액체 광택을 빛의 잠재력, 무모함의 물약과 함께 사용자 지정 강화 효과 바 물약 프리셋으로 쓸 수 있습니다."
L["Deaths show their real time of death during the fight instead of 0:00 until combat ends."] = "죽음 기록이 전투가 끝날 때까지 0:00 대신 전투 중 실제 죽은 시간을 보여 줍니다."
L["The refresh rate now bottoms out at 0.5s (lower saved values move up to it), trimming memory churn during combat."] = "갱신 간격의 최솟값이 0.5초가 되어(더 낮게 저장된 값은 0.5초로 올라감) 전투 중 메모리 사용 변동이 줄었습니다."
L["Entering an instance with the taintLog or scriptProfile debug CVars enabled shows a one-time reminder with a button to disable them, since they cost performance."] = "taintLog 나 scriptProfile 디버그 CVar 를 켠 채 인스턴스에 들어가면 성능을 떨어뜨리므로 끄는 버튼이 있는 알림을 한 번 띄웁니다."
L["Keybinds set in EllesmereUI's own key fields now fire when two or more modifiers are held (for example Ctrl+Alt+1); re-bind any that never triggered."] = "EllesmereUI 자체 단축키 칸에 지정한 단축키가 보조키를 둘 이상 누를 때도 작동합니다 (예: Ctrl+Alt+1). 작동하지 않던 것은 다시 지정하세요."
L["The LFG Reminder popup now matches dungeon names on every client language, not only English and Russian."] = "파티 찾기 알림 팝업이 영어와 러시아어뿐 아니라 모든 클라이언트 언어에서 던전 이름을 찾습니다."
L["Quest objective progress no longer stops updating until a reload (a fishing count or summon bar stuck mid-way)."] = "퀘스트 목표 진행도가 다시 불러오기 전까지 갱신을 멈추는 문제(낚시 횟수나 소환 바가 중간에 멈춤)를 고쳤습니다."
L["Tracked buffs no longer randomly stay hidden on some group members' frames."] = "추적 중인 강화 효과가 일부 파티원 프레임에서 무작위로 숨겨진 채 남는 문제를 고쳤습니다."
L["Max Health Style shows on its own again when Absorb Style is set to None."] = "흡수 모양이 없음일 때 최대 생명력 모양이 다시 혼자 표시됩니다."
L["Death Knight rune pips now honor Border on Individual Pips like every other pip type."] = "죽음의 기사 룬 칸도 다른 칸 종류처럼 칸별 테두리를 따릅니다."
L["The Whirlwind and Sweeping Strikes bar honors the Empty Bar Overlay again so spent charges show in Dark Mode, no longer draws a second set of divider lines with Bar Spacing set, hides its threshold strip while thresholds are disabled, and accepts a stack threshold up to 20."] = "소용돌이와 휩쓸기 일격 바가 빈 바 오버레이를 다시 지원하여 다크 모드에서도 소모된 충전 횟수가 표시되며, 바 간격 설정 시 구분선이 중복 표시되지 않고, 임계값 비활성화 시 임계값 표시선을 숨기며, 최대 20까지 중첩 임계값을 지원합니다."
L["The pet frame updates its name and portrait when you swap pets (for example Voidwalker to Felhunter)."] = "소환수를 바꾸면 소환수 프레임의 이름과 초상화가 갱신됩니다 (예: 공허방랑자에서 지옥사냥개로)."
L["A spec override setting Visibility to Never no longer leaves the frame missing after switching back to another spec."] = "표시 여부를 안 함으로 둔 전문화 재정의가 다른 전문화로 바꾼 뒤에도 프레임을 사라진 채로 두지 않습니다."
L["Class Resource pips no longer widen after a zone change on positions other than Above Health Bar."] = "생명력 바 위가 아닌 위치에서 지역을 옮긴 뒤 직업 자원 칸이 넓어지는 문제를 고쳤습니다."
L["Brazilian Portuguese, Korean and Traditional Chinese caught up on the 9.1.4 strings (bank grouping, visibility overrides, the queue timer style and more)."] = "브라질 포르투갈어, 한국어, 번체 중국어가 9.1.4 문구(은행 묶기, 표시 여부 재정의, 대기열 타이머 스타일 등)를 따라잡았습니다."
L["Bank Organization"] = "은행 정리"
L["The bank window catches up to the bags: nest OneBank and OneWarbank by expansion, group items by your bag categories with automatic splits by equipment slot, profession and material, and browse a category sidebar that spans your character bank and warband together."] = "은행 창이 가방을 따라잡았습니다: 통합 은행과 통합 전투부대 은행을 확장팩별로 묶고, 가방 분류대로 아이템을 모으며 장비 칸, 전문 기술, 재료별로 자동으로 나누고, 캐릭터 은행과 전투부대 은행을 함께 보는 분류 사이드바를 씁니다."
L["Configurable text color, size, bar height and text position for the queue accept countdown, via a swatch and cog beside Show Queue Timer"] = "대기열 수락 초읽기의 글자 색상, 크기, 바 높이, 글자 위치를 대기열 타이머 표시 옆의 색상 견본과 톱니바퀴에서 정할 수 있습니다"
L["Friendly NPC Name Styling"] = "우호 NPC 이름 꾸미기"
L["Name-only friendly NPC plates gain configurable name color, title color and title size in the Friendly NPC Settings cog"] = "이름만 표시하는 우호 NPC 이름표의 이름 색상, 칭호 색상, 칭호 크기를 우호 NPC 설정 톱니바퀴에서 정할 수 있습니다"
L["Whirlwind and Sweeping Strikes Thresholds"] = "소용돌이와 휩쓸기 일격 임계값"
L["Threshold and band colors work on the Whirlwind and Sweeping Strikes charge bar again, drawn as color ranges along the fill"] = "소용돌이와 휩쓸기 일격 충전 바에서 임계값 및 구간 색상이 다시 정상 작동하며, 채우기 진행도를 따라 색상 구간으로 표시됩니다"
L["With health decimals on, full health renders 100% instead of 100.0% while real decimals like 99.5% stay"] = "생명력 소수점을 켜도 가득 찬 생명력은 100.0% 대신 100%로 표시하고, 99.5% 같은 실제 소수는 그대로 둡니다"
L["Hovering names in the Guild & Communities roster no longer errors, and member tooltips keep their race and class lines."] = "길드 및 커뮤니티 명단에서 이름에 마우스를 올려도 오류가 나지 않고, 멤버 툴팁에 종족과 직업 줄이 유지됩니다."
L["Out-of-range coloring now tracks the spell actually on the icon while a proc or talent override replaces it, instead of the base spell's range."] = "발동 효과나 특성이 주문을 바꿔 놓은 동안 사거리 밖 색칠이 기본 주문이 아니라 아이콘에 실제로 있는 주문의 사거리를 따릅니다."
L["Apply to This Spell and Apply to Bar no longer reset a picked Active State color (or other value-carrying settings on preset icons, trinkets and racials) back to defaults."] = "이 주문에 적용과 바에 적용이 고른 활성 상태 색상(그리고 프리셋 아이콘, 장신구, 종족 특성의 다른 값 설정)을 기본값으로 되돌리지 않습니다."
L["In-combat ally breakdowns are now dungeon-only, cutting Damage Meters memory use in raids where duplicate specs blocked most of them anyway."] = "전투 중 아군 세부 내역이 던전에서만 작동하도록 바뀌어, 어차피 같은 전문화가 많아 대부분 막히던 공격대에서 데미지 미터기 메모리 사용이 줄었습니다."
L["A checked Hide visibility condition now always hides its element in both match modes, and every condition has its own Show and Hide row, with new Out of Combat and Not Skyriding (Airborne) rows."] = "체크한 숨기기 표시 조건은 이제 두 일치 방식 모두에서 항상 요소를 숨기고, 조건마다 표시와 숨기기 줄이 따로 있으며, 비전투와 하늘 경주 중 아님 (비행 중) 줄이 새로 생겼습니다."
L["Spec and conditional overrides can now hold the Visibility setting itself, replacing it with Never, Always or Mouseover for those specs."] = "전문화 재정의와 조건부 재정의가 이제 표시 여부 설정 자체를 가질 수 있어, 그 전문화에서 안 함, 항상, 마우스오버로 바꿀 수 있습니다."
L["Picking a raid marker from the fallback unit menu (shown for group members whose data has not streamed in) is now greyed out like the other unavailable actions there instead of throwing a blocked-action error."] = "대체 유닛 메뉴(정보를 아직 받지 못한 파티원에게 뜸)의 공격대 징표 고르기가 차단 오류를 내는 대신 그곳의 다른 쓸 수 없는 동작처럼 회색으로 표시됩니다."
L["With the Rectangular shape, player and party arrows no longer draw in the hidden bands above and below the map, and combat transitions no longer leave the map cut off wrong."] = "직사각형 모양에서 플레이어와 파티원 화살표가 지도 위아래의 숨겨진 띠에 그려지지 않고, 전투 전환 때 지도가 잘못 잘린 채 남지 않습니다."
L["Target, Focus and Targeted Spell cast bars no longer truncate spell names when there is no target text sharing the bar."] = "대상, 주시 대상, 대상 지정 주문 시전 바가 바를 함께 쓰는 대상 글자가 없을 때 주문 이름을 잘라내지 않습니다."
L["The target effect's border size no longer snaps back to normal while a cast bar is shown with Border Wraps Around Cast Bar enabled."] = "시전 바를 감싸는 테두리를 켠 상태로 시전 바가 표시되는 동안 대상 효과의 테두리 크기가 원래대로 돌아가지 않습니다."
L["Simplified Chinese caught up on the recent additions (chat recall, the performance reminder, Ignore Pain tracking and more)."] = "간체 중국어가 최근 추가분(대화 기록 불러오기, 성능 알림, 고통 감내 추적 등)을 따라잡았습니다."
L["Catch up on anything you may have missed"] = "놓친 내용 따라잡기"
