L["Combat Text Font"] = "전투 메시지 글꼴"
L["Cursor Position"] = "커서 위치"
L["EUI Buttons"] = "EUI 버튼"
L["EUI Global Font"] = "EUI 전체 글꼴"
L["EUI Options Language"] = "EUI 설정 언어"
L["EUI Options Scale"] = "EUI 설정 크기"
L["EUI Options Theme"] = "EUI 설정 테마"
