L["Pull Colors From"] = "색상 가져올 프로필"
-- add Core Tooltip (본체 툴팁)
L["Corner options place the bar flush with that corner of the target and set its grow direction to keep it there as bars change size."] = "모서리 기준점 옵션은 바를 대상의 해당 모서리에 밀착시키고, 바 크기가 바뀌어도 원래 위치를 유지하도록 확장 방향을 맞춥니다."
L["The taintLog and scriptProfile CVars are enabled."] = "taintLog 및 scriptProfile CVar가 켜져 있습니다."
L["The taintLog CVar is enabled."] = "taintLog CVar가 켜져 있습니다."
L["The scriptProfile CVar is enabled."] = "scriptProfile CVar가 켜져 있습니다."
L["It reduces performance and should be off unless you are capturing a bug report."] = "게임 성능이 저하될 수 있으므로, 버그 리포트 기록을 수집하는 중이 아니라면 꺼두세요."
L["Reload to finish importing."] = "가져오기를 완료하려면 UI를 다시 불러오세요(Reload)."
L["Flat, clean and modern. The look EllesmereUI was designed around."] = "깔끔하고 현대적인 플랫 디자인. EllesmereUI의 시그니처 기본 스타일입니다."
L["Blizzard's own frame and button art, with EllesmereUI's features."] = "블리자드 기본 프레임 및 버튼 그래픽에 EllesmereUI의 기능을 더한 스타일입니다."
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "클래식 원본 프레임, 링, 슬롯 그래픽에 EllesmereUI의 기능을 더한 스타일입니다."
L["Style changed for this profile. A UI reload is needed to apply it."] = "이 프로필의 스타일이 변경되었습니다. 적용하려면 UI를 다시 불러와야 합니다."
L["Same setup, same EllesmereUI features, a new look: switch to Blizzard Style or the new Classic WoW UI in one click, and switch back any time."] = "모든 설정과 기능은 유지한 채 스타일만 변경: 클릭 한 번으로 블리자드 스타일이나 클래식 WoW UI로 전환하고 언제든 되돌릴 수 있습니다."
L["Global Settings > Style sets the look for the whole UI or for each module."] = "[전역 설정 -> 스타일]에서 UI 전체 또는 모듈별 외형을 설정합니다."
L["Patch 12.1 changes a lot, and EllesmereUI changed with it. This video walks you through the most important changes so you can jump straight back in. Copy the link below and watch it in your browser."] = "12.1 패치에 맞춰 EllesmereUI의 많은 부분이 개편되었습니다. 주요 변경 사항을 빠르게 파악할 수 있도록 안내 영상을 제공합니다. 아래 링크를 복사해 브라우저에서 시청하세요."
L["Watch anytime: the link also lives at the top of Patch Notes."] = "언제든 다시 시청할 수 있습니다: 링크는 패치 노트 상단에도 상시 제공됩니다."
L["Settings Overrides are the most powerful system in EllesmereUI, and the deepest. A few minutes with this video will save you hours of working it out on your own."] = "설정 재정의(Overrides)는 EllesmereUI의 가장 강력하고 핵심적인 시스템입니다. 안내 영상을 시청하시면 복잡한 개별 설정을 손쉽게 익히실 수 있습니다."
L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "재정의가 활성화되어 있는 항목의 기본값을 변경했습니다. 재정의는 고유 설정을 유지하므로 이번 변경 사항은 해당 전문화나 조건에 반영되지 않습니다. 재정의 값을 변경하려면 모듈 검색창 옆의 직업 아이콘에서 해당 재정의를 선택하여 수정하세요."
L["Gold border settings have overrides. Hover info icon for details."] = "금색 테두리 설정에는 재정의가 활성화되어 있습니다. 자세한 내용은 정보 아이콘에 마우스를 올려 확인하세요."
L["Popular presets now live on the new EllesmereUI website including full previews, step-by-step install instructions, plus new presets added every day!"] = "EllesmereUI 공식 웹사이트에서 전체 미리보기와 단계별 설치 가이드가 포함된 인기 프리셋을 만나보실 수 있으며, 매일 새로운 프리셋이 추가됩니다!"
L["Each preset's page includes its import string."] = "각 프리셋 상세 페이지에서 가져오기 문자열을 확인할 수 있습니다."
L["This profile string does not carry any global settings."] = "이 프로필 문자열에는 전역 설정이 포함되어 있지 않습니다."
L["Apply the sharer's fonts, custom colours, dark mode, accent colour and UI scale. Off = keep your own global look and scale; only the selected modules' settings come in."] = "공유자의 글꼴, 사용자 지정 색상, 다크 모드, 강조 색상, UI 크기 비율을 적용합니다. 끄면 본인의 전역 스타일과 크기를 유지하고, 선택한 모듈의 설정만 가져옵니다."
L["Reload to finish switching to the new profile."] = "새 프로필 전환을 완료하려면 UI를 다시 불러오세요(Reload)."
L[" Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = " 이 요소는 마우스오버 재정의가 제한되어 있습니다: 마우스오버 동작이 공용 설정을 따르므로, 재정의 시 항상 표시 상태로만 유지할 수 있습니다."
L["This element cannot use group-based visibility."] = "이 요소는 파티/공격대 그룹 기반 표시 조건을 사용할 수 없습니다."
L["Requires a client with gliding events."] = "하늘비행 기능을 지원하는 클라이언트가 필요합니다."
L["Not available while a legacy visibility value is selected. Pick Never or Always first."] = "이전 버전의 표시 설정이 선택되어 있으면 사용할 수 없습니다. 먼저 '사용 안 함' 또는 '항상 표시'를 선택하세요."
L["Scales the text size of Blizzard tooltips."] = "블리자드 툴팁의 글자 크기를 조절합니다."
L["Sizes the movement alert's free text, bar number and icon countdown. Switching the alert's Display Mode re-seeds this value."] = "이동기 알림의 자유 글자, 바 숫자, 아이콘 초읽기 크기입니다. 알림의 표시 방식을 바꾸면 이 값이 다시 정해집니다."
L["%1$s is active: the tracker keeps Blizzard's own text."] = "%1$s 활성화됨: 추적기가 블리자드 기본 글자 스타일을 유지합니다."
L["Blizzard's own character sheet with the EllesmereUI stats, slot text and socket panel added; the Calc tab stays with the EllesmereUI look."] = "블리자드 기본 캐릭터 창에 EllesmereUI 능력치, 슬롯 정보, 보석 홈 패널을 추가합니다. 강화 계산기 탭은 EllesmereUI 스타일을 유지합니다."
L["Size of the Classic frame around the bar."] = "바를 둘러싼 클래식 테두리 프레임의 크기입니다."
L["%1$s is active. Settings that only apply to the EllesmereUI look are hidden."] = "%1$s 활성화됨: EllesmereUI 전용 외형 설정은 숨겨집니다."
L["Changing the style requires a UI reload to apply."] = "외형 스타일을 변경하면 UI를 다시 불러와야 적용됩니다."
L["Your setup and every EllesmereUI feature carry over; only the look changes. Apply a style to every module in one click, or set each module below. Changing a style reloads the UI."] = "기존 설정과 모든 기능은 유지되며 외형 스타일만 변경됩니다. 클릭 한 번으로 모든 모듈에 일괄 적용하거나 아래에서 모듈별로 설정할 수 있습니다. 스타일 변경 시 UI를 다시 불러옵니다."
L["Texture for every unit frame cast bar. Inherit follows each unit's bar texture."] = "모든 유닛 프레임 시전 바의 텍스처입니다. '상속'은 각 유닛 프레임의 바 텍스처 설정을 따릅니다."
L["Texture for the health, power and class resource bars."] = "생명력, 자원, 직업 자원 바의 텍스처입니다."
L["%1$s is active: chat keeps Blizzard's own background and tab art."] = "%1$s 활성화됨: 대화창이 블리자드 기본 배경 및 탭 그래픽을 유지합니다."
L["Used by the movement alert's Bar display mode."] = "이동기 알림의 바 표시 방식에서 씁니다."
L["*Blizzard's auto targeting (soft target) setting can cause brief flickering when your actual target dies but a soft-target is still active."] = "*블리자드의 자동 대상 지정(소프트 타깃) 기능 사용 시, 기존 대상이 사망해도 보조 대상 지정이 활성화되어 있으면 순간적인 깜빡임 현상이 발생할 수 있습니다."
L["Addon not loaded"] = "애드온이 로드되지 않음"
L["Anchor to Cursor"] = "커서에 고정"
L["Apply X to all Bars"] = "모든 바에 X좌표(가로) 적용"
L["at least one Celebration Trigger"] = "축하 연출 조건 최소 1개 이상"
L["Choose which addons to import. Any addons not included will use your active profile's settings in the new profile."] = "가져올 애드온을 선택하세요. 포함되지 않은 애드온은 새 프로필에서도 현재 활성화된 프로필의 설정을 유지합니다."
L["Choose which addons you want enabled. You can change any of these later in the EllesmereUI settings panel."] = "사용할 애드온을 선택하세요. 나중에 EllesmereUI 설정 패널에서 변경할 수 있습니다."
L["Coming soon"] = "곧 추가 예정"
L["Configure alerts for missing Beacon of Light or Faith."] = "빛의 봉화 또는 신앙의 봉화 누락 알림을 설정합니다."
L["Controls the text rendering style used across all UI elements"] = "모든 UI 요소에 적용되는 글자 렌더링 스타일을 설정합니다"
L["Disable "] = "비활성화 "
L["Discord"] = "디스코드"
L["Easy Stealth"] = "간편한 은신"
L["Enable "] = "활성화 "
L["Enable/disable any time via the options panel sidebar."] = "설정 패널 사이드바에서 언제든 켜고 끌 수 있습니다."
L["Enables sharpening to improve image clarity. Especially noticeable at lower render scales."] = "선명도를 높여 화면을 더 또렷하게 만듭니다. 렌더링 해상도 배율이 낮을 때 특히 효과적입니다."
L["Export settings for specific addons only. You can choose which addons to include in your exported profile."] = "특정 애드온의 설정만 내보냅니다. 내보낼 프로필에 포함할 애드온을 선택할 수 있습니다."
L["Havoc"] = "파멸"
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "게임 ESC(게임 메뉴)에서 EllesmereUI 버튼을 숨깁니다."
L["Hides the sync icons on the sidebar module list."] = "사이드바 모듈 목록에서 동기화 아이콘을 숨깁니다."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "게임 ESC(게임 메뉴)에서 잠금 해제 모드 버튼을 숨깁니다. EUI 설정 패널에서는 언제든 잠금 해제 모드를 켤 수 있습니다."
L["Import the anchor & size-match relationships from this profile. Off = keep your own layout; only the selected modules' own positions/settings come in."] = "이 프로필의 기준점(앵커) 및 크기 맞춤 연결 관계를 가져옵니다. 끄면 현재 레이아웃 배치를 유지하고 선택한 모듈의 고유 위치/설정만 가져옵니다."
L["In Maintenance"] = "점검 중"
L["Include the anchor & size-match relationships between modules. Off = export each module's own positions only, with no cross-module tying."] = "모듈 간 기준점(앵커) 및 크기 맞춤 연결 관계를 포함합니다. 끄면 모듈 간 연동 없이 각 모듈의 고유 위치만 내보냅니다."
L["Keybinds respond on key down instead of key up. This helps make your abilities feel more responsive."] = "키를 뗄 때가 아니라 누르는 즉시 단축키가 작동합니다. 스킬 시전 반응 속도를 높이는 데 도움이 됩니다."
L["Never miss an update again. The new Patch Notes section breaks down what's new each release, with quick links straight to every new setting."] = "새로운 패치 노트 메뉴에서 매 버전의 신규 기능과 변경점을 한눈에 확인하고, 해당 설정 메뉴로 바로 이동할 수 있습니다."
L["No conditional overrides yet. Click the Conditional Overrides button next to the module search bar and create a conditional group (Dungeon, Raid, Keybind...). Spec overrides always take precedence over conditionals."] = "아직 조건부 재정의가 없습니다. 모듈 검색창 옆의 [조건부 재정의] 버튼을 눌러 조건 그룹(던전, 공격대, 단축키 등)을 생성하세요. 전문화 재정의는 항상 조건부 재정의보다 우선 적용됩니다."
L["No other profiles to sync to"] = "동기화할 다른 프로필이 없습니다"
L["No Profile Level Customizations"] = "프로필 단위 사용자 설정 없음"
L["Open it anytime from Global Settings > Patch Notes."] = "[전역 설정 -> 패치 노트]에서 언제든 열 수 있습니다."
L["Patreon"] = "패트리온"
L["PayPal"] = "페이팔"
L["Pet Move"] = "소환수 이동"
L["Prevents Blizzard from dimming Swiftmend on action bars and CDM based on Efflorescence state."] = "꽃피움 활성화 여부에 따라 블리자드 기본 UI가 행동 단축바와 재사용 대기시간 관리자(CDM)에서 신속한 치유를 흐리게 표시하는 현상을 방지합니다."
L["Reset to default"] = "기본값으로 초기화"
L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "모든 EllesmereUI 요소(탭, 반짝임, 강조, 테두리)에 사용되는 강조 색상을 설정합니다. 기본값은 테마 색상입니다."
L["Show a pulsing dot on the Patch Notes button whenever EllesmereUI updates to a new version."] = "EllesmereUI가 새 버전으로 업데이트되면 패치 노트 버튼에 반짝이는 점 알림을 표시합니다."
L["Slug outline renders higher quality outlines compared to the base WoW outline mode but may make outline effects appear slightly thicker."] = "Slug 외곽선은 와우 기본 글꼴 외곽선보다 훨씬 깔끔하고 선명한 고품질 외곽선을 표현합니다 (약간 더 두껍게 보일 수 있음)."
L["Spirit Mend"] = "영혼의 치유"
L["Swatch 1"] = "색상 견본 1"
L["Swatch 2"] = "색상 견본 2"
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "재사용 대기시간 관리자는 단순히 대기시간만 보여주는 게 아니라 주문별 설정, 바 반짝임, 추적 바 등 훨씬 많은 기능이 있습니다! 더 잘 활용하는 팁과 요령을 확인해보세요."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "EllesmereUI 설정창의 표시 언어입니다. '자동'은 게임 클라이언트 언어를 따르며, 미번역 문구는 영문으로 표시됩니다."
L["the Randomly trigger"] = "무작위 발동 조건"
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "이 설정은 환경 그래픽 디테일보다 FPS(초당 프레임 수)와 시각적 선명도를 최우선으로 합니다. 텍스처는 고품질로 유지되므로 캐릭터와 배경이 여전히 깔끔하게 표현됩니다."
L["This bar will only show if you have an enemy targeted"] = "적을 대상으로 잡았을 때만 이 바를 표시합니다"
L["This element doesn't support both Height and Width matching"] = "이 요소는 너비와 높이 일치를 동시에 지원하지 않습니다"
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity."] = "높은 FPS와 시각적 선명도를 균형 있게 확보할 수 있도록 게임 내 그래픽 설정을 최적화합니다."
L["What we change:\n\nShadow Quality - Fair (balanced quality/FPS)\nLiquid Detail - Disabled\nParticle Density - Set to Ultra (keeps important spell effects)\nSSAO (Ambient Occlusion) - Disabled\nDepth Effects - Disabled\nCompute Effects - Disabled\nOutline Mode - Disabled\nTexture Resolution - Set to High\nSpell Density - Set to Essential\nProjected Textures - Enabled (needed for ground effects)\nView Distance - Reduced to 1\nEnvironment Detail - Reduced to 1\nGround Clutter - Reduced to 1\nRaid/Dungeon Settings - Uses same settings everywhere\nResample Sharpening - Enabled (crisper image)\nContrast - Boosted by +10 (if currently 55 or below)\nEnable Reverb - Disabled (spell and interrupt audio cues stay crisp)\n\nThese settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "변경 항목:\n\n그림자 품질 - 보통 (품질/FPS 균형)\n물 디테일 - 끔\n입자 밀도 - 최상 (중요 주문 효과 유지)\nSSAO (주변 차폐) - 끔\n입체 효과 - 끔\n연산 효과 - 끔\n외곽선 모드 - 끔\n텍스처 해상도 - 높음\n주문 밀도 - 필수만\n투영 텍스처 - 켬 (지면 바닥 효과 표시에 필수)\n시야 거리 - 1로 낮춤\n환경 디테일 - 1로 낮춤\n사물 표현 - 1로 낮춤\n공격대/던전 설정 - 모든 환경에서 동일 설정 적용\n리샘플 샤프닝 - 켬 (더 선명한 화면)\n대비 - +10 상향 (현재 55 이하인 경우)\n잔향 효과 - 끔 (주문 및 차단 효과음이 또렷하게 들림)\n\n이 설정은 환경 그래픽 디테일보다 FPS와 시각적 선명도를 우선시합니다. 텍스처 품질은 높음으로 유지되어 캐릭터와 주변 배경이 여전히 깔끔하게 보입니다."
L["This feature requires Snap Elements to be enabled"] = "이 기능을 사용하려면 '요소 자석 맞춤(스냅)' 설정이 켜져 있어야 합니다."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "주문 지연 허용 시간(Spell Queue Window) 설정입니다. 한 번에 너무 많은 주문이 밀려 입력이 씹히는 현상을 방지합니다. 권장값은 보통 최소 (200 + 내 핑)입니다. 기능을 잘 모르겠다면 기본값인 400으로 두세요."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally ~150 for melee and ~300 for casters. Higher if you have high local ping."] = "주문 지연 허용 시간(Spell Queue Window) 설정입니다. 한 번에 너무 많은 주문이 밀려 입력이 씹히는 현상을 방지합니다. 일반적으로 근접 직업은 약 150, 원거리/캐스터 직업은 약 300을 권장하며, 핑이 높다면 더 높은 값을 권장합니다."
L["This module can't be overridden. Exit the override editing session to open it."] = "이 모듈은 전문화 재정의를 지원하지 않습니다. 열려면 재정의 편집 세션을 종료하세요."
L["This option is only available for the Custom Color Theme"] = "이 설정은 사용자 지정 색상 테마에서만 사용할 수 있습니다."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "이 대상은 블리자드 기본 프레임을 사용 중이므로 설정할 수 있는 EllesmereUI 옵션이 없습니다."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "이 대상 프레임은 숨김 상태이므로 설정할 수 있는 EllesmereUI 옵션이 없습니다."
L["This will not reset addon-specific Quick Setup."] = "애드온별 빠른 설정은 초기화되지 않습니다."
L["Toggle EllesmereUI"] = "EllesmereUI 켜기/끄기"
L["Toggle EllesmereUI's optional buttons: the Escape menu buttons and the minimap button."] = "EllesmereUI의 추가 버튼(Esc 메뉴 버튼 및 미니맵 버튼) 표시를 전환합니다."
L["Track consumables and raid buffs for instanced content."] = "인스턴스 콘텐츠의 소모품과 공격대 강화 효과를 추적합니다."
L["Twitch"] = "트위치"
L["Unlock Mode is how you move and resize everything in EllesmereUI, and it is packed with tools: anchors, width matching, fallback anchors, per-group layouts. This video gets you fluent fast."] = "잠금 해제 모드는 EllesmereUI의 모든 프레임을 이동하고 크기를 조절하는 모드입니다. 기준점(앵커) 고정, 너비 맞춤, 대체 기준점, 그룹별 레이아웃 등 강력한 기능들을 제공하며, 튜토리얼 영상을 통해 빠르게 익히실 수 있습니다."
L["WARNING: This feature requires you to re-log or restart WoW to take effect."] = "경고: 이 설정을 적용하려면 캐릭터 재접속 또는 WoW 재시작이 필요합니다."
L["You changed settings while profile sync is active. Please reload your UI for sync changes to take effect."] = "프로필 동기화가 활성화된 상태에서 설정을 변경했습니다. 동기화된 변경 사항을 적용하려면 UI를 다시 불러오세요(Reload)."
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "현재 전문화에 할당된 프로필이 있어 다른 프로필로 전환할 수 없습니다. 전환하려면 먼저 할당을 해제하세요."
L["Your game client language uses a system font automatically.\nFont selection is not available for this locale."] = "현재 언어 환경에서는 한국어 시스템 글꼴이 자동으로 적용됩니다.\n해당 언어 환경에서는 글꼴 선택이 제한됩니다."
L["|cff0cd29dLeft-click:|r |cffE0E0E0Toggle EllesmereUI|r"] = "|cff0cd29d좌클릭:|r |cffE0E0E0EllesmereUI 켜기/끄기|r"
L["|cff0cd29dMiddle-click:|r |cffE0E0E0Hide Minimap Button|r"] = "|cff0cd29d휠클릭:|r |cffE0E0E0미니맵 버튼 숨기기|r"
L["|cff0cd29dRight-click:|r |cffE0E0E0Enter Unlock Mode|r"] = "|cff0cd29d우클릭:|r |cffE0E0E0잠금 해제 모드 진입|r"
-- add Core Popup (본체 팝업)
L["Better Character Panel conflicts with the EllesmereUI's Character Sheet. Disable either Better Character Panel or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Better Character Panel 애드온이 EllesmereUI 캐릭터 창과 충돌합니다. [블리자드 UI 개선] 설정에서 캐릭터 창 스킨을 끄거나 Better Character Panel 애드온을 비활성화하세요."
L["Blizzard's Edit Mode snapping may not work correctly until you reload your UI."] = "UI를 다시 불러오기(Reload) 전까지 블리자드 편집 모드의 자석 맞춤(스냅)이 정상 작동하지 않을 수 있습니다."
L["Changing cursor anchor requires a UI reload to take effect."] = "커서 기준점 변경 사항을 적용하려면 UI를 다시 불러와야 합니다."
L["Changing quest icons requires a UI reload to apply."] = "퀘스트 아이콘 변경 사항을 적용하려면 UI를 다시 불러와야 합니다."
L["Changing the frame source requires a UI reload to take effect."] = "프레임 소스 변경 사항을 적용하려면 UI를 다시 불러와야 합니다."
L["Changing the language requires a UI reload."] = "언어 설정을 변경하려면 UI를 다시 불러와야 합니다."
L["Chonky Character Sheet conflicts with the EllesmereUI's Character Sheet. Disable either Chonky or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Chonky Character Sheet 애드온이 EllesmereUI 캐릭터 창과 충돌합니다. [블리자드 UI 개선] 설정에서 캐릭터 창 스킨을 끄거나 Chonky 애드온을 비활성화하세요."
L["Combat text font changes require a logout to character select to take effect. This is a WoW engine limitation."] = "전투 메시지 글꼴 변경 사항은 캐릭터 선택 화면으로 나갔다 와야 적용됩니다 (WoW 게임 엔진 제한)."
L["Deja Character Stats conflicts with the EllesmereUI's Character Sheet. Disable either Deja or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Deja Character Stats 애드온이 EllesmereUI 캐릭터 창과 충돌합니다. [블리자드 UI 개선] 설정에서 캐릭터 창 스킨을 끄거나 Deja 애드온을 비활성화하세요."
L["EllesmereUI Basics has been split into separate addons. Since you had Basics disabled, Minimap, Friends, and Quest Tracker have been disabled to match. A reload is required to apply this change."] = "EllesmereUI Basics 모듈이 별도 애드온들로 분리되었습니다. 기존에 Basics를 비활성화하셨으므로 미니맵, 친구, 퀘스트 추적기도 동일하게 꺼집니다. 변경 사항을 적용하려면 UI를 다시 불러와야 합니다."
L["Enable & Reload"] = "활성화 후 다시 불러오기"
L["Enter a name for the new profile:"] = "새 프로필 이름 입력:"
L["Include CDM Spell Layout?"] = "CDM 주문 배치를 포함하시겠습니까?"
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "선택한 전문화의 재사용 대기시간 관리자(CDM) 주문 배치(어떤 주문이 어느 바에 놓이는지)와 주문별 세부 설정을 모두 포함합니다."
L["Leatrix Plus has chat and minimap features that conflict with EllesmereUI. Disable any chat or minimap related options within Leatrix Plus to stay compatible."] = "Leatrix Plus 애드온의 대화창 및 미니맵 기능이 EllesmereUI와 충돌합니다. 호환을 위해 Leatrix Plus 내의 대화창/미니맵 관련 옵션을 꺼주세요."
L["Many of ElvUI's modules are incompatible with EllesmereUI. Make sure to disable any conflicting modules."] = "ElvUI의 여러 모듈은 EllesmereUI와 호환되지 않습니다. 충돌이 발생하는 모듈을 반드시 비활성화해 주세요."
L["Reset All & Reload"] = "모두 초기화 후 다시 불러오기"
L["Save & Exit"] = "저장 후 나가기"
L["TellMeWhen overlaps with EllesmereUI's core positional architecture. If you ONLY use for sound alerts it should be okay but may still cause issues."] = "TellMeWhen 애드온은 EllesmereUI의 핵심 프레임 위치 구조와 충돌합니다. 소리 알림 전용으로만 사용하는 것은 대체로 괜찮지만 예기치 않은 오류가 발생할 수 있습니다."
L["This frame's source changes require a UI reload to take effect."] = "프레임 소스 변경 사항을 적용하려면 UI를 다시 불러와야 합니다."
L["You have unsaved position changes.\nWhat would you like to do?"] = "저장되지 않은 위치 변경 사항이 있습니다.\n어떻게 하시겠습니까?"
-- add Core Format (본체 포맷)
L["%1$s Module"] = "%1$s 모듈"
L["Anchor to %1$s"] = "%1$s에 고정"
L["Are you sure you want to %1$s %2$s?"] = "정말 %2$s을(를) %1$s하시겠습니까?"
L["Are you sure you want to reset all %1$s settings to their defaults? This will reload your UI."] = "%1$s의 모든 설정을 기본값으로 초기화하시겠습니까? UI를 다시 불러옵니다."
L["Are you sure you want to reset all %s settings to their defaults? This will reload your UI."] = "%s의 모든 설정을 기본값으로 초기화하시겠습니까? UI를 다시 불러옵니다."
L["Elements cannot be anchored to\n%s"] = "다음 요소에는 기준점을 고정할 수 없습니다:\n%s"
L["Export will include %1$s of %2$s addons."] = "내보내기에 전체 %2$s개 중 %1$s개 애드온이 포함됩니다."
L["Import will include %1$s of %2$s addons."] = "가져오기에 전체 %2$s개 중 %1$s개 애드온이 포함됩니다."
L["Importing %1$s"] = "%1$s 가져오는 중"
L["Keybind: %1$s"] = "단축키: %1$s"
L["Linked by Anchor/Width/Height Matching to: %1$s. These export together."] = "기준점/너비/높이 맞춤으로 연결됨: %1$s. 함께 내보냅니다."
L["Linked by Anchor/Width/Height Matching to: %1$s. These import together."] = "기준점/너비/높이 맞춤으로 연결됨: %1$s. 함께 가져옵니다."
L["Resolution Issue: Profile was made at %1$dx%2$d, yours is %3$dx%4$d"] = "해상도 차이: 프로필 제작 해상도는 %1$dx%2$d이며, 현재 해상도는 %3$dx%4$d입니다"
L["Select which specs you want %1$s to be assigned to"] = "%1$s을(를) 적용할 전문화를 선택하세요"
L["Snap Target: %1$s"] = "자석 맞춤(스냅) 대상: %1$s"
L["Snap to: %1$s"] = "자석 맞춤(스냅) 기준: %1$s"
L["This will overwrite %1$s settings on the selected profiles with your current settings. Continue?"] = "선택한 프로필의 %1$s 설정을 현재 설정으로 덮어씁니다. 계속하시겠습니까?"
L["'%s' is now customized for %s."] = "'%s'이(가) %s 맞춤 설정으로 변경되었습니다."
L["After anchoring, drag to an edge and choose a grow direction to maintain its corner spot as bars change size."] = "기준점을 고정한 후 가장자리로 드래그하고 확장 방향을 설정하면, 바 크기가 변경되어도 모서리 위치가 그대로 유지됩니다."
L["Assign this profile to the same specializations it was assigned to on export. Off = your current spec assignments stay as they are."] = "내보낼 당시 지정되어 있던 동일한 전문화에 이 프로필을 자동 할당합니다. 끄면 현재 전문화 할당이 유지됩니다."
L["Auto Assign to Specs"] = "전문화 자동 할당"
L["Beacon Reminders"] = "봉화 알림"
L["Clique controls click-casting on the same Raid & Party Frames as EllesmereUI's HoverCast, so they conflict. Disable the Clique addon to use HoverCast."] = "Clique 애드온은 EllesmereUI의 마우스오버 시전과 동일한 공격대/파티 프레임에서 클릭 시전을 제어하므로 서로 충돌합니다. 마우스오버 시전을 사용하려면 Clique 애드온을 비활성화하세요."
L["Combine Conditions"] = "조건 결합"
L["Coming Soon"] = "곧 추가 예정"
L["Conditional"] = "조건부"
L["Customizing Unlock Mode: %s (changes apply only to this group's specs)"] = "잠금 해제 모드 편집 중: %s (이 그룹에 속한 전문화에만 적용)"
L["Export"] = "내보내기"
L["Export CDM Spells"] = "CDM 주문 내보내기"
L["Fallback"] = "대체 기준점"
L["Fallback Direction"] = "대체 방향"
L["No patch notes yet."] = "아직 패치 노트가 없습니다."
L["On"] = "켜짐"
L["Page"] = "페이지"
L["Section"] = "섹션"
L["Paste Interrupted"] = "붙여넣기 중단됨"
L["Position and size settings are not synced and keep each profile's own values."] = "위치 및 크기 설정은 동기화되지 않으며 프로필별 고유 값을 유지합니다."
L["Processing"] = "처리 중"
L["The pasted string could not be read completely. Please paste it again."] = "붙여넣은 문자열을 끝까지 읽지 못했습니다. 다시 붙여넣어 주세요."
L["[ Import string captured (%1$s characters) ]"] = "[ 가져오기 문자열 인식됨 (%1$s자) ]"
L["no key set"] = "지정 안 됨"
L["House Favor"] = "집 경험치"
L["House Level"] = "집 레벨"
L["Favor"] = "호감도"
L["MINI PATCH"] = "마이너 패치"
L["FIRST TIME SETUP"] = "최초 설정"
L["Open it anytime from the EUI Options Sidebar."] = "EUI 설정 사이드바에서 언제든 열 수 있습니다."
L["NEW SYSTEM"] = "새 시스템"
L["Link copied - paste it into your browser"] = "링크가 복사되었습니다 - 웹 브라우저에 붙여넣으세요"
L["Recklessness"] = "무모함"   -- 매크로 공장 물약 라벨(241288 무모함의 물약 축약). 전사 주문 아님
L["Mind Freeze\n(Focus)"] = "정신 얼리기\n(주시)"
L["Asphyxiate\n(Focus)"] = "질식사시키기\n(주시)"
L["Death and Decay\n(Cursor)"] = "죽음과 부패\n(커서)"
L["Gorefiend's Grasp\n(Cursor)"] = "고어핀드의 손아귀\n(커서)"
