L["Combines with conditions: shows on hover only while they pass."] = "다른 조건과 함께 적용: 해당 조건들을 만족할 때만 마우스를 올렸을 때 표시합니다."
L["Conditions of the same kind are OR'd together; different kinds must all match. Mouseover combines as a hover gate."] = "동일한 유형의 조건은 하나라도 만족(OR)하면 되고, 서로 다른 유형의 조건은 모두 만족(AND)해야 합니다. 마우스오버는 추가 조건으로 함께 작동합니다."
L["Configure visuals and behavior for your action bars."] = "행동 단축바의 외형과 동작을 설정합니다."
L["Controls the opacity of the Blizzard icon slot background texture."] = "블리자드 아이콘 슬롯 배경 텍스처의 불투명도를 조절합니다."
L["Desaturates (grays out) action button icons while the ability is on cooldown. GCD-only cooldowns are excluded."] = "기술이 재사용 대기 중일 때 행동 단축 버튼 아이콘의 채도를 낮춥니다(흑백 처리). 전역 재사용 대기시간(GCD)만 돌아갈 때는 제외됩니다."
L["Dims action button icons to this opacity while on cooldown (100 = off), using the same detection as Desaturate on Cooldown."] = "기술이 재사용 대기 중일 때 행동 단축 버튼 아이콘을 지정한 불투명도로 어둡게 표시합니다 (100 = 끔). '재사용 대기 중 채도 낮춤'과 동일한 기준이 적용됩니다."
L["Disable Tooltips"] = "툴팁 비활성화"
L["Experience"] = "경험치"
L["Hide the charge number on action buttons when it reaches 0, instead of showing a 0. The number returns as soon as a charge or item comes back."] = "행동 단축 버튼의 충전 횟수가 0이 되면 숫자 '0'을 표시하는 대신 숨깁니다. 충전 횟수나 아이템이 회복되면 숫자가 다시 나타납니다."
L["Left-click to set a keybind."] = "좌클릭: 단축키 지정."
L["Only while airborne on a skyriding mount."] = "하늘비행 탈것을 타고 공중에 있을 때만."
L["Opacity of the cooldown swipe (the dark radial sweep); use the swatch to set its colour."] = "재사용 대기 회전 효과(어두운 방사형 쓸림 애니메이션)의 불투명도입니다. 색상 견본을 클릭해 색상을 설정할 수 있습니다."
