L["Paging Arrows"] = "페이지 넘김 화살표"
L["Show the recharge countdown on charge spells while a charge is still banked. When off, the recharge timer only appears at 0 charges (Blizzard default)."] = "충전 횟수가 남아 있어도 충전형 주문에 재충전 초읽기를 표시합니다. 끄면 충전 횟수가 0일 때만 재충전 타이머가 표시됩니다 (블리자드 기본값)."
L["Shows the consumable rank (quality) diamond icon on action buttons."] = "행동 단축 버튼에 소모품 등급(품질) 다이아몬드 아이콘을 표시합니다."
L["Standing"] = "평판 등급"
L["The highlight overlay that appears on a spell button while it is the active/current action. Disable to hide it."] = "주문이 활성화되어 있거나 현재 시전/수행 중일 때 버튼에 표시되는 강조 오버레이입니다. 끄면 표시되지 않습니다."
L["The overlay that appears on the icon when you hover your mouse over a spell button"] = "주문 버튼 위에 마우스를 올렸을 때 아이콘에 나타나는 오버레이입니다."
L["The overlay that appears on the icon when you press and hold a spell button"] = "주문 버튼을 누르고 있을 때 아이콘에 나타나는 오버레이입니다."
L["this action bar"] = "이 행동 단축바"
L["This is the full overlay that swipes from right to left on the icon during its cast duration"] = "시전 시간 동안 아이콘 전체를 오른쪽에서 왼쪽으로 채워나가는 오버레이입니다."
L["This option does not work with Blizzard Bars. Please use Blizzard Edit Mode."] = "이 설정은 블리자드 바에서는 작동하지 않습니다. 블리자드 편집 모드를 사용하세요."
L["This option is not supported for this bar type"] = "이 설정은 현재 바 유형에서는 지원되지 않습니다."
L["This option requires a custom glow to be selected"] = "이 설정을 사용하려면 사용자 지정 반짝임을 선택해야 합니다."
L["This option requires a non-custom shaped action bar"] = "사용자 지정 모양이 아닌 행동 단축바에서만 사용 가능합니다."
L["Toggles Blizzard's Show Numbers for Cooldowns setting (the countdownForCooldowns CVar) live. This is never saved to EllesmereUI -- it is the same as changing the option in Blizzard's settings."] = "블리자드의 '재사용 대기시간 숫자 표시' 설정(countdownForCooldowns CVar)을 실시간으로 전환합니다. 이 설정은 EllesmereUI에 저장되지 않으며, 블리자드 설정에서 직접 설정을 바꾸는 것과 동일합니다."
L["Toggling an action bar is only available out of combat"] = "행동 단축바 전환은 비전투 상태에서만 가능합니다."
