L["Show a glow on your debuffs while they can be refreshed without losing any duration."] = "효과 지속시간 손실 없이 약화 효과를 갱신할 수 있는 구간 동안 약화 효과에 반짝임을 표시합니다."
L["Rare/Quest Indicator"] = "희귀/퀘스트 징표"
