-- add Nameplates Tooltip (이름표 툴팁)
L["Shows a single Blood Plague debuff on enemy nameplates instead of one per copy (Blood Boil from weapon copies)."] = "적 이름표에 피의 역병 약화 효과를 복제본마다 중복 표시하지 않고 하나만 표시합니다 (춤추는 룬 무기 복제본의 피의 소용돌이로 인한 중복 방지)."
L["Size of the level in the border's plate. 0 follows the bar height."] = "이름표 테두리 플레이트에 표시되는 레벨의 크기입니다. 0으로 설정하면 바 높이에 맞춥니다."
L["Size of the icon that replaces the level on a boss. 0 follows the bar height."] = "우두머리 유닛의 레벨 대신 표시되는 우두머리 아이콘의 크기입니다. 0으로 설정하면 바 높이에 맞춥니다."
L["Disabled when the Name/Level text is centered on the health bar due to overlapping text"] = "텍스트 겹침 방지를 위해, 이름/레벨 글자가 생명력 바 중앙에 위치할 때는 비활성화됩니다."
L["Hide the 1-pixel border around the cast bar spell icon."] = "시전 바의 주문 아이콘 외곽 1픽셀 테두리를 숨깁니다."
L["Adjusts the size of friendly player names shown in Name Only mode. Default is 15."] = "'이름만 표시' 모드에서 표시되는 아군 플레이어의 이름 글자 크기를 조절합니다. 기본값은 15입니다."
L["Adjusts the vertical spacing between stacked nameplates. 100% = default, lower = tighter, higher = more spread."] = "상하로 정렬(스택)되는 이름표 사이의 세로 간격을 조절합니다. 100%는 기본값이며, 낮을수록 촘촘해지고 높을수록 넓어집니다."
L["Apply this pandemic glow to all CDM bars and tracking bars. A surface that can't show a style uses its closest match."] = "모든 CDM 바 및 추적 바에 이 팬데믹 반짝임 효과를 적용합니다. 해당 스타일을 표시할 수 없는 영역은 가장 유사한 스타일이 대체 적용됩니다."
L["Choose which nameplates stack vertically instead of overlapping."] = "이름표가 서로 겹치지 않고 상하로 정렬되도록 적용할 대상 유형을 선택합니다."
L["Colors enemy nameplates for quest mobs you still need to kill."] = "처치해야 할 퀘스트 대상 몬스터의 이름표에 별도 색상을 적용합니다."
L["Controls the highlight shown over a nameplate when you mouse over it. Set to 0 to disable."] = "이름표에 마우스를 올렸을 때(마우스오버) 표시되는 강조 효과를 조절합니다. 0으로 설정하면 끕니다."
L["Display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. This is the same setting as in the FocusKick bar options. Disabled for specs with no kick."] = "신화+에서 주시 대상을 지정하지 않았을 때, 시전형 몬스터나 중간 보스 아래에 \"FOCUS\" 문구를 표시합니다. FocusKick 바 옵션과 동일한 설정입니다. 차단 기술이 없는 전문화에서는 비활성화됩니다."
L["Draws a white letter F on your current focus target's nameplate."] = "현재 주시 대상의 이름표에 흰색 글자 'F'를 표시합니다."
L["Enables a three-tier tank aggro system: has aggro, losing aggro, and no aggro colors override all mob-type colors."] = "3단계 방어 전담 어그로 시스템을 활성화합니다. 어그로 획득, 어그로 상실 중, 어그로 없음 색상이 일반 몬스터 유형 색상보다 우선 적용됩니다."
L["Flash the enemy's cast bar and show \"Interrupted\" for a moment when their cast is interrupted. Use the swatch to change the flash colour."] = "적의 시전이 차단되었을 때 시전 바를 잠시 깜빡이며 \"차단됨\" 문구를 표시합니다. 색상 견본을 클릭해 깜빡임 색상을 변경할 수 있습니다."
L["Forces all casts to be shown in front of nameplates for visual clarity"] = "시인성을 높이기 위해 모든 시전 바를 이름표 앞에 우선 표시합니다."
L["Full alpha on empty part of bar"] = "바의 빈 영역에도 최대 불투명도 적용"
L["Has Aggro"] = "어그로 획득"
L["Hide consumable items (potions, healthstone) from the bar when you have none in your bags, instead of showing them dimmed. They reappear automatically once you have the item again."] = "가방에 소비용 아이템(물약, 생명석 등)이 하나도 없을 때 흐리게 남겨두는 대신 바에서 숨깁니다. 아이템을 다시 획득하면 자동으로 나타납니다."
L["Hide friendly player health bars and instead only see their names.\n\nRequires 'Simplified Friendly Nameplates' to be disabled in Blizzard's Nameplate settings (Esc > Options > Nameplates)."] = "아군 플레이어의 생명력 바를 숨기고 이름만 표시합니다.\n\n블리자드 기본 이름표 설정(ESC > 설정 > 이름표)에서 '단순화된 아군 이름표'를 비활성화해야 합니다."
L["Hide the enemy name text while that nameplate's cast bar is visible."] = "해당 이름표에 시전 바가 표시되는 동안 적의 이름 텍스트를 숨깁니다."
L["Increases the cast bar height on your focus target's nameplate. 100% = normal height."] = "주시 대상 이름표의 시전 바 높이를 확대합니다. 100%는 기본 높이입니다."
L["Increases the clickable hitbox height of enemy nameplates. 100% = matches bar height. Increase to make nameplates easier to click."] = "적 이름표의 클릭 판정 영역(히트박스) 높이를 늘립니다. 100%는 바 높이와 동일하며, 값을 높일수록 이름표를 클릭하기 수월해집니다."
L["Interrupt on CD"] = "차단 기술 재사용 대기 중"
L["Interruptible Cast"] = "차단 가능 시전"
L["Losing Aggro"] = "어그로 상실 중"
L["Make friendly player and NPC nameplates click-through so their names never block your mouse or cause accidental friendly targeting.\n\nUse this when friendly names get in the way of clicking the world or the enemy nameplates behind them."] = "아군 플레이어 및 NPC 이름표를 마우스 클릭이 통과되도록 설정하여, 이름이 마우스 클릭을 가로막거나 실수로 아군을 대상으로 잡는 일을 방지합니다.\n\n아군 이름 때문에 필드 클릭이나 뒤쪽의 적 이름표 클릭이 방해받을 때 유용합니다."
L["Make the spell icon a large square the combined height of the health bar plus the cast bar, flush with the top of the health bar and the bottom of the cast bar."] = "주문 아이콘을 생명력 바와 시전 바 높이를 합친 대형 정사각형으로 만들어, 생명력 바 상단부터 시전 바 하단까지 일치시킵니다."
L["Maximum number of debuff icons shown on enemy nameplates."] = "적 이름표에 표시되는 약화 효과 아이콘의 최대 개수입니다."
L["Mini-Bosses"] = "중간 보스"
L["Mini Enemies"] = "하급 몬스터"
L["Mini Coloring M+ Only"] = "신화+에서만 하급 몬스터 색상 지정"
L["Nameplates opacity for units that are out of line of sight. 0 = fully transparent, 1 = fully opaque."] = "시야(LoS) 밖 유닛의 이름표 불투명도입니다. 0 = 완전 투명, 1 = 완전 불투명."
L["Near Aggro"] = "어그로 임박"
L["No Aggro"] = "어그로 없음"
L["Nudge the cast bar up or down from its default spot under the health bar."] = "시전 바를 생명력 바 아래 기본 위치에서 위아래로 미세 조정합니다."
L["On quest mobs in the open world, replaces the quest icon with the objective progress (a kill quest shows 0/6, a percentage quest shows 50%). Falls back to the icon when no progress is available. Never shown in instances."] = "필드 퀘스트 몬스터의 경우, 퀘스트 아이콘 대신 목표 진행 수치를 표시합니다 (예: 처치 퀘스트 0/6, 달성도 퀘스트 50%). 진행 수치가 없으면 기본 아이콘으로 표시되며, 인스턴스 던전에서는 표시되지 않습니다."
L["On quest mobs in the open world, replaces the quest icon with the objective progress (ex: kill quests show 0/6, percentage objectives show 50%)."] = "필드 퀘스트 몬스터의 경우, 퀘스트 아이콘 대신 목표 진행 수치를 표시합니다 (예: 처치 퀘스트 0/6, 퍼센트 목표 50%)."
L["Pixel-perfect border around the cast bar. Set to 0 for no border."] = "시전 바 외곽에 1픽셀 테두리를 표시합니다. 0으로 설정하면 테두리를 끕니다."
L["Place the cast bar spell icon on the right side of the bars instead of the left."] = "시전 바의 주문 아이콘을 왼쪽 대신 오른쪽에 배치합니다."
L["Raise Strata"] = "레이어 계층(Strata) 올리기"
L["Requires Name Only mode"] = "이름만 표시 모드가 필요합니다"
L["Requires Name Only setting to be disabled"] = "'이름만 표시' 설정을 꺼야 사용할 수 있습니다"
L["Requires Show Friendly NPC Nameplates to be enabled"] = "아군 NPC 이름표 표시가 켜져 있어야 합니다"
L["Scales enemy nameplates while they are casting. 100% = no change."] = "적이 주문을 시전하는 동안 이름표 크기를 확대/축소합니다. 100%는 기본 크기입니다."
L["Scales your current target's nameplate. 100% = no change."] = "현재 대상의 이름표 크기를 확대/축소합니다. 100%는 기본 크기입니다."
L["Show a glow on the cast bar when the enemy is casting a spell Blizzard marks as important."] = "적이 블리자드 기본 UI에서 '중요'로 지정된 주문을 시전할 때 시전 바에 반짝임 효과를 표시합니다."
L["Show a shield icon on the cast bar when an enemy's cast cannot be interrupted."] = "차단할 수 없는 적의 주문 시전 시 시전 바에 방패(보호막) 아이콘을 표시합니다."
L["Show EUI Friendly Player Nameplates"] = "EUI 아군 플레이어 이름표 표시"
L["Show Hash Line on Target at Percent"] = "대상 생명력 백분율 기준선(눈금선) 표시"
L["Show/Hide Hitbox Overlay"] = "히트박스 오버레이 표시/숨기기"
L["Show the player's title or guild in a smaller line below their name on friendly nameplates."] = "아군 이름표의 이름 아래에 더 작은 글씨로 플레이어의 칭호나 길드를 표시합니다."
L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "차단 성공 시의 주문 차단 상태를 군중 제어(CC) 아이콘 칸에 표시합니다.\n\n애드온 API 제약상 표시되는 지속시간은 모든 직업에 공통 4초로 고정되므로 실제 지속시간과 약간 다를 수 있습니다."
L["Show/Hide on Preview"] = "미리보기에서 표시/숨김"
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "적 이름 텍스트 바로 앞에 공격대 징표를 표시합니다. 전역 '기준 위치' 설정 대신 고유 크기 설정을 사용합니다."
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "내 차단 기술의 재사용 대기시간이 끝나는 시점을 시전 바 위에 작은 흰색 눈금으로 표시합니다."
L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "파티/공격대의 다른 방어 전담(탱커)이 어그로를 잡고 있는 이름표에 전용 색상을 표시합니다."
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "일반 적(시전자 및 중간 보스 제외)의 어그로를 획득하지 못했을 때 전용 색상으로 표시합니다."
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "일반 적(시전자 및 중간 보스 제외)의 어그로를 획득했을 때 전용 색상으로 표시합니다."
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "적의 시전 중 내 차단 기술이 돌아오는 시점을 표시합니다. \"눈금\"은 준비되는 정확한 시점만 표시하며, \"눈금 + 바\"는 차단 가능한 전체 구간을 색상으로 채워 표시합니다."
L["Spell Casters"] = "시전자"
L["Spell Icon"] = "주문 아이콘"
L["This option is currently under maintenance"] = "이 설정은 현재 점검 중입니다."
L["This option is only used by the Basic border."] = "이 설정은 기본 테두리에서만 사용됩니다."
L["This option requires a text to be assigned"] = "이 설정을 사용하려면 글자가 할당되어 있어야 합니다."
L["This option requires an aura or indicator to be assigned"] = "이 설정을 사용하려면 오라 또는 표시기가 할당되어 있어야 합니다."
L["This will display ALL of your debuffs on enemy nameplates, rather than only the important ones."] = "주요 약화 효과뿐만 아니라, 내가 부여한 모든 약화 효과를 적 이름표에 표시합니다."
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important. Overrides the Interruptible Cast colour; your interrupt being on cooldown still takes priority."] = "적이 '중요' 주문을 시전할 때 시전 바를 지정된 중요 색상으로 강조합니다. 차단 가능 시전 색상보다 우선 적용되며, 내 차단기가 재사용 대기 중일 때의 색상이 가장 최우선합니다."
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important."] = "적이 '중요' 주문을 시전할 때 시전 바를 지정된 중요 색상으로 강조합니다."
L["Toggle visibility of enemy pet nameplates."] = "적 소환수 이름표 표시를 전환합니다."
L["Uses the Hover Effect color and opacity. Set to None for the flat hover highlight."] = "마우스오버 효과의 색상과 불투명도를 사용합니다. 단색 마우스오버 강조로 설정하려면 '없음'을 선택하세요."
L["Wrap"] = "자동 줄 바꿈"
L["Width %"] = "너비 %"
L["When disabled, EUI relinquishes full control of friendly player nameplates to Blizzard. Use Blizzard's own Nameplate settings (Esc > Options > Nameplates) to control them."] = "비활성화 시 아군 플레이어 이름표의 제어권을 블리자드 기본 UI로 되돌립니다. 블리자드 이름표 설정(ESC > 설정 > 이름표)에서 설정할 수 있습니다."
L["When enabled, nameplates stack vertically instead of overlapping."] = "활성화 시 이름표가 서로 겹치지 않고 상하로 정렬됩니다."
L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "차단 기술이 현재 재사용 대기 중이지만 적의 시전이 끝나기 전에 돌아오는 경우, 차단이 가능한 시전 바 구간을 별도 색상으로 표시합니다. 차단이 준비되는 즉시 색상이 복원됩니다."
L["Widens the clickable hitbox of enemy nameplates. 100% = matches bar width. Increase to make nameplates easier to click."] = "적 이름표의 클릭 판정 영역(히트박스) 너비를 넓힙니다. 100%는 바 너비와 동일하며, 값을 높일수록 이름표를 클릭하기 수월해집니다."
-- add Nameplates Popup (이름표 팝업)
