L["Lets long text wrap onto a second line instead of being cut off."] = "긴 텍스트가 잘리지 않도록 다음 줄로 자동 줄바꿈합니다."
L["Maximum width the text can fill before it truncates, as a percentage of the bar."] = "텍스트가 말줄임(...) 처리되기 전까지 표시할 수 있는 최대 너비입니다 (바 너비 대비 %)."
