L["This feature runs continuous range checks against every visible enemy nameplate. It is one of the more expensive features in EllesmereUI and can measurably increase CPU usage in crowded areas."] = "이 기능은 화면에 보이는 모든 적 이름표의 사거리를 실시간으로 계속 확인합니다. 시스템 자원을 비교적 많이 소모하는 기능으로, 적이 많은 장소에서는 CPU 사용량이 증가할 수 있습니다."
L["Custom Range"] = "사용자 지정 사거리"
L["Attack-range cutoff used by Out of Range Opacity. Five-yard steps match the available fallback range checks."] = "'사거리 밖 불투명도'가 적용될 사거리 기준입니다. 5야드 단위는 게임 엔진에서 제공하는 사거리 검사 기준에 맞춘 값입니다."
L["Hide Enemy Nameplates out of Combat"] = "비전투 시 적 이름표 숨김"
L["Hide enemy nameplates while you are out of combat; they return the moment combat starts. Drives the same game setting as the Show Enemy Name Plates keybind."] = "비전투 상태일 때 적 이름표를 숨기고, 전투가 시작되면 즉시 다시 표시합니다. 게임 기본 '적 이름표 표시' 단축키와 동일한 설정을 제어합니다."
