L["Force boss buffs into a single large column matched to the frame height."] = "우두머리 강화 효과를 프레임 높이에 맞춘 하나의 큰 세로줄로 강제 표시합니다."
L["Force boss debuffs into a single large column matched to the frame height."] = "우두머리 약화 효과를 프레임 높이에 맞춘 하나의 큰 세로줄로 강제 표시합니다."
L["Force debuffs to the Left of the frame and size them to match the frame height (excluding cast bar). Overrides the Debuffs Location and debuff size settings while enabled."] = "약화 효과를 프레임 왼쪽으로 강제 배치하고 프레임 높이에 맞게 크기를 조정합니다(시전 바 제외). 활성화 시 약화 효과 위치/크기 설정을 재정의합니다."
L["Hide combat indicator preview"] = "전투 표시기 미리보기 숨기기"
L["Leader Indicator"] = "공장(파장) 표시기"
L["None shape requires 3D Art Style"] = "없음 모양은 3D 아트 모양이 필요합니다"
L["Only available in Detached or Inside modes"] = "분리 또는 내부 모드에서만 사용 가능합니다"
L["Only available when Portrait Mode is Detached"] = "초상화 모드가 분리됨일 때만 사용할 수 있습니다."
L["Open Resource & Cast Bars > Cast Bar"] = "자원 및 시전 바 > 시전 바 열기"
L["Overrides the border size from the main frames for this frame only. Border color and texture still follow the main frames."] = "이 프레임에 한해 메인 프레임의 테두리 크기 설정을 무시하고 개별 적용합니다. 테두리 색상과 텍스처는 메인 프레임 설정을 그대로 유지합니다."
L["Overrides the Frame Strata set in the main frames for this frame only. Controls the order that overlapping frames display in; set higher to show above other frames."] = "이 프레임에 한해 메인 프레임의 프레임 레이어 설정을 무시하고 개별 적용합니다. 프레임이 겹칠 때의 표시 순서를 결정하며, 높을수록 다른 프레임보다 위에 표시됩니다."
L["Portrait Mode is set to None"] = "초상화 모드가 없음으로 설정되어 있습니다."
L["Power Colored Fill"] = "자원 색상 채우기"
L["Power Colored Text"] = "자원 색상 글자"
L["Reset all Ellesmere Unit Frames settings to defaults? This cannot be undone."] = "모든 Ellesmere 유닛 프레임 설정을 기본값으로 초기화하시겠습니까? 되돌릴 수 없습니다."
L["Sets a custom width for the cast bar. Set to 0 to match the boss frame width."] = "시전바의 너비를 사용자 지정합니다. 0으로 설정하면 우두머리 프레임 너비와 일치시킵니다."
L["Show Blizzard's private boss-mechanic aura icons on the player frame."] = "플레이어 프레임에 블리자드 비공개 우두머리 메커니즘 오라 아이콘을 표시합니다."
L["Show combat indicator preview"] = "전투 표시기 미리보기 표시"
L["Show Duration (Inside Cog)"] = "지속시간 표시 (톱니 아이콘)"
L["Show duration and stack count text on buff and debuff icons."] = "강화/약화 효과 아이콘에 지속시간과 중첩 수 표시."
L["Show one decimal place on health text: health values like 240.5k and health percent like 77.3%. Power text is unaffected. Off by default."] = "생명력 글자에 소수점 첫째 자리까지 표시합니다. (예: 생명력 수치 240.5k, 생명력 백분율 77.3%) 자원(마력) 글자에는 영향을 주지 않습니다. 기본값은 비활성화입니다."
L["Show player nicknames from supported addons instead of character names on your main frames."] = "주 프레임에 캐릭터 이름 대신 지원되는 애드온의 플레이어 별명을 표시합니다."
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "이 프레임에 메인 프레임의 마우스 오버 강조 테두리를 적용합니다. 비활성화하면 마우스를 올려도 색상이 바뀌지 않습니다. 메인 프레임 자체의 '마우스 오버 테두리 강조' 기능이 꺼져 있다면 작동하지 않습니다."
L["Show the name of who the boss is casting on."] = "우두머리가 시전 중인 대상의 이름을 표시합니다."
L["Shows only crowd-control auras"] = "군중 제어 효과만 표시합니다"
L["Shows only external defensive cooldowns cast on the unit"] = "해당 대상에게 시전된 외부 생존기 재사용 대기시간만 표시합니다"
L["Shows only major defensive cooldowns"] = "주요 생존기 재사용 대기시간만 표시합니다"
L["Shows only the Buffs/Debuffs that appear on Raid Frames"] = "공격대 프레임에 표시되는 강화/약화 효과만 보임"
L["Shows only the Buffs/Debuffs you apply"] = "내가 적용한 강화/약화 효과만 보임"
L["Shows only the spells Blizzard flags as Important"] = "블리자드가 중요로 표시한 주문만 보임"
L["Shows the raid target marker icon on boss frames."] = "우두머리 프레임에 공격대 징표 아이콘을 표시합니다."
L["Simple Buff Display"] = "단순 강화 효과 표시"
L["Simple Buff Position"] = "단순 강화 효과 위치"
L["Simple Debuff Display"] = "단순 약화 효과 표시"
L["Simple Debuff Position"] = "단순 약화 효과 위치"
L["This option is only available for formats that display a percentage."] = "이 설정은 백분율을 표시하는 형식에서만 사용할 수 있습니다."
L["This option is only available when Portrait Mode is Detached."] = "이 설정은 초상화 모드가 분리됨일 때만 사용 가능합니다."
L["This option requires a Class Icon other than None."] = "이 설정은 직업 아이콘이 없음 이외로 설정되어야 합니다."
L["This option requires a detached position to be active."] = "분리된 위치여야 사용 가능합니다."
L["This option requires a text position other than none."] = "글자 위치를 없음 외로 설정해야 합니다."
L["This option requires a text selection other than none."] = "이 설정을 사용하려면 없음 이외의 글자 선택이 필요합니다."
L["This option requires Class Resource to be set to Modern."] = "이 설정은 직업 자원이 모던으로 설정되어야 합니다."
L["This option requires Portrait Mode to be set to Detached."] = "이 설정은 초상화 모드가 분리됨으로 설정되어야 합니다."
L["When enabled, debuff icons keep Blizzard's colored border instead of using the custom border."] = "활성화 시 약화 효과 아이콘이 사용자 정의 테두리 대신 블리자드 기본 색상 테두리를 유지."
L["Shows external defensives cast on you (Pain Suppression, Ironbark, etc.) in its own movable frame; position it via Unlock Mode."] = "나에게 시전된 외부 생존기(고통 억제, 무쇠껍질 등)를 이동 가능한 별도 프레임에 표시합니다. 위치는 잠금해제 모드에서 조정합니다."
L["Which direction new icons extend from the frame's edge."] = "새 아이콘이 프레임 가장자리에서 어느 방향으로 늘어날지 정합니다."
