L["One-time copy of the Raid & Party Frames Buff Manager filters into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "공격대/파티 프레임 강화 효과 관리자 필터를 이 필터 목록으로 1회 복사합니다. 이름이 같은 필터는 덮어쓰기되며, 이후 두 목록은 독립적으로 유지됩니다."
