-- add RaidFrames Tooltip (공격대 프레임 툴팁)
L["Effect indicators show while a tracked buff is present. Absence-based modes are not available in 12.1."] = "효과 표시기는 추적 중인 강화 효과가 있을 때 나타납니다. 없을 때 표시하는 방식은 12.1에서 쓸 수 없습니다."
L["Active while you are not in a group."] = "그룹에 속하지 않았을 때 작동합니다."
L["Active in a PvE party."] = "PvE 파티에서 작동합니다."
L["Active in a PvE raid."] = "PvE 공격대에서 작동합니다."
L["Active in battlegrounds and arenas."] = "전장과 투기장에서 작동합니다."
L["Party frames in arenas and small raids count as Party; Friendly Boss frames count as Raid."] = "투기장과 소규모 공격대의 파티 프레임은 파티로, 우호 우두머리 프레임은 공격대로 칩니다."
L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You, or a filter an indicator shows, show nothing."] = "체크한 표시 필터에 모두 맞는 약화 효과만 표시합니다(해제 유형들은 하나로 칩니다). '플레이어 외 오라'와 '내가 시전함'처럼 서로 반대인 조합이나, 표시기가 보여 주는 필터는 아무것도 표시하지 않습니다."
L["Attached widens each frame by the portrait."] = "붙이기는 초상화만큼 프레임마다 폭을 넓힙니다."
L["This option requires a Border Style other than Solid."] = "이 설정을 사용하려면 테두리 모양이 단색이 아니어야 합니다."
L["Recolors the frame border in the threat color while the unit has aggro instead of drawing a separate border."] = "유닛이 어그로를 획득했을 때 별도의 테두리를 그리지 않고 프레임 테두리를 위협 색상으로 칠합니다."
L["Adds the Default Blizz Frames glow line where the shield meets current health."] = "보호막과 현재 생명력이 만나는 지점에 블리자드 기본 프레임의 반짝임 선을 추가합니다."
L["The glow line is not shown on a vertical fill or with the From Left Edge placement"] = "세로 채우기이거나 왼쪽 끝부터 배치할 때는 반짝임 선이 표시되지 않습니다"
L["Recolors the frame border in the dispel type color while a debuff of that type is shown."] = "그 유형의 약화 효과가 표시되는 동안 프레임 테두리를 해제 유형 색상으로 칠합니다."
L["Highest group size that uses this layout."] = "이 배치를 쓰는 가장 큰 그룹 인원입니다."
L["Group size at which this layout takes over from the 20 Man layout."] = "20인 배치 대신 이 배치를 쓰기 시작하는 그룹 인원입니다."
L["Group size at which this layout takes over from the 25 Man layout."] = "25인 배치 대신 이 배치를 쓰기 시작하는 그룹 인원입니다."
L["Group size at which this layout takes over from the 30 Man layout."] = "30인 배치 대신 이 배치를 쓰기 시작하는 그룹 인원입니다."
L["FrameSort sets the order while Sort By is FrameSort."] = "정렬 기준이 FrameSort 이면 FrameSort 가 순서를 정합니다."
L["Display separated raid groups in your chosen order."] = "나눈 공격대 그룹을 고른 순서대로 표시합니다."
L["Party Frames switches the party to the stock portrait party frames."] = "파티 프레임은 파티를 블리자드 기본 초상화 파티 프레임으로 바꿉니다."
L["Changing the party frame style requires a UI reload."] = "파티 프레임 모양을 바꾸려면 UI를 다시 불러와야 합니다."
