L["Automatically duplicates the raid's tanks into the Extra Frames group. Shares the 5-frame cap with hotkey picks."] = "공격대의 방어 전담을 추가 프레임 그룹에 자동으로 복제합니다. 단축키로 지정한 인원과 5프레임 한도를 공유합니다."
