L["Class Colored Background"] = "직업 배경 색상"
L["Controls when the tooltip appears as you hover a raid or party frame"] = "공격대 또는 파티 프레임에 마우스를 올렸을 때 툴팁이 표시되는 시점을 제어합니다."
L["Curse"] = "저주"
L["Custom Background Color"] = "사용자 배경 색상"
L["Custom Dynamic Colors: the health bar smoothly blends between three colors you pick -- one for full health (100%), one for half (50%), and one for empty (0%) -- shifting through them as the unit takes damage or is healed."] = "사용자 지정 동적 색상: 생명력 바가 선택한 세 가지 색상(생명력 가득 참(100%), 절반(50%), 고갈(0%)) 사이로 부드럽게 혼합되며, 유닛이 피해를 입거나 치유됨에 따라 색상이 변합니다."
