L["Collapse subgroups that have no members so the remaining groups close ranks. For example, if only groups 1, 2, 3 and 6 have players, they show with no gaps instead of leaving empty space where groups 4 and 5 would be. Real raid frames only."] = "인원이 없는 소그룹을 접어 나머지 그룹을 붙여 표시합니다. 예를 들어 1, 2, 3, 6 그룹에만 인원이 있으면 4, 5 그룹 자리를 비워 두지 않고 붙여서 보여줍니다. 실제 공격대 프레임에만 적용."
L["Custom Colored Background"] = "사용자 색상 배경"
L["Default Blizz Frames uses a fixed placement"] = "블리자드 기본 프레임은 고정 배치를 사용합니다"
L["Hide Buff Tooltips"] = "강화 효과 툴팁 숨김"
L["Hide role icons while you are in combat."] = "전투 중에는 역할 아이콘을 숨깁니다."
L["Hide the tooltip when hovering a buff/HoT icon on a raid or party frame."] = "공격대/파티 프레임의 강화 효과/도트힐 아이콘에 마우스를 올려도 툴팁을 띄우지 않습니다."
