L["Only works for Blizzard's whitelisted healer spell IDs (non-private auras)."] = "블리자드가 허용한 치유 주문 ID(비공개 오라 제외)에만 동작합니다."
L["Override Active:"] = "재정의 활성:"
L["Render the name and health text above buff and debuff icons."] = "이름/체력 글자를 강화 효과/약화 효과 아이콘 위에 그립니다."
L["Show Above Icons"] = "아이콘 위에 표시"
L["Show the leader/assistant icon while you are in combat. Disable to hide it during combat."] = "전투 중에도 공대장/부공장 아이콘을 표시합니다. 끄면 전투 중 숨김."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar; on Default Blizz Frames the glow line stays pinned at the right edge."] = "빈 체력을 넘어서는 보호막을 현재 체력 위로 겹쳐 표시합니다. 끄면 보호막은 빈 부분만 채우고, 블리자드 기본 프레임에서는 광택 선이 오른쪽 끝에 고정됩니다."
L["Shows only the buffs you apply"] = "내가 건 강화 효과만 표시"
L["Threshold Sound"] = "임계값 효과음"
