L["Shows the Power bar while your focus is below full, even when its Visibility setting hides it."] = "가시성 설정에 의해 숨겨져 있더라도 집중이 최대치 미만일 때 자원 바를 표시합니다."
L["Shows the Power bar while your mana is below full, even when its Visibility setting hides it."] = "가시성 설정에 의해 숨겨져 있더라도 마나가 최대치 미만일 때 자원 바를 표시합니다."
L["Shows the Power bar, or your shapeshifted mana bar, while your mana is below full, even when its Visibility setting hides it."] = "가시성 설정에 의해 숨겨져 있더라도 마나가 최대치 미만일 때 자원 바(또는 변신 시 마나 바)를 표시합니다."
L["Also Show Below"] = "지정 시간 미만일 때도 표시"
L["With Show When Missing, also show the buff for its last seconds. Buffs whose timers are hidden from addons in instances stay hidden there."] = "'없을 때 표시' 사용 시, 효과 만료 직전 지정한 잔여 시간 동안에도 표시합니다. 인스턴스 내부에서 지속시간 정보가 숨겨진 효과는 그대로 숨김 처리됩니다."
L["Seconds left when the buff shows again (0 = off)"] = "효과를 다시 표시할 잔여 시간(초, 0 = 끔)"
L["Requires Show When Missing"] = "없을 때 표시 필요"
L["How many icons to show on the base row (the row that fills first and that Row Growth keeps in place). The rest go on the second row."] = "첫 번째 기본 행에 표시할 아이콘 개수입니다 (먼저 채워지는 기준 행). 초과하는 아이콘은 두 번째 행에 배치됩니다."
L["Offsets the base row's icon size in pixels from Icon Scale. The second row keeps the base size."] = "첫 번째 기본 행의 아이콘 크기를 '아이콘 배율' 기준에서 픽셀 단위로 미세 조정합니다. 두 번째 행은 기본 크기를 유지합니다."
L["Offsets the second row's icon size in pixels from Icon Scale. The base row keeps the base size."] = "두 번째 행의 아이콘 크기를 '아이콘 배율' 기준에서 픽셀 단위로 미세 조정합니다. 첫 번째 기본 행은 기본 크기를 유지합니다."
L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected."] = "추적 중인 아이템에 행동 단축바와 동일한 제작 품질 등급 아이콘을 표시합니다. 제작 품질이 없는 아이템은 영향을 받지 않습니다."
L["Show the charge and stack counters on this bar's icons."] = "이 바의 아이콘에 충전 횟수 및 중첩 수를 표시합니다."
L["Keep keybind text identical when your action bar swaps -- rogue stealth, druid forms, skyriding. Also covers conditional macros like \"/cast [bonusbar:1] Backstab; Shadow Dance\", where the key would otherwise jump to whichever branch is live.\n\nThe key then only changes when you actually move the ability or rebind it.\n\nOn by default. Applies to every CDM bar at once."] = "도적 은신, 드루이드 변신, 하늘비행 등으로 행동 단축바가 교체되어도 단축키 글자를 일정하게 유지합니다. \"/시전 [bonusbar:1] 기습; 어둠의 춤\"처럼 현재 활성화된 상태에 따라 단축키가 바뀌는 조건부 매크로도 방지합니다.\n\n기술을 다른 슬롯으로 옮기거나 단축키를 직접 변경할 때만 갱신됩니다.\n\n기본값은 켜짐이며 모든 CDM 바에 일괄 적용됩니다."
