-- add CooldownManager Tooltip (재사용 대기시간 관리자 툴팁)
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI가 이 변경을 편집 모드 레이아웃에 저장하지 못해 직접 설정해야 합니다. 이 작업 중에는 재사용 대기시간 관리자를 꺼야 합니다. 관리자가 블리자드 재사용 대기시간 표시창을 숨기는데, 숨겨진 창은 편집 모드에서 고를 수 없기 때문입니다.\n\n"
L["This will keep appearing each login until the layout is correct."] = "레이아웃이 맞춰질 때까지 접속할 때마다 계속 나타납니다."
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "이 바에는 설정에 추가 바 위치 조정(X %1$s, Y %2$s)이 있습니다. 잠금 해제 모드에서는 기본 위치를 보여 주고, 끝내면 조정값이 다시 적용됩니다."
L["Show a tracked buff in this slot while it is active."] = "추적 중인 강화 효과가 활성화된 동안 이 칸에 표시합니다."
L["You're on this spec."] = "지금 이 전문화입니다."
L["This spec doesn't have this spell."] = "이 전문화에는 이 주문이 없습니다."
L["This is the spec you're syncing from -- it's always included."] = "동기화의 기준 전문화입니다 - 항상 포함됩니다."
L["How extra columns grow when the second column appears or disappears. Grow Right keeps the left column in place, Grow Left keeps the right column in place, Grow Centered keeps the bar centered."] = "두 번째 열이 생기거나 없어질 때 열이 늘어나는 방향입니다. 오른쪽 확장은 왼쪽 열을, 왼쪽 확장은 오른쪽 열을 제자리에 두고, 가운데 확장은 바를 가운데에 둡니다."
L["Not available while a spell on this bar uses a Cooldown State Shift Icons setting"] = "이 바의 주문이 재사용 대기 상태 아이콘 이동 설정을 쓰는 동안에는 쓸 수 없습니다"
L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "현재 전문화에 이 그룹의 바가 없으면, 그룹에 고정된 요소를 제자리에 두되 바 하나 높이만큼 위나 아래로 옮겨 빈 자리를 메웁니다 (톱니바퀴의 추가 Y 위치로 조정)."
L["This replaces %d existing value(s) for this setting across your specs."] = "모든 전문화에서 이 설정의 기존 값 %d개를 바꿉니다."
L["This replaces %d existing value(s) for this setting on this bar."] = "이 바에서 이 설정의 기존 값 %d개를 바꿉니다."
L["Already assigned to "] = "이미 할당됨: "
L["Already on "] = "이미 등록됨: "
L["Always Show Buffs"] = "강화 효과 항상 표시"
L["Apply Border Size to all Bars"] = "테두리 크기 모든 바에 적용"
L["Apply Duration Text to all Bars"] = "지속시간 글자 모든 바에 적용"
L["Apply Icon Shape to all Bars"] = "아이콘 모양 모든 바에 적용"
L["Apply Icon Spacing to all Bars"] = "아이콘 간격 모든 바에 적용"
L["Apply Name Text to all Bars"] = "이름 글자 모든 바에 적용"
L["Apply Pandemic Glow settings to all (Nameplates, CDM Bars)"] = "팬데믹 반짝임 설정을 모든 (이름표, CDM 바)에 적용"
L["Apply Stacks Text to all Bars"] = "중첩 글자 모든 바에 적용"
L["Apply the selected preset's style to every bar in this group."] = "선택한 프리셋의 스타일을 이 그룹의 모든 바에 적용합니다."
L["Apply the selected preset's style to this bar."] = "선택한 프리셋의 스타일을 이 바에 적용합니다."
L["Apply this pandemic glow to Nameplates, all CDM bars, and other tracking bars. A surface that can't show a style uses its closest match."] = "이 팬데믹 반짝임 효과를 이름표, 모든 CDM 바 및 기타 추적 바에 적용합니다. 해당 모양을 표시할 수 없는 영역은 가장 유사한 모양로 대체됩니다."
L["Apply this pandemic glow to Nameplates, all CDM bars, and tracking bars. A surface that can't show a style uses its closest match."] = "이 팬데믹 반짝임 효과를 이름표, 모든 CDM 바 및 추적 바에 적용합니다. 해당 모양을 표시할 수 없는 영역은 가장 유사한 모양으로 대체됩니다."
L["Apply Visibility Options to all Bars"] = "표시 설정 모든 바에 적용"
L["Automatically add a bar to this group for every spell in Blizzard's Tracked Bars section, now and whenever a new one appears."] = "현재 블리자드 기본 '추적 중인 바' 섹션에 있는 모든 주문과 향후 새로 나타나는 모든 주문에 대해 이 그룹에 바를 자동으로 추가합니다."
L["CDM bar customization, action bar glows, and buff bars."] = "CDM 바 사용자화, 행동 단축바 반짝임, 강화 효과 바."
L["Custom Top Row Count"] = "사용자 지정 상단 행 개수"
L["Disable CD Ready glow first"] = "먼저 '재사용 준비 시 반짝임'을 비활성화하세요"
L["Disable Proc Glow first"] = "먼저 '발동 시 반짝임'을 비활성화하세요"
L["Drag to Reorder. Click to add custom glows, active/cooldown state effects and more."] = "드래그하여 순서 변경, 클릭하여 사용자 지정 반짝임 효과, 활성화/재사용 대기시간 상태 효과 등을 추가합니다."
L["Force-hide Blizzard's Assisted Combat Highlight (rotation helper glow) on all CDM bars, even if enabled in Blizzard's Combat settings."] = "기본 전투 설정에서 활성화되어 있어도 모든 CDM 바에서 기본 보조 전투 강조(로테이션 도우미 반짝임)를 강제로 숨깁니다."
L["Group 2 or more Tracking Bars"] = "추적 바 2개 이상 그룹화"
L["Group Tracking Bars"] = "그룹 추적 바"
L["Hide the brief GCD swipe that flashes when you cast any spell. The actual ability cooldown swipe still shows."] = "주문 시전 시 잠깐 표시되는 GCD 회전 효과를 숨깁니다. 실제 능력 재사용 대기시간 회전 효과는 그대로 표시됩니다."
L["How many icons to show on the top row. The rest go on the bottom row."] = "상단 행에 표시할 아이콘 수. 나머지는 하단 행으로 이동합니다."
L["Item Count"] = "아이템 수량"
L["Max Stacks"] = "최대 중첩"
L["Max Stacks Glow"] = "최대 중첩 반짝임"
L["No buffs assigned. Right click a button in the preview to assign buffs."] = "할당된 강화 효과가 없습니다. 미리보기에서 버튼을 우클릭해 강화 효과를 할당하세요."
L["Only preset or custom buff bars can be added to all specs"] = "프리셋 또는 사용자 지정 강화 효과 바만 모든 전문화에 추가할 수 있습니다"
L["Only show this bar while the tracked buff/cooldown is active. Turn off to keep an empty bar on screen at all times."] = "추적 중인 강화 효과나 재사용 대기시간이 활성화되어 있을 때만 이 바를 표시합니다. 설정을 끄면 항상 화면에 빈 바가 유지됩니다."
L["Recolor the countdown text below Threshold Seconds."] = "남은 시간이 '임계값 초' 미만일 때 초읽기 글자 색상을 변경합니다."
L["Rename this group; leave blank for the default name."] = "이 그룹의 이름을 바꿉니다. 기본 이름을 사용하려면 비워 두십시오."
L["Save this bar's current style as a new preset."] = "이 바의 현재 스타일을 새 프리셋으로 저장합니다."
L["Seconds remaining below which Threshold Color and Threshold Decimals apply (0 = off)."] = "남은 시간이 '임계값 초' 미만일 때 임계값 색상과 소수점 표시가 적용됩니다 (0 = 끔)."
L["Show a 1-decimal countdown (2.7) below Threshold Seconds."] = "남은 시간이 '임계값 초' 미만일 때 소수점 한 자리까지 초읽기(2.7)를 표시합니다."
L["Show a 1-decimal countdown on presets and custom spell/item IDs when under the cog's Seconds Left threshold -- their active state on cooldown/utility bars, their buff duration on buff bars (both are hardcoded, so the remaining time is exact)."] = "톱니바퀴의 남은 시간 임계값(초) 미만일 때 프리셋 및 사용자 지정 주문/아이템 ID에 소수점 한 자리까지 초읽기를 표시합니다 (핵심 능력/보조 능력 바의 강화 효과/오라 발동 상태 및 강화 효과 바의 강화 효과 지속시간에 적용되며, 둘 다 고정 코드로 처리되어 남은 시간이 정확합니다)."
L["Show a glow on icons when the remaining duration is in the pandemic window (last 30%)"] = "남은 지속시간이 팬데믹 구간(마지막 30%)일 때 아이콘에 반짝임을 표시합니다"
L["Show a glow on the bar when the remaining duration is in the pandemic window (last 30%)"] = "남은 지속시간이 팬데믹 구간(마지막 30%)일 때 바에 반짝임을 표시합니다"
L["Show equipped trinkets even if they don't have an on-use effect."] = "사용 효과가 없어도 장착한 장신구를 표시합니다."
L["Show Keybind"] = "단축키 표시"
L["Show the FocusKick bar on your current target's nameplate instead of your focus target's nameplate."] = "주시 대상의 이름표 대신 현재 대상의 이름표에 FocusKick 바를 표시합니다."
L["Show Tooltip on Hover"] = "마우스 오버 시 툴팁 표시"
L["Stack Threshold"] = "중첩 임계값"
L["Thickness of any Pixel Glow assigned to this bar's buttons. Assign glows by right-clicking an icon in the preview."] = "이 바 버튼에 지정된 픽셀 반짝임의 두께입니다. 미리보기에서 아이콘을 우클릭해 반짝임을 지정합니다."
L["This option is not available for custom shaped icons"] = "사용자 지정 모양 아이콘에는 이 설정을 사용할 수 없습니다"
L["This option requires a Duration Text position other than None"] = "이 설정은 지속시간 글자 위치가 '없음'이 아니어야 합니다"
L["This option requires a Name Text position other than None"] = "이 설정은 이름 글자 위치가 '없음'이 아니어야 합니다"
L["This option requires a Stacks Text position other than None"] = "이 설정은 중첩 글자 위치가 '없음'이 아니어야 합니다"
L["This option requires exactly 2 rows"] = "정확히 2줄이 필요합니다"
L["This option requires Fill Color to be set to Custom"] = "이 설정은 채우기 색상이 '사용자 지정'으로 설정되어야 합니다"
L["This spell is already being used on "] = "이 주문은 이미 다음에서 사용 중: "
L["This will change the color of your bar if you have more than your chosen number of stacks"] = "선택한 중첩 수보다 많을 때 바 색상이 변경됩니다"
L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "주시 대상을 지정하지 않았을 때 신화+에서 시전자/소형 우두머리 몹 아래에 \"FOCUS\"를 표시합니다. 차단기가 없는 전문화에서는 비활성화됩니다."
L["When you press an ability's keybind, show the action button's \"pushed down\" look on its icon on this bar -- even while the ability is on cooldown."] = "스킬 단축키를 누르면, 해당 스킬이 쿨타임 중이더라도 이 바에 있는 아이콘이 '눌린 상태'로 보이게 합니다."
L["When your bags have none of one potion type, its icon swaps to track the other type."] = "가방에 한쪽 물약이 하나도 없으면 아이콘이 다른 쪽 물약 추적으로 바뀝니다."
