L["This will disable EllesmereUI Tracking Bars and show Blizzard's default Tracked Bars display instead."] = "EllesmereUI 추적 바를 비활성화하고 대신 기본 추적 바를 표시합니다."
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Custom bars are not affected. Continue?"] = "현재 전문화의 모든 기본 바 주문 할당을 기본 CDM 레이아웃에 맞춰 초기화합니다. 사용자 지정 바는 영향받지 않습니다. 계속하시겠습니까?"
L["Your Edit Mode layout is a Blizzard preset which cannot be modified by addons. Please switch to a custom Edit Mode layout so EllesmereUI can manage your CDM settings.\n\nOpen Edit Mode to create or select a custom layout."] = "현재 편집 모드 레이아웃은 애드온이 수정할 수 없는 블리자드 프리셋입니다. EllesmereUI가 CDM 설정을 관리하려면 사용자 지정 편집 모드 레이아웃으로 전환하세요.\n\n편집 모드를 열어 사용자 지정 레이아웃을 만들거나 선택하세요."
