L["Uncheck a spec to remove it from the sync. Removed specs keep their current trinkets, pots, racials & buff presets."] = "동기화에서 뺄 전문화는 체크를 해제하세요. 제외된 전문화는 현재 장신구/물약/종족 특성/강화 효과 프리셋을 유지합니다."
