L["Bar-style class resources (Insanity, Maelstrom, Astral Power, etc.) use Blizzard's default player frame bar artwork instead of the texture above."] = "바 형태의 직업 자원(광기, 소용돌이, 천공의 힘 등)에 위 텍스처 대신 블리자드 기본 플레이어 프레임 바 이미지를 사용합니다."
L["Blizzard Atlas Texture"] = "블리자드 기본 텍스처"
L["Blizzard's bar artwork is never recolored, so fill color modes and threshold colors will not tint the bar while this is enabled. To keep threshold colors visible, use Recolor Text Instead."] = "블리자드 바 이미지는 색상 변경이 지원되지 않으므로, 이 설정이 활성화되어 있으면 채우기 색상 모드 및 임계값 색상이 바에 적용되지 않습니다. 임계값 색상을 표시하려면 '바 대신 글자 색상 변경' 설정을 사용하세요."
L["Show the bar full of its fill color while no global cooldown is running, instead of the background color."] = "전역 재사용 대기시간(GCD)이 돌지 않는 동안 바를 배경색 대신 채우기 색상으로 가득 채워 표시합니다."
