-- add ResourceBars Tooltip (자원 바 툴팁)
L["One bar per weapon that can swing, each filling over the time to the next auto attack."] = "자동 공격이 가능한 무기마다 바가 하나씩 생성되며, 다음 자동 공격까지 남은 시간에 맞춰 채워집니다."
L["Height of each weapon row."] = "각 무기 줄의 높이입니다."
L["Gap between the weapon rows."] = "무기 줄 사이의 간격입니다."
L["Hide the bar while no swing is running."] = "자동 공격이 진행 중이 아닐 때 바를 숨깁니다."
L["Show an idle row full of its fill color instead of the background color."] = "대기 중인 줄을 배경 색상 대신 채우기 색상으로 가득 채워 표시합니다."
L["Start each row full and drain it as the swing timer elapses, instead of filling it up."] = "줄을 채워 나가는 대신 가득 찬 상태에서 시작해 자동 공격 타이머가 흐를수록 줄어들게 합니다."
L["Show a small glowing spark that moves along the leading edge of the fill while a swing is running."] = "자동 공격이 진행되는 동안 채워지는 끝을 따라 움직이는 작은 불꽃을 표시합니다."
L["Choose which weapons get a swing row. A row also needs a weapon in that slot."] = "자동 공격 바를 표시할 무기를 선택합니다. 해당 슬롯에 무기를 장착하고 있어야 바가 표시됩니다."
L["Show the off hand as a spark on the Main Hand bar instead of its own row."] = "보조 장비를 따로 줄로 표시하지 않고 주 장비 바 위의 불꽃으로 표시합니다."
L["Show the seconds left to the next swing on each row."] = "각 무기 줄에 다음 자동 공격까지 남은 시간(초)을 표시합니다."
L["Tag each row with its weapon slot: MH (Main Hand), OH (Off Hand), R (Ranged)."] = "각 줄에 무기 슬롯 약어를 표시합니다: MH (주 장비), OH (보조 장비), R (원거리)."
L["Dim a row and paint its text red while the current target is out of that weapon's auto attack range."] = "현재 대상이 해당 무기의 자동 공격 사거리 밖에 있을 때 줄을 흐리게 하고 글자를 붉은색으로 표시합니다."
L["While an on-next-swing attack is queued, the Main Hand and Off Hand rows take its color and show its name (Heroic Strike, Maul and Raptor Strike share one color, Cleave has its own)."] = "다음 자동 공격 때 발동하는 공격이 예약되어 있으면 주 장비와 보조 장비 줄이 그 색을 띠고 이름을 표시합니다 (영웅의 일격, 후려치기, 랩터의 일격은 같은 색, 회전베기는 따로)."
L["Opacity of a row whose target is out of range."] = "대상이 사거리 밖에 있을 때 무기 줄의 불투명도입니다."
L["Current Spec is affected by Threshold & Hash Lines."] = "현재 전문화에 임계값 및 기준선이 적용됩니다."
L["Current Spec is not affected by Threshold & Hash Lines."] = "현재 전문화에는 임계값 및 기준선이 적용되지 않습니다."
L["Thresholds have their own per-spec system and can't be edited while editing a spec group"] = "임계값은 전문화별로 따로 관리되므로 전문화 그룹을 편집하는 동안에는 변경할 수 없습니다"
L["Tracking it also makes the fill show Ignore Pain alone; without it the fill shows your total absorb, so other shields can add to it."] = "이것을 추적하면 채우기에 고통 감내만 표시됩니다. 추적하지 않으면 채우기에 전체 흡수량이 표시되어 다른 보호막도 더해질 수 있습니다."
L["Shows Sweeping Strikes charges on the resource bar; Unit Frames and the personal Nameplate show them regardless."] = "자원 바에 휩쓸기 일격 충전을 표시합니다. 유닛 프레임과 개인 이름표에는 이 설정과 관계없이 표시됩니다."
L["Enable the Threshold toggle to use these options."] = "이 설정을 사용하려면 '임계값'을 활성화하세요."
L["Whirlwind and Sweeping Strikes thresholds only support the 'From' direction."] = "소용돌이와 휩쓸기 일격 임계값은 '이상' 방향만 지원합니다."
L["Always on for Whirlwind and Sweeping Strikes charges: range coloring at/above the threshold is the only way these bars can display thresholds."] = "소용돌이와 휩쓸기 일격 충전에서는 항상 활성화됩니다. 해당 바는 임계값 이상 구간의 색상 지정을 통해서만 임계값을 표시할 수 있습니다."
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "'이상' 방향에서만 사용할 수 있습니다 - 임계값 이상의 구슬/조각을 강조합니다."
L["Replaces the class resource bar with Blizzard's own class resource frame, such as Holy Power, Combo Points, Chi, Soul Shards, Arcane Charges, Essence or Runes."] = "직업 자원 바를 블리자드 기본 직업 자원 프레임(신성한 힘, 연계 점수, 기, 영혼의 조각, 비전 충전물, 정수, 룬 등)으로 대체합니다."
L["This option can't be used while the Unit Frames class resource is set to Blizzard."] = "유닛 프레임의 직업 자원이 '블리자드'로 설정되어 있으면 이 설정을 사용할 수 없습니다."
L["This option is not available on this client."] = "현재 클라이언트 버전에서는 지원되지 않는 설정입니다."
L["This option can't be used while the Personal Resource Display hides the player frame's class resource."] = "개인 자원 표시가 플레이어 프레임의 직업 자원을 숨기도록 설정되어 있으면 이 설정을 사용할 수 없습니다."
L["This option requires a class resource that Blizzard shows as its own frame, such as Holy Power, Combo Points, Chi, Soul Shards, Arcane Charges, Essence or Runes."] = "이 설정을 사용하려면 블리자드가 별도 프레임으로 제공하는 직업 자원(신성한 힘, 연계 점수, 기, 영혼의 조각, 비전 충전물, 정수, 룬 등)이 있어야 합니다."
L["This option can't be used while you have the Power Bar Height Matched in the Unlock Mode."] = "잠금 해제 모드에서 '자원 바 높이 맞춤'이 활성화되어 있으면 이 설정을 사용할 수 없습니다."
L["Draws one frame around the resource bars instead of one per bar."] = "바마다 테두리를 따로 그리지 않고 자원 바 전체를 감싸는 단일 테두리를 표시합니다."
L["This option requires at least two resource bars to be shown."] = "이 설정을 사용하려면 자원 바가 2개 이상 표시되어야 합니다."
L["This option requires the resource bars to share one orientation."] = "이 설정을 사용하려면 자원 바들의 방향이 같아야 합니다."
L["This option requires the resource bars to be width matched to each other or to have matching widths."] = "이 설정을 사용하려면 자원 바들의 너비가 서로 맞춰져 있거나 같아야 합니다."
L["Shows a countdown to the Arcane Soul window over the last seconds of Arcane Surge, then the time left inside it. Sunfury Arcane Mages only."] = "비전 쇄도의 마지막 몇 초 동안 비전 영혼 구간까지의 초읽기를, 그다음에는 그 안에서 남은 시간을 표시합니다. 성난태양 비전 마법사 전용입니다."
L["Seconds of Arcane Surge left when the countdown appears. Always in seconds, including in GCD mode."] = "초읽기가 나타날 때 남은 비전 쇄도 시간(초)입니다. 전역 재사용 대기시간 방식에서도 항상 초 단위입니다."
L["Seconds counts the time down in tenths. GCD Count counts whole global cooldowns instead, so inside Arcane Soul it reads as the number of Arcane Barrages that still fit, ending on a coloured LAST. Seconds + GCD in Soul mixes the two: tenths counting down to the window, Barrage count once it opens."] = "'초'는 0.1초 단위로 시간을 표시합니다. '전역 재사용 대기시간 횟수'는 전역 재사용 대기시간(GCD) 단위로 세므로, 비전 영혼 구간 동안 남은 비전 탄막 시전 가능 횟수로 표시되며 마지막 탄막은 색상이 강조된 'LAST'로 표시됩니다. '초 + 영혼 안에서 전역 재사용 대기시간'은 두 방식을 조합하여, 비전 영혼 이전에는 0.1초 단위 초읽기로, 진입 후에는 탄막 횟수로 표시합니다."
L["Appends your latency in milliseconds to the cast timer, e.g. 1.8 (42ms)."] = "시전 시간에 지연 시간(밀리초)을 덧붙입니다. 예: 1.8 (42ms)."
L["Apply Border to all Bars"] = "테두리 모든 바에 적용"
L["Apply Opacity to all Bars"] = "투명도 모든 바에 적용"
L["Changes the cast bar color based on the current empower stage. Colors transition from red (stage 1) through yellow to green (max stage)."] = "현재 강화 단계에 따라 시전 바 색상을 변경합니다. 빨강(1단계) → 노랑 → 초록(최대 단계)로 전환됩니다."
L["Creates a class resource bar for Ignore Pain tracking. To see stack text, you must have Ignore Pain tracked in your Blizzard CDM \"Tracked Buffs\" or \"Tracked Bars\" section."] = "고통 감내 추적용 직업 자원 바를 생성합니다. 중첩 수치를 표시하려면 블리자드 재사용 대기시간 관리자(CDM)의 \"추적 강화 효과\" 또는 \"추적 바\" 항목에서 고통 감내를 추적하고 있어야 합니다."
L["Draws a hash line that resets to the right edge when you cast Ignore Pain and slides left as the buff runs out."] = "고통 감내를 시전할 때 오른쪽 끝으로 재설정되고, 지속시간이 소모됨에 따라 왼쪽으로 이동하는 기준선을 표시합니다."
L["Enable the toggle to set a custom gap color"] = "이 설정을 활성화하여 바 간격 색상을 사용자 지정합니다."
L["Enable/Disable per Spec"] = "전문화별 활성화/비활성화"
L["Guardian Druid Ironfur Bar"] = "수호 드루이드 무쇠가죽 바"
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "블리자드 활력 HUD가 표시되는 하늘비행 탈것에 탑승 중일 때 이 요소를 숨깁니다."
L["Highlights the final damage tick. Requires a supported channeled spell."] = "마지막 피해 틱을 강조 표시합니다. 지원되는 정신 집중 주문에만 적용됩니다."
L["Keep the GCD bar visible (sitting empty) when no global cooldown is running, instead of hiding it."] = "전역 재사용 대기시간이 돌지 않을 때도 바를 숨기지 않고 빈 상태로 계속 표시합니다."
L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "즉시 시전 기술에만 GCD 바를 표시합니다. 일반 시전이나 정신 집중 주문을 사용할 때는 바가 숨겨집니다 (시전 바에서 이미 진행 상황이 표시됩니다)."
L["Only show the GCD bar while in a dungeon, raid, arena or battleground."] = "던전, 공격대, 투기장 또는 전장에 있을 때만 GCD 바를 표시합니다."
L["Player Cast Bar"] = "플레이어 시전 바"
L["Power Colored"] = "자원 색상"
L["Replaces the class resource bar with an Ignore Pain tracker: the fill shows your current absorb amount scaled against your maximum health, and the bar text shows the absorb value."] = "직업 자원 바를 고통 감내 추적기로 대체합니다. 채우기 진행도는 최대 생명력 대비 현재 흡수량을 나타내며, 바 글자에는 흡수 수치가 표시됩니다."
L["Replaces the class resource bar with an Ironfur tracker. Each Ironfur cast adds a hash line that slides from right to left as its buff decays. Duration is talent-aware (Ursoc's Endurance and Guardian of Elune)."] = "직업 자원 바를 무쇠가죽 추적기로 대체합니다. 무쇠가죽을 시전할 때마다 눈금선이 하나씩 추가되며, 효과 지속시간이 소모됨에 따라 오른쪽에서 왼쪽으로 이동합니다. 지속시간은 특성(우르속의 인내력, 엘룬의 수호자)이 자동 반영됩니다."
L["Requires Enhancement Shaman with Class Resource enabled."] = "직업 자원이 활성화된 고양 주술사가 필요합니다."
L["Resource Text"] = "자원 글자"
L["Select a class above"] = "위에서 직업을 선택하세요"
L["Shifts any elements anchored to the class resource bar up or down to offset the missing class resource."] = "직업 자원 바에 고정된 요소들을 위아래로 옮겨 없는 직업 자원만큼 보정합니다."
L["Shifts any elements anchored to the power bar up or down to offset the missing power bar. Applies both when the Power Bar is disabled and for specs that have no power (for example, Beast Mastery and Marksmanship Hunters, whose Focus shows as the class resource bar)."] = "자원 바에 고정된 요소를 위/아래로 이동해 비활성화된 자원 바의 공간을 보정합니다. 자원 바를 껐을 때와, 별도 마나/분노가 없는 전문화(예: 집중이 직업 자원 바로 표시되는 야수 및 사격 사냥꾼) 모두에 적용됩니다."
L["Show a small glowing spark that moves along the leading edge of the fill."] = "바가 차오르는 앞쪽 가장자리를 따라 이동하는 작은 불꽃을 표시합니다."
L["Shows a bar that fills over the global cooldown."] = "전역 재사용 대기시간(GCD) 동안 차오르는 바를 표시합니다."
L["Shows a colored overlay at the end of the cast bar representing your network latency for each spell. Helps you time spell queuing."] = "시전 바 끝에 주문별 네트워크 지연을 나타내는 색상 오버레이를 표시합니다. 주문 예약 타이밍에 도움이 됩니다."
L["Shows elapsed / total duration (e.g. 0.4 / 2.0) instead of counting down from the total."] = "전체 시간에서 줄어드는 대신 경과/전체 시간(예: 0.4 / 2.0)을 표시합니다."
L["Shows tick marks on channeled spells. Only supported spells are shown, request missing spells on Discord."] = "정신 집중 주문에 틱 구분선을 표시합니다. 지원되는 주문에만 표시되며, 누락된 주문은 디스코드에 요청해 주세요."
L["Start the bar full and drain it as the global cooldown elapses, instead of filling it up."] = "바를 가득 찬 상태로 시작하여 전역 재사용 대기시간이 경과함에 따라 차오르는 대신 줄어들게 합니다."
L["this bar"] = "이 바"
L["This option can't be used while Expand Power Bar if No Resource is enabled."] = "'직업 자원 없을 때 자원 바 확장'이 활성화되어 있는 동안에는 이 설정을 사용할 수 없습니다."
L["This option can't be used while Shift Elements if No Resource is enabled."] = "'자원 없을 때 요소 이동'이 활성화되어 있는 동안에는 이 설정을 사용할 수 없습니다."
L["Threshold Color"] = "임계값 색상"
L["Tick Markers"] = "눈금 표시"
L["When enabled, BM and MM specs show Focus as the standard power bar instead of a class resource bar."] = "활성화 시 야수 및 사격 전문화가 집중을 직업 자원 바 대신 기본 자원 바로 표시합니다."
L["When your spec has no class resource, automatically adds the class resource height to the power bar. Automatically disabled when Power Bar height is matched to another element."] = "전문화에 별도 직업 자원이 없을 때 직업 자원 바의 높이만큼 자원 바 높이를 자동으로 늘립니다. 자원 바 높이가 다른 요소와 맞춰져 있을 때는 자동으로 비활성화됩니다."
L["Whenever not airborne on a skyriding mount."] = "하늘비행 탈것으로 활공 중이 아닐 때 항상."
L["Draw tick lines across the bar at positions you choose."] = "지정한 위치에 바를 가로지르는 눈금선을 긋습니다."
L["Out of Combat Opacity & Visibility"] = "비전투 시 투명도 및 가시성"
L["Shows the Health bar while your health is below full, even when its Visibility setting hides it."] = "생명력이 가득 차지 않았을 때 가시성 설정에 의해 숨겨진 상태라도 생명력 바를 표시합니다."
L["Show When Energy Missing"] = "기력이 줄었을 때 표시"
L["Shows the Power bar while its energy is below full, even when its Visibility setting hides it. Resources that rest at empty, such as rage, are not affected."] = "기력이 가득 차지 않았을 때 가시성 설정에 의해 숨겨진 상태라도 자원 바를 표시합니다. 분노처럼 비전투 시 0이 되는 자원은 영향을 받지 않습니다."
L["Show When Mana Missing"] = "마나가 줄었을 때 표시"
L["Shows the Power bar while it shows mana, or a shapeshifted druid's mana bar, while mana is below full, even when its Visibility setting hides it."] = "자원 바가 마나를 표시하거나 변신한 드루이드의 마나 바일 때, 마나가 가득 차지 않은 경우 가시성 설정에 의해 숨겨진 상태라도 표시합니다."
-- add ResourceBars Format (자원 바 포맷)
L["CDM Bar - %s"] = "CDM 바 - %s"   -- concat "CDM Bar - "..name; reverse-format template re-translates suffix (접두 결합, 접미 재번역)
L["Hash at %1$s"] = "%1$s 위치 눈금"
L["+ Add Buff"] = "+ 강화 효과 추가"
L["Active spec uses Advanced settings"] = "현재 전문화는 고급 설정을 사용 중"
L["Add Threshold"] = "임계값 추가"
L["Already used by another card for this spec"] = "이 전문화의 다른 카드가 이미 사용 중"
L["Anchor the text inside the bar. The X/Y offsets move it from there."] = "글자를 바 안쪽에 고정합니다. X/Y 좌표로 해당 위치에서 이동시킵니다."
L["Arms Warrior Sweeping Strikes Bar"] = "무기 전사 휩쓸기 일격 바"
L["Attach the spell icon to the right of the cast bar instead of the left."] = "주문 아이콘을 시전 바 왼쪽 대신 오른쪽에 붙입니다."
L["Bear"] = "곰"
L["Buff Colors"] = "강화 효과 색상"
L["Caster"] = "시전자"
L["Cat"] = "표범"
L["Choose the color of recharging runes instead of a dimmed version of the rune color."] = "충전 중인 룬에 기본 어두운 색상 대신 지정한 색상을 사용합니다."
L["Custom Recharge Color"] = "사용자 지정 충전 색상"
L["Enable/Disable per Form"] = "변신 형태별 켜기/끄기"
L["Enhance 5 Bar minimum is %d (if you want less just change 5 bar color)"] = "고양 주술사 5분할 바의 최솟값은 %d입니다 (더 적은 수치를 원하시면 5분할 바 색상을 변경하세요)"
L["Multi"] = "다중"
L["Recolor Text Instead Of Bar"] = "바 대신 글자 색상 변경"
L["Show rune count in center and remove recharge text/animation"] = "룬 개수를 중앙에 표시하고 충전 글자 및 애니메이션을 제거합니다"
L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "자원 바가 숨겨져 있을 때만 자원 글자를 표시합니다 (자원 바 비활성화, 현재 전문화에서 제외, 자원이 없는 전문화, '직업 자원 있을 때 자원 바 숨김'으로 숨겨진 경우 등). 설정을 끄면 항상 글자를 표시합니다."
L["Single-threshold options don't apply while Multi-band coloring is on."] = "다중 구간 색상이 활성화되어 있는 동안에는 단일 임계값 설정이 적용되지 않습니다."
L["Threshold Options"] = "임계값 옵션"
L["Threshold as"] = "임계값 기준"
L["Threshold color below value"] = "임계값 미만 색상"
L["Unavailable with Enhancement 5-bar style."] = "고양 5분할 바 스타일에서는 사용할 수 없습니다."
L["Value"] = "수치"
L["When the class resource bar is not shown, this automatically adds the class resource height to the power bar."] = "직업 자원 바가 표시되지 않을 때, 직업 자원 바의 높이만큼 자원 바 높이를 자동으로 늘립니다."
L["click to edit"] = "클릭하여 편집"
-- 2026-07-20 신규
L["Fill Settings"] = "채우기 설정"
L["Show the bright spark at the leading edge of the cast bar fill."] = "시전 바가 차오르는 앞쪽 끝에 밝은 불꽃을 표시합니다."
L["Border is only available when the Power Bar is shown."] = "테두리는 자원 바가 표시될 때만 사용할 수 있습니다."
L["Texture Settings"] = "텍스처 설정"
L["Blizzard Atlas Class Resource"] = "블리자드 기본 텍스처 직업 자원"
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "바 채우기 불투명도입니다. 100 미만으로 설정하면 배경 대신 채우기 영역 뒤로 배경 화면이 비쳐 보입니다."
L["Bar Layer"] = "바 표시 레이어"
L["Native Colors"] = "기본 색상"
L["Desaturated"] = "흑백(채도 감소)"
L["Keep the cast bar visible (sitting empty) when you are not casting, instead of hiding it."] = "시전 중이 아닐 때도 시전 바를 숨기지 않고 빈 상태로 계속 표시합니다."
-- 2026-08-10 신규 (시전 바 부드러운 채움)
L["Smooth Bar Animation"] = "부드러운 바 애니메이션"
L["Eases the cast fill between updates. Turn off for a raw, uneased fill."] = "시전 바의 갱신 진행도를 부드럽게 전환합니다. 끄면 보정 없이 즉각적으로 채워집니다."
