L["Width matched to Class Resource. Unmatch in Unlock Mode to edit."] = "너비가 직업 자원에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Width matched to Power Bar. Unmatch in Unlock Mode to edit."] = "너비가 자원 바에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Width matched to Health Bar. Unmatch in Unlock Mode to edit."] = "너비가 생명력 바에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Width matched to Cast Bar. Unmatch in Unlock Mode to edit."] = "너비가 시전 바에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Width matched to GCD Bar. Unmatch in Unlock Mode to edit."] = "너비가 GCD 바에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Width matched to Player Frame. Unmatch in Unlock Mode to edit."] = "너비가 플레이어 프레임에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Height matched to Class Resource. Unmatch in Unlock Mode to edit."] = "높이가 직업 자원에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Height matched to Power Bar. Unmatch in Unlock Mode to edit."] = "높이가 자원 바에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Height matched to Health Bar. Unmatch in Unlock Mode to edit."] = "높이가 생명력 바에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Height matched to Cast Bar. Unmatch in Unlock Mode to edit."] = "높이가 시전 바에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Height matched to GCD Bar. Unmatch in Unlock Mode to edit."] = "높이가 GCD 바에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
L["Height matched to Player Frame. Unmatch in Unlock Mode to edit."] = "높이가 플레이어 프레임에 맞춰져 있습니다. 잠금 해제 모드에서 맞춤 해제 후 편집하세요."
