L["Pick which content these Warlock reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "흑마법사 관련 알림을 표시할 콘텐츠를 선택합니다.\n휴식 구역(대도시 및 여관)에서는 항상 표시되지 않습니다."
L["When on, augment rune/flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "활성화 시 가방에 해당 소모품이 없더라도 증강 룬/영약/음식/무기 마법부여 알림을 흐리게 표시하여 재충전을 유도합니다.\n비활성화 시 해당 아이템을 소지하고 있지 않으면 알림을 완전히 숨깁니다."
L["Enable this to display a reminder to untalent\nout of this when it is not needed\n(all other dungeons/raids not selected)."] = "이 설정을 켜면 해당 특성이 불필요한 콘텐츠(선택되지 않은 다른 모든 던전/공격대)에 진입했을 때\n특성을 변경하라는 알림을 표시합니다."
L["Fullscreen Dialog"] = "전체화면 대화상자"
L["In Mythic Dungeons, show consumables reminders\nwhen the remaining buff time is less than this amount"] = "신화 던전에서 강화 효과의 남은 지속시간이\n설정한 시간 미만일 때 소모품 사용 알림을 표시합니다"
L["In Raids, show consumables reminders\nwhen the remaining buff time is less than this amount"] = "공격대에서 강화 효과의 남은 지속시간이\n설정한 시간 미만일 때 소모품 사용 알림을 표시합니다"
L["Inky Black Potion"] = "칠흑의 물약"
L["Master toggle for all aura, buff, and consumable reminders. Talent reminders are not affected."] = "모든 오라, 강화 효과, 소모품 알림을 일괄 활성화/비활성화합니다. 특성 알림에는 영향을 주지 않습니다."
L["Remind you to grab a Healthstone when a Warlock is in your group."] = "파티 또는 공격대에 흑마법사가 있을 때 생명석을 획득하도록 알림을 표시합니다."
L["Reminders are always hidden in rested areas (cities and inns)."] = "휴식 구역(대도시 및 여관)에서는 알림이 항상 숨겨집니다."
L["Show a reminder when you don't have an active pet summoned. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "소환수가 소환되어 있지 않을 때 알림을 표시합니다. 소환수 직업(사냥꾼, 흑마법사, 죽음의 기사, 마법사)에만 적용됩니다."
L["Show a reminder when your active pet is set to Passive stance. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "소환수의 공격 태세가 '수동적'으로 설정되어 있을 때 알림을 표시합니다. 소환수 직업(사냥꾼, 흑마법사, 죽음의 기사, 마법사)에만 적용됩니다."
L["Show a reminder when your Demonology Warlock has the wrong pet summoned (not Felguard)."] = "악마 흑마법사가 지옥수호병 외의 다른 소환수를 소환하고 있을 때 알림을 표시합니다."
L["Show special reminders while out in the open world."] = "야외 필드에 있을 때 특수 알림을 표시합니다."
L["Show special reminders while out in the open world.\nReminders are always hidden in rested areas (cities and inns)."] = "야외 필드에 있을 때 특수 알림을 표시합니다.\n휴식 구역(대도시 및 여관)에서는 알림이 항상 숨겨집니다."
L["This option only affects Raid Buffs and Paladin Beacons"] = "이 설정은 공격대 강화 효과 및 성기사의 봉화에만 적용됩니다"
L["This option requires a Glow Type other than None"] = "이 설정을 사용하려면 반짝임 유형을 '없음' 외의 유형으로 선택해야 합니다"
