-- 신규 모듈 2026-08-12 전수 등록. 키를 누르고 있으면 동작 메뉴가 열리는 기능.
-- nest = 하위 메뉴(중첩) / action menu = 동작 메뉴 로 통일.
L["Quickdraw"] = "빠른 실행"   -- 모듈 이름. 안의 '동작 메뉴' 용어와 짝 - 여기만 바꾸면 탭/초기화 버튼까지 바뀐다
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire."] = "단축키를 누르고 있으면 동작 메뉴가 열립니다. 마우스나 휠로 고른 뒤 키를 떼면 실행됩니다."
L["Hold a key to open a menu of actions; point or scroll to choose, release to fire."] = "키를 누르고 있으면 동작 메뉴가 열립니다. 마우스나 휠로 고른 뒤 키를 떼면 실행됩니다."
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire. Build up to 16 menus in Arc, Fan, or Grid layouts, nest menus inside menus, and tune every setting per menu."] = "단축키를 누르고 있으면 동작 메뉴가 열립니다. 마우스나 휠로 고른 뒤 키를 떼면 실행됩니다. 호(원)/부채꼴/격자 배치로 메뉴를 16개까지 만들고, 메뉴 안에 메뉴를 넣고, 메뉴마다 설정을 따로 조절할 수 있습니다."
