L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "지금 눌러도 아무 일도 하지 않는 항목에 색을 입힙니다. 대상이 사거리 밖이면 빨강, 자원이 부족하면 파랑, 그 밖의 이유로 사용할 수 없으면 회색입니다. 주문과 아이템에만 적용됩니다. 장난감은 게임이 전부 사용 불가로 보고하고, 매크로는 본문이 무엇으로 풀리는지에 따라 달라집니다."
L["How many entries a row of the grid holds. 1 stacks them into a single column; %1$s -- the most slots an action menu can hold -- lays them out in a single row."] = "격자 한 줄에 들어가는 항목 수입니다. 1이면 세로 한 줄로 쌓이고, %1$s(동작 메뉴가 가질 수 있는 최대 칸 수)면 가로 한 줄로 펼쳐집니다."
