-- add QoL Tooltip (편의 기능 툴팁)
L["Only shows the cursor circle while you are in combat."] = "전투 중에만 커서 원을 표시합니다."
L["Only shows the GCD circle while you are in combat."] = "전투 중에만 전역 재사용 대기시간 원을 표시합니다."
L["Only shows the cast bar circle while you are in combat."] = "전투 중에만 시전 바 원을 표시합니다."
L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat.\n\nNote: while this is active, holding Left+Right click to move forward won't work if your cursor is over a suppressed nameplate/unit, since this feature has to take over the right mouse button entirely to block targeting."] = "우클릭으로 대상 잡기를 막습니다. '적'은 어디서나 적용됩니다. '전투 중 아군'은 전투 중에만 우호 대상을 막으므로, 전투 밖에서는 상인이나 NPC를 우클릭할 수 있습니다.\n\n참고: 이 기능이 켜져 있으면 막힌 이름표/유닛 위에 커서가 있을 때 좌+우클릭을 눌러 앞으로 가기가 되지 않습니다. 대상 잡기를 막으려면 이 기능이 오른쪽 마우스 버튼을 완전히 가져가야 하기 때문입니다."
L["Edit the saved signup note."] = "저장한 신청 메모를 고칩니다."
L["Saved between reloads and relogs. In Group Finder, choose Copy, press Ctrl+C, then Ctrl+V."] = "다시 불러오기와 재접속 후에도 유지됩니다. 파티 찾기에서 복사를 고르고 Ctrl+C, Ctrl+V 를 누르세요."
L["Enter signup note..."] = "신청 메모 입력..."
L["Orbits the checked elements while Party Mode is active."] = "파티 모드가 켜져 있는 동안 체크한 요소를 돌게 합니다."
L["Full-window modes only. Shows start as a small icon, and the keybind switches between the icon and the full windows."] = "전체 창 방식에서만. 처음에는 작은 아이콘으로 나타나고, 단축키로 아이콘과 전체 창을 전환합니다."
L["Compact Band puts markers, ready check and pull timer in one resizable row. The other choices keep the original window layouts."] = "'간편 바'는 징표, 전투 준비 확인, 풀링 초읽기를 크기 조절이 가능한 한 줄에 모아 표시합니다. 다른 선택지는 기존 창 배치를 유지합니다."
L["Full-window modes only. Which way the windows extend from the collapsed icon when they open."] = "전체 창 방식에서만. 창이 열릴 때 접힌 아이콘에서 어느 쪽으로 펼쳐질지 정합니다."
L["Adds a 'Train All' button next to the Train button at profession trainers, allowing you to learn all available skills with one click."] = "전문기술 전문가 창의 '배우기' 버튼 옆에 '모두 배우기' 버튼을 추가하여, 한 번의 클릭으로 배울 수 있는 모든 기술을 배웁니다."
L["Adds a Calc toggle button to the character sheet that opens and closes the Upgrade Calculator."] = "강화 계산기를 여닫는 계산기 버튼을 캐릭터창에 추가합니다."
L["After a successful instance reset, automatically announces it in party or raid chat so your group knows they can re-enter."] = "인스턴스 초기화 성공 후 파티 또는 공격대 대화에 자동으로 알려 그룹이 재입장할 수 있도록 합니다."
L["Always show the crosshair."] = "크로스헤어를 항상 표시합니다."
L["Auto Open Containers Settings"] = "가방 자동 열기 설정"
L["Auto Repair"] = "자동 수리"
L["Automatically dismisses the 'new mount/pet/toy' fanfare notification when you receive one, so you don't have to click through the collections journal."] = "새로운 탈것, 애완동물, 장난감을 획득했을 때 나타나는 포장 해제(팡파르) 알림을 자동으로 제거합니다. 이제 수집품 창을 일일이 열어 확인하지 않아도 됩니다."
L["Automatically enables the 'Current Expansion Only' filter whenever you open the Auction House."] = "경매장을 열 때마다 '현재 확장팩만' 필터를 자동으로 활성화합니다."
L["Automatically inserts your key into the Font of Power."] = "쐐기돌을 마력의 샘에 자동으로 삽입합니다."
L["Automatically opens and closes the Upgrade Calculator when the Character Sheet is opened or closed."] = "캐릭터창이 열리거나 닫힐 때 장비 강화 계산기를 자동으로 열고 닫습니다."
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags."] = "가방에 추가되는 가방/상자/꾸러미를 자동으로 엽니다."
-- 2026-08-10 신규 (상자 자동 열기 - 장인 보상 보류)
L["Hold Capped Artisan Payouts"] = "한도 도달 시 자동 열기 중지"
L["Keeps Artisan's Consortium Payouts closed while Shard of Dundun is at its maximum, then resumes automatic opening after you spend shards."] = "둔둔의 조각이 최대치인 동안 장인 무역연합 대금을 열지 않고 보류했다가, 조각을 사용하면 자동 열기를 다시 시작합니다."
L["Automatically opens the Upgrade Calculator when the Crest Upgrade NPC window is opened."] = "문장 강화 NPC 창을 열면 강화 계산기를 자동으로 엽니다."
L["Automatically removes cosmetic transforms when they are applied to you, such as profession gear, holiday costumes, toys and consumables. Use the cog to pick exactly which transforms are removed. Transforms applied during combat are removed when combat ends."] = "전문 기술 장비, 축제 의상, 장난감, 소비용품 등 캐릭터에게 적용되는 외형 변신 효과를 자동으로 제거합니다. 설정 톱니바퀴를 사용해 제거할 변신 효과를 정확하게 선택할 수 있습니다. 전투 중에 적용된 변신 효과는 전투가 종료되면 제거됩니다."
L["Automatically repair all gear when visiting a repair vendor."] = "수리 가능한 상인을 방문하면 모든 장비를 자동으로 수리합니다."
L["Automatically sell all junk items when visiting a vendor."] = "상인을 방문하면 모든 잡동사니 아이템을 자동으로 판매합니다."
L["Automatically starts and stops combat logging when entering or leaving a loggable instance."] = "기록 가능한 인스턴스에 입장하거나 퇴장할 때 전투 기록을 자동으로 시작 및 중지합니다."
L["Automatically types DELETE when throwing away a valuable item. Also allows you to press enter to accept the deletion."] = "아이템을 파괴할 때 '지금파괴' 확인 문구를 자동으로 입력합니다. Enter 키를 눌러 바로 파괴할 수도 있습니다."
L["Background color for both Blizzard tooltips and EllesmereUI's own tooltips"] = "기본 블리자드 툴팁과 EllesmereUI 자체 툴팁의 배경 색상을 설정합니다."
L["BattleRes Icon"] = "전투 부활 아이콘"
L["Bloodlust Icon"] = "피의 욕망 아이콘"
L["Cast Bar Circle"] = "시전 바 원"
L["Changes the crosshair color when your current target is out of range."] = "현재 대상이 사정거리를 벗어났을 때 크로스헤어 색상을 변경합니다."
L["Checked transforms are removed automatically when applied to you."] = "체크된 변신 효과는 캐릭터에게 적용될 때 자동으로 제거됩니다."
L["Choose when the crosshair is shown."] = "크로스헤어를 표시할 조건을 선택합니다."
L["Choose which transforms are removed"] = "제거할 변신 효과를 선택합니다."
L["Controls when game tooltips appear"] = "게임 툴팁이 표시되는 시점을 제어합니다."
L["Ctrl + Left-Click Drag for a temporary move that resets when the panel closes."] = "컨트롤 + 좌클릭 드래그로 임시 이동 (패널을 닫으면 초기화)."
L["Delays stopping combat logging by 30 seconds after leaving an instance. Recommended for Warcraft Recorder compatibility."] = "인스턴스를 나간 후 전투 기록 중지를 30초 지연합니다. Warcraft Recorder 호환을 위해 권장됩니다."
L["Displays a crosshair at the center of the screen."] = "화면 중앙에 크로스헤어를 표시합니다."
L["Displays a spoiler tag over guild chat in the communities window that you can click to hide"] = "커뮤니티 창의 길드 채팅 위에 클릭해서 숨길 수 있는 가림 표시를 보여줍니다."
L["Displays a ZZZ indicator on your player frame when you are in a resting area."] = "휴식 지역에 있을 때 플레이어 프레임에 ZZZ 표시기를 표시합니다."
L["Displays cursor and player coordinates at the bottom of the world map."] = "전체 지도 하단에 커서와 플레이어 좌표를 표시합니다."
L["Displays secondary stat percentages (Crit, Haste, Mastery, Vers) at the top left of the screen."] = "화면 왼쪽 상단에 보조 능력치 비율(치명, 가속, 특화, 유연)을 표시합니다."
L["Double-click a group listing to instantly sign up without pressing the Sign Up button."] = "그룹 목록을 더블클릭하면 신청 버튼을 누르지 않고 즉시 신청됩니다."
L["Double-click a group listing to instantly sign up without pressing the Sign Up button. Hold Shift to keep the dialog open, e.g. to type a signup note."] = "그룹 목록을 더블클릭하면 신청 버튼을 누르지 않고 즉시 신청됩니다. Shift를 누르고 있으면 대화창이 열린 채로 유지됩니다(예: 신청 메모 입력)."
L["Enable the crosshair to use this option."] = "이 설정을 사용하려면 크로스헤어를 활성화하세요."
L["Enables auto loot and hides the loot window when looting. Hold Shift when looting to show."] = "자동 획득을 활성화하고 전리품 창을 숨깁니다. Shift 키를 누른 채 획득하면 전리품 창이 표시됩니다."
L["Exclude Warbound Containers"] = "전투부대 귀속 가방 제외"
L["Flashes a warning on screen when any equipped item drops below the configured durability threshold. Only triggers out of combat."] = "착용 장비 내구도가 설정한 기준 이하로 내려가면 화면에 경고를 표시합니다. 전투 중에는 작동하지 않습니다."
L["Font size for keystone entries in the popup (does not affect the header)."] = "팝업의 쐐기돌 항목 글꼴 크기 (제목에는 영향 없음)."
L["GCD Circle"] = "글쿨 원"
L["Hide crafted items from the gear tile list.\nCrafted items cannot be upgraded at the Upgrade NPC."] = "장비 타일 목록에서 제작 아이템을 숨깁니다.\n제작 아이템은 강화 NPC에서 강화할 수 없습니다."
L["Hide Item Transforms (ex: Chef's Hat)"] = "아이템 변신 숨기기 (예: 요리사 모자)"
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "블리자드의 튜토리얼 UI를 숨깁니다. 마법책, 특성, 지도, 수집품 및 기타 패널에 표시되는 노란색 도움말 말풍선과 반짝이는 (i) 도움말 버튼이 해당됩니다."
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "대부분의 붉은색 오류 메시지('분노 부족', '아직 사용할 수 없습니다' 등)를 숨깁니다. 가방 가득 참이나 퀘스트 목록 가득 참과 같은 중요한 오류는 계속 표시됩니다."
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "스크린샷 촬영 후 화면에 나타나는 '스크린샷 저장됨' 알림을 숨깁니다."
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "퀘스트와 던전 중에 나타나는 큰 NPC 대화 팝업을 숨깁니다."
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "Lua 오류 팝업을 숨깁니다. 전체 설정 > 개발자와 동일한 설정입니다."
L["Keeps your note text in the Sign Up dialog instead of clearing it each time you open it."] = "신청 창의 메모 글자를 매번 지우지 않고 유지합니다."
L["Low Durability Warning"] = "내구도 낮음 경고"
L["Makes the game tooltip follow your mouse cursor instead of appearing in the default screen corner. Use the arrows icon to pick the position relative to the cursor and fine-tune the X/Y offset."] = "게임 툴팁이 화면 구석의 기본 위치 대신 마우스 커서를 따라 표시되게 만듭니다. 화살표 아이콘으로 커서 대비 기준점을 선택하고 X/Y 간격을 미세하게 조정해 보세요."
L["No items queued, click tiles to add an item to queue."] = "대기열이 비었습니다. 타일을 클릭해 아이템을 추가하세요."
L["Only shows the cursor circle while the mouse is hidden -- that is, while you hold the left and/or right mouse button to pan the camera or move your character."] = "마우스가 숨겨졌을 때만 커서 원을 표시합니다 - 즉, 마우스 왼쪽/오른쪽 버튼을 눌러 카메라를 회전하거나 캐릭터를 이동할 때입니다."
L["Portal on Cooldown"] = "차원문 재사용 대기 중"
L["Preview durability warning"] = "내구도 경고 미리보기"
L["Refresh Data"] = "데이터 새로고침"
L["Refresh using tooltip scan data."] = "툴팁 갱신 데이터로 새로고침."
L["Refresh using tooltip scan data.\nFor exact costs, use |cffffffff'Update at Upgrader'|r\nwhile at an Item Upgrade NPC."] = "툴팁 갱신 데이터로 새로고침합니다.\n정확한 비용은 아이템 강화 NPC에게서\n|cffffffff'강화 NPC에서 갱신'|r을 사용하세요."
L["Requires the Item Upgrade window to be open."] = "아이템 강화 창이 열려 있어야 합니다."
L["Reskins Blizzard tooltips with a dark, minimal style matching the EUI aesthetic. Requires reload to apply."] = "블리자드 기본 툴팁에 EUI 다크 모드 스타일을 적용합니다. 스킨 설정은 UI를 다시 불러와야 완전히 적용됩니다."
L["Reskins Blizzard's right-click context menus and pop-up dialogs with the EUI dark style. Requires reload to apply."] = "블리자드 기본 우클릭 메뉴와 팝업 대화창에 EUI 다크 모드 스타일을 적용합니다. 스킨 설정은 UI를 다시 불러와야 완전히 적용됩니다."
L["Rested Indicator"] = "휴식 표시기"
L["Scale of the /keys popup window."] = "/keys 팝업 창의 크기 비율."
L["Scan all equipped gear costs at the Item Upgrade NPC."] = "강화 NPC에서 장착한 모든 장비의 비용을 검사합니다."
L["Scan all equipped gear costs at the Item Upgrade NPC.\nScans each slot one at a time — this can take up to 10 seconds.\nRequires the Item Upgrade window to be open."] = "아이템 강화 NPC에서 착용 장비 비용을 모두 갱신.\n부위를 하나씩 갱신 - 최대 10초 소요될 수 있습니다.\n아이템 강화 창이 열려 있어야 합니다."
L["Shift + Left-Click Drag to permanently save a panel's position."] = "Shift + 좌클릭 드래그로 패널 위치를 영구 저장합니다."
L["Shift + Scroll to permanently zoom a panel. Ctrl + Scroll for a temporary zoom."] = "Shift + 휠 스크롤로 패널을 영구적으로 확대/축소합니다. Ctrl + 휠 스크롤은 일시적으로 확대/축소합니다."
L["Show Coordinates on Map"] = "지도에 좌표 표시"
L["Show gear tiles for items already at their maximum item level."] = "이미 최대 아이템 레벨인 장비 타일을 표시합니다."
L["Show how many crests you can still earn before hitting the season cap (cap minus earned so far)."] = "시즌 한도에 도달하기까지 더 얻을 수 있는 문장 수를 표시합니다 (한도 - 현재 획득)."
L["Show only while in a dungeon, raid, arena or battleground. Combine with Combat to show only during instanced combat."] = "던전, 공격대, 투기장, 전장에 있을 때만 표시합니다. 전투 상태 설정과 함께 활성화하면 인스턴스 던전 안에서 전투 중일 때만 표시됩니다."
L["Show only while in combat. Combine with Instances to show only during instanced combat."] = "전투 중일 때만 표시합니다. 인스턴스 설정과 함께 활성화하면 인스턴스 던전 안에서 전투 중일 때만 표시됩니다."
L["Show Tertiary Stats"] = "3차 능력치 표시"
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "전투에 돌입하거나 벗어날 때 화면에 큰 글자(예: \"+전투 시작\" / \"-전투 종료\")를 표시합니다. 설정 톱니바퀴를 사용해 표시할 글자, 크기, 색상 및 전환 효과를 설정할 수 있으며, 잠금 해제 모드를 사용하여 알림의 위치를 변경할 수 있습니다."
L["Show the seasonal Earned / Cap column in the crest table."] = "문장 표에 시즌 획득/한도 열을 표시합니다."
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "파티원이나 공격대원이 사망할 때마다 화면에 큰 경고(예: \"플레이어 사망!\")를 표시하여 던전 및 공격대 진행 중 사망을 즉시 감지할 수 있도록 합니다. 경고 위치를 변경하려면 잠금 해제 모드를 사용하세요."
L["Shows a popup with party and guild keystones when typing /keys."] = "/keys 입력 시 파티 및 길드 쐐기돌 팝업을 표시합니다."
L["Shows the 'Disable Feature' text below the teleport button. When off, the text is hidden and the window is 20px shorter."] ="순간이동 버튼 아래에 '기능 비활성화' 문구를 표시합니다. 이 설정을 끄면 문구가 숨겨지고 창의 세로 길이가 20픽셀(px) 줄어듭니다."
L["Skip Cinematics"] = "시네마틱 건너뛰기"
L["Sort queue by crest type (cheapest first)"] = "문장 종류별 정렬 (저렴한 순)"
L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat."] = "우클릭 대상 지정을 막습니다. \"적\"은 모든 곳에 적용됩니다. \"전투 중 아군\"은 전투 중에만 아군 대상을 막으므로 전투 밖에서는 상인과 NPC를 우클릭할 수 있습니다."
L["This option is now controlled by the Raid Frames addon"] = "이 설정은 이제 공격대 프레임 애드온에서 제어합니다"
L["This option requires a custom thickness to be set."] = "이 설정을 사용하려면 사용자 지정 두께를 설정해야 합니다."
L["When enabled, left-click dragging a window will save its position without needing to hold Shift. Ctrl+drag still does a temporary move."] = "켜면 Shift를 누르지 않고도 좌클릭으로 창을 끌어 위치를 저장합니다. Ctrl+드래그는 여전히 임시 이동입니다."
L["When you join a Group Finder group for a dungeon that has a teleport, shows a small movable popup with the dungeon name and a one-click teleport button. It hides when you enter the dungeon, leave the group, or enter combat."] ="순간이동 기능이 있는 던전의 파티 찾기 파티에 참여하면, 던전 이름과 원클릭 순간이동 버튼이 있는 이동 가능한 작은 팝업창을 표시합니다. 던전에 입장하거나 파티를 탈퇴하거나 전투에 돌입하면 팝업창이 숨겨집니다."
L["When you press Escape or Space during a cinematic, the confirmation prompt is automatically accepted."] = "시네마틱 중 Escape 또는 Space를 누르면 확인 창이 자동으로 수락됩니다."
L["Shows the approximate distance to your current target as movable on-screen text (default 30-35). Use the cog for format, alignment, and text size; use Unlock Mode to position or Anchor to your Player Frame."] = "현재 대상까지의 대략적인 거리를 이동 가능한 화면 글자로 표시합니다(기본 30-35). 형식, 정렬, 글자 크기는 톱니바퀴에서 조정하고, 위치는 잠금해제 모드에서 옮기거나 플레이어 프레임에 고정할 수 있습니다."
L["Adds a mover for Blizzard's top-center event text and widgets (scenario, event, and encounter bars)."] = "블리자드 화면 상단 중앙의 이벤트 글자와 위젯(시나리오, 이벤트, 우두머리 바)에 이동 장치를 추가합니다."
L["Hides the Top Bar Event Text mover in Unlock Mode while keeping its saved position applied."] = "저장된 위치는 그대로 적용한 채, 잠금해제 모드에서 상단 이벤트 글자 이동 장치를 숨깁니다."
L["Shows the checked classes' mobility spell(s) counting down on cooldown. Nothing checked = feature disabled. Use Unlock Mode to reposition/resize."] = "체크한 직업의 이동기 재사용 대기시간을 초읽기로 표시합니다. 아무것도 체크하지 않으면 기능이 꺼집니다. 위치와 크기는 잠금해제 모드에서 조정합니다."
L["Only show the alert while in combat."] = "전투 중에만 알림을 표시합니다."
L["Speaks the ability name once, right when it comes off cooldown -- not a running countdown. None = no speech."] = "재사용 대기시간이 끝나는 순간 기술 이름을 한 번 읽어줍니다. 초읽기는 아닙니다. 없음 = 음성 없음."
L["Text-to-Speech is enabled and takes priority over Sound."] = "음성 안내(TTS)가 켜져 있어 소리보다 우선합니다."
L["Right-Click to set custom alert text."] = "우클릭으로 사용자 지정 알림 문구를 설정합니다."
L["Flashes a banner whenever a tracked mobility spell's cooldown is proc-reset. Use Unlock Mode to reposition/resize."] = "추적 중인 이동기의 재사용 대기시간이 효과 발동으로 초기화되면 배너를 표시합니다. 위치와 크기는 잠금해제 모드에서 조정합니다."
L["Warlock only. Alerts when your Gateway Control Shard is usable. Use Unlock Mode to reposition/resize."] = "흑마법사 전용. 관문 제어 파편을 사용할 수 있게 되면 알려줍니다. 위치와 크기는 잠금해제 모드에서 조정합니다."
-- add QoL Popup (편의 기능 팝업)
L["Changing the /keys popup requires a reload to update slash command registration."] = "'/keys 팝업' 변경은 슬래시 명령어 등록 갱신을 위해 UI 다시 불러오기가 필요합니다."
L["This will reset all saved panel positions and reload your UI."] = "저장된 모든 패널 위치를 초기화하고 UI를 다시 불러옵니다."
