L["The housing dashboard window background, border, and title bar."] = "하우징 대시보드 창의 배경, 테두리 및 제목 표시줄입니다."
L["The item conversion window (catalyst and similar kiosks)."] = "아이템 변환 창(생생한 촉매 및 유사한 상호작용 장치)입니다."
L["The item preview / transmog dressing room window."] = "아이템 미리보기 / 형상 변환 창입니다."
L["The macro editor: tabs, icon grid, text well, and buttons."] = "매크로 편집기: 탭, 아이콘 그리드, 입력창 및 버튼입니다."
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "우편함: 받은 우편함 목록, 우편 보내기, 우편 읽기 및 첨부 파일 슬롯입니다."
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "월간 달력 그리드, 이벤트 대화창 및 이동 화살표입니다."
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "NPC 대화 창: 인사말, 대화 및 임무 선택지, 작별 인사 버튼입니다."
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "NPC 임무 창: 임무 세부 정보, 진행 상황, 보상 패널 및 여러 임무가 있을 때의 인사말 목록입니다."
L["The Player Spells window: talents, spec selection, and the spellbook."] = "플레이어 주문 창: 특성, 전문화 선택 및 마법책입니다."
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "전문 기술 제작 창: 도안 목록, 제작식, 전문화 및 제작 주문입니다."
L["The professions overview book with squared icons and flat progress bars."] = "사각형 아이콘과 평면형 진행 바가 적용된 전문 기술 개요서입니다."
L["The recipe preview window shown from a linked recipe or an inspected crafter."] = "링크된 제작법이나 다른 플레이어 살펴보기 시 표시되는 제작법 미리보기 창입니다."
L["The transmogrification window at the transmogrifier."] = "형상 변환사 NPC에게서 열리는 형상 변환 창입니다."
L["The vendor window: item list, buyback, and bottom money bar."] = "상인 창: 아이템 목록, 재구입 탭 및 하단 소지금 표시줄입니다."
L["The world map window chrome and the quest log side panel."] = "세계 지도 창틀과 퀘스트 목록 측면 패널입니다."
