L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size, bar height and text offset."] = "대기열 수락 팝업 아래에 수락까지 남은 시간을 보여 주는 초읽기 바를 표시합니다. 스킨 적용 여부와 관계없이 작동합니다. 색상 견본과 톱니바퀴에서 초읽기 글자 색상, 글자 크기, 바 높이 및 글자 위치를 설정할 수 있습니다."
