L["Encounter Journal: instance select, boss details, loot lists, and the bottom nav tabs."] = "모험 안내서: 던전/공격대 선택, 우두머리 정보, 전리품 목록 및 하단 탐색 탭입니다."
L["Enhance QoL's Mover may conflict with this reskin. The reskin is auto-disabled when its mover is active."] = "Enhance QoL 프레임 이동 기능과 이 스킨이 충돌할 수 있습니다. 해당 기능 사용 시 스킨이 자동으로 비활성화됩니다."
L["Equipment panel with stat categories, item level, enchants, gems, and the inspect sheet."] = "능력치 카테고리, 아이템 레벨, 마법부여, 보석이 포함된 장비 패널 및 살펴보기 창입니다."
L["Equipped Item Level"] = "장착한 아이템 레벨"
L["Flattens the micro menu buttons into the EllesmereUI style."] = "게임 메뉴 버튼을 EllesmereUI 스타일의 깔끔한 플랫 디자인으로 변경합니다."
L["Group Finder and Premade Groups window, plus browsing quality-of-life extras."] = "파티 찾기 창의 탐색 및 편의 기능을 제공합니다."
L["Hide Item Text"] = "아이템 글자 숨기기"
L["Hides the health bar Blizzard shows at the bottom of unit tooltips."] = "유닛 툴팁 하단에 블리자드가 표시하는 생명력 바를 숨깁니다."
L["Increase the magnitude of your attacks and Abilities"] = "공격과 기술의 위력을 증가시킵니다."
L["Increases dodge chance and melee attack power"] = "회피 확률과 근접 공격력을 증가시킵니다."
L["Increases dodge chance by %.2f%%."] = "회피 확률을 %.2f%% 증가시킵니다."
L["Increases health"] = "생명력 증가"
L["Increases melee attack power"] = "근접 공격력을 증가시킵니다."
L["Increases parry chance by %.2f%%."] = "무기 막기 확률을 %.2f%% 증가시킵니다."
L["Increases the power of your spells and abilities"] = "주문 및 기술의 공격력을 증가시킵니다."
L["Inspect Sheet theme setting requires a UI reload to fully apply."] = "살펴보기 창 스킨 설정은 UI를 다시 불러와야 완전히 적용됩니다."
L["Item Level:"] = "아이템 레벨:"
L["M+ Score:"] = "신화+ 점수:"
L["Missing Items:"] = "빠진 아이템:"
L["Mounts, pets, toys, heirlooms, appearances, and campsites."] = "탈것, 애완동물, 장난감, 계승품, 형상 변환 및 야영지 창입니다."
L["No better items in inventory"] = "가방에 더 좋은 아이템이 없습니다"
L["Parry"] = "무기 막기"
L["Physical damage reduction: %.2f%%"] = "물리 피해 감소: %.2f%%"
L["Pick a style for all reskinned Blizzard windows."] = "아래의 모든 창에 일괄 적용할 스킨 스타일을 선택합니다."
L["Primary stat"] = "주 능력치"
L["Recolors headers, arrows, and spell titles in Blizzard tooltips and context menus to match your UI Accent Color."] = "블리자드 기본 툴팁과 우클릭 메뉴의 제목, 화살표 및 주문 이름을 UI 강조 색상으로 변경합니다."
L["Reduces physical damage taken"] = "받는 물리 피해 감소"
L["Remembers the Tank/Healer/DPS roles you last applied with and restores them the next time you sign up to a premade group (limited to roles your current spec can fill). Works with or without the reskin."] = "파티 찾기에서 마지막으로 신청할 때 선택한 방어/치유/공격 역할을 기억하여 다음 신청 시 복원합니다(현재 전문화로 수행 가능한 역할에 한함). 스킨 적용 여부와 무관하게 작동합니다."
L["Reskin setting requires a UI reload to fully apply."] = "모양 변경 설정은 UI를 다시 불러와야 완전히 적용됩니다."
L["Reskins Blizzard tooltips, right-click context menus, and popups with a dark, minimal style matching the EUI aesthetic. Requires reload to apply."] = "기본 UI 툴팁, 우클릭 메뉴, 팝업에 EUI 스타일에 어울리는 미니멀 다크 모드를 적용합니다. 적용하려면 UI 다시 불러오기가 필요합니다."
L["Reskins the ESC / Game Menu with the EUI dark style, matching fonts, and accent-colored title."] = "ESC / 게임 메뉴에 EUI 다크 모드, 일치하는 글꼴, 강조 색상 제목을 적용합니다."
L["Reskins the Great Vault window with custom tile backgrounds, progress colors, and completion states."] = "위대한 금고 창의 타일 배경, 진행 색상, 완료 상태 디자인을 변경합니다."
L["Reskins the LFG/dungeon queue accept popup with the EUI dark style and adds an accept countdown timer bar."] = "파티 찾기/던전 대기열 수락 팝업에 EUI 다크 모드를 적용하고 수락 초읽기 시간 바를 추가합니다."
L["Scales the font size of reskinned Blizzard tooltips, menus, and popups."] = "모양이 변경된 기본 UI 툴팁, 메뉴, 팝업의 글꼴 크기를 조정합니다."
L["Second Wind"] = "재기"
L["Show a panel of equipped-gear sockets on the character sheet; click a socket to gem it."] = "캐릭터창에 장착 장비의 보석 홈 패널을 표시합니다. 보석 홈을 클릭하면 보석을 장착합니다."
L["Show Detailed Tooltips"] = "상세 툴팁 표시"
L["Show Diminishing Returns"] = "점감 효과 표시"
L["Show Item Text"] = "아이템 글자 보이기"
L["Show Player Titles in Tooltips"] = "툴팁에 플레이어 칭호 표시"
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept."] = "대기열 수락 팝업 아래에 수락 가능한 시간을 보여주는 초읽기 바를 표시합니다."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin."] = "대기열 입장 수락 팝업 아래에 수락 가능 시간이 얼마나 남았는지 보여주는 초읽기 바를 표시합니다. 스킨 변경 여부와 상관없이 작동합니다."
L["Shows a player's RP title on their unit tooltip."] = "유닛 툴팁에 플레이어의 칭호를 표시합니다."
L["Shows full spell and ability descriptions in tooltips instead of just the name. Only enforced on login after you toggle this setting."] = "툴팁에 이름만이 아니라 주문/능력의 전체 설명을 표시합니다. 이 설정을 변경한 후에는 다음 접속 시에만 적용됩니다."
L["Shows saved instance lockouts with boss kill progress on the minimap calendar button tooltip."] = "미니맵 달력 버튼 툴팁에 우두머리 처치 진행도와 함께 저장된 인스턴스 잠금을 표시합니다."
L["Shows the item level on each item in the character sheet gear flyout (the popup of same-slot bag items that appears when hovering an equipped slot), coloured by quality."] = "캐릭터 창의 장비 슬롯에 마우스를 올릴 때 나타나는 동일 슬롯 가방 아이템 목록(팝업)에서, 각 아이템의 레벨을 등급별 색상으로 표시합니다."
L["Spell Power"] = "주문력"
L["Stagger Effect"] = "시간차 효과"
L["Stamina"] = "체력"
L["The amount of damage you can take"] = "받을 수 있는 피해량"
L["The size of your mana pool"] = "보유한 최대 마나량"
L["Themed Blizzard frames: Character Sheet, tooltips, menus, popups, Dragon Riding HUD."] = "테마 적용 블리자드 프레임: 캐릭터창, 툴팁, 메뉴, 팝업, 하늘 비행 HUD."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, Dragon Riding HUD."] = "테마가 적용된 블리자드 프레임: 창 스킨, 툴팁, 메뉴, 팝업창, 하늘비행 HUD."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, chat bubbles, Dragon Riding HUD."] = "테마가 적용된 블리자드 프레임: 창 스킨, 툴팁, 메뉴, 팝업창, 대화 말풍선, 하늘비행 HUD."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, chat bubbles."] = "테마가 적용된 블리자드 프레임: 창 스킨, 툴팁, 메뉴, 팝업창, 대화 말풍선."
L["Thrill"] = "스릴"
L["Toggle visibility of item level text on the inspect sheet."] = "살펴보기창의 아이템 레벨 글자 표시를 켜거나 끕니다."
L["Toggle visibility of upgrade track text on the inspect sheet."] = "살펴보기창의 강화 단계 글자 표시를 켜거나 끕니다."
L["Tooltips & Menus"] = "툴팁 & 메뉴"
L["Tooltips, Menus & Popups"] = "툴팁, 메뉴 & 팝업"
L["Weekly rewards window with custom tile backgrounds, progress colors, and completion states."] = "불러온 배경, 진행도 색상, 완료 상태가 표시되는 주간 보상 창입니다."
L["|cff888888(Against an evenly matched enemy)|r"] = "|cff888888(동일 레벨 적 기준)|r"
L["|cff888888(Before diminishing returns)|r"] = "|cff888888(점감 효과 적용 전)|r"
L["|cffff0000Error:|r EllesmereUI not found! Themed Inspect Sheet requires EllesmereUI."] = "|cffff0000오류:|r EllesmereUI를 찾을 수 없습니다! 테마 살펴보기창은 EllesmereUI가 필요합니다."
L["Adds a glowing, pulsating border around the Accept button of resurrection popups so a pending resurrect is hard to miss. Follows the Element & Text Color setting. Applies instantly, no reload needed."] = "부활 팝업의 수락 버튼 둘레에 고동치는 반짝임 테두리를 추가해 부활 대기를 놓치지 않게 합니다. 요소 및 글자 색상 설정을 따릅니다. 다시 불러올 필요 없이 즉시 적용됩니다."
L["Shows the items as a list instead of pages."] = "아이템을 페이지 대신 목록으로 표시합니다."
L["Merchant Show As List setting requires a UI reload to fully apply."] = "상품 목록의 '목록으로 표시' 설정을 완전히 적용하려면 UI 다시 불러오기가 필요합니다."
L["MERCHANT OPTIONS"] = "상점 옵션"
L["Bulk Buy"] = "대량 구매"
L["Buy"] = "구매"
L["Total: %s"] = "총액: %s"
L["Buy %1$d x %2$s for %3$s?"] = "%2$s %1$d개를 %3$s에 구매하시겠습니까?"
L["Shift-click a vendor item to buy more than one stack at a time."] = "상점 아이템을 Shift+클릭하여 한 번에 1묶음보다 많이 구매합니다."
L["Bulk Buy stopped after %1$d of %2$d."] = "대량 구매가 %2$d개 중 %1$d개에서 중단되었습니다."
L["This purchase is not refundable."] = "이 구매는 환불할 수 없습니다."
L["Pins a row with your gold per hour."] = "시간당 골드 획득량을 표시하는 행을 고정합니다."
L["Prices items from Auctionator scans."] = "Auctionator 경매장 스캔 데이터를 기반으로 아이템 가격을 표시합니다."
L["This option requires Auctionator to be loaded."] = "이 설정은 Auctionator 애드온이 로드되어 있어야 합니다."
L["This option requires Gold per Hour Tracker or Show Item Price to be enabled."] = "이 설정은 '시간당 골드 추적기' 또는 '아이템 가격 표시'가 켜져 있어야 합니다."
L["Adds a Targeting line showing who the hovered player or NPC is targeting, in green when it's you."] = "마우스를 올린 플레이어나 NPC가 누구를 대상으로 하는지 보여주는 줄을 추가합니다. 대상이 나면 초록색으로 표시됩니다."
L["Forces which way the default screen-anchored tooltip expands as lines are added. Default lets Blizzard decide from the tooltip's screen position."] = "줄이 늘어날 때 화면 고정 기본 툴팁이 어느 방향으로 커질지 지정합니다. 기본값은 툴팁의 화면 위치에 따라 블리자드가 정합니다."
L["Makes the game tooltip follow your mouse cursor instead of showing at its fixed screen position (drag the Tooltip box in Unlock Mode to change that). Use the arrows icon to pick the position relative to the cursor and fine-tune the X/Y offset."] = "게임 툴팁이 고정된 화면 위치 대신 마우스 커서를 따라다니게 합니다(고정 위치는 잠금해제 모드에서 툴팁 상자를 끌어 조정). 화살표 아이콘으로 커서 기준 위치를 고르고 가로/세로 위치를 미세 조정합니다."
