L["Draw a 1px divider between the spell icon and the cast bar, matching the border color."] = "주문 아이콘과 시전 바 사이에 테두리 색상과 같은 1픽셀 구분선을 그립니다."
L["Tint the bar with the Important colour when the enemy casts a spell the game flags as important."] = "적이 게임에서 중요로 지정한 주문을 시전하면 바를 중요 색상으로 칠합니다."
L["Previews the forces of every enemy in combat with a visible nameplate on the enemy forces bar."] = "이름표가 보이는 전투 중인 모든 적의 병력을 적 병력 바에 미리 표시합니다."
L["Opacity of the current pull on the enemy forces bar."] = "적 병력 바에 표시되는 현재 몹 몰이의 불투명도입니다."
L["Shows your best split on upcoming bosses instead of only killed ones."] = "처치한 우두머리뿐 아니라 앞으로 나올 우두머리의 최고 구간 기록도 표시합니다."
L["Compare only against splits from the same key level (off: new key levels compare against your dungeon best)."] = "같은 쐐기돌 단계의 구간 기록하고만 비교합니다 (끄면 처음 하는 단계는 그 던전의 최고 기록과 비교)."
L["Compare against the splits of your fastest completed run instead of your best individual splits."] = "구간별 최고 기록 대신 가장 빨리 완료한 기록의 구간과 비교합니다."
L["Show Enemy Forces"] = "적 병력 표시"
L["Show the game's spell tooltip when you hover a spell in a breakdown window."] = "상세 정보 창에서 주문에 마우스를 올리면 게임의 주문 툴팁을 표시합니다."
L["Show Timer Bar"] = "목표 시간 바 표시"
L["Show Timer Text"] = "목표 시간 글자 표시"
L["the module"] = "추가기능"
L["Timer Inside Bar"] = "바 내부 목표 시간"
L["Track Mythic+ run time, key thresholds, and dungeon objectives."] = "쐐기돌 진행 시간, 단계 기준, 던전 목표를 추적합니다."
L["A standalone cast bar for this unit, placeable anywhere in Unlock Mode. Runs alongside the Unit Frames cast bars."] = "이 유닛을 위한 독립형 시전 바입니다. 잠금 해제 모드에서 어디든 배치할 수 있으며, 유닛 프레임 시전 바와 함께 작동합니다."
L["Flash the cast bar and show \"Interrupted\" for a moment when the cast is interrupted."] = "시전이 차단되면 시전 바를 깜빡이고 잠시 동안 \"차단됨\"을 표시합니다."
L["Preview the bars at their position"] = "현재 위치에서 바 미리보기"
L["Show one plain cast bar per enemy nameplate that is casting, gathered into a single movable group with the spell name, its target, and the cast timer."] = "시전 중인 적 이름표마다 하나의 일반 시전 바를 표시하며, 주문 이름, 대상, 시전 타이머와 함께 이동 가능한 하나의 그룹으로 모아줍니다."
L["Show who each spell is being cast on, exactly like the nameplate cast bars."] = "이름표 시전 바와 정확히 동일하게, 각 주문의 대상이 누구인지 표시합니다."
L["Show who the spell is being cast on, exactly like the nameplate cast bars."] = "이름표 시전 바와 정확히 동일하게, 주문의 대상이 누구인지 표시합니다."
L["Shows where your interrupt will be ready during a cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "시전 중 차단 기술이 준비되는 시점을 표시합니다. \"눈금\"은 시전 바의 정확한 위치를 표시하고, \"눈금 + 바\"는 차단이 가능한 구간의 색상도 함께 변경합니다."
L["The most cast bars shown at once. Extra casters take a bar as soon as one frees up."] = "한 번에 표시되는 최대 시전 바 개수입니다. 빈 자리가 생기면 추가 시전자가 바로 바를 차지합니다."
L["Which way new bars stack as more enemies start casting."] = "더 많은 적이 시전을 시작할 때 새 바가 쌓이는 방향입니다."
