-- add QuestTracker Tooltip (퀘스트 추적기 툴팁)
L["Hides the master header and its minimize button at the top of the tracker."] = "추적기 맨 위의 전체 제목과 최소화 버튼을 숨깁니다."
L["Always: hide the tracker the whole time you are in a raid.\nBoss Combat: keep it visible and only hide during boss encounters."] = "항상: 공격대에 있는 동안에는 항상 추적기를 숨깁니다.\n우두머리 전투: 평소에는 표시하다가 우두머리와의 전투 중에만 숨깁니다."
L["Always: hide the tracker the whole time you are in a raid."] = "항상: 공격대에 있는 동안에는 추적기를 항상 숨깁니다."
L["Boss Combat: keep it visible and only hide during boss encounters."] = "우두머리 전투: 평소에는 표시하고 우두머리 전투 진행 중에만 숨깁니다."
L["Colors objectives by how far along they are."] = "진행도에 따라 목표에 색상을 적용합니다."
L["Draws a 1px accent line above the background at the top of the tracker."] = "추적기 상단의 배경 위에 1px 강조 라인을 그립니다."
L["Fades objective lines that are already done."] = "이미 완료된 목표 항목의 투명도를 낮춰 흐리게 표시합니다."
L["Posts your quest progress to party or instance chat, never in raids."] = "퀘스트 진행 상황을 파티 또는 인스턴스 대화에 전송합니다. 공격대에서는 작동하지 않습니다."
L["Reorders your tracked quests; Quest Log Order lists them as your quest log does."] = "추적 중인 퀘스트의 순서를 정렬합니다. '퀘스트 목록 순서'는 퀘스트 목록과 같은 순서로 표시합니다."
L["Requires Sort Quests set to something other than Quest Log Order."] = "퀘스트 정렬이 '퀘스트 목록 순서'가 아닌 다른 방식으로 설정되어 있어야 합니다."
L["Show Blizzard's native quest type icons/buttons on the right instead of EllesmereUI's custom icons. Requires a UI reload."] = "EllesmereUI의 사용자 정의 아이콘 대신 오른쪽에 블리자드 기본 퀘스트 유형 아이콘/버튼을 표시합니다. UI를 다시 불러와야 합니다."
L["Sorting, filtering and auto-tracking don't update while the map or quest log is open, in combat or in dungeons. Close the map to apply them."] = "정렬, 필터 및 자동 추적 기능은 지도나 퀘스트 일지가 열려 있거나 전투 중이거나 던전에 있는 동안 갱신되지 않습니다. 지도를 닫으면 적용됩니다."
L["Tracks your current zone's or dungeon's quests and untracks them when you leave."] = "현재 지역이나 던전의 퀘스트를 자동으로 추적하고, 해당 지역을 벗어나면 추적을 해제합니다."
L["Untracks quests that match the filters in the cog until they no longer match."] = "톱니바퀴에서 지정한 필터와 일치하는 퀘스트를 더 이상 일치하지 않을 때까지 추적 해제합니다."
L["Experimental Feature"] = "실험적 기능"
L["Experimental Quest Tools"] = "실험적 퀘스트 도구"
L["Quest sorting, filtering and zone auto-tracking are experimental and may cause occasional Lua errors. If you run into one, type /reload or turn this option off."] = "퀘스트 정렬, 필터링 및 지역 자동 추적은 실험적 기능이며 간혹 Lua 오류를 유발할 수 있습니다. 오류 발생 시 /reload를 입력하거나 이 설정을 끄세요."
L["Unlocks Sort Quests, Filter Quests and Auto Track Zone Quests."] = "퀘스트 정렬, 퀘스트 필터링, 지역 퀘스트 자동 추적 기능을 활성화합니다."
L["The interface style changed. Reload so the quest tracker matches it."] = "인터페이스 스타일이 변경되었습니다. 퀘스트 추적기에 반영하려면 UI를 다시 불러오세요."
L["The interface style changed. Type /reload so the quest tracker matches it."] = "인터페이스 스타일이 변경되었습니다. 퀘스트 추적기에 반영하려면 /reload를 입력하세요."
