L["Max rows per section in the Friends Online tooltip (0 = the 30-row max)."] = "접속한 친구 툴팁의 섹션별 최대 줄 수입니다 (0 = 최대 30줄)."
L["Max rows shown per section in the Friends Online tooltip. 0 = no cap."] = "온라인 친구 툴팁의 각 섹션별로 표시할 최대 줄 수입니다. 0으로 설정하면 제한이 없습니다."
L["Middle-click the minimap to open the EllesmereUI micro menu. When off, middle-click does nothing."] = "미니맵을 가운데 클릭하면 EllesmereUI 게임 메뉴가 열립니다. 끄면 가운데 클릭이 아무 동작도 하지 않습니다."
L["New Mail"] = "새 우편"
L["Outer-Group MM Button Size"] = "그룹 외부 미니맵 버튼 크기"
L["Override the size of ungrouped minimap buttons independently from the interactable button size."] = "상호작용 버튼 크기와 독립적으로 그룹 해제된 미니맵 버튼 크기를 재정의합니다."
L["Scales the custom tooltips shown by the unique minimap buttons (Great Vault, friends, calendar, mail, tracking)."] = "미니맵 전용 버튼(위대한 금고, 친구, 달력, 우편, 추적)이 표시하는 사용자 지정 툴팁의 크기를 조절합니다."
L["Scales the Friends, Great Vault and M+ Portals hover panels the extra buttons open."] = "친구, 위대한 금고, 쐐기돌 차원문 마우스 오버 패널의 추가 버튼이 열릴 때 크기 비율을 조절합니다."
L["Scales the M+ Portals flyout the portals button opens."] = "포탈 버튼으로 여는 신화+ 포탈 플라이아웃의 크기를 조절합니다."
L["Show black backgrounds behind minimap indicator buttons (tracking, calendar, mail, crafting, addon buttons, flyout toggle)."] = "미니맵 표시 버튼(추적, 달력, 우편, 제작, 애드온 버튼, 플라이아웃 토글) 뒤에 검은 배경을 표시합니다."
L["Show Coordinates Below Map"] = "미니맵 아래 좌표 표시"
L["Show the expansion landing page (Omnium Folio) button at the bottom-left of the minimap. Use the cog to nudge its position."] = "미니맵 좌측 하단에 확장팩 랜딩 페이지(옴니움 장서) 버튼을 표시합니다. 톱니로 위치를 미세 조정하세요."
L["Show the expansion landing page (Omnium Folio) button on the minimap. Use the cog to choose its corner and nudge its position."] = "미니맵에 확장팩 대문(옴니움 장서) 버튼을 표시합니다. 톱니바퀴 아이콘을 사용해 표시할 구석 위치를 선택하고 세부 위치를 미세 조정할 수 있습니다."
L["Size of addon minimap buttons in the flyout grid"] = "플라이아웃 그리드의 애드온 미니맵 버튼 크기"
L["Size of mail, calendar, tracking, and minimap button group toggle"] = "우편, 달력, 추적, 미니맵 버튼 그룹 토글의 크기"
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position."] = "활성화 시 미니맵 버튼(우편, 달력, 추적, 애드온 버튼)을 쉬프트+클릭하여 원하는 위치로 끌 수 있습니다."
L["When enabled, the extra buttons (Great Vault, M+ Portals, Friends Online, Group Button) and any ungrouped minimap buttons only show while the mouse is over the minimap. The M+ Portals flyout keeps them shown until it closes."] = "활성화하면 추가 버튼(위대한 금고, 신화+ 포탈, 접속한 친구, 그룹 버튼)과 그룹에 속하지 않은 미니맵 버튼이 미니맵에 마우스를 올렸을 때만 표시됩니다. 신화+ 포탈 플라이아웃은 닫힐 때까지 계속 표시됩니다."
L["Which minimap corner the Blizzard element row (tracking, calendar, mail, crafting) builds out from and the direction it grows."] = "블리자드 요소 줄(추적, 달력, 우편, 제작)이 미니맵의 어느 모서리에서 시작해 어느 방향으로 늘어날지 정합니다."
L["Which minimap corner the button row builds out from and the direction it grows."] = "버튼 줄이 미니맵의 어느 모서리에서 시작해 어느 방향으로 늘어날지 정합니다."
L["Zone in Show Blizzard Elements"] = "지역 표시"
