L["Show Addon Compartment"] = "애드온 서랍 표시"
L["Show Blizzard's addon compartment button on the minimap. Use the cog to choose its corner and nudge its position."] = "블리자드 애드온 서랍 버튼을 미니맵에 표시합니다. 톱니에서 모서리 선택과 위치 미세 조정을 할 수 있습니다."
