L["Scales the tracking blips drawn on the map (herbs, ore, quest dots). The map itself keeps its size; other minimap elements are unaffected."] = "지도 위에 그려지는 추적 표시(약초, 광석, 퀘스트 점) 크기를 조절합니다. 지도 자체 크기와 다른 미니맵 요소는 그대로 유지됩니다."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position. While dragging, buttons snap to nearby buttons and the minimap border; hold Ctrl together with Shift to disable snapping."] = "활성화 시 미니맵 버튼(우편, 달력, 추적, 애드온 버튼)을 쉬프트+클릭하여 원하는 위치로 끌 수 있습니다. 끄는 동안 주변 버튼과 미니맵 테두리에 자석처럼 붙습니다. 컨트롤과 쉬프트를 같이 누른 채 끌면 자석이 해제됩니다."
