-- add Chat Tooltip (대화 툴팁)
L["Chat recall is unavailable here. Use Alt+Up and Alt+Down."] = "여기서는 대화 기록 불러오기를 쓸 수 없습니다. Alt+위, Alt+아래를 쓰세요."
L["Abbreviates channel prefixes, like [Party] to [P] and [Guild] to [G]; world channels show their number."] = "[파티]를 [파], [길드]를 [길]처럼 채널 머리말을 줄입니다. 공개 채널은 번호로 표시합니다."
L["Shows General, Trade, Local Defense, World Defense and LFG as letters instead of their channel numbers."] = "일반, 거래, 지역 방어, 전역 방어, 파티 찾기 채널을 번호 대신 글자로 표시합니다."
L["EllesmereUI restyles Blizzard's chat bubbles and turns on the switches it needs. Party and Raid keep your current setting, and everything is put back when you turn this off."] = "EllesmereUI가 블리자드 대화 말풍선 모양을 바꾸고 필요한 설정을 켭니다. 파티와 공격대는 지금 설정을 유지하고, 끄면 모두 원래대로 돌아갑니다."
L["chat tabs border spacing background sidebar friends voice url copy whisper channel abbreviate shortened class color names timestamps timestamp all messages font size bubbles bubble speech balloon nameplate"] = "대화 탭 테두리 간격 배경 사이드바 친구 음성 주소 복사 귓속말 채널 줄임 직업 색상 이름 시간 표시 모든 메시지 글꼴 크기 말풍선 이름표"
L["Copy Chat"] = "대화 복사"
L["Extends the chat background up behind the tabs, and the sidebar to match, for one seamless panel."] = "채팅창 배경을 위쪽 탭 뒤까지 확장하고 사이드바도 이에 맞추어 하나의 일체형 패널로 만듭니다."
L["Hide Tooltip on Hover"] = "마우스 오버 시 툴팁 숨김"
L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "메인 대화창의 크기 조절 손잡이를 숨겨 실수로 크기 변경하는 것을 방지합니다."
L["Saves the most recent lines per chat tab (per character), except Blizzard's combat log window, so they reappear after /reload or relog. Stored separately from layout profiles."] = "블리자드 전투 기록 창을 제외하고 대화 탭별(캐릭터별) 최근 줄을 저장해 /reload 나 재접속 후에도 다시 표시합니다. 레이아웃 프로필과 별도로 저장됩니다."
L["Scroll to Bottom"] = "맨 아래로 스크롤"
L["Voice/Channels"] = "음성/채널"
L["Chat Menu"] = "대화 메뉴"
L["When enabled, Shift+Click any sidebar icon to drag it to a custom position."] = "활성화 시 사이드바 아이콘을 쉬프트+클릭하여 원하는 위치로 끌 수 있습니다."
L["Your chat position is now controlled by Blizzard Edit Mode.\nPlease adjust its position there."] = "채팅창 위치는 이제 블리자드 편집 모드에서 제어합니다.\n해당 메뉴에서 위치를 조정해 주세요."
L["Separates the sidebar from the chat panel and gives it its own background and border."] = "사이드바를 채팅 패널에서 분리해 별도의 배경과 테두리를 적용합니다."
L["Texture drawn over the chat background color."] = "채팅 배경 색상 위에 그려지는 텍스처입니다."
L["Texture drawn over the tab background colors."] = "탭 배경 색상 위에 그려지는 텍스처입니다."
L["Gives the selected tab its own border color."] = "선택한 탭에 별도의 테두리 색상을 적용합니다."
L["Places the tabs inside one continuous chat panel background, including the sidebar when visible."] = "탭을 하나로 이어진 채팅 패널 배경 안에 배치합니다. 사이드바가 보일 때는 사이드바까지 포함합니다."
L["Aligns the tab bar to the outer sidebar edge instead of only the chat panel edge."] = "탭 줄을 채팅 패널 가장자리가 아닌 사이드바 바깥 가장자리에 맞춥니다."
-- add Chat Popup (대화 팝업)
L["A UI reload is needed to apply the extended chat background."] = "확장된 채팅창 배경을 적용하려면 UI를 다시 불러와야 합니다."
L["Outline mode changed. A UI reload is needed to apply."] = "외곽선 모드가 변경되었습니다. 적용을 위해 UI 다시 불러오기가 필요합니다."
