L["Replaces full bar borders with bottom separators using the Pixels border artwork."] = "바 전체 테두리 대신 픽셀 테두리 아트를 사용한 하단 구분선으로 대체합니다."
L["Value Gradient: highest damage, healing or other tracked value is green; lowest is red. Threat windows use green for low threat and red for high threat."] = "수치 그라데이션: 추적 중인 피해량/치유량 등의 최고 수치는 녹색, 최저 수치는 빨간색으로 표시됩니다. 위협 수준 창의 경우 위협이 낮으면 녹색, 높으면 빨간색으로 표시됩니다."
L["Adds a vertical separator between the icon and bar using the bar border"] = "바 테두리를 사용하여 아이콘과 바 사이에 세로 구분선을 추가합니다."
L["Shows the white stripe on the left edge of your own threat bar."] = "자신의 위협 수준 바 좌측에 흰색 강조선을 표시합니다."
L["Threat Gradient: smoothly colors values from green at 0% to red at 100% of pull threat. Click again to use your fixed value color."] = "위협 수준 그라데이션: 어그로 획득 위협의 0%(녹색)부터 100%(빨간색)까지 부드럽게 색상을 적용합니다. 다시 클릭하면 고정 수치 색상을 사용합니다."
L["Bar Border Settings"] = "바 테두리 설정"
L["Replaces each bar's border with a bottom separator, kept inside the window."] = "각 바의 테두리 대신 창 내부에 유지되는 하단 구분선으로 대체합니다."
