L["Split this stack into empty slots repeatedly until only the chosen amount or less remains. Alt+Enter does the same."] = "정한 개수 이하만 남을 때까지 이 묶음을 빈 칸으로 계속 나눕니다. Alt+Enter 도 같습니다."
