L["Display Binds on Equipped / Warbound until Equipped on equipment items in your bags and bank."] = "가방 및 은행에 있는 장비 아이템에 '착용 시 귀속' 또는 '착용 전까지 전투부대 귀속' 여부를 표시합니다."
