L["Drag categories on bag sidebar to reposition, group or ungroup."] = "가방 사이드바의 카테고리를 드래그하여 위치 이동, 그룹화, 그룹 해제할 수 있습니다."
L["Enhanced inventory system with sidebar categories, item levels, and quality borders."] = "사이드바 카테고리, 아이템 레벨, 품질 테두리를 갖춘 향상된 소지품 시스템."
L["Expand Sidebar"] = "사이드바 펼치기"
