L["Font size for stack counts, keystone levels, and dungeon abbreviations."] = "수량, 쐐기돌 단계, 던전 약어의 글자 크기입니다."
L["Grow the bag window (more columns + taller, keeping its shape) so all of the active tab's slots are visible without scrolling. It only grows while open -- switching to a bigger tab enlarges it, smaller tabs keep the size -- and resets when you close the bags. Never smaller than your normal size."] = "활성 탭의 모든 칸이 스크롤 없이 보이도록 가방 창을 (모양을 유지한 채 가로 및 세로로) 키웁니다. 열려 있는 동안에만 커지며 - 더 큰 탭으로 바꾸면 커지고 작은 탭은 크기를 유지 - 가방을 닫으면 초기화됩니다. 기본 크기보다 작아지지는 않습니다."
L["Grow the bag window (more columns + taller, keeping its shape) so all of the active tab's slots are visible without scrolling. It only grows while open -- switching to a bigger tab enlarges it, smaller tabs keep the size -- and resets when you close the bags."] = "활성 탭의 모든 칸이 스크롤 없이 보이도록 가방 창을 (모양을 유지한 채 가로 및 세로로) 키웁니다. 열려 있는 동안에만 커지며 - 더 큰 탭으로 바꾸면 커지고 작은 탭은 크기를 유지 - 가방을 닫으면 초기화됩니다."
L["Hide sidebar categories that have no items in them."] = "아이템이 없는 사이드바 카테고리를 숨깁니다."
L["Hide the warning text at the top of the OneBag view."] = "통합 가방 보기 상단의 경고 글자를 숨깁니다."
L["Hides Pinned Items. Re-show in settings."] = "고정한 아이템을 숨깁니다. 설정에서 다시 표시할 수 있습니다."
L["Hides Recent Items. Re-show in settings."] = "최근 아이템을 숨깁니다. 설정에서 다시 표시할 수 있습니다."
L["Hides the Add Category button at the bottom of the bag sidebar."] = "가방 사이드바 하단의 '카테고리 추가' 버튼을 숨깁니다."
L["In the All Items bag view, show each category's items under indented expansion sub-headers (newest expansions first), even when everything in that category is from one expansion."] = "모든 아이템 가방 보기에서, 한 카테고리의 아이템이 모두 한 확장팩 것이더라도 각 카테고리의 아이템을 확장팩별 하위 제목(최신 확장팩 먼저) 아래에 들여써서 표시합니다."
L["MultiBag uses Blizzard's built-in sorting system, which reorganizes the items in your default Blizzard bags. The changes persist even if you disable EllesmereUI Bags."] = "멀티 가방은 블리자드 기본 정렬 시스템을 사용하며, 기본 블리자드 가방의 아이템을 재배치합니다. EllesmereUI Bags 를 꺼도 변경은 유지됩니다."
L["Open bags and bank to the OneBag/OneBank view by default instead of categorized views."] = "카테고리 보기 대신 기본으로 통합 가방/통합 은행 보기로 가방 및 은행을 엽니다."
