L["That setting is stored by list position and can't be safely overridden."] = "이 설정은 목록 위치로 저장되어 안전하게 재정의할 수 없습니다."
L["The active override's Buff Manager is bound to the open page. Leave the Buff Manager tab to switch overrides."] = "활성 재정의의 강화 효과 관리자가 열린 페이지에 묶여 있습니다. 재정의를 전환하려면 강화 효과 관리자 탭을 벗어나세요."
L["The active override's custom Buff Manager is bound to this page. Leave the Buff Manager tab to switch to another override."] = "활성 재정의의 사용자 지정 강화 효과 관리자가 이 페이지에 묶여 있습니다. 다른 재정의로 전환하려면 강화 효과 관리자 탭을 벗어나세요."
L["This condition is coming in a future update."] = "이 조건은 향후 업데이트에서 추가됩니다."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "이 조건은 지금 활성 상태가 아닙니다. 조건 중 하나를 먼저 충족하세요(예: 던전 입장). 그래야 실제 상황에서 배치를 정리할 수 있습니다."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "이 그룹의 사용자 지정 강화 효과 관리자는 해당 전문화 중 하나를 플레이하는 동안에만 활성화하거나 편집할 수 있습니다."
L["This module is excluded from Spec Overrides."] = "이 추가기능은 전문화 재정의에서 제외됩니다."
L["This page is excluded from overrides."] = "이 페이지는 재정의에서 제외됩니다."
L["This setting already has an override for %s"] = "이 설정은 이미 %s에 대한 재정의가 있습니다"
L["This setting can't be overridden."] = "이 설정은 재정의할 수 없습니다."
L["This will create a fully unique Buff Manager for this conditional group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect it."] = "이 조건 그룹에 완전히 독립적인 강화 효과 관리자를 만듭니다. 현재 강화 효과 관리자 설정이 시작점으로 복사되며, 이후 기본 강화 효과 관리자를 변경해도 여기에 영향을 주지 않습니다."
L["This will create a fully unique Buff Manager for this override group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect these specs."] = "이 재정의 그룹에 완전히 독립적인 강화 효과 관리자를 만듭니다. 현재 강화 효과 관리자 설정이 시작점으로 복사되며, 이후 기본 강화 효과 관리자를 변경해도 이 전문화들에 영향을 주지 않습니다."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "이 조건 그룹에 완전히 독립적인 잠금 해제 모드를 만듭니다. 이후 기본 잠금 해제 모드를 변경해도 여기에 영향을 주지 않습니다."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "이 재정의 그룹에 완전히 독립적인 잠금 해제 모드를 만듭니다. 이후 기본 잠금 해제 모드를 변경해도 이 전문화들에 영향을 주지 않습니다."
L["Toggle Key"] = "전환 키"
L["Ungrouped"] = "그룹 없음"
L["View All / Remove Overrides"] = "전체 보기 / 재정의 제거"
L["Your current spec has its own custom Buff Manager, so conditional Buff Managers never apply to it."] = "현재 전문화에는 자체 사용자 지정 강화 효과 관리자가 있어, 조건부 강화 효과 관리자가 적용되지 않습니다."
L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "현재 전문화에는 자체 사용자 지정 잠금 해제 모드가 있어, 조건부 잠금 해제 모드가 적용되지 않습니다. 이를 사용자 지정하려면 없는 전문화로 전환하세요."
