L["Party Frames kit override: Debuff Size %d (Party > Frame Style)"] = "파티 프레임 키트 재정의: 약화 효과 크기 %d (파티 > 프레임 스타일)"
L["These overrides hold their own debuff settings."] = "이 재정의는 자체 약화 효과 설정을 사용합니다."
