L["Remove the stranded '%s' override for %s? The spec returns to the shared default."] = "고립된 '%s' 재정의를 %s에서 제거할까요? 해당 전문화는 공유 기본값으로 돌아갑니다."
L["Rescue tool for a profile built inside an override: the selected group's settings and layouts become this profile's own baseline, then ALL spec override groups are deleted. Conditional overrides are not affected."] = "재정의 안에 만들어진 프로필을 위한 복구 도구: 선택한 그룹의 설정과 배치가 이 프로필의 기준이 되고, 모든 전문화 재정의 그룹이 삭제됩니다. 조건부 재정의는 영향받지 않습니다."
