L["The damage and tank cut of Light of Nitex. The same style refocused on your rotation, procs, and cooldowns front and center."] = "Light of Nitex의 딜러/탱커 버전. 같은 스타일을 순환, 발동 효과, 재사용 대기시간에 다시 집중해 중앙에 배치합니다."
L["The dark counterpart to Lazar's Dawn. A moody, high-contrast layout that keeps focus locked on the fight."] = "Lazar's Dawn의 다크 버전. 전투에 집중을 고정하는 무겁고 대비가 강한 레이아웃입니다."
