-- (batch 2: 가져오기/내보내기/전환 UI)
L["Apply the sharer's Blizzard Skins+ Window Skins and Tooltips & Menus settings. These are account-wide and will overwrite yours across ALL profiles. Off = keep your own."] = "공유자의 블리자드 스킨+ 창 스킨과 툴팁 및 메뉴 설정을 적용합니다. 이 설정은 계정 전체에 적용되며 모든 프로필에서 내 설정을 덮어씁니다. 끄면 내 설정을 유지합니다."
L["Export All Data with Profile"] = "프로필과 모든 데이터 내보내기"
L["Full Export"] = "전체 내보내기"
L["Include your Blizzard Skins+ settings from the Window Skins and Tooltips & Menus tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "창 스킨과 툴팁 및 메뉴 탭의 블리자드 스킨+ 설정을 포함합니다. 이 설정은 계정 전체에 적용되며, 가져오는 사람이 선택하면 그 사용자의 모든 프로필 설정을 덮어씁니다."
L["Override to Promote"] = "전환할 재정의"
L["Overwrite Window & Tooltip Settings?"] = "창 및 툴팁 설정을 덮어쓸까요?"
L["Presets"] = "프리셋"
L["Regular Import"] = "일반 가져오기"
L["This cannot be undone. Consider exporting this profile as a backup first."] = "되돌릴 수 없습니다. 먼저 이 프로필을 백업으로 내보내는 것을 권장합니다."
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "이 내보내기는 편의 기능, Hovercast 등 표준 프로필과 보통 공유하지 않아야 할 프로필 간 설정을 포함하며, 가져오는 사용자의 설정을 덮어씁니다. 프로필을 공개적으로 공유하는 데는 권장하지 않습니다."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "재정의 '%s'의 설정으로 이 프로필 설정을 영구적으로 덮어씁니다: 캡처된 설정과 사용자 지정 잠금 해제 모드 및 강화 효과 관리자 배치(있는 경우)가 모든 전문화의 프로필 기준이 됩니다. 이후 이 프로필의 모든 전문화 재정의 그룹이 삭제되고 UI를 다시 불러옵니다. 조건부 재정의는 영향받지 않습니다."
L["Ultrawide Import"] = "울트라와이드 가져오기"
L["UI Scale Mismatch"] = "UI 배율 불일치"
L["Match Scale"] = "배율 맞추기"
L["Keep Mine"] = "내 설정 유지"
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "이 프로필은 UI 배율 %1$d%%에서 만들어졌고, 현재 배율은 %2$d%%입니다. 가져온 프로필에 맞춰 UI 배율을 변경할까요? UI 배율은 프로필별 설정이 아니므로 모든 프로필이 이 배율로 표시되지만, 언제든지 원래 값으로 되돌릴 수 있습니다."
L["Include Overrides"] = "재정의 포함"
L["Import the sharer's complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. This replaces ALL of your own overrides. Off = keep yours untouched."] = "공유한 사람의 재정의 설정 전체를 가져옵니다. 전문화 및 조건부 재정의 값, 그룹, 해당 그룹의 사용자 지정 잠금 해제 모드 배치, 강화 효과 관리자 재정의가 포함됩니다. 내 재정의는 전부 교체됩니다. 끄면 내 설정을 그대로 유지합니다."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "이 프로필 문자열에는 창 및 툴팁 스킨 설정이 들어 있지 않습니다."
L["Could not build the export string."] = "내보내기 문자열을 만들지 못했습니다."
L["Export Failed"] = "내보내기 실패"
L["Import & Reload"] = "가져오기 및 다시 불러오기"
L["Import Full Account Data"] = "전체 계정 데이터 가져오기"
L["This cannot be undone. Export your own profile as a backup first."] = "되돌릴 수 없습니다. 먼저 내 프로필을 백업으로 내보내세요."
L["This profile string does not carry any override data."] = "이 프로필 문자열에는 재정의 데이터가 들어 있지 않습니다."
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "이 문자열은 전체 계정 내보내기입니다. 프로필뿐 아니라 편의 기능, 마우스오버 시전 단축키, 재사용 대기시간 관리자 주문 구성, 잠금 해제 기준점, UI 배율, 프로필 단축키를 포함한 계정 전체 설정이 보낸 사람의 것으로 교체됩니다. 다른 프로필은 유지되지만 같은 이름의 프로필은 교체됩니다."
L["This will replace YOUR Blizzard Skins+ settings (the Window Skins and Tooltips & Menus tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "창 스킨과 툴팁 및 메뉴 탭의 블리자드 스킨+ 설정이 공유자의 것으로 교체되며, 내 모든 프로필에 적용됩니다. 두 탭의 현재 설정은 이후 복구할 수 없습니다."
L["Window skins changed for this profile. A UI reload is needed to apply them."] = "이 프로필의 창 스킨이 변경되었습니다. 적용하려면 UI 다시 불러오기가 필요합니다."
