L["Can Apply Aura"] = "내가 시전 가능한 오라"
L["Shown on Modifier"] = "조합키(Modifier) 사용 시 표시"
L["Party Frames in Small Raids"] = "소규모 공격대 파티 프레임"

--핵심 애드온 - 공격대 /파티 - 툴팁
L["Shows the ping mark on a member's frame when someone pings them (needs Blizzard's Show Pings on Raid Frames setting on)."] = "누군가 파티원을 지정해 신호를 보내면 해당 파티원 프레임에 신호 표시를 나타냅니다 (블리자드 설정의 '공격대 프레임에 신호 표시' 기능이 켜져 있어야 합니다)."
L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "전체 지속 시간이 해당 시간(초) 이하인 약화 효과만 표시합니다. 필터 조건과 함께 적용되며, '제한 없음'을 선택하면 상한선이 적용되지 않습니다."
L["Debuffs caused by any player or player pet. The opposite of Non-Player Auras; checking one clears the other."] = "플레이어 또는 플레이어의 소환수가 부여한 약화 효과입니다. 'NPC(몬스터) 오라'와 반대되는 설정이며, 둘 중 하나를 선택하면 다른 하나는 선택 해제됩니다."
L["Debuffs applied by you or your pet."] = "나 또는 내 소환수가 적용한 약화 효과입니다."
L["Debuffs with the Magic dispel type."] = "마법 해제 유형의 약화 효과입니다."
L["Debuffs with the Curse dispel type."] = "저주 해제 유형의 약화 효과입니다."
L["Debuffs with the Poison dispel type."] = "독 해제 유형의 약화 효과입니다."
L["Debuffs with the Disease dispel type."] = "질병 해제 유형의 약화 효과입니다."
L["Debuffs with the Bleed dispel type."] = "출혈 해제 유형의 약화 효과입니다."
L["Debuffs your own class is able to apply."] = "본인의 직업 스킬로 부여할 수 있는 약화 효과입니다."
L["In raid groups under 10 players, show group 1 as party frames and hide everyone else."] = "10인 미만 공격대에서 파티 1을 파티 프레임으로 표시하고 나머지는 숨깁니다."

--핵심 애드온 - 행동단축바
L["Skyriding (Airborne)"] = "하늘 비행 (비행 중)"
L["Skyriding Mount"] = "하늘 비행 탈것"
L["Mounted"] = "탈것 탑승 중"
L["Enemy Target"] = "적 대상"

--핵심 애드온 - 행동단축바 - 툴팁
L["While you are inside a house or plot."] = "건물 내부나 지정된 부지(주둔지, 농장 등)에 있을 때 적용됩니다."
L["A target you can attack."] = "공격 가능한 대상입니다."
L["Hide while this condition is true"] = "이 조건이 참일 때 숨기기"
L["Reveal on hover only. Combines with the conditions below: hover-reveals while they all pass, stays hidden while any fails."] = "마우스를 올렸을 때만 표시합니다. 아래 조건들과 결합되어 작동합니다. 조건을 '모두 만족'하면 마우스 오버 시 표시되고, 하나라도 만족하지 못하면 숨겨진 상태를 유지합니다."
L["Only while AIRBORNE on a glide-capable mount or flight form. For the mount itself, ground included, use Skyriding Mount."] = "활공 가능한 탈것이나 비행 형태를 타고 '공중에 떠 있는' 동안에만 적용됩니다. 지상을 포함하여 탈것 자체를 조건으로 지정하려면 '하늘 비행 탈것'을 사용하세요."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "블리자드 기본 UI에 기력 바가 표시되는 활공 가능한 탈것에 탑승한 상태(지상 포함)에 적용됩니다. '하늘 비행 (비행 중)' 조건은 여기에 추가로 실제 비행 중이어야 합니다."
L["Dungeons, raids, scenarios, arenas and battlegrounds. Garrisons do not count."] = "던전, 공격대, 시나리오, 투기장 및 전장입니다. 주둔지는 포함되지 않습니다."
L["Druid travel, aquatic and flight forms count as mounted."] = "드루이드의 여행, 바다, 비행 형태도 탈것 탑승 상태로 간주합니다."
L["Five-player dungeons, Mythic+ included. Delves, raids and scenarios do not count."] = "5인 던전입니다(신화+ 포함). 구렁, 공격대, 시나리오는 포함되지 않습니다."
L["While Party Mode is active. Party Mode can start in combat (Bloodlust); secure elements such as action bars then keep their current visibility until combat ends."] = "파티 모드가 켜져 있는 동안 적용됩니다. 파티 모드는 전투 중에도(피의 욕망) 시작될 수 있으며, 이때 행동 단축바 같은 보안 요소는 전투가 끝날 때까지 지금 표시 상태를 유지합니다."
L["Glow Ring"] = "반짝임 고리"
L["Button Overlay"] = "버튼 오버레이"
L["Ring + Overlay"] = "고리 + 오버레이"
L["How Blizzard's next-spell suggestion is drawn on the button. Button Overlay replaces the blue ring with a flat tint, leaving the button edge free for the proc glow."] = "블리자드가 추천하는 다음 주문을 버튼에 표시하는 방식입니다. '버튼 오버레이'는 파란 고리 대신 단색 덮개를 씌워, 버튼 테두리를 발동 시 반짝임용으로 비워 둡니다."
L["Opacity of the Button Overlay tint."] = "버튼 오버레이 색의 불투명도입니다."
L["Button Overlay Color"] = "버튼 오버레이 색상"
L["This option requires the Button Overlay style"] = "이 옵션을 사용하려면 '버튼 오버레이' 스타일이 필요합니다"
L["Moves the blue Assisted Highlight ring outward (or inward at negative values) so it no longer overlaps the proc glow on the same button. With Ring + Overlay the tint resizes along with it, so the two stay flush."] = "파란 보조 강조 효과 고리를 바깥쪽으로(음수면 안쪽으로) 옮겨 같은 버튼의 발동 시 반짝임과 겹치지 않게 합니다. '고리 + 오버레이'에서는 색 덮개도 함께 크기가 바뀌어 둘이 딱 맞게 유지됩니다."
L["Fit Ring to Cropped Buttons"] = "잘라내기 버튼에 고리 맞춤"
L["On Cropped bars, shapes the Assisted Highlight ring to the button instead of a square."] = "잘라내기 형태의 바에서 보조 강조 효과 고리를 정사각형 대신 버튼 모양에 맞춥니다."

--핵심 애드온 - 이름표
L["Hide Border"] = "테두리 숨기기"
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Only Dispellable shows just the buffs that can be dispelled, purged or soothed; Show All shows every buff. With a Dispel Glow style set, every dispellable buff shown glows."] = "적 이름표에 표시할 강화 효과를 지정합니다. '중요'는 블리자드가 적 이름표용으로 지정한 강화 효과와 해제 가능한 효과를 모두 표시하고, '해제 가능만'은 마법 해제, 정화, 진정시킬 수 있는 강화 효과만 표시하며, '모두 표시'는 모든 강화 효과를 표시합니다. 해제 가능 효과 반짝임 모양을 설정해 두면 표시되는 모든 해제 가능 강화 효과가 반짝입니다."
L["Only Dispellable"] = "해제 가능만"
L["a Dispel Glow Style"] = "해제 가능 효과 반짝임 모양"
L["Color by Type"] = "유형별 색상"
L["Color by Type (Magic/Enrage)"] = "유형별 색상 (마법/격노)"
L["This option requires Blizzard's Assisted Highlight to be enabled"] = "이 옵션을 사용하려면 블리자드의 '보조 강조 효과'를 활성화해야 합니다"
L["Assisted Highlight"] = "보조 강조 효과"
L["Assisted Highlight Outset"] = "보조 강조 효과 돌출"
L["This option requires a style that draws the glow ring"] = "이 옵션을 사용하려면 보조 강조 효과 스타일로 반짝임 고리를 선택해야 합니다"

--핵심 애드온 - 지원 및 시전바
L["Queue Timer Style"] = "대기열 타이머 스타일"
L["Text Offset Y"] = "텍스트 Y축 오프셋"
L["Not Skyriding (Airborne)"] = "하늘 비행 중 아님 (공중)"
L["Countdown Text Color"] = "초읽기 글자 색상"
L["Resting"] = "휴식 중"
L["In Vehicle"] = "탈것 탑승 중"
L["While seated in a vehicle."] = "탈것에 탑승해 있는 동안."
L["While resting, in a city or at an inn."] = "대도시나 여관 등에서 휴식 중인 동안."

--핵심 애드온 - 지원 및 시전바 - 툴팁
L["Moves the countdown number up or down relative to the bar."] = "바를 기준으로 초읽기 숫자를 위 또는 아래로 이동합니다."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size. bar height and text offset."] = "대기열 수락 팝업 아래에 수락할 수 있는 남은 시간을 나타내는 초읽기 바를 표시합니다. 스킨 적용 여부와 관계없이 작동합니다. 색상 견본과 톱니바퀴 아이콘을 사용하여 초읽기 글자 색상, 글자 크기, 바 높이, 글자 위치를 설정할 수 있습니다."
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "이 요소는 '표시' 조건 중 하나만 일치해도 즉시 표시됩니다. '숨기기'는 두 일치 모드 모두에서 원래의 의미를 유지합니다. '숨기기'에 체크되어 있으면 모든 행에서 항상 숨겨집니다."
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "하늘 비행(비행 중)의 정반대 조건: 활강 가능한 탈것이나 비행 변신 상태로 공중에 떠 있지 않은 모든 상태(지상에 서 있는 상태 포함)를 의미합니다."

--핵심 애드온 - 유닛 프레임 
L["Hide Trailing Zeros"] = "소수점 끝의 0 숨기기"
L["Frame Source & Visibility"] = "프레임 출처 및 표시 여부"
L["Show When Health Missing"] = "생명력이 줄었을 때 표시"
L["Shows the frame while this unit is below full health; while enabled, a frame hidden by its visibility setting can still be clicked."] = "이 유닛의 생명력이 가득 차 있지 않으면 프레임을 표시합니다. 켜 두면 표시 여부 설정으로 숨겨진 프레임도 클릭할 수 있습니다."
L["Change health visibility out of combat"] = "전투 밖에서 변경 가능"
L["the Frame Source to be EllesmereUI"] = "프레임 출처 EllesmereUI"
L["Due to Blizzard API restrictions, Blizzard's native target-of-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Target frame's source -- both Blizzard Default, or both EllesmereUI."] = "블리자드 API 제한 때문에 블리자드 기본 대상의 대상 프레임은 전투 중에 숨길 수 없어, 전투 내내 표시됩니다. 권장: 대상 프레임과 출처를 맞추세요 - 둘 다 블리자드 기본이거나 둘 다 EllesmereUI."
L["Due to Blizzard API restrictions, Blizzard's native focus-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Focus frame's source -- both Blizzard Default, or both EllesmereUI."] = "블리자드 API 제한 때문에 블리자드 기본 주시 대상의 대상 프레임은 전투 중에 숨길 수 없어, 전투 내내 표시됩니다. 권장: 주시 프레임과 출처를 맞추세요 - 둘 다 블리자드 기본이거나 둘 다 EllesmereUI."
L["\"Blizzard Default\" is only available when the Target frame's source is set to Blizzard Default -- the target-of-target then comes from Blizzard's target frame."] = "'블리자드 기본'은 대상 프레임의 출처가 블리자드 기본일 때만 쓸 수 있습니다 - 그때 대상의 대상은 블리자드 대상 프레임에서 나옵니다."
L["\"Blizzard Default\" is only available when the Focus frame's source is set to Blizzard Default -- the focus-target then comes from Blizzard's focus frame."] = "'블리자드 기본'은 주시 프레임의 출처가 블리자드 기본일 때만 쓸 수 있습니다 - 그때 주시 대상의 대상은 블리자드 주시 프레임에서 나옵니다."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "이 프레임의 현재 설정을 덮어씁니다. 프레임 위치, 표시 여부, 사용 여부는 바뀌지 않습니다."
L["Dark Mode drives a Dark Mode override condition and can't be changed while editing an override"] = "다크 모드는 다크 모드 덮어쓰기 조건을 정하는 값이라, 덮어쓰기를 편집하는 동안에는 바꿀 수 없습니다"
L["Apply Border Size to all Frames"] = "테두리 크기 모든 프레임에 적용"
L["Focus Tracked Auras"] = "주시 추적 오라"
L["Boss Tracked Auras"] = "우두머리 추적 오라"
L["Tracked Auras"] = "추적 오라"
L["Included debuffs show in addition to your Debuff Filter selection (unless it is set to Only Tracked Auras)."] = "여기 넣은 약화 효과는 약화 효과 필터 선택과 별개로 추가로 표시됩니다('추적된 오라만'으로 설정한 경우는 제외)."
L["You are displaying NO debuffs at all."] = "약화 효과를 전혀 표시하지 않고 있습니다."
L["You are displaying NO buffs at all."] = "강화 효과를 전혀 표시하지 않고 있습니다."
L["Blizz Colored Target Header"] = "블리자드식 대상 이름 배경 바 색상"
L["Colors the strip behind the target's name by its reaction."] = "대상 이름 뒤의 배경 표시줄을 대상의 반응(적대, 중립, 우호)에 따라 색칠합니다."
L["Custom Colors"] = "사용자 지정 색상"
L["Class Reactive"] = "직업 반응형"
L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "생명력 바를 한 가지 색 대신 남은 생명력에 따라 색칠합니다. '클래식'은 가득 찼을 때 초록에서 노랑을 거쳐 비었을 때 빨강이 됩니다. '사용자 지정 색상'은 이 줄의 세 색상 견본(가득 100%, 절반 50%, 없음 0%) 사이를 섞습니다. '직업 반응형'은 가득 찼을 때 직업 색상으로 시작해 피해를 받을수록 50%와 0% 색상으로 번집니다. '끔'이면 채우기 색상 견본이 그대로 쓰입니다. 어느 쪽이든 아래 그라데이션은 여기서 고른 색에서 시작해 계속 적용됩니다."
L["Level Text: Difficulty Color"] = "레벨 글자: 난이도 색상"
L["Colors level text by difficulty, from grey (trivial) through green, yellow and orange to red (5+ levels above you)."] = "레벨 글자를 난이도에 따라 회색(아주 쉬움)부터 초록, 노랑, 주황을 거쳐 빨강(나보다 5레벨 이상 높음)까지 색칠합니다."
L["Level Text: Include Friendly"] = "레벨 글자: 우호 대상 포함"
L["Friendly units get their level's color too, instead of gold."] = "우호 유닛도 금색 대신 레벨에 맞는 색을 씁니다."
L["Difficulty Color"] = "난이도 색상"
L["Colors an attackable unit's level by difficulty, as the default UI does."] = "기본 UI처럼 공격 가능한 유닛의 레벨을 난이도에 따라 색칠합니다."
L["This option does not apply to the player frame."] = "이 설정은 플레이어 프레임에는 적용되지 않습니다."
L["Power Border Options"] = "자원 바 테두리 설정"
L["Spell Cost Prediction"] = "주문 비용 예측"
L["While you cast, shows on the bar the mana the spell will cost."] = "시전하는 동안 그 주문이 소모할 마나를 바에 표시합니다."
L["Spell Cost Color"] = "주문 비용 색상"
L["Show spell cost preview"] = "주문 비용 미리보기 표시"
L["Hide spell cost preview"] = "주문 비용 미리보기 숨기기"
L["Apply Show Cast Bar and Cast Color to Target and Focus"] = "시전 바 표시와 시전 색상을 대상과 주시에 적용"
L["This client has no Blizzard class resource bar to attach to the frame"] = "이 클라이언트에는 프레임에 붙일 블리자드 직업 자원 바가 없습니다"
L["This option can't be used while Blizzard Class Resource Art is enabled in Resource Bars."] = "자원 바에서 '블리자드 직업 자원 아트'가 켜져 있으면 이 설정을 쓸 수 없습니다."
L["Buffs join the debuff stack as its first rows; debuffs continue on the next row and move as buff rows change."] = "강화 효과가 약화 효과 묶음의 첫 줄로 들어갑니다. 약화 효과는 다음 줄부터 이어지고, 강화 효과 줄 수가 바뀌면 함께 움직입니다."
L["This option is not available on the player frame"] = "플레이어 프레임에서는 쓸 수 없는 설정입니다"
L["This option requires Blizzard Style to be disabled"] = "이 설정을 사용하려면 블리자드 스타일을 꺼야 합니다"
L["Blizzard Border"] = "블리자드 테두리"
L["Purgeable Buffs"] = "해제 가능한 강화 효과"
L["Glow the buffs you can purge or spellsteal"] = "해제하거나 훔칠 수 있는 강화 효과 반짝임"
L["Glow Style"] = "반짝임 모양"
L["Glows the buffs you can purge or spellsteal. Glowing buffs lead the row and have their own Max Buffs count."] = "해제하거나 마법 훔치기로 가져올 수 있는 강화 효과를 반짝이게 합니다. 반짝이는 강화 효과는 줄 맨 앞에 오고, '최대 강화 효과' 개수를 따로 적용합니다."
L["a Glow Style"] = "반짝임 모양"
L["Uncheck All Debuffs to choose how the Show filters combine."] = "'모든 약화 효과'를 끄면 표시 필터를 어떻게 조합할지 고를 수 있습니다."
L["Match Any Filter"] = "필터 하나라도 일치"
L["Shows debuffs that match any checked Show filter (the default)."] = "체크한 표시 필터 중 하나라도 맞는 약화 효과를 표시합니다(기본값)."
L["Match All Filters"] = "모든 필터 일치"
L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You show nothing."] = "체크한 표시 필터에 모두 맞는 약화 효과만 표시합니다(해제 유형들은 하나로 칩니다). '플레이어 외 오라'와 '내가 시전함'처럼 서로 반대인 조합은 아무것도 표시하지 않습니다."
L["From Top Edge"] = "위쪽 끝부터"
L["From Bottom Edge"] = "아래쪽 끝부터"
L["Hide heal absorb preview"] = "치유 흡수 미리보기 숨기기"
L["Above Absorb Bar"] = "흡수 바 위"
L["Shows incoming heals past the health bar: yours, then other players'."] = "들어올 치유량을 생명력 바 뒤쪽에 표시합니다. 내 치유가 먼저, 그다음 다른 플레이어의 치유입니다."
L["Show heal prediction preview"] = "치유 예측 미리보기 표시"
L["Hide heal prediction preview"] = "치유 예측 미리보기 숨기기"
L["Your heals"] = "내 치유"
L["Other players' heals"] = "다른 플레이어의 치유"
L["Flat"] = "단색"
L["Overheal"] = "초과 치유"
L["How far incoming heals can extend past the end of the health bar, as a percent of its length. 0 keeps them inside the bar."] = "들어올 치유가 생명력 바 끝을 넘어 얼마나 더 뻗을 수 있는지를 바 길이에 대한 백분율로 정합니다. 0이면 바 안에만 표시됩니다."
L["Heal Prediction Texture"] = "치유 예측 텍스처"
L["The Combat Indicator is not available for the Focus frame."] = "주시 프레임에는 전투 표시를 쓸 수 없습니다."
