L["Debuffs caused by any player or player pet. The opposite of Non-Player Auras; checking one clears the other"] = "플레이어나 플레이어 소환수가 건 약화 효과입니다. '플레이어 외 오라'의 반대라서 하나를 체크하면 다른 하나는 꺼집니다"
L["Debuffs with the Magic dispel type"] = "해제 유형이 마법인 약화 효과"
L["Debuffs with the Curse dispel type"] = "해제 유형이 저주인 약화 효과"
