L["Debuffs with the Disease dispel type"] = "해제 유형이 질병인 약화 효과"
L["Debuffs with the Bleed dispel type"] = "해제 유형이 출혈인 약화 효과"
L["Debuffs your own class is able to apply"] = "내 직업이 걸 수 있는 약화 효과"
L["New Buff Bar"] = "새 강화 효과 바"
L["New Debuff Bar"] = "새 약화 효과 바"
L["Hide these instead of showing them"] = "표시하는 대신 숨기기"
L["Buffs you can spellsteal or purge"] = "마법 훔치기 또는 해제 가능한 강화 효과"
L["Major defensive cooldowns"] = "주요 생존기"
L["Auras with a dispel type you can dispel"] = "내가 해제할 수 있는 유형의 오라"
L["UNIT FRAME AURA FILTERS"] = "유닛 프레임 오라 필터"
L["Target Tracked Auras"] = "대상 추적 오라"
L["Copy Included/Excluded Spells From:"] = "포함/제외된 주문 복사 대상:"
L["Debuffs Blizzard flags as important"] = "블리자드가 중요하다고 지정한 약화 효과"
L["Fill Color Settings"] = "채우기 색상 설정"
L["Dynamic Color"] = "동적 색상"
L["Only Tracked Auras"] = "추적된 오라만"
L["Important Only"] = "중요 약화 효과만"
L["Important and Own"] = "중요 및 자신이 부여한 약화 효과"
L["Important or Own"] = "중요 또는 자신이 부여한 약화 효과"
L["Not overridable"] = "재정의 불가"

--핵심 애드온 - 유닛 프레임 - 툴팁
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "이 프레임의 추적 오라만 표시합니다. 메뉴 상단의 '추적 오라 편집'에서 추가할 수 있습니다."
L["Shows every debuff on this frame."] = "이 프레임에 모든 약화 효과를 표시합니다."
L["Shows only the debuffs you apply."] = "자신이 부여한 약화 효과만 표시합니다."
L["Shows only debuffs Blizzard flags as important."] = "블리자드가 중요하다고 지정한 약화 효과만 표시합니다."
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "블리자드가 중요하다고 지정한 약화 효과 중 자신이 부여한 것만 표시합니다."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "자신이 부여한 약화 효과와 모든 대상의 중요 약화 효과를 함께 표시합니다."
L["Combines with the conditions below: shows outright once at least one passes, otherwise still reveals on hover. A checked Hide state still hides it, hover included."] = "아래 조건들과 조합됩니다. 조건 중 하나라도 만족하면 항상 표시되고, 만족하지 않더라도 마우스를 올리면 표시됩니다. 단, '숨김' 상태가 선택되어 있으면 마우스를 올려도 계속 숨겨집니다."
L["Makes this the override. It replaces the whole Visibility setting, so the conditions below no longer apply while it does. Click it again to remove the override."] = "이 설정을 전문화 재정의로 지정합니다. 전체 표시 설정을 대체하므로, 재정의가 활성화되어 있는 동안에는 아래 조건들이 적용되지 않습니다. 재정의를 해제하려면 다시 클릭하세요."
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies."] = "재정의할 수 없습니다. 이 조건들은 모든 전문화가 공유하며, 재정의를 편집하고 있지 않을 때만 변경할 수 있습니다. 전문화 재정의가 활성화되면 기본 표시 설정(사용 안 함, 항상 표시, 마우스오버)이 재정의 값으로 완전히 대체되며 여기서 설정한 모든 조건은 무시됩니다."
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies. Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "재정의할 수 없습니다. 이 조건들은 모든 전문화가 공유하며, 재정의를 편집하고 있지 않을 때만 변경할 수 있습니다. 전문화 재정의가 활성화되면 기본 표시 설정(사용 안 함, 항상 표시, 마우스오버)이 재정의 값으로 완전히 대체되며 여기서 설정한 모든 조건은 무시됩니다. 또한 이 요소는 마우스오버 설정이 고정되어 있어 공통 설정을 따르므로, 재정의를 적용하더라도 항상 표시 상태로만 유지됩니다."
L["Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "이 요소는 마우스오버 설정이 고정되어 있습니다. 마우스오버 작동 방식은 공통 설정을 따르므로, 재정의를 적용하더라도 항상 표시 상태로만 유지됩니다."

