--핵심 애드온 - 재사용 대기시간 관리자 - 툴팁
L["Hide every Cooldown Manager glow out of combat and bring them all back the moment you enter combat."] = "비전투 시에는 모든 재사용 대기시간 관리자 반짝임 효과를 숨기고, 전투에 돌입하는 순간 모두 다시 표시합니다."
L["Replaces Buff Glow: the icon glows when its stack count matches the comparison below, using this spell's Buff Glow style (Modern WoW Glow if none is set)."] = "'강화 효과 반짝임'을 대체합니다. 중첩 수가 아래 비교 조건과 일치할 때 해당 주문의 강화 효과 반짝임 스타일(미설정 시 '최신 와우 반짝임')을 적용하여 아이콘이 반짝입니다."
L["Not available in Buff Missing mode"] = "강화 효과 누락 모드에서는 사용할 수 없습니다."
L["Only glow once the buff's stack count matches the comparison set via the gear."] = "톱니바퀴 아이콘을 통해 설정한 비교 조건과 강화 효과의 중첩 수가 일치할 때만 반짝입니다."
L["Hide every Cooldown Manager glow while you are out of combat: proc glows, active state, max stacks, buff and pandemic glows, cooldown ready glows and bar glows.\n\nThey come back the moment you enter combat, including a glow that started before the pull.\n\nApplies to every CDM bar and to the Tracking Bars at once. Glows from other EllesmereUI modules are not affected.\n\nThe Bar Glows page keeps its own per-mapping Only In Combat toggle; this one applies on top of it."] = "비전투 상태일 때 재사용 대기시간 관리자(CDM)의 모든 반짝임 효과(발동 시 반짝임, 강화 효과/오라 발동 시, 최대 충전 시, 강화 효과 및 팬데믹 반짝임, 재사용 준비 시 반짝임, 바 반짝임)를 숨깁니다.\n\n풀링 전에 시작된 반짝임을 포함하여, 전투에 돌입하는 즉시 모두 다시 표시됩니다.\n\n모든 CDM 바와 추적 바에 일괄 적용되며, 다른 EllesmereUI 모듈의 반짝임은 영향을 받지 않습니다.\n\n'바 반짝임' 페이지의 개별 설정보다 이 전역 비전투 숨김 설정이 우선 적용됩니다."
L["How many pixels the custom effect extends beyond the icon."] = "사용자 지정 효과가 아이콘 바깥쪽으로 확장되는 픽셀 크기입니다."
L["Thickness in physical pixels for Solid Border and Pixel Glow."] = "단색 테두리 및 픽셀 반짝임 효과의 물리적 픽셀 두께입니다."
L["Choose the profile-wide border or glow used for Blizzard's Assisted Combat suggestion."] = "블리자드의 '전투 지원' 추천 강조 표시에 사용할 프로필 공용 테두리 또는 반짝임 효과를 선택합니다."

