L["Enter the maximum debuff duration in seconds:"] = "약화 효과 최대 지속시간(초) 입력:"
L["Show a reminder when your Warlock's active pet isn't one of the demons picked in Allowed Demons. A demon only counts while its summon spell is known, so leaving only Felguard picked stays silent for specs/builds that haven't talented Summon Felguard."] = "현재 소환된 악마가 '소환 가능 악마' 목록에 없을 때 알림을 표시합니다. 해당 악마 소환 주문을 배운 상태에서만 체크되므로, '지옥수호병 소환' 특성이 없는 전문화/빌드에서는 지옥수호병만 선택되어 있어도 알림이 발생하지 않습니다."
L["Pick which demons count as correct for Wrong Demon. A demon only counts while its summon spell is known; with none picked (or everything picked), the reminder never fires."] = "'잘못된 악마 소환' 알림에서 정상 소환으로 인정할 악마를 선택합니다. 소환 주문을 배운 악마만 체크되며, 아무것도 선택하지 않거나 모두 선택하면 알림이 울리지 않습니다."
L["Show the Sated/Exhaustion lockout countdown on the icon."] = "아이콘에 만족함/탈진(블러드 약화 효과) 남은 시간 초읽기를 표시합니다."
L["Once the lockout expires, show a Ready label on the icon in place of the countdown. The visibility rule above still applies."] = "대기시간이 만료되면 초읽기 대신 아이콘에 '준비 완료' 문구를 표시합니다. 위의 표시 규칙은 그대로 적용됩니다."

