--편의기능 - 편의기능 - 공격대 도구 - 툴팁
L["Keeps a saved signup note you can copy into the Sign Up dialog with the Copy button."] = "파티 신청 창에 '복사' 버튼으로 손쉽게 붙여넣을 수 있도록 작성한 신청 메모를 저장해 둡니다."
L["Adds three optional world-marker keybinds that remain usable in combat. Place drops the first free marker at the cursor in Star to Skull order; Undo removes the last marker placed through Quick Fire; Clear removes all world markers. Every binding starts empty. Marker changes made elsewhere during combat are picked up afterward."] = "전투 중에도 사용할 수 있는 지면 징표 단축키 3개를 추가합니다. '지면 징표 놓기'는 별부터 해골 순서대로 마우스 커서 위치에 비어 있는 징표를 배치하고, '마지막 징표 취소'는 빠른 징표로 가장 최근에 배치한 징표를 제거하며, '모든 징표 지우기'는 모든 지면 징표를 제거합니다. 단축키는 기본적으로 비어 있습니다. 전투 중에 다른 방식으로 변경된 징표 상태는 전투 종료 후 반영됩니다."
L["Shows the Role Check button in window layouts and enables Right Click: Role Check on Compact Band."] = "창 레이아웃에 역할 확인 버튼을 표시하고, 간편 바에서 우클릭 시 역할 확인 기능을 활성화합니다."
L["Countdown length in seconds. Compact Band uses First with Ctrl + Left Click, Second with Shift + Left Click, Third with Left Click, and Right Click stops the timer. Set a timer to 0 to disable that shortcut."] = "초 단위 초읽기 시간입니다. 간편 바에서는 Ctrl + 좌클릭 시 첫 번째, Shift + 좌클릭 시 두 번째, 좌클릭 시 세 번째 초읽기가 작동하며, 우클릭하면 초읽기를 중지합니다. 단축키를 비활성화하려면 시간을 0으로 설정하세요."

