L["Adds a small filled dot at the center of the cursor circle. Uses the same color and opacity as the circle."] = "커서 원 중앙에 작은 채워진 점을 추가합니다. 원과 동일한 색상 및 투명도가 적용됩니다."

--편의 기능 - 데이터 바 - 툴팁
L["Every condition you set has to match. The default."] = "설정한 모든 조건이 일치해야 합니다. (기본값)"
L["This element shows as soon as ONE condition matches, and a Hide lane then means show while that condition is false."] = "조건 중 하나라도 일치하면 즉시 표시되며, '숨김'으로 지정된 조건은 해당 조건이 만족되지 않을 때(거짓일 때) 표시함을 의미합니다."
L["Any LibDataBroker plugin registered right now. One block per plugin -- add the block again for a second one."] = "현재 등록되어 있는 LibDataBroker 플러그인 목록입니다. 플러그인마다 하나의 블록이 생성되며, 추가로 배치하려면 블록을 다시 추가하세요."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "플러그인의 글자를 표시합니다. 끄면 툴팁 및 클릭 동작은 유지된 채 아이콘만 표시됩니다."
L["Removes the color codes the plugin writes into its own text, so this block's Text Color applies. Off keeps the plugin's colors."] = "플러그인 자체 글자의 색상 코드를 제거하고 이 블록의 '글자 색상'을 적용합니다. 끄면 플러그인 고유 색상이 유지됩니다."
L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "블록 너비를 고정하고 넘치는 글자는 잘라내어, 글자 길이가 수시로 변해도 인접 블록이 밀려나지 않도록 방지합니다. 0으로 설정하면 플러그인의 글자 길이에 맞춰 너비가 자동 조절됩니다."
L["Prefixes the plugin's own name to its text."] = "플러그인의 이름을 글자 앞에 접두어로 붙입니다."
L["Shows the plugin's own icon next to its text."] = "글자 옆에 플러그인의 아이콘을 표시합니다."

