L["Changing the Friend Notifications reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "친구 알림 스킨 스타일(블리자드 / 엘스미어)을 완전히 전환하려면 UI를 다시 불러와야(Reload) 합니다."
L["The friends window backdrop, frame border, tabs, search boxes, bottom buttons and close button. Friend entries stay untouched; Blizz Default keeps the Friends List module's own flat look."] = "친구 창의 배경, 테두리, 탭, 검색창, 하단 버튼 및 닫기 버튼에 스킨을 적용합니다. 친구 목록 항목 자체는 변경되지 않으며, '블리자드 기본'을 선택하면 모듈의 플랫 스타일이 유지됩니다."

