L["RUN SUMMARY"] = "쐐기 요약"
L["Enable Run Summary"] = "쐐기 요약 사용"
L["History Size"] = "기록 보관 개수"
L["Show After Looting"] = "전리품 획득 후 표시"
L["Panel Scale"] = "패널 크기 비율"
L["COLUMNS"] = "표시할 항목"
L["Show Spec Icons"] = "전문화 아이콘 표시"
L["Draws each group's filled slots with EllesmereUI's icons: the member's specialization on a ring, with the leader's crown. Off, the game's own class and role icons stay at their own size (Role Icon Size goes to 100%; back on, to 125%). The same setting as Show Specialization in the window's Group Settings menu."] = "파티의 찬 슬롯을 EllesmereUI 고유 아이콘으로 표시합니다(원형 테두리 안의 전문화 및 파티장 왕관). 끄면 게임 기본 직업 및 역할 아이콘이 기본 크기로 유지됩니다(역할 아이콘 크기가 100%로 변경되며, 다시 켜면 125%로 복귀). 파티 찾기 창의 그룹 설정 메뉴에 있는 '전문화 표시'와 동일한 설정입니다."
L["M+ Score"] = "신화+ 점수"
L["Loot"] = "전리품"
L["%1$d Deaths"] = "사망 %1$d회"
L["(%1$d Chest)"] = "(상자 %1$d개)"

--UI 모양 변경 - 쐐기돌 도구  - 툴팁
L["Combat data stayed restricted for this run"] = "이번 쐐기 진행 중 전투 데이터 기록이 제한되었습니다."
L["Current season score plus the gain from this run. Your own gain is the exact value the server reports; for party members it is their score before the key subtracted from their score after it."] = "현재 시즌 점수에 이번 쐐기 완료로 획득한 점수를 더해 표시합니다. 본인의 점수 상승량은 서버에서 보고한 정확한 값이며, 파티원은 던전 시작 전 점수와 완료 후 점수의 차이로 계산됩니다."
L["Delete every recorded Mythic+ run for this character?"] = "이 캐릭터에 기록된 모든 신화+ 쐐기 기록을 삭제하시겠습니까?"
L["Depleted"] = "소진 (시간 초과)"
L["No loot recorded for this player in this run."] = "이번 쐐기에서 이 플레이어가 획득한 전리품 기록이 없습니다."
L["No runs recorded yet"] = "기록된 쐐기 진행 내역이 없습니다."
L["Open the overview once the end of run chest has been looted. With this off it opens as soon as the key ends. /ov reopens it at any time."] = "던전 완료 상자에서 전리품을 획득한 후 요약창을 엽니다. 이 설정을 끄면 쐐기가 끝나는 즉시 열립니다. 언제든지 /ov 명령어로 다시 열 수 있습니다."
L["Records every finished Mythic+ key and shows an overview of the group when the run ends. Nothing is registered or created while this is off."] = "완료된 모든 신화+ 기록을 저장하고 던전 종료 시 파티 요약창을 표시합니다. 이 설정을 끄면 기록이 저장되지 않습니다."
L["Run Summary is disabled in Mythic+ Tools."] = "쐐기돌 도구에서 '쐐기 요약'이 비활성화되어 있습니다."
L["Score"] = "점수"
L["Shown in grey next to each name. Item levels are read by inspecting party members during the run, so a member who stayed out of range shows none."] = "각 이름 옆에 회색으로 표시됩니다. 아이템 레벨은 던전 진행 중 파티원 살펴보기로 수집하므로, 사거리를 벗어나 있던 파티원은 표시되지 않을 수 있습니다."
L["Size of the player rows. The title and column headers keep their own size."] = "플레이어 행의 크기입니다. 제목 및 열 머리글 크기는 유지됩니다."
L["Taken"] = "받은 피해"
L["What each player looted. Your own chest reward always appears; other players' items only when the server announces the loot to the group, which it does not always do for the end of run chest."] = "각 플레이어가 획득한 전리품입니다. 본인의 상자 보상은 항상 표시되지만, 다른 파티원의 획득 아이템은 서버가 파티에 알림을 보낼 때만 표시됩니다(완료 상자는 항상 알림이 오지 않을 수 있음)."

--UI 모양 변경 - 데미지 미터기
L["Outfits"] = "복장"
L["Show/Hide Windows Keybind"] = "창 표시/숨기기 단축키"
L["Keybind Scope"] = "단축키 적용 범위"
L["Include Combat Timer"] = "전투 타이머 포함"
L["Include Spell History"] = "주문 기록 포함"
L["Unsafe Refresh Rate"] = "비권장 갱신 속도"

-- UI 모양 변경 - 대미지 미터기 - 툴팁
L["Hide and show every damage meter window at once. The state is not saved; a reload restores the configured visibility.\n\nThe bound key is taken over while it is set. Use the cog to include the combat timer and Spell History.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "모든 대미지 미터기 창을 한 번에 표시하거나 숨깁니다. 임시 상태는 저장되지 않으며, UI를 다시 불러오면(Reload) 설정된 표시 상태로 복원됩니다.\n\n단축키가 설정되어 있는 동안에는 해당 키 입력을 전용으로 사용합니다. 톱니바퀴 아이콘을 눌러 전투 타이머 및 주문 기록 창도 함께 제어할 수 있습니다.\n\n좌클릭: 단축키 지정\n우클릭: 단축키 해제"
L["Blizzard damage meter is off"] = "블리자드 미터기가 꺼져 있습니다."
L["Read from Blizzard's own damage meter. With that meter switched off this column, Damage Taken and Interrupts stay empty."] = "블리자드 기본 대미지 미터기에서 데이터를 가져옵니다. 해당 미터기가 꺼져 있으면 이 열과 '받은 피해', '차단' 항목이 빈칸으로 유지됩니다."
L["Faster than 0.5s makes the meters work much harder in combat and can cost you frames, especially with several windows open."] = "갱신 속도를 0.5초보다 빠르게 설정하면 전투 중 미터기 연산량이 급증하여 특히 여러 창이 열려 있을 때 프레임 드랍(렉)이 발생할 수 있습니다."
L["Lets you set Refresh Rate faster than 0.5s. The meters update more often but work much harder in combat, which can cost you frames. Only turn this on if your PC has performance to spare."] = "갱신 속도를 0.5초보다 빠르게 설정할 수 있도록 허용합니다. 미터기 수치가 더 부드럽게 갱신되지만 전투 중 연산 부하가 증가하여 프레임이 떨어질 수 있습니다. PC 사양에 여유가 있을 때만 켜세요."

-- UI 모양 변경 - 대화 - 대화 말풍선
L["Only works outside of Instances"] = "인스턴스 외부에서만 동작"
L["Enable Chat Bubbles Customization"] = "대화 말풍선 커스텀 사용"
L["Chat Bubbles"] = "대화 말풍선"
L["Follow Blizzard Default Color"] = "블리자드 기본 색상 사용"
L["Channels"] = "채널"
L["Say"] = "일반"
L["Yell"] = "외치기"
L["NPCs"] = "NPC"
L["Emotes"] = "감정표현"
L["Hide Chat Bubbles in Instances"] = "인스턴스 내부에서 말풍선 숨기기"
L["Padding"] = "여백"
L["Maximum Width"] = "최대 너비"
L["Vertical Offset"] = "세로 위치"

-- UI 모양 변경 - 대화 - 대화 말풍선  - 툴팁
L["Choose which channels get a bubble."] = "말풍선을 표시할 대화 채널을 선택합니다."
L["Space between the text and the edge of the bubble."] = "글자와 말풍선 테두리 사이의 내부 여백입니다."
L["Font size."] = "글꼴 크기."

--UI 모양 변경 - 가방
L["Show Clear Button"] = "목록 비우기 버튼 표시"
L["GROUPING"] = "그룹화"
L["Group by Category"] = "카테고리별 그룹화"
L["Category Sidebar"] = "카테고리 사이드바"
L["Hide Empty Slots When Grouped"] = "그룹화 시 빈 슬롯 숨기기"
L["Hide Bank Tabs in Sidebar"] = "사이드바에서 은행 탭 숨기기"
L["Stack Splitter"] = "아이템 묶음 분할기"
L["Auto Split"] = "자동 분할"
L["Split Stack"] = "묶음 분할"
L["Empty Slots"] = "빈 슬롯"
L["No Items"] = "아이템 없음"

--UI 모양 변경 -가방 - 툴팁
L["Turn on Category Sidebar first, or the sidebar would have nothing left to navigate with."] = "'카테고리 사이드바' 설정을 먼저 켜야 합니다. 그렇지 않으면 사이드바에 표시할 탐색 메뉴가 없습니다."
L["Right-click a tab in the bank sidebar to rename it or set its deposit filters."] = "은행 사이드바의 탭을 우클릭하여 이름을 변경하거나 보관 필터를 설정할 수 있습니다."
L["Window scale, icon zoom and item level settings are shared with the Bags page."] = "창 크기 비율, 아이콘 확대 및 아이템 레벨 설정은 가방 설정과 공유됩니다."
L["In the OneBank and OneWarbank views, split the grid under expansion headers, newest first. Per-tab views are unaffected."] = "통합 개인 은행 및 통합 전투부대 은행 보기에서 아이템 격자를 확장팩별 머리글로 구분하고 최신 확장팩부터 표시합니다. 탭별 보기에는 영향을 주지 않습니다."
L["List item categories in the bank sidebar the way the bags sidebar does -- groups such as The Armory with Weapons and Armor under them. Selecting one filters the grid to that category. Categories that split further list their parts as a third level while selected: Professions by profession, Armor by equipment slot, Trade Goods by material. Spans your character bank and warband together, so a category shows everything you own."] = "가방 사이드바처럼 은행 사이드바에도 '무기고(무기/방어구)' 등의 아이템 카테고리를 표시합니다. 카테고리를 선택하면 해당 아이템만 필터링되어 격자에 나타납니다. 하위 카테고리는 3단계로 세분화됩니다(전문 기술별, 장비 부위별, 재질별 등). 캐릭터 은행과 전투부대 은행이 통합 검색되므로 보유한 모든 아이템을 한눈에 확인할 수 있습니다."
L["Turn on Nest by Expansion or Group by Category first; the flat view has nowhere to move empty slots to."] = "'확장팩별 분류' 또는 '카테고리별 그룹화'를 먼저 켜야 합니다. 기본 목록 보기에서는 빈 슬롯을 정리할 공간이 없습니다."
L["Split items by category -- Armor, Consumables, Professions and so on -- using the same category list, order and renames as the All Items bag view. Nests inside the expansion headers when Nest by Expansion is also on. Categories that split further do so automatically: gear by equipment slot, Professions and Trade Goods by profession and material type."] = "'모든 아이템' 가방 보기와 동일한 카테고리 목록, 순서, 이름을 사용하여 아이템을 카테고리(방어구, 소모품, 전문 기술 등)별로 분류합니다. '확장팩별 분류'가 켜져 있으면 확장팩 머리글 내부에 분류됩니다. 세부 분류가 있는 카테고리는 장비 부위별 장비, 전문 기술 및 재질별 전문 기술/무역 상품 등으로 자동 분류됩니다."
L["Shift-click a stack in the bags or bank to open a split dialog with an Auto Split button, which splits the stack into empty slots repeatedly until only the chosen amount or less remains. Off uses the default split popup."] = "가방이나 은행에서 아이템 묶음을 Shift+클릭하면 '자동 분할' 버튼이 포함된 분할 창이 열립니다. 설정한 수량 이하가 남을 때까지 빈 슬롯으로 묶음을 반복해서 나눕니다. 끄면 기본 분할 팝업이 열립니다."
L["Drop the individual Tab 1 / Tab 2 / Warbank Tab entries once the category list is doing the navigating. The consolidated views stay. Note that right-clicking a tab entry is the only way to rename a tab or change its deposit filters, so leave this off if you still need that."] = "카테고리 목록이 탐색 기능을 대신 수행하므로 개별 탭 1 / 탭 2 / 전투부대 탭 항목을 제거합니다. 통합 뷰는 유지됩니다. 탭 이름을 변경하거나 보관 필터를 변경하려면 탭을 우클릭하는 것이 유일한 방법이므로, 해당 기능이 필요하다면 이 옵션을 꺼두세요."
L["While either grouping toggle is on, drop the trailing block of empty slots so the view only shows items. Turn this off to keep the free slots visible for depositing."] = "두 그룹화 설정 중 하나라도 켜져 있는 동안, 마지막에 남는 빈 슬롯들을 숨겨 아이템만 깔끔하게 표시합니다. 아이템 보관을 위해 빈 슬롯을 계속 표시하려면 이 설정을 끄세요."

--UI 모양 변경 - 기본 ui 개선 - 툴팁,메뉴&팝업
L["Restyles Blizzard's on-screen progress bars (event objectives, nameplate counters) to the EUI look. Requires reload to apply.\n\nThese bars are drawn over rather than modified, so if the game ever reports their contents as protected the original bar is shown instead.\n\nUse the cog to set a minimum size, so bars on shrunken nameplates stay readable."] = "블리자드 기본 진행 바(이벤트 목표, 이름표 카운터 등)를 EUI 스타일로 변경합니다. 적용하려면 UI를 다시 불러와야(Reload) 합니다.\n\n이 바들은 내부 코드를 변경하는 대신 위에 새로 덧그리는 방식이므로, 게임 내에서 보호 항목으로 지정할 경우 원래의 기본 바가 표시됩니다.\n\n톱니바퀴 아이콘에서 최소 크기를 설정하여 축소된 이름표에서도 진행 바를 또렷하게 볼 수 있습니다."

--UI 모양 변경 - 쐐기돌 도구 - 툴팁
L["Fade a bar when the enemy is beyond your active interrupt spell's range. Has no effect for specs without an interrupt."] = "적이 현재 활성화된 차단 주문의 사거리를 벗어나면 시전 바를 흐리게 표시합니다. 차단기가 없는 전문화에는 효과가 없습니다."
L["Show the enemy's raid target marker to the left of the spell name."] = "시전 주문 이름 왼쪽에 대상의 공격대 징표를 표시합니다."
L["Glow the bar when the enemy casts a spell Blizzard flags as important."] = "적이 블리자드 지정 중요 주문을 시전할 때 시전 바를 반짝입니다."
L["Limit the bars to the selected content and combat states; nothing selected shows them everywhere."] = "선택한 콘텐츠 및 전투 상태에서만 시전 바를 표시합니다. 아무것도 선택하지 않으면 모든 지역에서 항상 표시됩니다."

-- WOW 포에버 - 첫화면 
L["NOW ON WOW FOREVER"] = "WOW 포에버 출시"
L["EllesmereUI Forever"] = "EllesmereUI 포에버"
L["The full suite now runs on WoW Forever, crafted with a clean base layout for your first login."] = "이제 전체 기능이 WoW 포에버에서 실행되며, 첫 로그인 시 깔끔한 기본 레이아웃으로 구성됩니다."
L["Everything from retail, ported to WoW Forever"] = "본섭의 모든 기능이 WoW 포에버로 이식됨"
L["One EllesmereUI: the same install runs on either game"] = "하나의 EllesmereUI: 동일한 설치로 두 게임 모두 구동"
L["Export and import your profiles between the two clients"] = "두 클라이언트 간 프로필 내보내기 및 가져오기"
L["ALSO NEW"] = "신규 기능"
L["Blizzard Style"] = "블리자드 스타일"
L["BLIZZARD ART"] = "블리자드 아트"
L["Keep every EllesmereUI feature and setting, with Blizzard's own art. Pick the look per module in Global Settings -> Style."] = "블리자드 고유의 아트를 통해 모든 EllesmereUI 기능과 설정을 유지합니다. [전역 설정 -> 스타일]에서 모듈별 외형을 선택하세요."
L["On WoW Forever the same install sets itself up on first login."] = "WoW 포에버에서는 동일한 설치 파일이 첫 로그인 시 자동으로 설정됩니다."

-- WOW 포에버 - 편의 기능 -  Swing Timer 
L["SWING TIMER"] = "평타 타이머"
L["Enable Swing Timer"] = "평타 타이머 사용"
L["Only Show In Combat"] = "전투 중일 때만 표시"
L["Highlight Queued Attacks"] = "대기열 공격 강조"
L["Highlight Active Attack"] = "자동 공격 활성화 강조"
L["Active Attack Color"] = "자동 공격 색상"
L["Latency Overlay"] = "지연율 오버레이"
L["Latency Color"] = "지연율 색상"
L["Smooth Swing Timing"] = "부드러운 스윙 타이밍"
L["Attack State"] = "공격 상태"
L["Queued Only"] = "예약만"
L["Queued"] = "예약"
L["Full"] = "전체"
L["Waiting"] = "대기"
L["Queued Only colors and names a queued attack; Full also colors rows while the attack is on or waiting."] = "'예약만'은 예약된 공격에 색상을 입히고 기술 이름을 표시합니다. '전체'는 공격이 켜져 있거나 대기 중인 동안에도 바에 색상을 입힙니다."
L["Attack State Colors"] = "공격 상태 색상"
