L["The current WoW Forever client has a bug that prevents some Action Bars functionality. Bars, buttons and keybinds work; page switching on stance and form changes, conditional bar hiding and empty-slot handling do not. This resolves itself once Blizzard fixes the client."] = "현재 WoW Forever 클라이언트의 버그로 인해 일부 행동 단축바 기능이 정상 작동하지 않습니다. 바, 버튼, 단축키는 정상 작동하나 자세 및 변신 변경 시 페이지 전환, 조건부 바 숨김, 빈 슬롯 처리는 작동하지 않습니다. 이 문제는 블리자드가 클라이언트를 수정하면 자연스럽게 해결됩니다."
