-- == Chat prints (채팅창 print 출력 - 소스 엘키(L/Lf) 삽입 대기) ==================
-- 원본이 print() 에 영문 리터럴을 직접 쓰는 곳들. 엔진 자동번역 밖이라 소스에서
-- L()/Lf() 래핑이 들어가야 적용된다 (보류 목록: project_pending_bags_lwrap 참고).
-- 키는 소스 verbatim (색코드 포함). 디버그 전용 덤프(/dump류)는 제외.
-- (아래 8줄: 각 섹션에 흩어져 있던 기존 채팅 출력 키를 여기로 이동)
L["Cannot open options in combat"] = "전투 중에는 설정을 열 수 없습니다"
L["In-game countdown unavailable in combat; the boss mod pull timer still started."] = "전투 중에는 블리자드 기본 초읽기를 시작할 수 없습니다. 대신 보스 모드의 풀링 초읽기가 시작되었습니다."
L["Raid Tools cannot be toggled by slash command in combat -- use the keybind."] = "전투 중에는 명령어(/)로 공격대 관리 도구를 열고 닫을 수 없습니다. 단축키를 사용하세요."
L["Raid Tools is disabled in the EllesmereUI options."] = "공격대 도구가 EllesmereUI 설정에서 비활성화되어 있습니다."
L["%d junk item(s) could not be sold."] = "잡동사니 %d개를 판매하지 못했습니다."
L["|cff00ff98EllesmereUI:|r Managers intro reset. The announcement popup fires on your next /reload."] = "|cff00ff98EllesmereUI:|r 관리 도구 튜토리얼을 초기화했습니다. 다음 /reload 시 안내 팝업이 다시 표시됩니다."
L["|cff00ff98EllesmereUI:|r Overrides intro reset. The announcement popup fires on your next /reload; the video guide fires on your next click of the overrides glyph."] = "|cff00ff98EllesmereUI:|r 개별 설정(재정의) 튜토리얼을 초기화했습니다. 다음 /reload 시 안내 팝업이, 개별 설정 아이콘 클릭 시 가이드 영상이 다시 표시됩니다."
L["|cff00ff98EllesmereUI:|r Video guides and tutorial tips reset. Badges are back; one-time popups will fire again."] = "|cff00ff98EllesmereUI:|r 가이드 영상 및 튜토리얼 팁을 초기화했습니다. 안내 배지가 복원되며 팝업이 다시 표시됩니다."
L["|cffff6060[EllesmereUI]|r Spec changed: Unlock Mode closed, unsaved layout changes discarded."] = "|cffff6060[EllesmereUI]|r 전문화 변경됨: 잠금 해제 모드가 종료되었으며 저장되지 않은 레이아웃 변경 사항이 취소되었습니다."
L["|cffff6060[EllesmereUI]|r Cannot enter Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r 전투 중에는 잠금 해제 모드를 실행할 수 없습니다."
L["|cff00ccffEllesmere:|r Reload required to create custom bars. Type /reload"] = "|cff00ccffEllesmere:|r 사용자 지정 바 생성을 적용하려면 UI를 다시 불러와야 합니다. /reload를 입력하세요."
L["|cffff5555EllesmereUI Raid Frames:|r layout did not settle after 3 passes; a re-entrant loop was bounded. Please report this if frames look wrong."] = "|cffff5555EllesmereUI 공격대 프레임:|r 3회 시도 후에도 배치가 안정되지 않아 재진입 루프를 제한했습니다. 프레임이 이상해 보이면 제보해 주세요."
L["|cff00ff00[EllesmereUI]|r All hints reset. /reload to see them again."] = "|cff00ff00[EllesmereUI]|r 모든 힌트를 초기화했습니다. 다시 확인하려면 /reload를 입력하세요."
L["|cff00ff00[EllesmereUI]|r UI scale reset. /reload to re-snapshot from your Blizzard scale."] = "|cff00ff00[EllesmereUI]|r UI 배율을 초기화했습니다. 블리자드 기본 배율을 다시 적용하려면 /reload를 입력하세요."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat. Use /eui to view Patch Notes."] = "|cffff6060[EllesmereUI]|r 전투 중에는 설정을 열 수 없습니다. 패치 노트는 /eui 로 볼 수 있습니다."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat."] = "|cffff6060[EllesmereUI]|r 전투 중에는 설정을 열 수 없습니다."
L["|cffff6060[EllesmereUI]|r Cannot toggle Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r 전투 중에는 잠금 해제 모드를 전환할 수 없습니다."
L["|cffff6060[EllesmereUI]|r Options closed -- entering combat."] = "|cffff6060[EllesmereUI]|r 전투에 돌입하여 설정 창을 닫았습니다."
L["|cffff6060[EllesmereUI]|r Party Mode addon is not loaded."] = "|cffff6060[EllesmereUI]|r 파티 모드 애드온이 로드되지 않았습니다."
L["|cffff6060[EllesmereUI]|r Unlock Mode is not available."] = "|cffff6060[EllesmereUI]|r 잠금 해제 모드를 사용할 수 없습니다."
L["|cff0cd29fEllesmereUI CDM:|r Cooldown Viewer settings are managed by EllesmereUI. Edit Mode changes are disabled."] = "|cff0cd29fEllesmereUI CDM:|r 재사용 대기시간 뷰어 설정은 EllesmereUI가 관리합니다. 블리자드 편집 모드에서의 변경은 비활성화됩니다."
L["Raid Tools is hidden in a raid without leader or assist -- none of its buttons work there."] = "공격대 도구는 공격대에서 공격대장 또는 부공격대장 권한이 없으면 숨겨지며, 버튼이 동작하지 않습니다."
L["|cffff6600EllesmereUI:|r Profile data for %1$s was corrupted and has been repaired. Your settings may have been reset to defaults."] = "|cffff6600EllesmereUI:|r %1$s 프로필 데이터가 손상되어 복구했습니다. 설정이 기본값으로 초기화됐을 수 있습니다."
-- 던전 초기화 알림 (SendChatMessage 로 파티/공대에 전송되는 기본 문구)
L["Instance has been reset - you can re-enter now!"] = "던전이 초기화되었습니다 - 다시 입장할 수 있습니다!"
L["Reset failed - there are still players inside the instance."] = "초기화 실패 - 아직 던전 안에 남아 있는 사람이 있습니다."


-- == 행동 단축바 끝 장식 (End Caps) 및 배경 ==
L["Apply End Caps to all Bars"] = "모든 바에 장식 표시 적용"
L["Apply Show Bar Background to all Bars"] = "모든 바에 배경 표시 적용"
L["Micro Menu End Caps"] = "게임 메뉴 장식 표시"
L["End Caps"] = "장식 표시"
L["Left Endcap"] = "왼쪽 장식 표시"
L["Right Endcap"] = "오른쪽 장식 표시"
L["Bag Bar End Caps"] = "가방 바 장식 표시"
L["Show the frame and dividers behind the bar's buttons."] = "바의 버튼 뒤에 프레임과 구분선을 표시합니다."
L["Modern shows gryphons or wyverns by faction, Classic the vanilla gryphons, WoW Forever this client's own."] = "모던은 진영에 따라 그리폰 또는 와이번을 보여주고, 클래식은 오리지널 그리폰을, WoW Forever는 해당 클라이언트의 고유한 장식을 보여줍니다."

-- == 딜사이클 보조 (Rotation Assist) ==
L["Rotation Assist Icon"] = "딜사이클 보조 아이콘"
L["ROTATION ASSIST ICON"] = "딜사이클 보조 아이콘"
L["Show Rotation Assist Icon"] = "딜사이클 보조 아이콘 표시"
L["Only in Combat"] = "전투 중에만"
L["Show GCD"] = "전역 재사용 대기시간(GCD) 표시"
L["Highlight Blizzard's next recommended ability on all CDM bars. Requires Assisted Highlight to be enabled in Blizzard's options. Disabling this hides only the CDM highlight.\n\nPress the normal ability's keybind yourself. This does not cast spells or use the Single-Button Assistant, so it does not add that assistant's global cooldown penalty. Only abilities present on your CDM bars can be highlighted."] = "모든 CDM 바에 블리자드의 다음 추천 스킬을 강조 표시합니다. 블리자드 설정에서 '보조 강조 효과'를 활성화해야 합니다. 이 설정을 끄면 CDM 강조 표시만 숨겨집니다.\n\n해당 스킬의 단축키를 직접 누르십시오. 주문을 직접 시전하거나 '단일 버튼 보조'를 사용하지 않으므로 보조 기능의 전역 재사용 대기시간 페널티가 추가되지 않습니다. CDM 바에 있는 스킬만 강조 표시할 수 있습니다."
L["Show Blizzard's current recommendation in a separate icon. Requires Assisted Highlight to be enabled in Blizzard's options. Press the spell's normal keybind; this display never casts spells. Blizzard supplies one recommendation, not a queue of future casts."] = "독립된 아이콘으로 블리자드의 현재 추천 스킬을 표시합니다. 블리자드 설정에서 '보조 강조 효과'를 활성화해야 합니다. 주문의 원래 단축키를 누르십시오. 이 아이콘은 주문을 시전하지 않습니다. 블리자드는 향후 시전 대기열이 아닌 하나의 추천 스킬만 제공합니다."
L["Show the global cooldown as a swipe over the recommended ability. The swipe shows when the GCD ends; casting, channeling and ability requirements can still delay your next action."] = "추천 스킬 위에 전역 재사용 대기시간(GCD)을 회전 애니메이션으로 표시합니다. 회전 애니메이션은 GCD가 끝나는 시점을 보여주지만, 시전, 채널링 및 기술 요구 조건으로 인해 다음 행동이 여전히 지연될 수 있습니다."
L["Hide outside combat. Unlock Mode shows a placeholder when no recommendation is available."] = "전투 외에는 숨깁니다. 잠금 해제 모드에서는 추천 스킬이 없을 때 임시로 위치를 표시해 둡니다."
L["Horizontal screen offset. You can also drag the Rotation Assist Icon in Unlock Mode."] = "수평 화면 위치입니다. 잠금 해제 모드에서 딜사이클 보조 아이콘을 직접 드래그할 수도 있습니다."
L["Vertical screen offset. You can also drag the Rotation Assist Icon in Unlock Mode."] = "수직 화면 위치입니다. 잠금 해제 모드에서 딜사이클 보조 아이콘을 직접 드래그할 수도 있습니다."
L["Use the CDM keybind mapping. Configure the font, outline, position, background and border with the cog."] = "CDM 단축키 매핑을 사용합니다. 톱니바퀴 버튼에서 글꼴, 외곽선, 위치, 배경 및 테두리를 설정할 수 있습니다."
L["Set opacity to 0% for text without a background."] = "배경이 없는 텍스트로 표시하려면 불투명도를 0%로 설정하세요."
L["Set opacity to 0% to hide the keybind badge border."] = "단축키 배지 테두리를 숨기려면 불투명도를 0%로 설정하세요."

-- == 특성 조건 (Talent Conditions) ==
L["Show this icon only while the talents you pick are taken, or not taken."] = "선택한 특성을 선택했거나 선택하지 않았을 때만 이 아이콘을 표시합니다."
L["Click a talent to require it: Taken, then Not Taken, then cleared. Every condition must hold for the icon to show."] = "특성을 클릭하여 조건을 설정하세요: 선택됨, 선택되지 않음, 조건 없음 순으로 변경됩니다. 아이콘이 표시되려면 모든 조건을 만족해야 합니다."
L["Shown only while this talent is taken"] = "이 특성이 선택되었을 때만 표시됨"
L["Shown only while this talent is NOT taken"] = "이 특성이 선택되지 않았을 때만 표시됨"
L["Conditions on talents not shown above (they still apply):"] = "위에 표시되지 않은 특성 조건 (여전히 적용됨):"
L["Unknown talent"] = "알 수 없는 특성"
L["Talent data is not available right now."] = "지금은 특성 데이터를 사용할 수 없습니다."

-- == 가방, 은행 및 게임패드 ==
L["Include Reagent Bag"] = "재료 가방 포함"
L["Open Bank Slots"] = "은행 칸 열기"
L["Counts the reagent bag's slots along with your regular bags."] = "일반 가방과 함께 재료 가방의 칸 수를 계산합니다."
L["Shows the bag icon next to the slot count."] = "칸 수 옆에 가방 아이콘을 표시합니다."
L["Your base bank slots come with a free bank tab. Open it once to start using your bank."] = "기본 은행 칸에는 무료 은행 탭이 제공됩니다. 은행을 사용하려면 한 번 여십시오."
L["Gamepad"] = "게임패드"
L["Everything here applies only while a controller is connected and WoW's gamepad mode is on."] = "이 곳의 모든 설정은 컨트롤러가 연결되어 있고 WoW의 게임패드 모드가 켜져 있을 때만 적용됩니다."
L["Checked bars hide while a controller is connected and gamepad mode is on, the way Visibility set to Never hides them."] = "컨트롤러가 연결되고 게임패드 모드가 켜져 있는 동안 체크된 바를 숨깁니다 (표시 여부를 '절대 표시 안 함'으로 설정한 것과 동일)."
L["Mouse and keyboard play is unaffected."] = "마우스와 키보드 조작에는 영향을 주지 않습니다."
L["Hide Action Bars"] = "행동 단축바 숨기기"
L["Hidden bars still show in Quick Keybind mode so you can bind them."] = "숨겨진 바도 빠른 단축키 지정 모드에서는 보이므로 단축키를 지정할 수 있습니다."
L["CAST BARS"] = "시전 바"
L["Hide Unit Frames Cast Bar"] = "유닛 프레임 시전 바 숨기기"
L["Hide Resource Bars Cast Bar"] = "직업 자원 바 시전 바 숨기기"
L["Hides the Resource & Cast Bars cast bar while a controller is connected and gamepad mode is on. Blizzard's gamepad interface shows its own."] = "컨트롤러가 연결되고 게임패드 모드가 켜져 있는 동안 직업 자원 및 시전 바의 시전 바를 숨깁니다. 블리자드의 게임패드 인터페이스에는 자체 시전 바가 표시됩니다."
L["This option requires the cast bar in Resource & Cast Bars to be enabled"] = "이 옵션은 직업 자원 및 시전 바에서 시전 바가 활성화되어 있어야 합니다."

-- == 초상화 용 장식 (Portrait Dragon) 및 유닛 프레임 ==
L["Elite Enemy Dragon"] = "정예 용 장식"
L["Enable Elite Enemy Dragon"] = "정예 용 장식 활성화"
L["Dragon Size"] = "용 장식 크기"
L["Dragon Strata"] = "용 장식 프레임 우선순위"
L["Dragon Frame Level"] = "용 장식 프레임 레벨"
L["Curls a gold dragon around the portrait of elite and boss enemies, and a silver one around rares."] = "정예 및 우두머리 적의 초상화 주위에 금테를, 희귀 적의 초상화 주위에는 은테를 두릅니다."
L["Also show the dragon in dungeons and raids, where most enemies are elite."] = "대부분의 적이 정예인 던전 및 공격대에서도 용 장식을 표시합니다."

-- == 신화+ 타이머 (Mythic+ Timer) ==
L["Show/Hide Preview"] = "미리보기 표시/숨김"
L["The Mythic+ timer window in keys."] = "신화+ 쐐기돌 던전 진행 시 타이머 창을 표시합니다."
L["Battlegrounds"] = "전장"
L["Kick Tracker Bars"] = "차단 추적기 바"
L["Kick Tracker Bar Name Size"] = "차단 추적기 바 이름 크기"
L["Kick Tracker Bar Texture"] = "차단 추적기 바 텍스처"
L["Kick Tracker Bar Timer Size"] = "차단 추적기 바 타이머 크기"
L["Kick Tracker Timer Size"] = "차단 추적기 타이머 크기"
L["TIMER BAR"] = "타이머 바"
L["Timer Bar Height"] = "타이머 바 높이"
L["In-Bar Timer"] = "바 내부 타이머"
L["In-Bar Height"] = "바 내부 높이"
L["TITLE AND AFFIXES"] = "던전 이름 및 어픽스"
L["Height of the timer bar. While the timer is inside the bar, In-Bar Height sets the minimum."] = "타이머 바의 높이입니다. 타이머가 바 안에 있을 때는 바 내부 높이가 최소값이 됩니다."
L["Forces Bar Height"] = "적 병력 바 높이"
L["Title/Affix Position"] = "던전 이름/어픽스 위치"
L["Time Position"] = "시간 위치"
L["Percent Position"] = "진행도(퍼센트) 위치"

-- == 신화+ 도구: 차단 추적기 (Kick Tracker) ==
L["Kick Tracker"] = "차단 추적기"
L["Mythic+ timer, Kick Tracker, cast bars and target/focus bars."] = "신화+ 타이머, 차단 추적기, 시전 바 및 대상/주시 대상 바를 설정합니다."
L["KICK TRACKER"] = "차단 추적기"
L["Enable Kick Tracker"] = "차단 추적기 활성화"
L["Who in the group kicked each enemy and when their interrupt comes back, read from Blizzard's own damage meter (which must be on). Others' cooldowns follow their class, spec and talents, read before a key starts; yours follow your own talents."] = "블리자드 기본 미터기(켜져 있어야 함) 데이터를 기반으로 파티원이 차단한 대상과 쿨다운을 추적합니다. 다른 파티원의 쿨다운은 쐐기돌 시작 전 확인된 직업/전문화/특성을 따르며, 플레이어 본인은 현재 특성을 따릅니다."
L["Focus Announce"] = "주시 대상 알림"
L["Tells the party your focus marker at ready checks."] = "전투 준비 확인 시 파티 대화로 자신의 주시 대상 징표를 알립니다."
L["Edit Announce Text"] = "알림 문구 편집"
L["Change the line Focus Announce sends: your own words, with {marker} where your raid marker goes."] = "주시 대상 알림으로 보낼 문구를 변경합니다: {marker} 부분에 자신의 공격대 징표가 들어갑니다."
L["Sent in party chat at the ready check. {marker} stands for your raid marker. Empty brings the default line back."] = "전투 준비 확인 시 파티 대화로 전송됩니다. {marker}는 자신의 공격대 징표를 나타냅니다. 비워두면 기본 문구로 복원됩니다."
L["Nameplate Kick Icons use this to auto-assign kicks when a mob is first marked."] = "이름표 차단 아이콘은 몬스터에게 징표가 처음 지정될 때 이 설정을 기반으로 차단을 자동 배정합니다"
L["Enter your announce line..."] = "알림 문구를 입력하세요..."
L["My Focus Kick is %s"] = "내 주시 대상 차단 징표: %s"
L["The tracker runs in Mythic and Mythic+ dungeons and arenas only; untick one to turn it off there."] = "차단 추적기는 신화 및 신화+ 던전과 투기장에서만 작동합니다. 체크를 해제하면 해당 구역에서는 비활성화됩니다."
L["NAMEPLATE ICON"] = "이름표 아이콘"
L["Show on Nameplates"] = "이름표에 표시"
L["The side of the nameplate the icon sits on."] = "아이콘을 표시할 이름표의 위치입니다."
L["Position Offsets"] = "위치 미세 조정"
L["On EllesmereUI nameplates."] = "EllesmereUI 이름표 적용 시."
L["On Blizzard's or another addon's nameplates."] = "블리자드 기본 또는 다른 애드온 이름표 적용 시."
L["Cooldown Timer"] = "재사용 대기시간 타이머"
L["Timer Position"] = "타이머 위치"
L["Kick icons with their cooldown on the kicked enemies' nameplates."] = "차단당한 적 이름표에 재사용 대기시간이 포함된 차단 아이콘을 표시합니다."
L["Kick Icon"] = "차단 기술 아이콘"
L["Spec Icon"] = "전문화 아이콘"
L["The kicker's interrupt icon, their spec icon or their class icon. A kick the tracker cannot place on a member shows no icon."] = "차단자의 차단 기술 아이콘, 전문화 아이콘 또는 직업 아이콘을 표시합니다. 차단한 파티원을 특정할 수 없는 경우에는 아이콘이 표시되지 않습니다."
L["Show Cooldown Timer"] = "재사용 대기시간 표시"
L["The seconds left on the kicker's interrupt."] = "차단자의 차단 기술 잔여 시간을 초 단위로 표시합니다."
L["Icon Effects"] = "아이콘 효과"
L["The cooldown swipe, a border in the kicker's class color, and greying the icon while the interrupt is on cooldown."] = "재사용 대기 회전 효과, 차단자의 직업 색상 테두리, 재사용 대기 중 흑백 표시 효과를 설정합니다."
L["The dark sweep over the icon that clears as the interrupt comes back."] = "차단 기술 재사용 대기시간이 돌아옴에 따라 아이콘 위를 시계 방향으로 지워나가는 어두운 회전 효과입니다."
L["Class Color Border"] = "직업 색상 테두리"
L["The icon's border in the kicker's class color; black when the game hides the kicker's class."] = "아이콘 테두리를 차단자의 직업 색상으로 표시합니다 (차단자가 숨겨진 경우 검은색)."
L["Grey the icon while the kicker's interrupt is on cooldown."] = "차단자의 차단 기술이 재사용 대기 중인 동안 아이콘을 흑백으로 표시합니다."
L["Show Above Overlapping Nameplates"] = "겹친 이름표 위에 표시"
L["The icons draw over every other nameplate, so an overlapping plate never hides one. When off, an icon stays inside its own nameplate, behind any plate that covers it."] = "이름표가 겹치더라도 아이콘이 다른 모든 이름표 위에 그려지도록 하여 가려지지 않게 합니다. 끄면 해당 이름표 내부에 그려져 겹친 이름표 뒤로 가려집니다."
L["Show Bars"] = "바 표시"
L["A row per group member with an interrupt: the interrupt's icon, their name on a bar in their class color, and the seconds left while it is on cooldown."] = "차단 기술을 보유한 파티원별로 줄을 생성하여 아이콘, 직업 색상 바 위의 이름, 재사용 대기 잔여 시간을 표시합니다."
L["Which way the rows stack."] = "줄이 쌓이는 방향을 설정합니다."
L["Dark Class Color"] = "어두운 직업 색상"
L["Behind each row: a darkened version of the member's class color, or one custom color."] = "각 줄의 배경을 설정합니다: 파티원 직업 색상의 어두운 버전 또는 사용자 지정 단일 색상."
L["Display Elements"] = "표시 요소"
L["Element Settings"] = "요소 설정"
L["Timer"] = "타이머"
L["The interrupt's icon at the end of the row."] = "줄 끝에 표시되는 차단 기술 아이콘입니다."
L["The member's name on the row."] = "줄에 표시되는 파티원의 이름입니다."
L["The seconds left on the interrupt, on the right of its row."] = "해당 줄 우측에 표시되는 차단 잔여 시간입니다."
L["The interrupt's icon, the member's name, the seconds left on the interrupt and the raid marker of the enemy they interrupted."] = "차단 기술 아이콘, 파티원 이름, 차단 잔여 시간, 차단한 적의 공격대 징표를 표시합니다."
