L["Your group's interrupts on the enemy nameplates themselves: who kicked what, who is ready next and where the next kick should land. It keeps working inside Mythic+ keys."] = "적 이름표에 파티원의 차단 현황을 직접 표시합니다. 누가 어떤 대상을 차단했는지, 다음 차단이 준비된 사람은 누구인지, 다음 차단을 넣을 대상은 어디인지 한눈에 확인할 수 있습니다. 신화+ 쐐기돌 던전에서도 정상 작동합니다."
