L["Grid shows item icons in a grid. List shows one row per item, grouped by category with a Junk section at the end (OneBag and MultiBag keep slot order, as in the grid): click a column name on the bag window to sort within each category, drag it to reorder, or right-click it to add or remove columns. Requires a UI reload."] = "격자는 아이콘을 바둑판 배열로 표시합니다. 목록은 범주별로 분류하고 끝에 잡동사니 항목을 두어 아이콘 대신 한 줄씩 표시합니다(단일 가방 및 다중 가방은 격자와 동일하게 슬롯 순서를 유지합니다). 가방 창에서 열 이름을 클릭하여 범주 내에서 정렬하거나, 드래그하여 순서를 변경하거나, 우클릭하여 열을 추가/제거할 수 있습니다. UI 재시작이 필요합니다."
L["Show one row per item instead of the icon grid, with the same columns, sorting and round icon option as the bags List display. Empty slots and headers with no items are hidden. Click a column name on the bank window to sort, drag it to reorder, or right-click it to add or remove columns. Requires a UI reload."] = "아이콘 격자 대신 아이템당 한 줄씩 표시하며, 가방 목록 표시와 동일한 열, 정렬, 둥근 아이콘 옵션을 사용합니다. 빈 슬롯과 아이템이 없는 제목은 숨겨집니다. 은행 창에서 열 이름을 클릭하여 정렬하거나, 드래그하여 순서를 변경하거나, 우클릭하여 열을 추가/제거할 수 있습니다. UI 재시작이 필요합니다."
L["Show the item icons in the bag and bank lists as circles instead of squares."] = "가방 및 은행 목록의 아이템 아이콘을 사각형 대신 원형으로 표시합니다."
L["Text size of the bag and bank lists."] = "가방 및 은행 목록의 글자 크기입니다."
L["The List View never shows empty slots."] = "목록 보기에서는 빈 슬롯이 표시되지 않습니다."
