-- 2026-09-20 신규 (스타일 전환 및 주문 시전 편의 기능)
L["Always casts your highest rank."] = "항상 최고 레벨(랭크) 주문을 시전합니다."
L["Before a binding casts, cancel any spell still waiting for a target (the glowing hand cursor left by a cast on a unit it can't take), so the press casts instead of being swallowed."] = "단축키가 시전되기 전에, 대상을 기다리며 대기 중인 주문(유효하지 않은 유닛 시전으로 남은 반짝이는 손 커서)을 취소하여 키 입력이 씹히지 않고 시전되도록 합니다."
L["The interface style changed. Reload so the bags match it."] = "인터페이스 스타일이 변경되었습니다. 가방에 적용하려면 UI를 다시 불러오세요."
L["The interface style changed. Type /reload so the bags match it."] = "인터페이스 스타일이 변경되었습니다. 가방에 적용하려면 /reload 를 입력하세요."
L["The interface style changed. Reload so the action bars match it."] = "인터페이스 스타일이 변경되었습니다. 행동 단축바에 적용하려면 UI를 다시 불러오세요."
L["The interface style changed. Type /reload so the action bars match it."] = "인터페이스 스타일이 변경되었습니다. 행동 단축바에 적용하려면 /reload를 입력하세요."
L["EllesmereUI Style, Blizzard Style and Classic WoW UI reload the UI once to apply. Each module can be switched separately later."] = "EllesmereUI 스타일, 블리자드 스타일 및 클래식 WoW UI는 적용을 위해 UI를 한 번 다시 불러옵니다. 각 모듈은 나중에 개별적으로 전환할 수 있습니다."
L["Every look but the one in use reloads the UI once to apply. Each module can be switched separately later."] = "현재 사용 중인 모양 외의 다른 모양은 적용을 위해 UI를 한 번 다시 불러옵니다. 각 모듈은 나중에 개별적으로 전환할 수 있습니다."
L["WoW Forever, Blizzard Style and Classic WoW UI reload the UI once to apply. Each module can be switched separately later."] = "WoW Forever, 블리자드 스타일 및 클래식 WoW UI는 적용을 위해 UI를 한 번 다시 불러옵니다. 각 모듈은 나중에 개별적으로 전환할 수 있습니다."
L["Cooldown Manager spells from the other game client were not imported."] = "다른 게임 클라이언트의 재사용 대기시간 관리자 주문은 가져오지 않았습니다."
L["Its Cooldown Manager spells come from the other game client and will not be imported."] = "이 재사용 대기시간 관리자 주문은 다른 게임 클라이언트의 주문이므로 가져오지 않습니다."

