-- == 공통 신규 툴팁 및 옵션 (Shared: 가방, 이름표, 행동 단축바, 유닛 프레임 등) ==
L["Which part of the row stays in place as reminders appear and disappear."] = "알림 아이콘이 나타나고 사라질 때 행의 어느 위치를 고정할지 설정합니다."
L["Sell Junk"] = "잡동사니 판매"
L["Height of each row in the bag and bank lists. Icons shrink to fit short rows."] = "가방 및 은행 목록의 각 행 높이입니다. 행 높이가 낮아지면 아이콘도 크기에 맞게 축소됩니다."
L["Remove the shading on every other row in the bag and bank lists."] = "가방 및 은행 목록에서 한 줄 건너 들어가는 교차 음영을 제거합니다."
L["Draw a border in the item's quality color around item icons in the bags and bank. Round list icons have no border."] = "가방과 은행의 아이템 아이콘 주변에 아이템 등급 색상으로 테두리를 그립니다. 목록의 원형 아이콘에는 테두리가 없습니다."
L["Show the total vendor sell price of each section's items next to its count in the bag list."] = "가방 목록에서 각 섹션의 아이템 개수 옆에 상점 총 판매 가격을 표시합니다."
L["Adds Mana to the Attributes section."] = "기본 능력치 섹션에 마나를 추가합니다."
L["Shows the item level and stat titles in Blizzard's yellow."] = "아이템 레벨과 능력치 제목을 블리자드 기본 노란색으로 표시합니다."
L["Character Sheet: Blizz Default"] = "캐릭터 창: 블리자드 기본"
L["Choose what shows on each equipped item."] = "착용 중인 각 장비에 표시할 정보를 선택합니다."
L["Choose which channels show the speaker."] = "말한 사람(화자)을 표시할 채널을 선택합니다."
L["Auto Size"] = "자동 크기 조절"
L["Hide the arrows beside equipment slots on the Equipment tab. The slot flyouts remain usable."] = "장비 탭의 장비 슬롯 옆에 있는 화살표를 숨깁니다. 슬롯 펼침 메뉴는 계속 사용할 수 있습니다."
L["How enchants show beside each item."] = "각 아이템 옆에 마법부여를 표시하는 방식입니다."
L["Items below this quality are not shown."] = "이 등급 미만의 아이템은 표시하지 않습니다."
L["Show each item's main and secondary stat (or its armor) and each weapon's damage per second beside its slot."] = "각 슬롯 옆에 아이템의 주 능력치 및 보조 능력치(또는 방어도)와 무기의 초당 공격력(DPS)을 표시합니다."
L["The dots at the two ends of the track."] = "경로의 양쪽 끝에 있는 점입니다."
L["Threat Gap shows on your target's plate only."] = "위협 차이는 현재 대상의 이름표에만 표시됩니다."
L["Color by Threat"] = "위협에 따라 색상 지정"
L["Colors the number by threat status. Off shows it in white."] = "위협 상태에 따라 숫자의 색상을 지정합니다. 끄면 흰색으로 표시됩니다."
L["Colors the number. Off shows it in white."] = "숫자에 색상을 적용합니다. 끄면 흰색으로 표시됩니다."
L["Only show the meter while there is threat to list. Unchecked keeps the header and its buttons on screen."] = "표시할 위협이 있을 때만 미터를 표시합니다. 체크 해제하면 헤더와 버튼이 화면에 계속 유지됩니다."
L["Percent of the end caps' normal size."] = "장식의 기본 크기 대비 백분율(%)입니다."
L["Positive values move both end caps away from the bar."] = "양수 값을 입력하면 장식이 바 바깥쪽으로 이동합니다."
L["Pull % reaches 100 where a player would take aggro, Tank % where they match the tank's threat."] = "'어그로 %'는 플레이어가 어그로를 획득하는 순간 100%에 도달하며, '탱커 %'는 탱커의 위협과 동일해지는 지점입니다."
L["This class has ten debuffs."] = "이 직업은 이미 최대 개수(10개)의 약화 효과가 등록되어 있습니다."
L["Thickens the border by this many pixels while it shows a debuff color."] = "약화 효과 색상이 표시되는 동안 테두리를 이 픽셀만큼 두껍게 만듭니다."
L["Where nameplates show threat colors."] = "이름표에 위협 색상을 표시할 위치입니다."
L["Also applies the target Border Color and Border Size effects to friendly nameplates."] = "아군 이름표에도 대상 테두리 색상 및 테두리 크기 효과를 함께 적용합니다."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Only Dispellable shows just the buffs that can be dispelled, purged or soothed; Show All shows every buff. With Show Glow on (in the cog), every dispellable buff shown gets a border."] = "이름표에 표시할 적의 강화 효과를 선택합니다. '중요'는 블리자드가 적 이름표용으로 지정한 강화 효과와 해제 가능한 효과를 표시합니다. '해제 가능만'은 마법 해제, 마법 훔치기 또는 격노 해제가 가능한 효과만 표시합니다. '모두 표시'는 모든 강화 효과를 표시합니다. 톱니바퀴의 '반짝임 표시'를 켜면 표시되는 모든 해제 가능 강화 효과에 테두리가 표시됩니다."
L["Choose this text's slot position."] = "이 글자가 표시될 슬롯 위치를 선택합니다."
L["Draws the border style's seam line between the health and cast bars."] = "생명력 바와 시전 바 사이에 테두리 스타일의 경계선을 그립니다."
L["Gives debuff, buff and crowd control icons the custom border instead of the 1-pixel border."] = "약화 효과, 강화 효과 및 군중 제어 아이콘에 1픽셀 테두리 대신 사용자 지정 테두리를 적용합니다."
L["Gives the cast bar spell icon the custom border instead of its 1-pixel border."] = "시전 바 주문 아이콘에 1픽셀 테두리 대신 사용자 지정 테두리를 적용합니다."
L["Shows the level box right of the health bar; with it off, Left Text can show the level instead."] = "생명력 바 오른쪽에 레벨 상자를 표시합니다. 끄면 왼쪽 글자에 레벨을 대신 표시할 수 있습니다."
L["This option requires at least one aura type to show its border."] = "이 설정은 테두리를 표시하도록 설정된 효과(오라) 유형이 하나 이상 있어야 합니다."
L["This option requires two debuffs for the same class"] = "이 설정은 동일 직업의 약화 효과가 2개 이상 선택되어 있어야 합니다."
L["This option requires a debuff to be selected"] = "이 설정을 사용하려면 약화 효과를 선택해야 합니다."
L["%1$d. Combo"] = "%1$d번째 연계 약화 효과"
L["%1$d. Debuff"] = "%1$d번째 약화 효과"
L["%1$s Combo %2$d"] = "%1$s 약화 효과 조합 %2$d"
L["%1$s Debuff %2$d"] = "%1$s 약화 효과 %2$d"
L["Pick at least two debuffs"] = "약화 효과를 2개 이상 선택하세요"
L["Enter a valid debuff spell ID."] = "유효한 약화 효과 주문 ID를 입력하세요."
L["Shown by %1$s instead."] = "%1$s 항목에 의해 대신 표시됩니다."
L["Shown by %1$s, which comes first."] = "우선순위가 앞서는 %1$s 항목에 의해 표시됩니다."
L["Spell ID: %1$s"] = "주문 ID: %1$s"
L["Chooses which parts of the nameplate show the threat colors; with Health Bar off, the bar keeps its Enemy Types color."] = "이름표에서 위협 색상을 표시할 부분을 선택합니다. '생명력 바'를 끄면 바는 '적 유형' 색상을 유지합니다."
L["Colors enemy health bars, or their borders, while the chosen debuffs are on them."] = "선택한 약화 효과가 걸려 있는 동안 적 생명력 바 또는 테두리에 색상을 적용합니다."
L["Colors your target's custom spell icon border, or a full-size wrapped 1-pixel one, with the target border color."] = "대상의 사용자 지정 주문 아이콘 테두리(또는 1픽셀 둘레 테두리)를 대상 테두리 색상으로 표시합니다."
L["Combo Color"] = "약화 효과 조합 색상"
L["Counts only the debuffs you applied."] = "자신이 직접 부여한 약화 효과만 계산합니다."
L["Debuff Color"] = "약화 효과 색상"
L["Debuff Coloring"] = "약화 효과 색상 지정"
L["How enemy plates look while out of combat."] = "비전투 상태일 때 적 이름표를 표시하는 방식입니다."
L["Show Threat % on Nameplates"] = "이름표에 위협 % 표시"
L["Show Threat Colors"] = "위협 색상 표시"
L["Shows your threat percentage on each enemy nameplate while you are in combat with it."] = "전투 중인 각 적의 이름표에 위협 백분율을 표시합니다."
L["10% Lines"] = "10% 구분선"
L["5% Ticks"] = "5% 눈금"
L["Toggles Blizzard's cooldown numbers setting."] = "블리자드 기본 재사용 대기시간 숫자 설정을 토글합니다."
L["This option requires a bar set to Mouseover"] = "이 옵션은 '마우스 올릴 때 표시'로 설정된 바가 필요합니다."
L["Where the bar text sits inside the bar; the offsets nudge it from there."] = "바 내부에서 글자가 위치할 기준 위치입니다. 오프셋으로 미세 조정할 수 있습니다."
L["Shows the XP from quests in your quest log ahead of the fill."] = "채워진 경험치 앞쪽에 퀘스트 목록에 있는 퀘스트 완료 경험치를 미리 표시합니다."
L["This option requires Current %, Current or Current / Max"] = "이 옵션은 현재 %, 현재값 또는 현재값 / 최대값 설정이 필요합니다."
L["Draws this bar's button borders over proc glows, the assisted highlight and the cooldown swipe."] = "발동 반짝임, 보조 강조 표시 및 재사용 대기시간 음영 위에 이 바의 버튼 테두리를 그립니다."
L["Hovering one Mouseover bar shows them all."] = "'마우스 올릴 때 표시'로 설정된 바 중 하나에 마우스를 올리면 모든 바를 함께 표시합니다."
L["Keeps this bar on its page in any form."] = "변신이나 태세를 변경해도 이 단축바의 페이지를 고정합니다."
L["On bars with a textured border style, a press lights up the button's own border instead of drawing lines."] = "텍스처 테두리 스타일이 적용된 바에서 버튼을 누르면 선을 그리는 대신 버튼 자체의 테두리가 밝아집니다."
L["On bars with a textured border style, hovering lights up the button's own border instead of drawing lines."] = "텍스처 테두리 스타일이 적용된 바에서 마우스를 올리면 선을 그리는 대신 버튼 자체의 테두리가 밝아집니다."
L["On bars with a textured border style, the active spell shows a colored border instead of the highlight fill."] = "텍스처 테두리 스타일이 적용된 바에서 활성화된 주문이 강조 채우기 대신 색상 테두리로 표시됩니다."
L["Shows Blizzard's slot art on empty slots."] = "빈 슬롯에 블리자드 기본 슬롯 이미지를 표시합니다."
L["Draws boss aura icon borders over their cooldown swipes and glows. Duration and stack text stay above the borders."] = "우두머리 오라 아이콘 테두리를 재사용 대기시간 음영 및 반짝임 효과 위에 그립니다. 지속시간 및 중첩 글자는 테두리 위에 유지됩니다."
L["Draws the selected border style between the attached portrait and the bars."] = "연결된 초상화와 바 사이에 선택한 테두리 스타일을 그립니다."
L["Mirrors playable-race portraits in 2D. Always flips class art horizontally."] = "플레이 가능한 종족의 2D 초상화를 좌우 대칭으로 반전합니다. 직업 이미지는 항상 좌우 반전됩니다."
L["Pick what NPCs show in Class art instead of their 2D portrait."] = "2D 초상화 대신 직업 이미지로 표시할 NPC 유형을 선택합니다."
L["Show the border style and size controls for the cast bar."] = "시전 바의 테두리 스타일 및 크기 설정 컨트롤을 표시합니다."
L["Text shown before the target's name."] = "대상 이름 앞에 표시할 텍스트입니다."
L["This option only applies when Name > Target is selected."] = "이 설정은 '이름 > 대상'이 선택되어 있을 때만 적용됩니다."
L["This option only applies when Name > Target or Target is selected."] = "이 설정은 '이름 > 대상' 또는 '대상'이 선택되어 있을 때만 적용됩니다."
L["This option only applies when Target is selected."] = "이 설정은 '대상'이 선택되어 있을 때만 적용됩니다."
L["This option only applies when the text shows a name."] = "이 설정은 텍스트가 이름을 표시할 때만 적용됩니다."
L["This option requires Custom Border Style, Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "이 설정은 EllesmereUI 스타일에 사용자 지정 테두리 스타일, 아이콘 표시, 아이콘을 바의 일부로 포함 옵션이 필요합니다."
L["This option requires Show Icon and the EllesmereUI style."] = "이 설정은 아이콘 표시와 EllesmereUI 스타일이 필요합니다."
L["This option requires Show Icon beside the cast bar and the EllesmereUI style."] = "이 설정은 시전 바 옆 아이콘 표시와 EllesmereUI 스타일이 필요합니다."
L["This option requires a textured Aura Border with a size above 0, and its Show Behind and Behind Unit Frame options disabled."] = "이 설정은 크기가 0보다 큰 텍스처 오라 테두리가 필요하며, '뒤에 표시' 및 '유닛 프레임 뒤에 표시' 옵션이 꺼져 있어야 합니다."
L["Use the cast bar's border style, size and color around the icon."] = "아이콘 주변에 시전 바의 테두리 스타일, 크기 및 색상을 사용합니다."
L["Adds a second ring around a round portrait; Match Frame Border follows your frame border style."] = "원형 초상화 주위에 두 번째 링을 추가합니다. '프레임 테두리에 맞춤'은 유닛 프레임의 테두리 스타일을 따릅니다."
L["Adds a soft shadow inside a round portrait."] = "원형 초상화 안쪽에 은은한 그림자를 추가합니다."
L["Apply Non-Player Portrait to all Frames"] = "플레이어 외 초상화 설정을 모든 프레임에 적용"
L["Art used for the leader crown and the assistant icon."] = "파티장 왕관과 부공격대장 아이콘에 사용할 이미지입니다."
L["Badge shows a small icon; Pixels Dragon wraps the portrait in classification art."] = "배지는 작은 아이콘을 표시하고, 픽셀 드래곤은 초상화를 정예/희귀 이미지로 감쌉니다."
L["Keeps the unit's class or reaction color on the ring in Dark Mode instead of your own class color."] = "다크 모드에서 플레이어 본인의 직업 색상 대신 해당 유닛의 직업 또는 관계(우호/적대) 색상을 링에 유지합니다."
L["Marks elite, rare elite and rare targets; the Pixels Dragon style also marks players."] = "정예, 희귀 정예 및 희귀 대상을 표시합니다. 픽셀 드래곤 스타일은 플레이어도 표시합니다."
L["Match Frame draws the dragon with the portrait. A higher strata draws it over the rest of the frame, border included."] = "'프레임 맞춤'은 초상화와 함께 드래곤을 그립니다. 더 높은 프레임 레이어는 테두리를 포함한 프레임 전체 위에 드래곤을 그립니다."
L["Mirrors playable-race portraits in 2D and 3D. Always flips class art horizontally."] = "플레이 가능한 종족의 2D 및 3D 초상화를 좌우 대칭으로 반전합니다. 직업 이미지는 항상 좌우 반전됩니다."
L["Raises the dragon within its strata. Higher values draw it over more of the frame."] = "해당 프레임 레이어 내에서 드래곤의 표시 순서를 높입니다. 값이 클수록 프레임을 더 많이 덮습니다."
L["Shows your threat percentage on the target frame while you are in combat with it. The cog adds the focus frame."] = "대상과 전투 중일 때 대상 프레임에 위협 백분율을 표시합니다. 톱니바퀴에서 주시 대상 프레임도 추가할 수 있습니다."
L["Size of the dragon, as a percent of its fit around the portrait."] = "초상화 둘레에 맞춘 기준 크기 대비 드래곤의 크기 비율(%)입니다."
L["Size of the outer ring relative to the portrait."] = "초상화 대비 바깥쪽 링의 상대적 크기입니다."
L["This option requires a Circle or Pixels Circle Shape."] = "이 설정은 원형 또는 픽셀 원형 모양이 필요합니다."
L["This option requires a border style with divider art and a Border Size above 0."] = "이 설정은 구분선 이미지가 포함된 테두리 스타일과 0보다 큰 테두리 크기가 필요합니다."
L["This option requires the Class Colored Shape Border and Dark Mode."] = "이 설정은 직업 색상 모양 테두리와 다크 모드가 필요합니다."
L["Turns the dragon to face the other way around the portrait."] = "초상화 주변의 드래곤이 반대 방향을 바라보도록 회전합니다."
L["Adds the Blizzard shield glow line where the shield meets current health."] = "보호막이 현재 생명력과 만나는 경계면에 블리자드 보호막 반짝임 선을 추가합니다."
L["Art used for the glow line and the overshield edge."] = "반짝임 선과 초과 보호막 테두리에 사용할 이미지입니다."
L["Mana keeps the bar on Mana in Bear and Cat Form. Mana + Form Power also shows your Energy or Rage in a second bar."] = "곰 및 표범 변신 상태에서도 바에 마나를 유지합니다. '마나 + 폼 자원'은 두 번째 바로 기력이나 분노도 함께 표시합니다."
L["Astral Power (Except Cat & Bear)"] = "천공의 힘 (표범 및 곰 제외)"
L["The first choice follows your form, with Energy in Cat Form and Rage in Bear Form. Mana stays on Mana in every form, and Astral Power (Except Cat & Bear) shows Astral Power in every form but those two."] = "첫 번째 옵션은 변신 형태를 따릅니다(표범 형태에서는 기력, 곰 형태에서는 분노). '마나'는 모든 형태에서 마나를 유지하며, '천공의 힘 (표범 및 곰 제외)'은 이 두 형태를 제외한 모든 형태에서 천공의 힘을 표시합니다."
L["The first choice follows your form: Energy in Cat Form, Rage in Bear Form and Mana in the others. The other choices keep their power in every form."] = "첫 번째 옵션은 변신 형태를 따릅니다(표범 형태에서는 기력, 곰 형태에서는 분노, 그 외 형태에서는 마나). 나머지 옵션은 모든 형태에서 해당 자원을 유지합니다."
L["Requires Power Type: Mana + Form Power."] = "자원 유형 설정이 '마나 + 폼 자원'이어야 합니다."
L["Form Power Bar"] = "폼 자원 바"
L["Form Power Text"] = "폼 자원 텍스트"
L["Form Text Position"] = "폼 텍스트 위치"
L["Form Text Color"] = "폼 텍스트 색상"
L["Apply Important Cast Glow to Target and Focus"] = "중요한 시전 반짝임을 대상 및 주시 대상에 적용"
L["Colors the dispel type borders with your Dispel Colors instead of Blizzard's."] = "해제 유형 테두리를 블리자드 기본 색상 대신 사용자의 해제 색상으로 표시합니다."
L["Only show buffs that have a duration, excluding permanent ones. Combines with the filters below."] = "지속시간이 있는 강화 효과만 표시하고 영구 효과는 제외합니다. 아래의 필터와 결합됩니다."
L["Only show debuffs that have a duration, excluding permanent ones. Tracked Auras always show."] = "지속시간이 있는 약화 효과만 표시하고 영구 효과는 제외합니다. 추적 중인 오라는 항상 표시됩니다."
L["Recolors the frame border, portrait outer ring and enabled power and portrait separators in the dispel type color while a debuff of that type is shown."] = "해당 유형의 약화 효과가 표시되는 동안 프레임 테두리, 초상화 외곽 링 및 활성화된 구분선을 해제 유형 색상으로 변경합니다."
L["Show Icon on Portrait"] = "초상화에 아이콘 표시"
L["Shows the spell icon over the portrait while casting and lets the bar use the full width."] = "시전 중에 초상화 위에 주문 아이콘을 표시하고 시전 바가 전체 너비를 사용하도록 합니다."
L["Embed in Player Portrait"] = "플레이어 초상화에 포함"
L["Show the spell icon over the player portrait while casting."] = "시전 중에 플레이어 초상화 위에 주문 아이콘을 표시합니다."
L["This option requires an enabled player portrait in Unit Frames."] = "이 설정은 유닛 프레임에서 플레이어 초상화가 활성화되어 있어야 합니다."
L["This option requires a Dispel Overlay, Color Custom Borders or Use Dispel Colors."] = "이 설정은 해제 오버레이, 사용자 지정 테두리 색상화 또는 해제 색상 사용 옵션이 필요합니다."
L["This option requires an attached Power Bar, a Border Size above 0 and a border style with seam art."] = "이 설정은 결합된 자원 바, 0보다 큰 테두리 크기 및 이음매 이미지가 포함된 테두리 스타일이 필요합니다."
L["Apply Cast Bar Border Style to all Frames"] = "시전 바 테두리 스타일을 모든 프레임에 적용"
L["Apply Cast Bar Border to all Frames"] = "시전 바 테두리를 모든 프레임에 적용"
L["Border art drawn around the boss frames. Inherit (Main Frames) uses the main frames' border."] = "우두머리 프레임 주변에 그려질 테두리 이미지입니다. '상속 (주 프레임)'은 주 프레임의 테두리를 따릅니다."
L["Border art drawn around the cast bar."] = "시전 바 주변에 그려질 테두리 이미지입니다."
L["Draw a divider between the integrated icon and the bar, using the cast bar's border appearance."] = "시전 바의 테두리 모양을 사용하여 통합 아이콘과 바 사이에 구분선을 그립니다."
L["Draw the custom cast bar border around the icon and the bar together. An icon with an offset keeps its own border."] = "아이콘과 시전 바 전체를 둘러싸도록 사용자 지정 시전 바 테두리를 그립니다. 오프셋이 적용된 아이콘은 자체 테두리를 유지합니다."
L["Draws the border behind the cast bar instead of over it."] = "시전 바 위가 아닌 뒤쪽에 테두리를 그립니다."
L["Draws the border style's seam art between the health bar and an attached power bar."] = "생명력 바와 결합된 자원 바 사이에 테두리 스타일의 이음매 이미지를 그립니다."
L["Draws the dispel-colored ring in this border style's shape instead of flat lines."] = "해제 색상 링을 단순한 직선 대신 이 테두리 스타일의 모양으로 그립니다."
L["Equipped items get a rarity color border."] = "장착 중인 아이템 테두리에 등급 품질 색상을 표시합니다."
L["Hides the Unit Frames player cast bar while a controller is connected and gamepad mode is on. Blizzard's gamepad interface shows its own."] = "컨트롤러가 연결되어 있고 게임패드 모드가 켜져 있는 동안 유닛 프레임의 플레이어 시전 바를 숨깁니다. 블리자드 게임패드 인터페이스에 자체 시전 바가 표시됩니다."
L["Overlay fills empty health first, then draws any excess over current health. Overlay Reverse draws the shield back over current health; a shield larger than current health spans from the bar's left end. From Right Edge and From Left Edge grow the whole shield from that end of the bar."] = "'오버레이'는 잃은 생명력을 먼저 채우고 초과분을 현재 생명력 위에 그립니다. '오버레이 역방향'은 현재 생명력 위로 보호막을 되돌려 그리며, 현재 생명력보다 큰 보호막은 바 왼쪽 끝에서 확장됩니다. '오른쪽 가장자리부터'와 '왼쪽 가장자리부터'는 바의 해당 끝에서부터 보호막 전체를 확장합니다."
L["Requires a spell with a range"] = "유효 사거리가 있는 주문이 필요합니다"
L["Right by default, or Bottom with Horizontal Frames. With Frame Style: Party Frames, the side holding the buffs is not available."] = "기본값은 오른쪽이며, 가로형 프레임에서는 아래쪽입니다. 프레임 스타일이 '파티 프레임'인 경우 강화 효과가 표시되는 쪽은 선택할 수 없습니다."
L["Scales the 3D character from the portrait's bottom edge, for use with the full-body 3D Zoom range above 300."] = "초상화 하단 가장자리를 기준으로 3D 캐릭터 크기를 조절합니다 (300 이상의 전신 3D 줌 범위에서 사용)."
L["Show a smaller secure target button beside each party frame. Left-click a button to target that party member's current target."] = "각 파티 프레임 옆에 작은 대상 지정 버튼을 표시합니다. 좌클릭하면 해당 파티원의 현재 대상을 대상으로 지정합니다."
L["Above 300 the camera pulls back to show the whole character."] = "300보다 높으면 카메라가 뒤로 물러나 캐릭터 전체를 보여줍니다."
L["The bar fills with missing health, growing as the unit takes damage."] = "유닛이 피해를 입을 때 잃은 생명력으로 바가 채워집니다."
L["Adds your group's pets beside these frames, with their health, name, range and click-casting."] = "프레임 옆에 파티원/공격대원의 소환수를 생명력, 이름, 사거리 및 클릭 시전 기능과 함께 추가합니다."
L["Makes the pet frames taller or shorter relative to the frame size."] = "프레임 크기에 비례하여 소환수 프레임의 높이를 조절합니다."
L["Places the bar at the bottom of the frame instead of the top."] = "바를 프레임 상단 대신 하단에 배치합니다."
L["Widens or narrows the pet frames relative to the frame size."] = "프레임 크기에 비례하여 소환수 프레임의 너비를 조절합니다."
L["This option requires an Inside position"] = "이 설정은 '내부' 위치 설정이 필요합니다."
L["Also show your own target beside your frame."] = "자신의 프레임 옆에 현재 대상도 함께 표시합니다."
L["Class Color uses the class color for players and the reaction color for NPCs."] = "'직업 색상'은 플레이어에게 직업 색상을, NPC에게는 관계(우호/적대) 색상을 사용합니다."
L["Shows Fortitude, Mark of the Wild, Spirit or Thorns on a member who is missing it, for the buffs you can cast yourself (choose which in the cog)."] = "자신이 시전할 수 있는 강화 효과 중 해당 효과가 누락된 파티원에게 인내, 야생의 징표, 천상의 정신 또는 가시를 표시합니다(톱니바퀴에서 선택)."
L["Mana Colored"] = "마나 색상"
L["Mana keeps the bar on Mana in Bear and Cat Form."] = "곰 및 표범 변신 상태에서도 바에 마나를 유지합니다."
L["On a vertical Power Bar, Below is the right side and Above is the left side."] = "세로형 자원 바에서 '아래'는 오른쪽이고 '위'는 왼쪽입니다."
L["Shows a thin mana bar with the Power Bar while in Bear and Cat Form."] = "곰 및 표범 변신 상태에서 자원 바와 함께 얇은 마나 바를 표시합니다."
L["This option requires Position to be Below or Above"] = "이 설정은 위치를 '아래' 또는 '위'로 설정해야 합니다."
L["This option requires Power Type to be set to Match Form"] = "이 설정은 자원 유형을 '폼에 맞춤'으로 설정해야 합니다."
L["Draws the icon divider in the border style's art instead of a solid line."] = "아이콘 구분선을 실선 대신 테두리 스타일 이미지로 그립니다."
L["Grays the fill while your target is out of range of the spell being cast."] = "시전 중인 주문의 유효 사거리 밖에 대상이 있으면 바 채우기를 회색으로 표시합니다."
L["Spell Text Color"] = "주문 글자 색상"
L["Draws a line in each gap between the pips."] = "자원 칸 사이의 각 간격에 선을 그립니다."
L["Draws separator lines along the bar edge and between the pips."] = "바 가장자리와 자원 칸 사이에 구분선을 그립니다."
L["Draws the class resource background inside each pip so the gaps between pips stay clear."] = "자원 칸 사이의 간격이 깔끔하게 유지되도록 각 칸 안쪽에 직업 자원 배경을 그립니다."
L["Draws the class resource bar above the health, power and GCD bar borders."] = "생명력, 자원 및 GCD 바 테두리 위에 직업 자원 바를 그립니다."
L["Draws the line along the bar's bottom edge."] = "바의 하단 가장자리를 따라 선을 그립니다."
L["Separators"] = "구분선"
L["This option can't be used while Border on individual pips is enabled."] = "이 설정은 '개별 자원 칸 테두리'가 켜져 있는 동안에는 사용할 수 없습니다."
L["Draws a separator line along the bar's bottom edge."] = "바의 하단 가장자리를 따라 구분선을 그립니다."
L["Grows the border past the bar's bottom edge on screen without resizing the bar."] = "바 크기를 변경하지 않고 화면상에서 바 하단 가장자리 너머로 테두리를 확장합니다."
L["Grows the border past the bar's top edge on screen without resizing the bar."] = "바 크기를 변경하지 않고 화면상에서 바 상단 가장자리 너머로 테두리를 확장합니다."
L["Grows the border past the bar's left edge on screen without resizing the bar."] = "바 크기를 변경하지 않고 화면상에서 바 좌측 가장자리 너머로 테두리를 확장합니다."
L["Grows the border past the bar's right edge on screen without resizing the bar."] = "바 크기를 변경하지 않고 화면상에서 바 우측 가장자리 너머로 테두리를 확장합니다."
L["Draws the power bar's border above the GCD bar where the two overlap."] = "자원 바와 GCD 바가 겹치는 영역에서 자원 바 테두리를 GCD 바 위에 그립니다."
L["Colors the bar while a chosen spell is ready."] = "선택한 주문이 사용 가능할 때 바에 색상을 적용합니다."
L["Draws this bar's border in your own border style, size and color instead of the thin black line."] = "얇은 검은색 선 대신 사용자가 지정한 테두리 스타일, 크기 및 색상으로 이 바의 테두리를 그립니다."
L["How far the border reaches past the bar."] = "테두리가 바 바깥쪽으로 확장되는 거리입니다."
L["Runs the bar text along the bar."] = "바 텍스트를 바 방향을 따라 표시합니다."
L["Runs the divider percentages along the bar."] = "구분선 백분율을 바 방향을 따라 표시합니다."
L["This option requires Custom Icon Shape to be set to Cropped"] = "이 옵션은 사용자 지정 아이콘 모양을 '잘림(Cropped)'으로 설정해야 합니다."
L["Custom Spell..."] = "사용자 지정 주문..."
L["This option requires a Visibility other than Never"] = "이 설정은 표시 설정을 '표시 안 함' 이외로 설정해야 합니다."
L["Shows each guild or friend note on a second line under its row. The tooltip gets taller."] = "길드원 또는 친구 메모를 해당 행 아래 둘째 줄에 표시합니다. 툴팁 높이가 늘어납니다."
L["Size of the icons on the map, such as group members, quest objectives and gathering nodes. The same setting as Blizzard's Edit Mode Icon Size."] = "파티원, 퀘스트 목표, 채집 노드 등 지도 아이콘의 크기입니다. 블리자드 편집 모드의 아이콘 크기 설정과 동일합니다."
L["Fades the minimap while it is shown. Visibility still decides when it shows."] = "미니맵이 표시되는 동안 서서히 투명도를 조절합니다. 표시 조건은 가시성 설정에 따릅니다."
L["Turns Dark Mode on or off for each module."] = "각 모듈별로 다크 모드를 켜거나 끕니다."
L["Color and opacity behind Dark Mode bars."] = "다크 모드 바 뒤쪽의 배경 색상과 불투명도입니다."
L["Darkens class, resource and power colors."] = "직업, 보조 자원 및 기본 자원 색상을 어둡게 합니다."
L["Fill color and opacity of Dark Mode bars."] = "다크 모드 바의 채우기 색상과 불투명도입니다."
L["Share this section's colors across profiles."] = "이 섹션의 색상을 모든 프로필에서 공유합니다."
L["Shows your damage taken, healing, avoids and combat enter/leave above the player frame instead of Blizzard's combat text, whose other messages are hidden while this is on. Move it in Unlock Mode."] = "블리자드 기본 전투 메시지 대신 플레이어 프레임 위에 받은 피해, 치유량, 방어/회피 및 전투 시작/종료를 표시합니다. 켜져 있는 동안 블리자드의 다른 전투 메시지는 숨겨집니다. 잠금 해제 모드에서 위치를 이동할 수 있습니다."
L["Self Combat Text"] = "플레이어 전투 메시지"
L["Scroll Distance"] = "스크롤 이동 거리"
L["Scroll Duration"] = "스크롤 지속 시간"
L["Crit Scale"] = "치명타 크기 비율"
L["Stagger Hits"] = "동시 피격 분산 표시"
L["Spaces out hits that land together so none hides another."] = "동시에 들어오는 타격을 분산시켜 글자가 서로 가려지지 않게 합니다."
L["Auto Select Single Gossip"] = "단일 대화 선택지 자동 선택"
L["Auto Gossip Settings"] = "대화 자동 선택 설정"
L["Disable in Instances"] = "인스턴스에서 비활성화"
L["Picks an NPC's only dialog option for you."] = "NPC의 대화 선택지가 하나뿐일 때 자동으로 선택합니다."
L["Blizzard Default keeps the game's whisper sound. Any other sound replaces it, and None plays no sound."] = "'블리자드 기본'은 게임 기본 귓속말 소리를 유지합니다. 다른 소리를 선택하면 해당 소리로 대체되며, '없음'은 소리를 재생하지 않습니다."
L["Max rows per section in the Friends Online tooltip (0 = the 30-row max). The cog can show each note under its row."] = "접속 중인 친구 툴팁의 섹션당 최대 행 수입니다 (0 = 최대 30행). 톱니바퀴에서 각 행 아래에 메모를 표시할 수 있습니다."
L["Colors the number when free slots drop below this many; the swatch picks the color. Zero turns it off."] = "남은 빈 칸이 이 수치 미만으로 떨어지면 숫자에 색상을 적용합니다. 색상 견본에서 색을 선택하며, 0으로 설정하면 꺼집니다."
L["Which slot count the block shows."] = "블록에 표시할 가방 칸 수 유형을 선택합니다."
L["Includes instance chat."] = "인스턴스(던전/공격대) 대화를 포함합니다."
L["Incomplete Color"] = "미완료 색상"
L["Missing Buffs"] = "누락된 강화 효과"
L["Only counts quests in your current zone."] = "현재 지역의 퀘스트만 계산합니다."
L["Only counts quests that are ready to turn in."] = "완료 보고 가능한 퀘스트만 계산합니다."
L["Opacity of the row background."] = "행 배경의 불투명도입니다."
L["Rotated text reads from top to bottom."] = "회전된 텍스트는 위에서 아래로 읽힙니다."
L["Sets the scale of the whole game UI. 0.53 = 0.5333 and 0.71 = 0.7111"] = "전체 게임 UI의 배율을 설정합니다. 0.53 = 0.5333, 0.71 = 0.7111"
L["Show Names"] = "이름 표시"
L["Restore My Graphics Settings"] = "내 그래픽 설정 복원"
L["Put back your graphics from before optimizing."] = "최적화 이전의 원래 그래픽 설정으로 되돌립니다."
L["Tune graphics for higher FPS and clarity."] = "높은 FPS와 선명함을 위해 그래픽 설정을 조정합니다."
L["What Does This Do?"] = "어떤 기능인가요?"
L["Graphics changed by Optimize My FPS and Graphics stay as they are. To undo them, click Restore My Graphics Settings first."] = "'FPS 및 그래픽 최적화'로 변경된 설정은 유지됩니다. 되돌리려면 먼저 '내 그래픽 설정 복원'을 클릭하세요."
L["After optimizing, the button changes to 'Restore My Graphics Settings', which reverts every change."] = "최적화 후 버튼이 '내 그래픽 설정 복원'으로 변경되며, 클릭 시 모든 변경 사항을 되돌립니다."
L["Width matched to %1$s. Unmatch to edit."] = "%1$s 요소에 너비가 고정됨. 편집하려면 맞춤을 해제하세요."
L["Height matched to %1$s. Unmatch to edit."] = "%1$s 요소에 높이가 고정됨. 편집하려면 맞춤을 해제하세요."
L["Width matched to %1$s. Unmatch in Unlock Mode to edit."] = "%1$s 요소에 너비가 고정됨. 편집하려면 잠금 해제 모드에서 맞춤을 해제하세요."
L["Height matched to %1$s. Unmatch in Unlock Mode to edit."] = "%1$s 요소에 높이가 고정됨. 편집하려면 잠금 해제 모드에서 맞춤을 해제하세요."
L["Active while Dark Mode is on."] = "다크 모드가 켜져 있는 동안 활성화됩니다."

-- == 리테일 전용 신규 툴팁 및 옵션 (Retail: 시즌 패널, 신화+, 하늘비행, 쿨다운 매니저 등) ==
L["Add a Great Vault button to the Season Panel."] = "시즌 패널에 위대한 금고 버튼을 추가합니다."
L["Adds diminishing returns info to Secondary and Tertiary stat tooltips."] = "보조 및 3차 능력치 툴팁에 점감 효과 정보를 추가합니다."
L["Hovering a Secondary or Tertiary stat highlights the gear that has it."] = "보조 또는 3차 능력치에 마우스를 올리면 해당 능력치가 붙은 장비를 강조 표시합니다."
L["How Secondary and Tertiary stat values are shown."] = "보조 및 3차 능력치 수치를 표시하는 방식입니다."
L["Secondary Stats or Tertiary Stats"] = "보조 능력치 또는 3차 능력치"
L["Choose Stats..."] = "능력치 선택..."
L["Reorder Shown Stats"] = "표시할 능력치 순서 변경"
L["Keeps this bar on its page while skyriding."] = "하늘비행 중에도 이 단축바의 페이지를 고정합니다."
L["Shows a button next to the bar that lands you at the next flight point."] = "바 옆에 다음 비행 경로(비행 조련사) 거점에 착륙할 수 있는 버튼을 표시합니다."
L["Where the enemy forces percentage is shown: in the label text, in the bar or beside it."] = "적 병력 백분율이 표시될 위치입니다: 라벨 텍스트 안, 바 안 또는 바 옆."
L["Which side of each boss objective shows its split times and Split Compare text."] = "각 우두머리 목표의 어느 쪽에 구간 기록과 구간 비교 텍스트를 표시할지 설정합니다."
L["Texture of the enemy forces bar. The swatches next to it set the Enemy Bar Color (theme accent or a custom color)."] = "적 병력 바의 텍스처입니다. 옆의 색상 견본에서 적 병력 바 색상(테마 강조색 또는 사용자 지정 색상)을 설정합니다."
L["Align the timer text to the left edge of the bar instead of centering it."] = "타이머 텍스트를 가운데 정렬하는 대신 바의 왼쪽 가장자리에 정렬합니다."
L["Fades the timer in at takeoff and out on landing."] = "이륙 시 타이머가 서서히 나타나고 착륙 시 서서히 사라집니다."
L["Minimum height of the timer bar while the timer is inside it. The larger of this and Timer Bar Height is used."] = "타이머가 바 내부에 있을 때 타이머 바의 최소 높이입니다. 이 값과 '타이머 바 높이' 중 더 큰 값이 적용됩니다."
L["Opacity of the bar fill while the timer is inside it."] = "타이머가 바 내부에 있을 때 바 채우기의 불투명도입니다."
L["Cannot open the Cooldown Manager during combat."] = "전투 중에는 재사용 대기시간 관리자를 열 수 없습니다."
L["Cannot open the Cooldown Manager with the Gamepad interface style."] = "게임패드 인터페이스 스타일에서는 재사용 대기시간 관리자를 열 수 없습니다."
L["Disable the Cooldown State glow first"] = "먼저 '재사용 대기 상태 반짝임'을 끄세요"
L["Glows on action bar and CDM buttons while a tracked buff is active (or missing), set per entry on the Bar Glows page. Counted for the current specialization; the template never changes them."] = "추적 중인 강화 효과가 활성화(또는 누락)되었을 때 행동 단축바 및 CDM 버튼에 표시되는 반짝임으로, '바 반짝임' 페이지에서 항목별로 설정합니다. 현재 전문화 기준으로 적용되며, 템플릿으로 변경되지 않습니다."
L["Proc Glow, Active State Glow, Max Charges Glow, Buff Glow, CD Ready Glow and Glow Effect Color can be set per icon: right-click an icon in the CDM Bars preview. Counted for the current specialization; the template never changes them."] = "발동 반짝임, 활성 상태 반짝임, 최대 충전 반짝임, 강화 효과 반짝임, 재사용 준비 시 반짝임 및 효과 색상은 아이콘별로 설정할 수 있습니다: CDM 바 미리보기에서 아이콘을 우클릭하세요. 현재 전문화 기준으로 적용되며, 템플릿은 이를 변경하지 않습니다."
L["Mythic raids allow only 20 players (groups 1-4), so hide groups 5-8 while inside one. Groups 1-4 still follow Show Groups, and Show Groups applies as normal everywhere else."] = "신화 공격대는 20인(1~4파티)으로 진행되므로, 신화 공격대 내부에서는 5~8파티를 숨깁니다. 1~4파티는 여전히 '파티 표시' 설정을 따르며, 다른 곳에서는 파티 표시 설정이 정상 적용됩니다."
L["Environment Ping"] = "지형 핑"
L["While held, left-clicking the world sends a ping that ignores units and only targets the environment.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "누른 상태에서 지면을 좌클릭하면 유닛을 무시하고 배경 지형에만 핑을 보냅니다.\n\n좌클릭하여 단축키 지정.\n우클릭하여 지정 해제."

-- == 포에버 전용 신규 툴팁 및 옵션 (WoW Forever: 주문 승급, 5초 규칙, 전리품 피드 등) ==
L["Swaps new spell ranks onto your action bars."] = "새로 배운 상위 등급의 주문을 행동 단축바에 자동으로 교체합니다."
L["Upranked %s on 1 action slot."] = "단축바 슬롯 1개의 %s 주문을 상위 등급으로 교체했습니다."
L["Upranked %1$s on %2$d action slots."] = "단축바 슬롯 %2$d개의 %1$s 주문을 상위 등급으로 교체했습니다."
L["5-Second Rule sweeps a spark across the bar for 5 seconds after you spend mana, until mana regen resumes. Regen Ticks then keeps sweeping every 2 seconds while mana regenerates."] = "5초 규칙은 마나를 소비한 후 자연 회복이 재개될 때까지 5초 동안 바에 불꽃을 이동시킵니다. 이후 회복 눈금은 마나가 재생되는 동안 2초마다 계속 이동합니다."
L["Shows Sunder Armor and its stacks on enemy nameplates, including stacks applied by other warriors."] = "다른 전사가 부여한 중첩을 포함하여, 적 이름표에 방어구 가르기와 그 중첩 수를 표시합니다."
L["Loot Feed"] = "전리품 피드"
L["Shows what you loot and gain as short-lived rows that fade out."] = "획득한 전리품과 아이템을 서서히 사라지는 피드 형태로 표시합니다."
L["0 hides the accent bar."] = "0으로 설정하면 강조 바를 숨깁니다."
L["0 hides the border."] = "0으로 설정하면 테두리를 숨깁니다."
L["Shows a sample row for every enabled source."] = "활성화된 모든 출처에 대해 예시 행을 표시합니다."
L["Reskins Blizzard's call totem bar in this look and moves it with Unlock Mode instead of Edit Mode."] = "블리자드 토템 바에 이 외형 스킨을 적용하고 편집 모드 대신 잠금 해제 모드로 이동할 수 있게 합니다."

-- == 패치 노트 (Patch Notes: 9.3.5 ~ 9.3.8) ==
-- 9.3.8
L["Reminders now follow Where to Show in Island Expeditions, Torghast and other scenarios, which get their own Scenario entry, and housing plots now count as Open World."] = "군도 탐험, 토르가스트 및 기타 시나리오에서도 '표시 위치' 설정을 따르며 자체 시나리오 항목이 추가되었고, 주택 구역은 야외 필드로 분류됩니다."
L["The keyring button on the bag bar opens your keyring again instead of the bags."] = "가방 바의 열쇠고리 버튼을 누르면 가방 대신 열쇠고리가 정상적으로 열립니다."
L["Chat placed near the bottom or left edge of the screen no longer shifts up and to the right after logging in or opening Edit Mode."] = "화면 하단이나 좌측 가장자리에 배치된 대화창이 로그인하거나 편집 모드를 열었을 때 우측 상단으로 밀리던 문제를 수정했습니다."
L["Targeted Spell Bars now follow Where to Show in scenarios, which get their own Scenario entry, and housing plots now count as Open World."] = "대상 지정 주문 바가 시나리오에서 '표시 위치' 설정을 따르며 자체 시나리오 항목이 추가되었고, 주택 구역은 야외 필드로 분류됩니다."
L["Brazilian Portuguese translation updated for the latest options."] = "최신 설정 옵션에 맞춰 브라질 포르투갈어 번역을 업데이트했습니다."

-- 9.3.7
L["Quest XP Overlay"] = "퀘스트 경험치 오버레이"
L["The XP bar can show the XP from the quests in your log ahead of its fill, completed quests in green and the rest in gold"] = "경험치 바에 퀘스트 목록의 퀘스트 경험치를 미리 표시합니다. 완료된 퀘스트는 녹색, 진행 중인 퀘스트는 금색으로 표시됩니다."
L["Raid Buffs"] = "공격대 강화 효과"
L["Mark of the Wild, Fortitude, Arcane Intellect and Battle Shout get their own Raid Buffs section: any rank counts, and a click buffs whoever needs it"] = "야생의 징표, 신의 권능: 인내, 신비한 지능, 전투의 외침 전용 공격대 강화 효과 섹션이 추가되었습니다. 모든 등급이 반영되며, 클릭 한 번으로 필요한 대상에게 효과를 부여합니다."
L["Player Buffs on Tooltips"] = "툴팁에 플레이어 강화 효과 표시"
L["Hovering a player can show their buffs as icons on the tooltip, with position, size and per-row settings"] = "플레이어에게 마우스를 올렸을 때 툴팁에 강화 효과를 아이콘으로 표시할 수 있으며, 위치, 크기, 줄당 표시 개수를 설정할 수 있습니다."
L["Loot Feed Styles"] = "전리품 피드 스타일"
L["The loot feed now uses a new Accent Bar look, with Icon Tray, Loot Toast and the old Box look to pick from, and a live preview on the Loot page"] = "전리품 피드에 새로운 강조 바 디자인이 적용되었으며 아이콘 트레이, 전리품 토스트, 기존 상자형 디자인 중에서 선택할 수 있고 전리품 페이지에서 실시간 미리보기를 제공합니다."
L["Auto Uprank Spells"] = "주문 자동 상위 등급 교체"
L["Learning a new spell rank swaps it onto your action bars in place of the old rank"] = "새로운 주문 등급을 배우면 행동 단축바의 기존 등급을 자동으로 교체합니다."
L["The Travel page shows the flight timer flying a sample route on a loop, so every setting shows as you change it"] = "이동 페이지에서 비행 타이머 예시 경로를 반복 재생하여 설정을 변경할 때 실시간으로 확인할 수 있습니다."
L["Debuff Border Coloring"] = "약화 효과 테두리 색상"
L["Debuff Based Nameplate Coloring (formerly Debuff Colors) can color an enemy plate's border instead of its health bar, and thicken it while it shows"] = "약화 효과 기반 이름표 색상(구 약화 효과 색상) 설정을 통해 적 이름표의 생명력 바 대신 테두리에 색상을 적용하고, 표시되는 동안 테두리를 두껍게 만들 수 있습니다."
L["Talking to an NPC with only one dialog option picks it for you, unless they have a quest for you"] = "NPC와의 대화 선택지가 하나뿐일 때 자동으로 선택합니다 (퀘스트가 있는 NPC는 제외)."
L["Ignore Low Level Quests"] = "저레벨 퀘스트 무시"
L["Auto Accept can leave low level quests for you to pick up yourself"] = "퀘스트 자동 수락 기능 사용 시 저레벨 퀘스트는 자동으로 수락하지 않고 직접 받을 수 있게 남겨둡니다."
L["Down and then Right"] = "아래로 확장 후 오른쪽으로"
L["Group Growth can lay raid groups out in a grid, two groups down each column before the next column starts to the right"] = "그룹 확장 설정을 통해 공격대 파티를 격자형으로 배치할 수 있습니다. 각 열에 2개 그룹을 아래로 배치한 후 다음 열을 오른쪽에 시작합니다."
L["Fixed a niche issue that could cause cooldown errors from Blizzard's hidden action buttons when entering combat."] = "전투 돌입 시 블리자드의 숨겨진 단축 버튼으로 인해 재사용 대기시간 오류가 발생할 수 있던 드문 문제를 수정했습니다."
L["Custom spell reminders now count every rank of the spell and its group version, so a higher rank no longer leaves the reminder showing."] = "사용자 지정 주문 알림이 해당 주문의 모든 등급 및 그룹 버전을 정상 인식하여, 상위 등급을 배운 후에도 알림이 계속 남아있던 문제를 수정했습니다."
L["Chat and its input bar no longer blink or jump when Edit Mode re-applies its layout (at login, on level-ups and on layout switches), which could also make right-clicks on names do nothing or pick the wrong player."] = "편집 모드에서 레이아웃이 다시 적용될 때(로그인, 레벨업, 레이아웃 전환 시) 대화창과 입력창이 깜빡이거나 튀는 현상 및 이름 우클릭 시 아무 동작도 하지 않거나 다른 플레이어가 선택되던 문제를 수정했습니다."
L["Icons no longer show the previous spell's keybind after you add a spell in Blizzard's Cooldown Manager settings."] = "블리자드 재사용 대기시간 관리자 설정에서 주문을 추가한 후 아이콘에 이전 주문의 단축키가 표시되던 문제를 수정했습니다."
L["Minimap buttons on a round minimap now sit around the edge of the circle instead of in a straight row beside it."] = "원형 미니맵에서 미니맵 버튼이 옆에 일렬로 나열되는 대신 원형 가장자리를 따라 배치됩니다."
L["Debuff coloring changes now apply as you make them, without an Apply Coloring button, and the coloring uses less CPU."] = "'색상 적용' 버튼을 누르지 않아도 약화 효과 색상 변경 사항이 즉시 적용되며 CPU 사용량이 감소했습니다."
L["Debuff coloring no longer uses the previous profile's debuff lists after a spec profile switches profiles at login."] = "로그인 시 전문화별 프로필이 전환된 후 이전 프로필의 약화 효과 목록이 그대로 적용되던 문제를 수정했습니다."
L["Self Combat Text's Stagger Hits now spaces out hits that land together so none hides another, and Straight text rises in a straight line instead of drifting side to side."] = "플레이어 전투 메시지의 '동시 피격 분산 표시' 옵션이 동시에 들어오는 타격을 분산 배치하여 글자가 서로 가려지지 않게 하고, '직선' 텍스트는 좌우로 흔들리지 않고 곧게 올라갑니다."
L["Debuff Manager filters now dim when another indicator already shows those debuffs, and hovering one names that indicator."] = "다른 표시기가 이미 해당 약화 효과를 표시하고 있는 경우 약화 효과 관리자 필터가 흐리게 표시되며, 마우스를 올리면 해당 표시기 이름이 표시됩니다."
L["Blizzard's cast bar no longer comes back next to ours after leveling up in combat."] = "전투 중 레벨업 시 블리자드 기본 시전 바가 우리 시전 바 옆에 다시 나타나던 문제를 수정했습니다."
L["Moving or resizing Blizzard Style unit frames no longer causes errors."] = "블리자드 스타일 유닛 프레임을 이동하거나 크기를 조절할 때 오류가 발생하던 문제를 수정했습니다."
L["Traditional Chinese translation updated for the latest options, and Unlock Mode's size-match, anchor and override messages can now be translated."] = "최신 설정에 맞춰 번체 중국어 번역을 업데이트했으며, 잠금 해제 모드의 크기 맞춤, 고정 위치 및 재정의 메시지도 번역할 수 있도록 개선했습니다."

-- 9.3.6
L["Click-cast bindings with Enable Dynamic Rez, HoverCast keys holding both a friendly and an enemy spell, and HoverCast Dynamic Rez keys work again."] = "동적 부활이 활성화된 클릭 시전 단축키, 아군과 적군 주문을 모두 가진 마우스오버 시전 단축키, 마우스오버 시전 동적 부활 단축키가 다시 정상 작동합니다."

-- 9.3.5
L["XP Bar Overhaul"] = "경험치 바 개편"
L["The XP bar gets its own tab with frame styles, gradient and animated fills, divider ticks and its own background and rested colors. Up to seven texts can sit around or inside it, each mixing XP, rested, quest XP, level, XP per hour and time to level in the order you drag them."] = "경험치 바 전용 탭이 추가되어 프레임 스타일, 그라데이션 및 애니메이션 채우기, 구분 눈금, 자체 배경 및 휴식 색상을 지원합니다. 바 주변이나 내부에 최대 7개의 글자를 배치할 수 있으며, 드래그한 순서대로 경험치, 휴식, 퀘스트 경험치, 레벨, 시간당 경험치, 레벨업까지 남은 시간을 조합할 수 있습니다."
L["Debuff Colors"] = "약화 효과 색상"
L["Enemy health bars can take a color while your chosen debuffs are on them: up to ten per class in priority order, plus combo colors for two to four debuffs at once. Only your own class's list ever loads, and Apply Coloring sends your changes to the plates."] = "선택한 약화 효과가 걸려 있는 동안 적 생명력 바에 색상을 적용할 수 있습니다: 직업당 우선순위 순서로 최대 10개까지 설정할 수 있으며, 2~4개 약화 효과의 조합 색상도 지원합니다. 자신의 직업 목록만 불러오며, 색상 적용 버튼을 누르면 이름표에 변경 사항이 반영됩니다."
L["Bags and the bank can show items as a list with sortable, resizable columns, adjustable rows and an Upgrade Track column. Drag a corner to resize the bags or bank, and drop items picked up elsewhere anywhere on the empty bag space."] = "가방과 은행의 아이템을 정렬 및 크기 조절이 가능한 열, 높이 조절 가능한 행, 강화 단계 열이 포함된 목록 형태로 표시할 수 있습니다. 모서리를 드래그하여 가방이나 은행 크기를 조절할 수 있으며, 외부에서 집어든 아이템을 빈 공간 어디든 놓아 넣을 수 있습니다."
L["Shows your damage taken, healing, avoids and entering or leaving combat as scrolling text above the player frame in place of Blizzard's combat text, with its own font, colors and animation; move it in Unlock Mode."] = "블리자드 기본 전투 메시지 대신 플레이어 프레임 위에 받은 피해, 치유, 회피/방어, 전투 시작/종료를 스크롤 텍스트로 표시합니다. 전용 글꼴, 색상, 애니메이션을 지원하며 잠금 해제 모드에서 위치를 변경할 수 있습니다."
L["Modifier/Target Paging"] = "수정키/대상별 단축바 전환"
L["Shift, Ctrl, Alt, Friendly and Hostile Target paging sit behind one toggle that turns them off without losing your picks"] = "Shift, Ctrl, Alt 및 아군/적대적 대상 전환 설정을 기존 지정값을 유지한 채 한 번에 끄고 켤 수 있습니다."
L["Show Equipped Item Color"] = "장착 아이템 품질 색상 표시"
L["Buttons holding an equipped item, such as a trinket, can show a border in its rarity color (on by default in WoW Forever)"] = "장신구 등 장착 중인 아이템이 올려진 버튼 테두리를 아이템 품질 색상으로 표시합니다 (WoW Forever에서는 기본 활성화)."
L["Forever XP Bar Style"] = "Forever 경험치 바 스타일"
L["The XP bar can wear the bronze border of the chat and Damage Meters windows"] = "경험치 바에 대화창 및 미터기 창과 동일한 청동 테두리를 적용할 수 있습니다."
L["Other windows, like the Auction House, can now come in front of the bags; turn it off to keep the bags on top, as before"] = "경매장 등의 다른 창이 가방 앞으로 올 수 있게 허용합니다. 설정을 끄면 이전처럼 가방이 항상 맨 위에 유지됩니다."
L["Special Bags"] = "특수 가방"
L["Quivers, ammo pouches and soul, herb and enchanting bags get their own OneBag sections and a Special Bags category"] = "화살통, 탄약통, 영혼/약초/마법부여 가방이 통합 가방 전용 섹션과 특수 가방 카테고리로 분리됩니다."
L["Character Sheet Blizz Default"] = "캐릭터 창 블리자드 기본"
L["Blizz Default keeps Blizzard's sheet with the EllesmereUI stats, item text and socket panel, and a new Off leaves the sheet untouched"] = "블리자드 기본 창 형태를 유지하면서 EllesmereUI 능력치, 아이템 정보, 보석 홈 패널을 표시하며, 새로 추가된 '끔'은 캐릭터 창을 전혀 변경하지 않습니다."
L["Chat Bubbles moved here from Chat, with their own font and outline, optional speaker names and a live preview"] = "말풍선 설정이 대화 모듈에서 이전되었으며, 전용 글꼴 및 외곽선, 화자 이름 표시 옵션, 실시간 미리보기를 제공합니다."
L["Health Strip Texture and Height"] = "생명력 표시줄 텍스처 및 높이"
L["Show Health Strip's cog sets the tooltip health strip's texture and height"] = "'생명력 표시줄 표시'의 톱니바퀴에서 툴팁 생명력 바의 텍스처와 높이를 설정할 수 있습니다."
L["Inspect Sheet Enchant Text"] = "살펴보기 창 마법부여 글자"
L["The inspect sheet can show enchant names as text like the character sheet, picked from a new Enchants dropdown on both sheets"] = "살펴보기 창에서도 캐릭터 창처럼 마법부여 이름을 글자로 표시할 수 있으며, 양쪽 창 모두 새로운 마법부여 드롭다운에서 선택할 수 있습니다."
L["Stat Item Highlight"] = "능력치 아이템 강조"
L["Hovering a secondary or tertiary stat on the character sheet can glow the equipped items that grant it"] = "캐릭터 창에서 보조 또는 3차 능력치에 마우스를 올리면 해당 능력치를 제공하는 장착 아이템이 반짝입니다."
L["New Window Skins"] = "신규 창 스킨"
L["The Looking For Group, Progress Legacy, micro menu and bag bar windows take the EllesmereUI look, each with its own Window Skins card"] = "파티 찾기, 유산 진행 상황, 게임 메뉴, 가방 바 창에 EllesmereUI 디자인이 적용되며, 각각 전용 창 스킨 카드가 제공됩니다."
L["Glow On Cooldown"] = "재사용 대기 중 반짝임"
L["Glow (On CD) marks a spell for its whole cooldown, by default with Blackout, a black fill under the swipe that is also a Glow Style and Bar Glow"] = "재사용 대기 중 반짝임은 전체 재사용 대기시간 동안 주문을 강조 표시하며, 기본값은 스와이프 아래 검은색 채우기인 암전(Blackout) 효과입니다 (반짝임 스타일 및 바 반짝임에서도 사용 가능)."
L["Bar Glow Conditions"] = "바 반짝임 조건"
L["A Bar Glow can also require a second buff to be active or missing, be limited to one hero talent tree, and be duplicated"] = "바 반짝임에 보조 강화 효과의 활성 또는 누락 조건을 추가할 수 있고, 특정 영웅 특성 트리에만 제한하거나 복제할 수 있습니다."
L["Hidden Until Usable"] = "사용 가능할 때까지 숨김"
L["A Cooldown State Effect that hides a spell until it is usable, so procs like Overpower and Victory Rush show only when they can be pressed"] = "사용 가능해질 때까지 주문을 숨기는 재사용 대기 상태 효과로, 제압이나 승리의 일격처럼 발동되어 누를 수 있을 때만 표시됩니다."

-- == 2026-10-09 신규 (v9.4 핵심 기능: 모서리 둥글기, 가방/은행 잡동사니 지정, 폼/태세 CDM, 이름표 약화 효과) ==
L["Corner Radius"] = "모서리 곡률"
L["Rounded Corners"] = "둥근 모서리"
L["This option requires the Solid, Glow or Shadow border style."] = "이 설정은 단색, 반짝임 또는 그림자 테두리 스타일이 필요합니다."
L["Junk Marker"] = "잡동사니 지정"
L["Click items to mark or unmark them as junk."] = "아이템을 클릭하여 잡동사니로 지정하거나 지정을 해제합니다."
L["Pick up an item, then press the coin to mark it as junk"] = "아이템을 집어든 후 동전을 누르면 잡동사니로 지정됩니다"
L["Sells all your junk items."] = "모든 잡동사니 아이템을 상점에 판매합니다."
L["Sold %1$d junk item(s)"] = "잡동사니 아이템 %1$d개를 판매했습니다"
L["Show a coin on the corner of each junk item's icon."] = "각 잡동사니 아이템 아이콘의 모서리에 동전을 표시합니다."
L["Choose how junk items look in the bags and bank."] = "가방 및 은행에서 잡동사니 아이템이 표시되는 형태를 선택합니다."
L["Bank Display"] = "은행 표시 방식"
L["How items are arranged in the bank window."] = "은행 창에서 아이템이 배열되는 방식입니다."
L["Compact Display"] = "압축 표시"
L["Compact"] = "압축"
L["Bag Top Bar Icons"] = "가방 상단 바 아이콘"
L["Bags Icon"] = "가방 아이콘"
L["Junk Icon"] = "잡동사니 아이콘"
L["Sort Icon"] = "정리 아이콘"
L["Choose which icons show in the bag window's top bar; the Junk Icon is the Junk Marker."] = "가방 창 상단 바에 표시할 아이콘을 선택합니다. 잡동사니 아이콘은 잡동사니 지정 기능입니다."
L["Hide Sidebar Icons When Collapsed"] = "접었을 때 사이드바 아이콘 숨김"
L["Hides a collapsed sidebar; its expand arrow sits by the Inventory title."] = "사이드바를 접었을 때 완전히 숨깁니다. 펼치기 화살표는 소지품 제목 옆에 위치합니다."
L["Window Lock"] = "창 잠금"
L["Quality Item Border"] = "품질별 아이템 테두리"
L["Bag Bar Skin"] = "가방 바 스킨"
L["Micro Menu Skin"] = "게임 메뉴 바 스킨"
L["Same setting as the Bag Bar card on Blizzard Skins+ > Window Skins."] = "블리자드 스킨+ > 창 스킨의 가방 바 카드와 동일한 설정입니다."
L["Same setting as the Micro Menu card on Blizzard Skins+ > Window Skins."] = "블리자드 스킨+ > 창 스킨의 게임 메뉴 카드와 동일한 설정입니다."
L["Which view bags open to by default."] = "가방을 열었을 때 기본으로 표시할 방식을 선택합니다."
L["Hidden Outside Form/Stance"] = "변신/태세 외 숨김"
L["Type /cd to open Blizzard CDM"] = "/cd 입력 시 블리자드 CDM 열기"
L["Lets /cd open or close Blizzard's Cooldown Manager settings."] = "/cd 입력으로 블리자드 기본 재사용 대기시간 관리자 설정을 열거나 닫을 수 있게 허용합니다."
L["The /cd change applies after a UI reload."] = "/cd 명령어 변경 사항은 UI를 다시 불러온 후 적용됩니다."
L["+ Add Class"] = "+ 직업 추가"
L["COMBOS"] = "연계 약화 효과"
L["DEBUFFS"] = "약화 효과"
L["Combos"] = "연계 약화 효과"
L["A combo holds up to four debuffs."] = "연계 약화 효과는 최대 4개의 약화 효과를 조합할 수 있습니다."
L["NAME FORMAT"] = "이름 표기 방식"
L["Name Format"] = "이름 표기 방식"
L["Enemy nameplate names and their targets."] = "적 이름표의 이름 및 대상 이름입니다."
L["Friendly player nameplates, in both modes."] = "아군 플레이어 이름표 이름입니다 (두 모드 공통)."
L["Raid and party frame names."] = "공격대 및 파티 프레임의 이름입니다."
L["Player names on the meter bars."] = "미터기 바에 표시되는 플레이어 이름입니다."
L["Player names on the threat meter, for all your characters."] = "위협 수준 미터기에 표시되는 플레이어 이름입니다 (내 모든 캐릭터 적용)."
L["Every unit frame text that shows a name."] = "이름을 표시하는 모든 유닛 프레임 텍스트입니다."
L["Other players' names show in full during combat."] = "전투 중에는 다른 플레이어의 이름이 전체 이름으로 표시됩니다."
L["Checked modules show their first name. A module checked in both lists shows the full name."] = "체크된 모듈은 이름을 표시합니다. 양쪽 목록 모두 체크된 모듈은 전체 이름을 표시합니다."
L["Checked modules show their last name. A module checked in both lists shows the full name."] = "체크된 모듈은 성을 표시합니다. 양쪽 목록 모두 체크된 모듈은 전체 이름을 표시합니다."
L["Choose where your combo points show."] = "연계 점수가 표시될 위치를 선택합니다."
L["Class Resource must be set to Blizzard"] = "직업 자원이 블리자드 기본으로 설정되어 있어야 합니다."
L["Blizzard's combo points return to its target frame after a UI reload."] = "UI를 다시 불러오면 블리자드 연계 점수가 원래 대상 프레임으로 복귀합니다."
L["Outline style override for all Raid Frames text. EUI Global Outline follows the global Outline Mode setting above."] = "공격대 프레임의 모든 텍스트에 적용되는 외곽선 스타일 오버라이드입니다. EUI 전역 외곽선은 상단의 전역 외곽선 모드 설정을 따릅니다."
L["Outline style override for all Forever Essentials text. EUI Global Outline follows the global Outline Mode setting above."] = "Forever Essentials의 모든 텍스트에 적용되는 외곽선 스타일 오버라이드입니다. EUI 전역 외곽선은 상단의 전역 외곽선 모드 설정을 따릅니다."
L["Dispel Type Icon"] = "해제 유형 아이콘"
L["Pet Frames"] = "소환수 프레임"
L["Current / Max"] = "현재 / 최대"
L["Choose the specs this action menu works in."] = "이 액션 메뉴가 활성화될 전문화를 선택합니다."
L["Two action menus can share a keybind when Assign to Spec keeps them from ever loading in the same spec."] = "'전문화 지정'을 통해 두 액션 메뉴가 동일한 전문화에서 절대 동시에 활성화되지 않는 경우, 동일한 단축키를 공유할 수 있습니다."
L["%1$s now shares %2$s with %3$s."] = "%1$s이(가) 이제 %3$s와 %2$s 단축키를 공유합니다."
L["%1$s no longer shares the key of %2$s: they can now load in the same spec."] = "%1$s이(가) 더 이상 %2$s의 단축키를 공유하지 않습니다. 이제 동일한 전문화에서 로드될 수 있습니다."
L["%1$s share it and will lose it too."] = "%1$s도 단축키를 공유하고 있으므로 함께 해제됩니다."
L["%1$s shares it and will lose it too."] = "%1$s도 단축키를 공유하고 있으므로 함께 해제됩니다."
L["Shared with %1$s."] = "%1$s와(과) 공유 중입니다."
L["and %1$s, which shared it"] = "및 단축키를 공유하던 %1$s"
L["Dim Unusable Actions"] = "사용 불가능한 액션 어둡게 표시"
L["Dims any actions you can't use right now."] = "현재 사용할 수 없는 액션을 어둡게 표시합니다."
L["Hide Unavailable Actions"] = "사용 불가능한 액션 숨김"
L["Hides any actions not available to this character."] = "이 캐릭터가 사용할 수 없는 액션을 숨깁니다."
L["Ignore Older Expansion Quests"] = "이전 확장팩 퀘스트 무시"
L["Blessings by Role"] = "역할군별 축복"
L["Tank Blessing"] = "방어 전담 축복"
L["Healer Blessing"] = "치유 전담 축복"
L["DPS Blessing"] = "공격 전담 축복"
L["Thorns Only on Tank"] = "방어 전담에만 가시"
L["Thorns shows on tanks only while the group has one, and on you while solo or without a tank."] = "파티에 방어 전담이 있을 때는 방어 전담에게만 가시 강화 효과를 표시하고, 솔로 플레이거나 방어 전담이 없을 때는 자신에게 표시합니다."
L["Latest"] = "최신"
L["Major Features"] = "주요 기능"
L["Additional Features"] = "추가 기능"
