L["Combo Points Placement"] = "연계 점수 표시 위치"

-- == 2026-10-09 신규 (v9.4 패치 노트: EUI 9.4 What's New) ==
L["Choose the layer the bags and bank draw on; it replaces Allow Windows Over Bags, and your choice there carries over"] = "가방과 은행 창이 표시될 화면 레이어를 선택합니다. 기존의 '가방 위에 다른 창 허용'을 대체하며 이전 설정이 유지됩니다"
L["The player frame can show the dispel type's icon on a corner of its health bar, with its own size and offsets, as Raid Frames does"] = "공격대 프레임처럼 플레이어 프레임 생명력 바 모서리에도 해제 유형 아이콘을 전용 크기 및 위치 조정 옵션과 함께 표시할 수 있습니다"
L["Auto Accept can leave quests from older expansions for you to pick up yourself once you reach max level"] = "최고 레벨 달성 후 퀘스트 자동 수락 기능이 이전 확장팩 퀘스트는 자동으로 받지 않고 직접 수락할 수 있도록 제외합니다"
L["Bag Style and Bank Display have a new Compact choice: each category becomes a block of icons with its name and count on top, side by side with a small gap and arranged to keep the window short. In the bag window, carry an item to drop it on a category."] = "가방 스타일 및 은행 표시에 새로운 '압축' 옵션이 추가되었습니다: 각 카테고리가 상단에 이름과 수량이 표시된 아이콘 블록으로 정렬되며, 좁은 간격으로 나란히 배치되어 창 높이를 간결하게 유지합니다. 가방 창에서 아이템을 집어 원하는 카테고리에 놓아 이동시킬 수 있습니다."
L["Unit Frames, Raid Frames, Nameplates and Resource Bars can round their corners: a Corner Radius cog next to each border color rounds the bars along with their Solid, Glow or Shadow border. Corners stay square until you set a radius."] = "유닛 프레임, 공격대 프레임, 이름표 및 자원 바의 모서리를 둥글게 설정할 수 있습니다: 각 테두리 색상 옆의 '모서리 곡률' 톱니바퀴에서 단색, 반짝임 또는 그림자 테두리와 함께 바 모서리를 둥글게 만듭니다. 곡률을 설정하기 전까지는 기존처럼 직각 모서리로 유지됩니다."
L["A new Cooldown State Effect, picked in each spell's menu, shows a spell only in the form or stance it can be cast in, so caster spells hide while you are in a form that cannot cast them. A Shift Icons version also closes the gap the hidden icons leave."] = "각 주문 메뉴에서 선택할 수 있는 새로운 재사용 대기 상태 효과입니다: 해당 주문을 시전할 수 있는 변신 형태나 태세일 때만 주문을 표시하므로, 시전할 수 없는 변신 상태일 때는 일반 시전자 주문이 자동으로 숨겨집니다. '아이콘 당김' 버전을 사용하면 숨겨진 아이콘이 남긴 빈 공간도 자동으로 채웁니다."
L["A coin button on the bags, on by default, marks items as junk with a click. Marked and grey items gather in their own Junk category, Junk Item Visuals picks how they look, and Sell Junk or Auto Sell Junk sells them at merchants."] = "가방 상단에 기본으로 표시되는 동전 단추를 클릭하여 아이템을 잡동사니로 간편하게 지정할 수 있습니다. 지정된 아이템과 회색 아이템은 전용 '잡동사니' 카테고리에 모이며, '잡동사니 아이템 시각 효과'로 표시 형태를 변경하고, 상점에서 '잡동사니 판매' 또는 자동 판매 기능으로 일괄 매각할 수 있습니다."
L["Pick which of the Bags, Junk and Sort icons show in the bag window's top bar"] = "가방 창 상단 바에 표시할 가방, 잡동사니, 정리 아이콘을 선택합니다"
L["A collapsed sidebar can hide completely, with its expand arrow next to the Inventory title"] = "사이드바를 접었을 때 완전히 숨길 수 있으며, 펼치기 화살표는 소지품 제목 옆에 위치합니다"
L["One setting now colors item borders by quality in every bag and bank display, on by default; Grid and Compact can now turn it off"] = "하나의 설정으로 모든 가방 및 은행 표시에서 아이템 테두리를 품질 색상으로 표시합니다 (기본 켜짐). 격자 및 압축 표시에서도 이제 개별적으로 끌 수 있습니다"
L["The bag and bank windows get a corner lock: unlocked, a plain drag moves them (no Shift needed) and a grip resizes them"] = "가방 및 은행 창 모서리에 자물쇠가 추가되었습니다: 잠금을 풀면 Shift 없이 아무 곳이나 드래그하여 이동할 수 있고, 크기 조절 손잡이가 표시됩니다"
L["Friends show as EllesmereUI tiles with class icons, class colors, region icons and optional faction banners, and invites can auto-accept"] = "친구 목록을 직업 아이콘, 직업 색상, 지역 아이콘 및 진영 깃발이 포함된 EllesmereUI 타일 형태로 표시하며, 파티 초대를 자동으로 수락할 수 있습니다"
L["Pick first, last or full names for every module at once, now also on friendly player nameplates, Damage Meters and the threat meter"] = "모든 모듈의 이름 표기를 이름, 성, 전체 이름 중 한 번에 일괄 설정할 수 있으며, 아군 플레이어 이름표, 데미지 미터기 및 위협 수준 미터기에도 적용됩니다"
L["/cd now opens Blizzard's Cooldown Manager only while this new option is on; it is off by default, leaving /cd free for other addons"] = "이 옵션이 켜져 있을 때만 /cd 명령어로 블리자드 재사용 대기시간 관리자를 엽니다. 기본적으로 꺼져 있어 다른 애드온과의 명령어 충돌을 방지합니다"
L["Each action menu can be assigned to the specs it works in, and menus that never load in the same spec can share one keybind"] = "각 액션 메뉴를 사용할 전문화에 개별 지정할 수 있으며, 같은 전문화에서 겹치지 않는 메뉴끼리는 동일한 단축키를 공유할 수 있습니다"
L["Missing Buffs reminds you of the blessing you pick for each role (Kings while solo), and Thorns can show on tanks only"] = "누락된 강화 효과 알림에서 역할군별로 지정한 축복을 안내하며(솔로 플레이 시 왕의 축복), 가시 강화 효과를 방어 전담에게만 표시할 수 있습니다"
L["Debuff filters on the unit frames, Player Aura Bars and Raid Frames can now show or hide Sated and the other Bloodlust lockout debuffs"] = "유닛 프레임, 플레이어 오라 바 및 공격대 프레임의 약화 효과 필터에서 만족함, 탈진 등 피의 욕망 재사용 대기 약화 효과를 표시하거나 숨길 수 있습니다"
L["The Blizzard-style combo points can now show on the target frame, the player frame, or not at all"] = "블리자드 스타일 연계 점수를 대상 프레임, 플레이어 프레임에 표시하거나 완전히 숨길 수 있습니다"
L["On a first install, the Pet Bar no longer starts hidden in the top-left corner when no pet was out: it starts set to Always above your other bars, where Blizzard places it (the Stance Bar too, for characters without forms yet)."] = "처음 애드온을 설치할 때 소환수가 없더라도 소환수 바가 좌측 상단 구석에 숨겨진 채 시작되지 않습니다: 블리자드 기본 위치인 단축바 상단에 '항상 표시'로 배치됩니다 (변신 폼이 아직 없는 캐릭터의 태세 바도 동일)."
L["Recent Items now lists your newest pickups first in every view, moves an item back to the top when you loot more of it, and no longer lists gear you take off or swap out with an equipment set."] = "'최근 획득 아이템'이 모든 뷰에서 가장 최근에 획득한 아이템을 맨 위에 표시하고 추가 획득 시 최상단으로 이동시키며, 장비 세트 교체나 장비 탈의 시에는 목록에 추가되지 않습니다."
L["Picking an item to pin or file now ends when you click outside the bags (instead of passing the click through) or close them, and the selection no longer holds the keyboard."] = "고정하거나 분류할 아이템을 선택할 때 가방 외부를 클릭하거나 가방을 닫으면 선택 모드가 정상 종료되며, 키보드 입력이 고정되지 않습니다."
L["An open bank window now follows the bags' search box and Window Scale changes right away, and the Desaturate option of Junk Item Visuals now also greys junk in the bank's Grid and Compact displays."] = "열려 있는 은행 창이 가방 검색창과 창 크기 비율 변경을 즉시 반영하며, '잡동사니 아이템 시각 효과'의 흑백 표시 옵션이 은행의 격자 및 압축 표시에서도 정상 적용됩니다."
L["The Hide links on the Pinned Items and Recent Items headers now always hide the section you clicked, even after switching between OneBag and All Items."] = "'고정된 아이템' 및 '최근 획득 아이템' 상단의 숨기기 링크를 클릭하면 OneBag과 All Items 보기 사이를 전환한 후에도 해당 섹션이 항상 정상적으로 숨겨집니다."
L["A custom category's Edit | Delete links no longer stay on screen after you switch to another view."] = "사용자 지정 카테고리의 편집/삭제 링크가 다른 뷰로 전환한 후에도 화면에 남아 있던 문제를 수정했습니다."
L["Switching profiles now applies that profile's categories right away."] = "프로필을 전환하면 해당 프로필의 카테고리가 즉시 화면에 적용됩니다."
L["The Pinned Items and Recent Items hints now show when you hover their titles, and new users get a one-time tip that sidebar categories can be dragged to reorder them."] = "'고정된 아이템'과 '최근 획득 아이템' 제목에 마우스를 올리면 힌트가 표시되며, 신규 사용자에게 사이드바 카테고리를 드래그하여 순서를 바꿀 수 있다는 안내가 1회 제공됩니다."
L["Merge Duplicate Items, Category Title Size and Group Gear by Slot (formerly Group Armory by Slot) now also apply to the List display, which merges duplicates unless you turn it off and groups gear under equipment slot headers."] = "'중복 아이템 합치기', '카테고리 제목 크기' 및 '장비를 부위별로 묶기'(구 무기고 부위별 묶기)가 목록 표시에도 적용되어, 중복 아이템을 합치고 장비 부위별 하위 제목으로 분류합니다."
L["The OneBag Randomize button and the OneBag / MultiBag warning text are gone."] = "OneBag 무작위 섞기 버튼과 OneBag / MultiBag 경고 안내 문구가 제거되었습니다."
L["Showing player buffs on tooltips no longer causes an error when hovering raid or party frames in combat."] = "전투 중 공격대나 파티 프레임에 마우스를 올렸을 때 툴팁에 플레이어 강화 효과를 표시하는 기능이 더 이상 오류를 일으키지 않습니다."
L["Resurrect Accept Glow now needs Reskin Popups and Menus, and is greyed out while that is off."] = "'부활 수락 반짝임' 설정에 '팝업 및 메뉴 스킨 변경' 옵션이 필요하게 변경되었으며, 해당 옵션이 꺼져 있으면 비활성화됩니다."
L["Spell ID on Tooltip is now on by default for new installs; existing setups keep their setting."] = "새로 설치 시 '툴팁에 주문 ID 표시'가 기본 활성화됩니다. 기존 설정값은 유지됩니다."
L["The Premade Groups filter's reset X now draws above the filter button's border."] = "파티 찾기 필터의 초기화(X) 버튼이 필터 버튼 테두리 위에 정상적으로 그려집니다."
L["The Looking For Group skin's refresh button now shows its icon, its options cog is a plain cog that is always visible, the big eye in the top left corner is gone, and the role header's background ends on the line under it."] = "파티 찾기 스킨의 새로고침 버튼에 아이콘이 표시되고, 설정 톱니바퀴가 항상 표시되며, 좌측 상단의 큰 눈 아이콘이 제거되고 역할군 헤더 배경이 깔끔하게 정돈되었습니다."
L["The Character window's Reputation tab now matches the other tabs in the EllesmereUI look, keeping Blizzard's own list on the window's background."] = "캐릭터 창의 평판 탭이 다른 탭들과 동일하게 EllesmereUI 테마 디자인으로 통일되었습니다."
L["The inspect window's Talents button no longer covers the average item level, and the ranged slot now fits beside the other weapons with its own item level and enchant."] = "살펴보기 창의 특성 버튼이 평균 아이템 레벨을 가리지 않으며, 원거리 무기 슬롯이 다른 무기 옆에 자체 아이템 레벨 및 마법부여와 함께 알맞게 배치됩니다."
L["Whisper tabs now blink when a whisper arrives while you are viewing another tab."] = "다른 대화 탭을 보고 있을 때 귓속말이 도착하면 해당 귓속말 탭이 깜빡입니다."
L["A queued Heroic Strike, Cleave, Maul or Raptor Strike now lights up on the Cooldown Manager with the same highlight your action bars show."] = "다음 자동 공격에 발동 대기 중인 영웅의 일격, 회전베기, 후려치기, 랩터의 일격이 단축바와 동일한 하이라이트로 재사용 대기시간 관리자에도 강조 표시됩니다."
L["Choosing the WoW Forever look now gives the Blizzard Skins+ windows the EllesmereUI skin instead of Blizz Default (the micro menu and bag bar keep Blizzard's look)."] = "WoW Forever 스타일을 선택하면 블리자드 스킨+ 창에 블리자드 기본 대신 EllesmereUI 스킨이 적용됩니다 (게임 메뉴 및 가방 바는 블리자드 디자인 유지)."
L["With Debuff Coloring set to Color Border, a combo's color now always shows over its single debuffs."] = "약화 효과 색상 설정을 '테두리 색상'으로 설정했을 때, 개별 약화 효과 색상보다 조합(콤보) 색상이 항상 우선하여 표시됩니다."
L["Dim Unusable Actions now grays out mount entries where you can't mount, such as indoors."] = "'사용 불가능한 액션 어둡게 표시'가 실내 등 탈것을 탈 수 없는 지역에서 탈것 항목을 회색으로 표시합니다."
L["Quickdraw is no longer part of Spec Overrides: its per-spec overrides are dropped (your current settings stay), and Assign to Spec on each action menu takes their place."] = "Quickdraw가 전문화별 오버라이드에서 분리되었습니다: 전문화별 오버라이드 대신 각 액션 메뉴의 '전문화 지정' 기능이 이를 대체합니다 (현재 설정값 유지)."
L["With Smooth Bars off, the Devourer Demon Hunter's soul fragments bar no longer eases its fill; every bar now follows its Smooth Bars setting."] = "'부드러운 바 채우기'를 껐을 때 파멸 악마사냥꾼의 영혼 파편 바가 더 이상 지연 애니메이션을 적용하지 않으며, 모든 바가 자신의 부드러운 바 설정을 정확히 따릅니다."
L["Blizzard Class Resource Art now centers each class's points on the Class Resource Bar's spot, so it no longer sits off center or shifts when you switch characters."] = "블리자드 직업 자원 아트가 직업 자원 바 위치의 중앙에 정렬되어, 캐릭터를 변경해도 위치가 틀어지거나 중심을 벗어나지 않습니다."
L["The Mana Bar while Shapeshifted now follows the Power Bar's Smooth Bars setting."] = "변신 중 마나 바가 자원 바의 '부드러운 바 채우기' 설정을 따릅니다."
L["The swing timer's Highlight Queued Attacks now also lights up for the Hunter's Raptor Strike."] = "스윙 타이머의 '발동 대기 공격 강조'가 사냥꾼의 랩터의 일격에도 정상적으로 활성화됩니다."
L["Rogues now have their own class resource setting under the EllesmereUI style, hidden until you turn it on, so a rogue's choice no longer changes other classes on the same profile."] = "도적이 EllesmereUI 스타일에서 독립적인 직업 자원 설정을 가지게 되어, 도적의 설정이 동일 프로필의 다른 직업에 영향을 주지 않습니다."
L["Brazilian Portuguese, German, Simplified Chinese and Traditional Chinese translations updated for the latest options, and the Cooldown Manager's add-by-ID popups now show their error messages in your language."] = "최신 옵션에 맞춰 번역이 업데이트되었으며, 재사용 대기시간 관리자의 주문 ID 추가 팝업에서 오류 메시지가 한국어로 정상 표시됩니다."

-- 2026-10-15 신규

L["SELF COMBAT TEXT"] = "플레이어 전투 메시지"
L["Show Speaker Name"] = "대화명 표시"
L["EUI Legends"] = "EUI 명예의 전당"
L["Blizzard Skins+"] = "블리자드 스킨+"
L["Glow Settings"] = "반짝임 설정"
L["Which ends of the bar show end cap art; the cog picks the art."] = "바의 양쪽 끝 장식을 설정합니다. 톱니바퀴 아이콘에서 아트 선택." 
L["Show Dividers"] = "구분선 표시"
L["+ Add Text Slot"] = "+ 텍스트 슬롯 추가"
L["Text Background"] = "텍스트 배경"
L["Next and previous page, from the keybinds or the paging arrows, skip the pages your other enabled bars use."] = "단축키나 페이지 넘김 화살표로 이전/다음 페이지 이동 시, 다른 활성화된 단축바가 사용 중인 페이지를 건너뜁니다."
L["This option does not work with the Gamepad interface style (after switching away from it, reload to use it)."] = "이 옵션은 게임패드 인터페이스 스타일에서 작동하지 않습니다 (다른 스타일로 전환한 후 사용하려면 UI를 다시 불러오세요)."
L["Glow When Usable"]               = "사용 가능할 때 빛나기"
L["Glow When Visible"]             = "표시될 때 빛나기"
L["Keeps the icon in full color while you lack the resource to cast it. Out of range still tints it red."] = "시전할 자원이 부족해도 아이콘이 전체 색상으로 유지됩니다. 사정거리를 벗어나면 여전히 빨간색으로 표시됩니다."
L["Only available for a buff in Active mode"] = "활성 모드의 강화 효과에만 사용할 수 있습니다."
L["this ability"]                  = "이 능력"
L["This option is not available in Glow When Usable mode"] = "이 옵션은 사용 가능할 때 빛나기 모드에서는 사용할 수 없습니다."
L["Usable"]                        = "사용 가능"
L["How far from the top of the screen nameplates stop. 0 lets them reach the edge."] = "이름표가 화면 상단에서 얼마만큼 떨어져 멈출지 설정합니다. 0으로 설정하면 화면 맨 위까지 올라갑니다."
L["How fast stacked nameplates slide into place. 100% is Blizzard's default."] = "중첩된 이름표가 제자리로 정렬되는 속도입니다. 100%는 블리자드 기본값입니다."
L["Join Cast Bar"]                 = "시전 바 결합"
L["Show a border on enemy buffs you can dispel, purge or soothe."] = "해제, 정화 또는 진정시킬 수 있는 적 강화 효과에 테두리를 표시합니다."
L["Show a border on your debuffs while they can be refreshed without losing any duration."] = "지속 시간을 잃지 않고 갱신할 수 있는 약화 효과에 테두리를 표시합니다."
L["Show the spell tooltip when you hover a buff or debuff icon on a nameplate.\n\nWhile the cursor is over an icon, the plate behind it will not highlight or take mouseover targeting."] = "이름표의 강화 효과 또는 약화 효과 아이콘 위에 마우스를 올릴 때 주문 툴팁을 표시합니다.\n\n커서가 아이콘 위에 있는 동안에는 뒤에 있는 이름표가 강조 표시되거나 마우스오버 타겟팅을 받지 않습니다."
L["While a cast shows, rounds the health bar and the cast bar under it as one shape."] = "시전 바가 활성화되어 있는 동안, 생명력 바와 그 아래의 시전 바 모서리를 하나의 프레임처럼 둥글게 만듭니다."
L["Debuff Filter: Important or Own"] = "약화 효과 필터: 중요 또는 내 것"
L["Health # Short (230.5K)"]       = "생명력 # 요약 (230.5K)"
L["Join Power Bar"]                = "자원 바 결합"
L["Limits important debuffs not cast by you."] = "내가 시전하지 않은 다른 중요 약화 효과의 표시 개수를 제한합니다."
L["Rounds a detached power bar right above or below the frame as one shape with it."] = "프레임 바로 위나 아래에 분리된 자원 바를 프레임과 일체형처럼 모서리를 둥글게 만듭니다."
L["The frame whose aura look the pet copies."] = "소환수가 오라 외형을 복사할 프레임입니다."
L["Match Highlight Colors"]        = "강조 색상 일치"
L["Pixels or Pixels Textured Border Style"] = "픽셀 또는 픽셀 텍스처 테두리 스타일"
L["Requires Divider."]             = "구분선이 필요합니다."
L["Requires Match Frame Border and Divider."] = "프레임 테두리 일치 및 구분선이 필요합니다."
L["Separates the name bar from the health bar."] = "이름 바를 생명력 바에서 분리합니다."
L["Show Healer, Tank, or DPS text instead of the role icon, using the same size, position, and Show Role settings."] = "역할 아이콘 대신 힐러, 탱커 또는 딜러 텍스트를 동일한 크기, 위치 및 역할 표시 설정으로 표시합니다."
L["Size and color follow the frame border while Match Frame Border is enabled."] = "프레임 테두리 일치가 활성화된 동안 크기와 색상이 프레임 테두리를 따릅니다."
L["The divider follows hover and target colors."] = "구분선은 마우스오버 및 대상 색상을 따릅니다."
L["Top Name Bar Options"]          = "상단 이름 바 옵션"
L["Uses the frame border's art, size and color."] = "프레임 테두리의 아트, 크기 및 색상을 사용합니다."
L["Appends the spell's rank to the spell name, for spells that have one."] = "등급이 존재하는 주문의 경우, 주문 이름 뒤에 등급을 표시합니다."
L["Hides the power bar whenever the class resource bar is showing."] = "직업 자원 바가 표시되는 동안 자원 바를 숨깁니다."
L["Adds /way, which prints a map pin link."] = "지도 핀 링크를 출력하는 /way를 추가합니다."
L["Also announces arrival at pins you place."] = "배치한 핀에 도착했을 때도 알립니다."
L["Cannot determine your current zone."] = "현재 지역을 확인할 수 없습니다."
L["Changing the /way command requires a reload to update slash command registration."] = "/way 명령어를 변경하려면 슬래시 명령어 등록을 업데이트하기 위해 UI를 다시 불러와야 합니다."
L["Click a link to place the pin, then click the pin on the map to track it."] = "링크를 클릭하여 핀을 배치하고 지도에서 핀을 클릭하여 추적하세요."
L["Hand-Placed Pin Arrival"]       = "수동 배치 핀 도착"
L["Map pins cannot be placed inside instances."] = "인스턴스 내부에 지도 핀을 배치할 수 없습니다."
L["Map pins cannot be placed on %1$s."] = "%1$s에 지도 핀을 배치할 수 없습니다."
L["Next:"]                         = "다음:"
L["Potion Ready"]                  = "물약 준비 완료"
