L["Several zones match %1$s:"]     = "%1$s과 일치하는 여러 지역:"
L["Shows on-screen text when a potion you used is off cooldown again. Use the cog to set the text, size and color; use Unlock Mode to reposition the alerts."] = "사용한 물약의 재사용 대기시간이 돌아왔을 때 화면에 텍스트를 표시합니다. 톱니바퀴를 사용하여 텍스트, 크기, 색상을 설정하고, 잠금 해제 모드를 사용하여 경고 위치를 재배치하세요."
L["Shows on-screen text while you have unspent talent points. It stays up until you spend them or open your talents, and returns after a level-up. Use the cog to set the text, size and color; use Unlock Mode to reposition the alerts."] = "사용하지 않은 특성 포인트가 있는 동안 화면에 텍스트를 표시합니다. 포인트를 사용하거나 특성을 열 때까지 유지되며 레벨 업 후 다시 나타납니다. 톱니바퀴를 사용하여 텍스트, 크기, 색상을 설정하고, 잠금 해제 모드를 사용하여 경고 위치를 재배치하세요."
L["To remove the pin, ctrl-click it on the world map."] = "핀을 제거하려면 세계 지도에서 Ctrl 키를 누른 채 클릭하세요."
L["Unknown map ID: %1$s"]            = "알 수 없는 지도 ID: %1$s"
L["Unknown zone: %1$s"]            = "알 수 없는 지역: %1$s"
L["Unspent talent points"]         = "사용하지 않은 특성 포인트"
L["Unspent Talents Alert"]         = "미사용 특성 경고"
L["Unspent Talents Alert Settings"] = "미사용 특성 경고 설정"
L["Usage:"]                        = "사용법:"
L["You have arrived:"]             = "도착했습니다:"
L["CDM module"]                    = "쿨다운 매니저 모듈"
L["During Mythic+ boss fights, shows a glowing red Beacon on your tank's raid frame while they have your Beacon of Light or Beacon of Faith."] = "신화+ 우두머리 전투 중, 탱커가 빛의 봉화나 믿음의 봉화를 가지고 있을 때 탱커의 공격대 프레임에 빛나는 빨간색 봉화를 표시합니다."
L["for in combat aura/rotational reminders please use the %s"] = "전투 중 오라/딜 사이클 알림을 위해 %s을(를) 사용하세요."
L["Open the Cooldown Manager's Buffs bar"] = "쿨다운 매니저의 강화 효과 바 열기"
L["Reminds you when you have no Well Fed buff."] = "‘포만감’ 강화 효과가 없을 때 알림을 표시합니다."
L["This module is for OUT OF COMBAT non-rotational buff/consumable reminders,"] = "이 모듈은 비전투 중 딜 사이클과 관계없는 강화 효과/소모품 알림용입니다."
L["Adds Leech, Avoidance and Speed (L, A, S) in smaller letters behind the secondary stats in the gear flyout."] = "장비 확장 메뉴의 부 능력치 뒤에 생명력 흡수, 광역 회피, 이동 속도(L, A, S)를 작은 글자로 추가합니다."
L["Shows each item's secondary stats as letters in the gear flyout, largest first (C Crit, H Haste, M Mastery, V Versatility), so items with the same icon are told apart."] = "장비 확장 메뉴에서 각 아이템의 부 능력치를 수치가 높은 순서대로(C 치명타, H 가속도, M 특화, V 유연성) 문자로 표시하여 아이콘이 같은 아이템을 쉽게 구분할 수 있도록 합니다."
L["Shows each socketed gem's secondary stats as letters on its icon, largest first (C Crit, H Haste, M Mastery, V Versatility)."] = "보석이 장착된 홈 아이콘 위에 부 능력치를 수치가 높은 순서대로(C 치명타, H 가속도, M 특화, V 유연성) 문자로 표시합니다."
L["Socket Panel Settings"]         = "보석 홈 패널 설정"
L["Tertiary Stat Letters"]         = "3차 능력치 문자 표시"
L["WoW Forever's frame round the chat panel, input box, tabs and sidebar buttons. Slim Textured uses Blizzard's current art; a style whose art this client lacks draws Slim. Applies after a UI reload."] = "채팅 패널, 입력창, 탭 및 사이드바 버튼을 둘러싼 WoW Forever 프레임입니다. 슬림 텍스처는 블리자드의 현재 아트를 사용하며, 아트가 부족한 스타일은 슬림으로 그려집니다. UI를 다시 불러온 후 적용됩니다."
L["Click: %s"]                     = "클릭: %s"
L["Hide from Other Categories"]    = "다른 카테고리에서 숨기기"
L["Highlights the items your spells can work on (%s). Click a matching item while this mode is on, or Alt-click it. Out of combat only."] = "주문이 작용할 수 있는 아이템을 강조 표시합니다(%s). 이 모드가 켜져 있는 동안 일치하는 아이템을 클릭하거나 Alt-클릭하세요. 비전투 중에만 가능합니다."
L["Leave Quick Actions."]          = "빠른 작업 나가기."
L["Pinned items show only in Pinned Items, not in their categories or Recent Items."] = "고정된 아이템은 해당 카테고리나 최근 아이템이 아닌 고정된 아이템에만 표시됩니다."
L["Quick Actions Icon"]            = "빠른 작업 아이콘"
L["The bags automatically open when the character window is opened and close again when the character window is closed."] = "캐릭터 창이 열릴 때 가방이 자동으로 열리고 캐릭터 창이 닫힐 때 다시 닫힙니다."
L["Circle: the round map in WoW Forever's ring. Square: the EllesmereUI square map in a thin bronze frame, with the zone name in its title bar. Applies after a UI reload."] = "원형: WoW Forever 링의 둥근 지도. 사각형: 얇은 청동 프레임에 타이틀 바의 지역 이름이 있는 EllesmereUI 사각형 지도. UI를 다시 불러온 후 적용됩니다."
L["Forever Circle"]                = "Forever 원형"
L["Forever Circle: the round map in WoW Forever's ring. Forever Square: the EllesmereUI square map in the bronze frame of WoW Forever's windows, with the zone name in its title bar. Applies after a UI reload."] = "Forever 원형: WoW Forever 링의 둥근 지도. Forever 사각형: 타이틀 바에 지역 이름이 있는 WoW Forever 창의 청동 프레임 속 EllesmereUI 사각형 지도. UI를 다시 불러온 후 적용됩니다."
L["Forever Square"]                = "Forever 사각형"
L["This client is missing WoW Forever's window frame art."] = "이 클라이언트에는 WoW Forever의 창 프레임 아트가 누락되어 있습니다."
L["WoW Forever's frame round the meter windows, the breakdown, Spell History and the Forever Essentials threat meter. Slim Textured uses Blizzard's current art; a style whose art this client lacks draws Slim. Applies after a UI reload."] = "미터기 창, 상세 내역, 주문 기록 및 Forever Essentials 위협 수준 미터기를 둘러싼 WoW Forever 프레임입니다. 슬림 텍스처는 블리자드의 현재 아트를 사용하며, 아트가 부족한 스타일은 슬림으로 그려집니다. UI를 다시 불러온 후 적용됩니다."
