L["Edit your macros by click: a line editor with every option and the live macro text. /euimacros opens this page."] = "클릭으로 매크로를 편집하세요: 모든 옵션이 포함된 줄 편집기와 라이브 매크로 텍스트. /euimacros로 이 페이지를 엽니다."
