L["Pet: passive"] = "소환수: 수동적"
L["Pet: stay"] = "소환수: 대기"
L["Pet: toggle autocast"] = "소환수: 자동 시전 전환"
L["Pick Up"] = "집기"
L["Please enter a name."] = "이름을 입력하세요."
L["Presses another button by its frame name, e.g. to trigger an action bar slot."] = "프레임 이름으로 다른 버튼을 누릅니다(예: 액션바 슬롯 트리거)."
L["Price Position"] = "가격 위치"
L["Puts a raid marker on your target: 1 star, 2 circle, 3 diamond, 4 triangle, 5 moon, 6 square, 7 cross, 8 skull."] = "대상에게 공격대 징표를 부여합니다: 1 별, 2 동그라미, 3 다이아몬드, 4 세모, 5 달, 6 네모, 7 가위표(X), 8 해골."
L["Raid marker"] = "공격대 징표"
L["Raid Warning"] = "공격대 경보"
L["Random item"] = "무작위 아이템"
L["Random spell"] = "무작위 주문"
L["Remembers a unit as focus so you can cast on it with @focus."] = "@focus로 주문을 시전할 수 있도록 유닛을 주시 대상으로 기억합니다."
L["Remove line"] = "줄 제거"
L["Removes a buff from you, e.g. Ice Block or a speed buff."] = "얼음 방패나 이속 강화 효과 등 자신에게서 강화 효과를 제거합니다."
L["Reveal Unexplored Areas Settings"] = "미탐험 지역 표시 설정"
L["Runs a line of Lua code (same as /run)."] = "Lua 코드 한 줄을 실행합니다(/run과 동일)."
L["Runs a line of Lua code. Protected actions (spells, targeting) are blocked in combat."] = "Lua 코드 한 줄을 실행합니다. 보호된 작업(주문, 대상 지정)은 전투 중 차단됩니다."
L["Save the macro first."] = "먼저 매크로를 저장하세요."
L["Saved For"] = "저장 대상"
L["Saved, but the game changed the text: this is what it kept."] = "저장되었지만 게임이 텍스트를 변경했습니다: 유지된 내용은 다음과 같습니다."
L["Saved."] = "저장됨."
L["Sends a chat message (say, party, raid, emote...). %t is replaced by your target's name."] = "채팅 메시지를 보냅니다(일반, 파티, 공격대, 감정표현...). %t는 대상의 이름으로 대체됩니다."
L["Sends your pet to attack your target (or the unit you choose)."] = "소환수를 보내어 대상(또는 선택한 유닛)을 공격하게 합니다."
L["Set focus"] = "주시 대상 설정"
L["Setting and value, e.g. Sound_EnableSFX 0"] = "설정 및 값, 예: Sound_EnableSFX 0"
L["Shift is held down."] = "Shift 키를 누르고 있음."
L["Shortens Equip: and Set: stat lines on item tooltips to +X Stat."] = "아이템 툴팁의 장착 효과 및 세트 효과 능력치 줄을 +X 능력치로 줄입니다."
L["Show Empty Bag Slots"] = "빈 가방 칸 표시"
L["Show Spell Tooltip"] = "주문 툴팁 표시"
L["Shows equal spell damage and healing as one Spell Power line."] = "동일한 주문 피해와 치유량을 하나의 주문력 줄로 표시합니다."
L["Shows free and total bag slots as the title."] = "제목으로 빈 가방 칸과 전체 칸을 표시합니다."
L["Shows the parts of the world map you have not explored yet. Use the cog to pick their color."] = "아직 탐험하지 않은 세계 지도 부분을 표시합니다. 톱니바퀴를 사용하여 색상을 선택하세요."
L["Shows your cheapest junk in a small window."] = "작은 창에 가장 저렴한 잡템을 표시합니다."
L["Skip Confirmation for White Items"] = "흰색 아이템 확인 건너뛰기"
L["Slot and item, e.g. 16 Thunderfury"] = "슬롯과 아이템, 예: 16 우뢰검"
L["Spell (several: Spell1/Spell2)"] = "주문 (여러 개: 주문1/주문2)"
L["spell known"] = "아는 주문"
L["Spell1, Spell2, Spell3"] = "주문1, 주문2, 주문3"
L["Spells/Items"] = "주문/아이템"
L["Stance %d"] = "태세 %d"
L["Start attack"] = "공격 시작"
L["Stat Color"] = "능력치 색상"
L["stealthed"] = "은신 중"
L["Stop attack"] = "공격 중지"
L["Stop casting"] = "시전 중지"
L["Stop macro here"] = "여기서 매크로 중지"
L["Swap action bar pages"] = "액션바 페이지 교체"
L["swimming"] = "수영 중"
L["Switches autocast for a pet ability on or off."] = "소환수 능력의 자동 시전을 켜거나 끕니다."
L["Switches your main action bar to another page (like Shift+1 ... 6). Great with modifiers or stances."] = "주 행동 단축바를 다른 페이지로 전환합니다 (Shift+1 ~ Shift+6 기능). 조합 키나 태세 변환 매크로와 함께 사용하면 매우 유용합니다."
L["Takes over the target of another unit or player (e.g. the main tank)."] = "다른 유닛이나 플레이어(예: 메인 탱커)의 대상을 이어받습니다."
L["Target exact name"] = "정확한 이름의 대상 지정"
L["Target nearest enemy"] = "가장 가까운 적 지정"
L["Target nearest enemy player"] = "가장 가까운 적 플레이어 지정"
L["Target nearest friend"] = "가장 가까운 아군 지정"
L["Target nearest friendly player"] = "가장 가까운 우호적 플레이어 지정"
L["Target party member"] = "파티원 지정"
L["Target raid member"] = "공격대원 지정"
L["Targeting"] = "대상 지정"
L["Targets a unit or the closest match for a name. Leave the name empty and pick e.g. @mouseover."] = "유닛 또는 이름과 가장 일치하는 대상을 지정합니다. 이름을 비워두고 @mouseover 등을 선택하세요."
L["Targets only a unit with exactly this name."] = "정확히 이 이름을 가진 유닛만 지정합니다."
L["Targets the last enemy you had targeted."] = "이전에 지정했던 마지막 적을 지정합니다."
L["Targets the last friendly unit you had targeted."] = "이전에 지정했던 마지막 아군 유닛을 지정합니다."
L["The line only runs while the left ones are true and the right (Not) ones are false."] = "이 줄은 왼쪽 조건이 참이고 오른쪽(아님) 조건이 거짓일 때만 실행됩니다."
L["The lines were rebuilt from the macro text. Click again."] = "매크로 텍스트에서 줄이 재구축되었습니다. 다시 클릭하세요."
L["The macro is empty."] = "매크로가 비어 있습니다."
L["The question mark shows the spell's icon (with #showtooltip)."] = "물음표는 주문의 아이콘을 표시합니다(#showtooltip 사용)."
L["The stance or form action bar: warrior 1 Battle, 2 Defensive, 3 Berserker; druid 1 Cat, 3 Bear; rogue 1 Stealth."] = "각 직업의 태세 및 형태별 행동 단축바 매칭 안내: 전사(1 전투, 2 방어, 3 광폭), 드루이드(1 표범, 3 곰), 도적(1 은신)."
L["The target can be attacked."] = "대상을 공격할 수 있습니다."
L["The target exists."] = "대상이 존재합니다."
L["The target is dead."] = "대상이 죽었습니다."
L["The target is friendly (can be healed)."] = "대상은 우호적입니다(치유 가능)."
L["The target is in your party."] = "대상이 파티에 있습니다."
L["The target is in your raid."] = "대상이 공격대에 있습니다."
L["Then Ctrl + Left Click the item again to delete it."] = "그런 다음 아이템을 다시 Ctrl + 왼쪽 클릭하여 삭제하세요."
L["This macro changed outside the editor. Select it again."] = "편집기 외부에서 이 매크로가 변경되었습니다. 다시 선택하세요."
L["Tints the areas you have not explored yet. White shows them as they are."] = "아직 탐험하지 않은 지역에 색조를 입힙니다. 흰색은 그대로 표시합니다."
L["Toggles your main action bar between two pages."] = "주 행동 단축바를 지정한 두 페이지 사이에서 전환 합니다."
L["Too long: %1$d / %2$d characters."] = "제한 수 초과: %1$d / %2$d자."
L["Tooltip Spell"] = "툴팁 주문"
L["Turns off auto-attack, e.g. so you do not break crowd control."] = "자동 공격을 종료합니다 (예: 군중 제어 효과를 깨뜨리지 않으려 할 때 유용)."
L["Turns off autocast for a pet ability."] = "소환수 능력의 자동 시전을 끕니다."
L["Turns on auto-attack (melee or wand) against your target."] = "대상에 대한 자동 공격(근접 또는 마법봉)을 켭니다."
L["Turns on autocast for a pet ability."] = "소환수 능력의 자동 시전을 켭니다."
L["Two pages, e.g. 1 2"] = "두 페이지, 예: 1 2"
L["Unexplored Color"] = "미탐험 지역 색상"
L["Unit or Name"] = "유닛 또는 이름"
L["Unsaved changes"] = "저장되지 않은 변경 사항"
L["Use item / slot"] = "아이템 / 슬롯 사용"
L["Uses a random item from the list (e.g. mounts or toys)."] = "목록에서 무작위 아이템을 사용합니다(예: 탈것 또는 장난감)."
L["Uses an item by name, an equipment slot (13/14 = trinkets) or bag and slot (e.g. 0 1). Works with spells too."] = "이름, 장비 슬롯(13/14 = 장신구) 또는 가방과 슬롯(예: 0 1)으로 아이템을 사용합니다. 주문에도 작동합니다."
L["Variants are checked top to bottom: the first one whose conditions match is used. A variant without conditions is the fallback."] = "변형은 위에서 아래로 확인됩니다: 조건이 일치하는 첫 번째 변형이 사용됩니다. 조건이 없는 변형은 대체용입니다."
L["When the sequence starts over: target (target change), combat (leaving combat), shift/ctrl/alt or seconds. Separate several with /."] = "순차 시전 매크로가 초기화되는 시점 설정: target (대상 변경 시), combat (전투 종료 시), shift/ctrl/alt (조합 키 입력 시) 또는 시간(초). 여러 조건은 /로 구분합니다."
L["Which mouse button clicked the action button (or which key binding: 1 = normal)."] = "액션 버튼을 클릭한 마우스 버튼(또는 단축키: 1 = 일반)."
L["Which page your main action bar is on right now (Shift+1 ... 6)."] = "현재 주 행동 단축바가 위치한 페이지 번호입니다 (Shift+1 ~ Shift+6 기능)."
L["White stacks delete on the first Ctrl + Left Click instead of the second."] = "흰색 아이템은 두 번째가 아니라 첫 번째 Ctrl + 왼쪽 클릭 시 삭제됩니다."
L["With a Value"] = "값 포함"
L["You are channeling a spell."] = "주문을 집중 시전 중입니다."
L["You are channeling exactly this spell."] = "정확히 이 주문을 집중 시전 중입니다."
L["You are in a group."] = "파티에 속해 있습니다."
L["You are in a party or in a raid group."] = "파티 또는 공격대 그룹에 속해 있습니다."
L["You are indoors."] = "실내에 있습니다."
L["You are mounted."] = "탈것에 타고 있습니다."
L["You are outdoors."] = "실외에 있습니다."
L["You are stealthed."] = "은신 상태입니다."
L["You are swimming."] = "수영 중입니다."
L["You have a pet."] = "소환수가 있습니다."
L["You have an item of this type equipped, e.g. only shoot with a bow or gun, Shield Bash only with a shield."] = "이 유형의 아이템이 장착되어 있습니다(예: 활이나 총으로만 사격, 방패로만 방패 밀쳐내기)."
L["You know this spell (e.g. to use one macro on several characters)."] = "이 주문을 알고 있습니다(예: 여러 캐릭터에서 하나의 매크로를 사용하기 위해)."
L["Your pet attacks every enemy in range."] = "소환수가 범위 내의 모든 적을 공격합니다."
L["Your pet attacks whatever attacks you or it."] = "소환수가 자신이나 당신을 공격하는 모든 것을 공격합니다."
L["Your pet has this name or is of this family (warlock demons, hunter pet families)."] = "소환수가 이 이름이거나 이 종류에 속합니다(흑마법사 악마, 사냥꾼 소환수 종류)."
L["Your pet never attacks on its own."] = "소환수가 스스로 절대 공격하지 않습니다."
L["Your pet stays where it is."]   = "소환수가 그 자리에 대기합니다."
L["Your pet stops and follows you."] = "소환수가 멈추고 당신을 따라옵니다."
L["Keep Standalone"] = "독립 버전 유지"
L["Keeping the standalone leaves this copy idle. You can switch later from the Simple Loot Council page."] = "독립 버전을 유지하면 이 복사본은 유휴 상태로 유지됩니다. 나중에 간편한 전리품 분배 위원회 페이지에서 전환할 수 있습니다."
L["Loot council voting for your raid, synced over addon messages."] = "애드온 메시지를 통해 동기화되는 공격대를 위한 전리품 분배 위원회 투표."
L["Simple Loot Council did not start: the EllesmereUI module expected the standalone copy to load, and it did not. Please report this; turning SimpleLootCouncil on in the AddOns list works around it."] = "간편한 전리품 분배 위원회가 시작되지 않았습니다: EllesmereUI 모듈이 독립 버전이 로드될 것으로 예상했으나 로드되지 않았습니다. 이를 신고해 주세요. 애드온 목록에서 SimpleLootCouncil을 켜면 해결할 수 있습니다."
L["Simple Loot Council is installed twice, and the standalone copy is the one running. Switch to the EllesmereUI module? It keeps the council, history and settings it already has; the standalone copy's own are left as they are."] = "Simple Loot Council이 중복 설치되었으며 현재 독립 실행형 버전이 실행 중입니다. EllesmereUI 모듈 버전으로 전환하시겠습니까? 기존의 전리품 분배 내역 및 옵션 설정이 그대로 마이그레이션되며, 기존 독립 실행형 데이터는 안전하게 유지됩니다."
L["Simple Loot Council is installed twice, and the standalone copy is the one running. Switch to the EllesmereUI module? Your council, history and settings carry over."] = "간편한 전리품 분배 위원회가 두 번 설치되었으며 독립 버전이 실행 중입니다. EllesmereUI 모듈로 전환하시겠습니까? 위원회, 기록 및 설정이 그대로 이어집니다."
L["Simple Loot Council: the standalone copy could not be turned off for you. Turn off SimpleLootCouncil in the AddOns list, then reload."] = "Simple Loot Council: 독립 실행형 버전을 자동으로 비활성화할 수 없었습니다. 게임 내 애드온 목록에서 SimpleLootCouncil 항목을 체크 해제하여 끈 다음, UI를 다시 불러와(Reload) 주세요."
L["STANDALONE COPY RUNNING"] = "독립 버전 실행 중"
L["Switch To The EllesmereUI Module"] = "EllesmereUI 모듈로 전환"
L["Detail level of logging"] = "로그 상세 수준"
L["Quiet records warnings and errors; Normal adds main events; Verbose records everything."] = "'간략히'는 경고 및 오류만 기록하고, '보통'은 주요 이벤트를 추가하며, '상세히'는 모든 내용을 기록합니다."
L["Quiet"] = "간략히"
