-- == WoW Forever 편의 기능 (Quest Rewards, Fishing, Companion Pets) ==========
L["QUEST REWARDS"] = "퀘스트 보상"
L["Most Valuable Reward"] = "가장 가치 있는 보상"
L["Among a quest's reward choices, a money bag marks the one that sells for most, its count included."] = "퀘스트 보상 선택지 중 수량을 포함하여 상점 판매가가 가장 높은 아이템에 돈주머니 아이콘을 표시합니다."

L["FISHING"] = "낚시"
L["Fishing Key"] = "낚시 단축키"
L["One key casts your line, equipping your best fishing pole first. Use the cog for reeling in, the bobber indicator and lures."] = "단축키 하나로 낚싯줄을 던지며, 낚싯대를 착용하지 않은 경우 가방에서 가장 좋은 낚싯대를 먼저 착용합니다. 톱니바퀴 아이콘에서 낚아채기, 찌 표시기, 미끼 사용 설정을 변경할 수 있습니다."
L["Double-Click to Cast"] = "더블 클릭으로 낚싯줄 던지기"
L["With a fishing pole in hand, double right-click the world to cast."] = "낚싯대를 착용한 상태에서 게임 화면(지면)을 우클릭 두 번 하면 낚싯줄을 던집니다."
L["Bobber Indicator"] = "찌 표시기"
L["Bobber found: %s reels in"] = "찌 감지됨: %s 키로 낚아채기"
L["Bobber not found: keep it on screen, cast again, or right-click it to reel in."] = "찌 감지 안 됨: 찌가 화면 안에 들어오게 시점을 조정하거나, 다시 던지거나, 찌를 직접 우클릭하여 낚아채세요."
L["Fishing Sounds"] = "낚시 효과음"
L["While you fish: music and ambience down, effects up, sound on in the background."] = "낚시하는 동안 음악과 환경 소리를 낮추고 음향 효과를 높이며, 게임이 백그라운드 상태여도 소리를 재생합니다."
L["Apply Lure"] = "미끼 사용"
L["Reel In With the Key"] = "단축키로 낚아채기"
L["With no lure on your pole, a double-click applies your best lure first."] = "낚싯대에 미끼가 없으면 더블 클릭 시 가방에서 가장 좋은 미끼를 먼저 바릅니다."
L["With no lure on your pole, the key applies your best lure first."] = "낚싯대에 미끼가 없으면 낚시 단축키로 가방에서 가장 좋은 미끼를 먼저 바릅니다."
L["Once the bobber bites and is on screen, the Fishing Key reels it in."] = "입질이 오고 찌가 화면 안에 보이면 낚시 단축키로 낚아챕니다."
L["Shows whether the key will reel in. Place it in Unlock Mode."] = "단축키로 낚아챌 수 있는지 표시합니다. 잠금 해제 모드에서 위치를 조정합니다."

L["COMPANION PETS"] = "애완동물"
L["Auto Summon Pet"] = "애완동물 자동 소환"
L["Brings a random favorite pet back after loading screens, flights and deaths; a pet you dismiss stays away."] = "로딩 화면, 비행 경로 이용, 사망 후에 즐겨찾는 애완동물 중 하나를 무작위로 다시 소환합니다. 직접 소환을 해제한 애완동물은 다시 소환하지 않습니다."
L["Favorites per Character"] = "캐릭터별 즐겨찾기"
L["Favorite for This Character"] = "이 캐릭터의 즐겨찾기"
L["Pick this character's favorites from a pet's right-click menu in the Pet Journal."] = "애완동물 도감에서 애완동물을 우클릭하여 이 캐릭터의 즐겨찾기를 지정합니다."

