L["DPS Exceptions"] = "공격 전담 예외"
L["Use the Tank List"] = "방어 전담 목록 사용"
L["Use the Healer List"] = "치유 전담 목록 사용"
L["Use the DPS List"] = "공격 전담 목록 사용"
L["Reminds you of the first checked blessing a tank lacks, top to bottom."] = "방어 전담에게 누락된 축복 중 선택된 첫 번째 축복을 위에서부터 순서대로 안내합니다."
L["Reminds you of the first checked blessing a healer lacks, top to bottom."] = "치유 전담에게 누락된 축복 중 선택된 첫 번째 축복을 위에서부터 순서대로 안내합니다."
L["Reminds you of the first checked blessing a damage dealer lacks, top to bottom. Members with no assigned role use this list too."] = "공격 전담에게 누락된 축복 중 선택된 첫 번째 축복을 위에서부터 순서대로 안내합니다. 역할이 지정되지 않은 파티원에게도 이 목록이 적용됩니다."

-- == What's New: Patch Notes ================================================
L["CD and utility bars can hold empty slots to space their icons into groups (Add menu > Empty Slot)"] = "재사용 대기시간 및 유틸리티 단축바에 빈 슬롯을 추가하여 아이콘을 그룹별로 띄워 정렬할 수 있습니다 (추가 메뉴 > 빈 슬롯)"
L["/cd Command"] = "/cd 명령어"
L["Type /cd to open or close Blizzard's Cooldown Manager settings"] = "/cd 명령어를 입력하여 블리자드 재사용 대기시간 관리자 설정을 열거나 닫을 수 있습니다"
L["Blizzard Icon Style"] = "블리자드 아이콘 스타일"
L["Bags, gold, item level, location, coordinates, durability, travel, audio, spec, professions and the micro menu can show the game's own icons"] = "가방, 골드, 아이템 레벨, 위치, 좌표, 내구도, 이동, 오디오, 전문화, 전문 기술 및 게임 메뉴에 게임 고유 아이콘을 표시할 수 있습니다"
L["Text Display Options"] = "텍스트 표시 옵션"
L["The XP / Reputation bar can show a percentage or values, with or without level or faction, and profession blocks can show skill values"] = "경험치/평판 바에 백분율이나 수치, 레벨 및 진영 표시 여부를 선택할 수 있으며, 전문 기술 블록에 숙련도 수치를 표시할 수 있습니다"
L["Micro Menu Order"] = "게임 메뉴 순서"
L["Drag the entries in Menu Elements to set the micro menu's button order"] = "메뉴 요소 목록의 항목을 드래그하여 게임 메뉴 단추 순서를 원하는 대로 설정할 수 있습니다"
L["A new block counts your ammo, thrown weapon and class reagents; right-click it to choose which ones show"] = "탄약, 투척 무기, 직업 전용 시약 수량을 세어주는 새로운 정보 블록입니다 (우클릭하여 표시할 항목 선택)"
L["First Aid"] = "응급치료"
L["The secondary professions block also shows First Aid"] = "보조 기술 정보 블록에 응급치료 숙련도도 함께 표시됩니다"
L["Professions and Legacy Buttons"] = "전문 기술 및 유산 버튼"
L["The micro menu can show the Professions and Legacy buttons; turn them on in Menu Elements"] = "게임 메뉴에 전문 기술 및 유산 진행 버튼을 표시할 수 있습니다 (메뉴 요소에서 활성화)"
L["Shows what you loot and gain (items, money, reputation, currencies and skill ups) as short rows that fade out"] = "획득한 전리품(아이템, 골드, 평판, 화폐, 숙련도 상승)을 서서히 사라지는 간결한 줄 형태로 표시합니다"
L["A new button on Global Settings puts back the game settings EUI changed, then turns EUI off and reloads; turning a module off puts back its own"] = "전체 설정에 추가된 단추로 EUI가 변경한 게임 설정을 기본값으로 복원한 후 애드온을 끄고 UI를 재시작합니다 (개별 모듈을 끌 때도 해당 설정이 복원됨)"
L["The options window has a Window Scale slider in its top corner that resizes it in smooth 5% steps; Shift + mouse wheel over it works too"] = "설정 창 상단 모서리에 5% 단위로 부드럽게 크기를 조절하는 슬라이더가 추가되었습니다 (창 위에서 Shift + 마우스 휠로도 조절 가능)"
L["Style Picks"] = "스타일 선택"
L["The Style page sets each look's modules from a dropdown under its card, and Apply Styles applies every change with one reload"] = "스타일 페이지에서 각 테마별 모듈을 드롭다운으로 설정하며, '스타일 적용'을 누르면 UI를 한 번 다시 불러와 모든 변경 사항이 반영됩니다"
L["Per-Section Color Sources"] = "섹션별 색상 출처"
L["Class, Power and Class Resource colors each choose their own Apply to All Profiles and Pull Colors From"] = "직업, 자원, 직업 자원 색상별로 각각 '모든 프로필에 적용' 및 '색상 가져오기 대상'을 독립적으로 설정할 수 있습니다"
L["Addon Plugins"] = "애드온 플러그인"
L["Other addons can add their own sections to the settings panel, and can no longer change or break EllesmereUI's own pages"] = "다른 애드온이 설정 패널에 자체 섹션을 추가할 수 있으며, EllesmereUI의 기존 페이지를 임의로 변경하거나 손상시킬 수 없도록 보호됩니다"
L["The Show Coordinates cog sets how many decimal places the coordinates show"] = "'좌표 표시' 톱니바퀴에서 좌표의 소수점 자릿수를 설정할 수 있습니다"
L["Per-Bar Spell Target"] = "바별 주문 대상 표시"
L["Show Spell Target now sits in the Target and Focus Cast Bar sections, so the spell target can show on one bar and not the other"] = "'주문 대상 표시'가 대상 및 주시대상 시전 바 섹션에 각각 분리되어, 원하는 시전 바에만 선택적으로 대상을 표시할 수 있습니다"
L["Core Text Positions"] = "기본 텍스트 위치"
L["Core Text Positions lists only the texts you use, with Add Text Slot, a menu on each text's name to move it, and Remove in its dropdown"] = "기본 텍스트 위치 목록에 현재 사용하는 텍스트만 표시되며, 슬롯 추가, 위치 이동 메뉴, 드롭다운 내 삭제 기능을 제공합니다"
L["Core Text Coloring"] = "기본 텍스트 색상"
L["Each text gets Custom, Hostility / Class or Level Difficulty coloring in its own Core Text Coloring section, with Level | Name parts colored apart"] = "각 텍스트마다 사용자 지정, 적대감/직업, 레벨 난이도 색상을 설정할 수 있으며, 레벨과 이름 부분을 서로 다른 색상으로 구분하여 표시할 수 있습니다"
L["Core Positions Checklists"] = "기본 위치 체크리스트"
L["Each Core Positions slot is a checklist: Rare and Quest switch separately, and Debuffs with CC or Rare/Quest with Faction can share a slot"] = "각 기본 위치 슬롯이 체크리스트 형태로 제공되어 희귀 및 퀘스트 아이콘을 개별 전환할 수 있고, 군중 제어와 약화 효과 또는 진영과 희귀/퀘스트 아이콘이 슬롯을 공유할 수 있습니다"
L["Shield Placement"] = "보호막 위치"
L["The Absorb Settings cog picks where shields draw: Overlay, Overlay Reverse, From Right Edge or From Left Edge"] = "흡수 보호막 설정 톱니바퀴에서 보호막이 그려질 위치를 덮어쓰기, 역방향 덮어쓰기, 오른쪽 끝에서 시작, 왼쪽 끝에서 시작 중에서 선택할 수 있습니다"
L["The Enemy Buff Filter has a Show All choice that shows every buff on enemy nameplates"] = "적 강화 효과 필터에 적 이름표의 모든 강화 효과를 표시하는 '모두 표시' 옵션이 추가되었습니다"
L["Draws a divider in your custom border's style between the cast bar and a spell icon that is part of the bar"] = "시전 바와 일체형 주문 아이콘 사이에 사용자 지정 테두리 스타일의 구분선을 그립니다"
L["Threat Gap"] = "위협 수준 격차"
L["The Threat % text can show the flat threat lead on your target's plate, green when you lead and blue when someone else does"] = "대상 이름표의 위협 수준 % 텍스트에 어그로 선두 격차를 표시합니다 (내가 1위일 때는 녹색, 다른 사람이 1위일 때는 파란색)"
L["Spinning Party and Raid Frames"] = "회전 파티 및 공격대 프레임"
L["Spinning can now orbit your party and raid frames, which snap back into place for every fight"] = "파티 및 공격대 프레임에 회전 애니메이션 효과를 줄 수 있으며, 전투 돌입 시 원래 위치로 즉시 복귀합니다"
L["Asks before you spend a bonus roll and shows your loot specialization, with an option to confirm Pass too"] = "추가 주사위 굴림 사용 전에 획득 전문화와 함께 확인창을 띄우며, 포기 시에도 확인하는 옵션을 제공합니다"
L["While the key is held, left-clicking the world pings the spot under your cursor instead of a unit"] = "단축키를 누른 상태에서 필드를 좌클릭하면 유닛 대신 커서 위치에 신호(핑)를 찍습니다"
L["Character Stats Display"] = "캐릭터 능력치 정보 표시"
L["The Secondary Stat Display shows your character pane's stats, from attack and spell power to crit, haste, hit, regen, armor and resistances"] = "보조 능력치 표시창에서 공격력과 주문력부터 치명타, 가속, 적중, 회복, 방어도 및 저항력까지 캐릭터의 모든 능력치를 표시합니다"
L["Clear Stuck Spell Targeting"] = "시전 대기 주문 대상 취소"
L["HoverCast clears a spell left waiting for a target before it casts, so your next press goes through; on by default"] = "마우스오버 시전 시 대상을 기다리며 멈춰 있던 이전 주문을 자동으로 취소하여 다음 기술이 즉시 입력되도록 합니다 (기본 켜짐)"
L["Combat Rez Items"] = "전투 부활 아이템"
L["Classes without a battle rez use an Emergency Soul Link from their bags through Dynamic Rez and Smart Rez on a dead ally in combat"] = "전투 부활이 없는 직업도 동적 부활 및 스마트 부활을 통해 가방 안의 비상 영혼 연계기 아이템으로 사망한 아군을 부활시킵니다"
L["Health Bar Absorbs"] = "생명력 바 흡수 보호막"
L["The Health Bar can show damage and heal absorbs, each with its own style, color and opacity, and a max health reduction overlay"] = "생명력 바에 피해 및 치유 흡수 보호막을 각각 전용 스타일, 색상, 불투명도와 함께 표시하며 최대 생명력 감소 오버레이를 지원합니다"
L["Power Bar Spenders"] = "자원 소모기 알림"
L["The Power Bar can change color while a spell you choose is ready to cast, set per entry under Threshold Settings"] = "임계값 설정에 등록된 주문을 시전할 준비가 되었을 때 자원 바 색상이 변경되도록 설정할 수 있습니다"
L["Cast Bar Upgrades"] = "시전 바 개선"
L["The cast bar can turn gray while your target is out of range, and its spell icon can be resized and offset to sit beside the bar"] = "대상이 사거리 밖에 있을 때 시전 바를 회색으로 표시할 수 있으며, 주문 아이콘의 크기와 위치를 조정하여 바 옆에 배치할 수 있습니다"
L["Expand Extra Y Offset"] = "확장 시 추가 세로 위치"
L["Expand Power Bar if No Resource gains an Extra Y Offset, so the expanded bar can cover a gap left by the class resource"] = "'자원 없을 때 자원 바 확장'에 추가 세로 위치 옵션이 추가되어, 직업 자원이 빠진 빈 공간을 자연스럽게 채울 수 있습니다"
L["Per-Bar Texture and Strata"] = "바별 텍스처 및 레이어"
L["The Texture and Frame Strata cogs give the health and power bars their own texture and strata, or Match Main to follow the row"] = "텍스처 및 프레임 레이어 톱니바퀴에서 생명력 바와 자원 바에 독립적인 텍스처와 프레임 레이어를 설정하거나 프레임 설정을 따르도록 할 수 있습니다"
L["Overlay Reverse (Full)"] = "역방향 덮어쓰기 (전체)"
L["A new shield Placement shows a shield larger than current health from the start of the bar"] = "현재 생명력보다 큰 보호막을 바의 처음부터 표시해주는 새로운 보호막 배치 옵션입니다"
L["Portrait Mirroring"] = "초상화 좌우 대칭"
L["Mirror Portrait now also turns 3D portraits of playable races; in 2D it flips playable-race portraits only (class art always flips)"] = "초상화 대칭 기능이 플레이 가능한 종족의 3D 초상화도 회전시키며, 2D에서는 플레이어 종족 초상화만 뒤집습니다 (직업 아트는 항상 뒤집힘)"
L["Focus Aura Borders"] = "주시대상 오라 테두리"
L["The Focus frame's Buffs and Debuffs section gets Border Style, Border Size, color and border options, like Player and Target"] = "플레이어 및 대상 프레임처럼 주시대상 프레임의 강화 효과/약화 효과에도 테두리 스타일, 크기, 색상 옵션을 지정할 수 있습니다"
L["Boss Frame Borders"] = "우두머리 프레임 테두리"
L["Boss frames gain Mirror Portrait, a Vertical Border Separator, a Power Bar Seam and Border Above Effects for aura borders"] = "우두머리 프레임에 초상화 대칭, 수직 테두리 구분선, 자원 바 연결 이음새 및 오라 테두리 강조 효과가 추가되었습니다"
L["Mini Frame Looks"] = "보조 프레임 외형 복사"
L["Target of Target, Focus Target and Pet choose which main frame they copy their look from, and the Target of Target portrait can be mirrored"] = "대상의 대상, 주시대상의 대상, 소환수 프레임이 디자인을 복사해 올 메인 프레임을 선택할 수 있으며, 대상의 대상 초상화를 좌우 대칭할 수 있습니다"
L["An equipped item dragged onto or off a bar now shows or drops its border right away instead of after a mouseover."] = "장착 아이템을 단축바에 올리거나 뺄 때 마우스를 올릴 때까지 기다리지 않고 즉시 테두리가 표시되거나 사라집니다."
L["The XP, reputation and House Favor bars' text now always shows your chosen font, including in the standalone Action Bars download and right after logging in to a character whose spec profile uses another font."] = "경험치, 평판 및 가문 호감도 바 텍스트가 다른 글꼴을 사용하는 캐릭터로 전환하거나 단독 단축바 모듈 사용 시에도 항상 지정된 글꼴로 일관되게 표시됩니다."
L["Switching from Blizzard's XP/Rep bars back to EllesmereUI's now offers a reload popup instead of a chat message."] = "블리자드 경험치/평판 바에서 EllesmereUI 바로 전환할 때 대화창 메시지 대신 다시 불러오기 확인창을 제공합니다."
L["The live preview shows Action Bar 1's paging arrows while they are turned on."] = "행동 단축바 1의 페이징 화살표가 켜져 있을 때 실시간 미리보기에 화살표가 정상 표시됩니다."
L["In the WoW Forever style, our own XP and reputation bars no longer draw Blizzard's segment marks; turn on Show Dividers to mark them."] = "WoW Forever 스타일에서 자체 경험치 및 평판 바에 블리자드 기본 눈금이 강제로 그려지지 않으며, '구분선 표시'를 켜서 표시할 수 있습니다."
L["Merged duplicate items now split into their stacks while a vendor is open, as at the mailbox, auction house and bank, since selling one only ever sold a single stack."] = "상인을 열었을 때 우체통, 경매장, 은행처럼 중복 합쳐진 아이템이 원래 묶음 단위로 풀려 표시되어 단일 묶음 판매가 정상 작동합니다."
L["Equipped bag icons now update after swapping a bag."] = "가방을 교체했을 때 착용 중인 가방 아이콘이 즉시 갱신됩니다."
L["OneBag Sort and Randomize no longer try to move items into a quiver, ammo pouch or other special bag, or pull ammo out of it."] = "통합 가방 정리 및 무작위 정렬 시 화살통, 탄약통 등 특수 가방으로 아이템을 넣거나 탄약을 빼내지 않도록 개선했습니다."
L["Blizz UI Enhanced is now called Blizzard Skins+, and its tabs are now Window Skins and Skyriding."] = "Blizz UI Enhanced의 명칭이 블리자드 스킨+로 변경되었으며 탭 이름이 '창 스킨'과 '하늘비행'으로 개편되었습니다."
L["Reset now also restores the Character Sheet, Inspect, Merchant and tooltip options."] = "초기화 시 캐릭터 창, 살펴보기, 상점 및 툴팁 설정도 함께 기본값으로 복원됩니다."
L["The Great Vault is no longer reskinned while Disable Window Skins is on."] = "'창 스킨 비활성화'가 켜져 있을 때는 위대한 금고 창의 스킨이 변경되지 않습니다."
L["The equipment set icon picker is no longer dimmed and unclickable on the EllesmereUI and Modern character sheets."] = "EllesmereUI 및 모던 캐릭터 창에서 장비 관리 세트 아이콘 선택창이 어둡게 비활성화되던 문제를 수정했습니다."
L["Inspect sheet enchant tooltips no longer pop up on its other tabs or while enchants are hidden."] = "살펴보기 창의 마법부여 툴팁이 다른 탭을 볼 때나 마법부여가 숨겨져 있을 때 잘못 뜨지 않습니다."
L["Character sheet stat titles no longer show a custom color you switched off when the sheet first opens."] = "캐릭터 창을 처음 열었을 때 이미 꺼둔 사용자 지정 능력치 제목 색상이 나타나지 않습니다."
L["Blizzard Style and Classic WoW UI now keep the item text beside the character sheet's slots, as WoW Forever does."] = "블리자드 스타일 및 클래식 WoW UI에서도 WoW Forever처럼 캐릭터 창 슬롯 옆에 아이템 정보를 정상 표시합니다."
L["The inspect sheet shows each item's enchant, as the character sheet does."] = "살펴보기 창에서도 캐릭터 창과 동일하게 각 장비의 마법부여를 표시합니다."
L["With the Gamepad interface style, the window, popup and tooltip skins step aside, so navigating bags and windows with a controller no longer causes blocked-action errors."] = "게임패드 인터페이스 스타일 사용 시 창, 팝업 및 툴팁 스킨이 비활성화되어 컨트롤러로 가방과 창을 조작할 때 작업 차단 오류가 발생하지 않습니다."
L["Idle fade now wakes only for chat in the tab you are looking at (or an open undocked window), and chat no longer fades while your mouse is over it after a new message arrives."] = "대화창 유휴 페이드 기능이 현재 보고 있는 탭의 대화에만 반응하며, 새 메시지가 도착했을 때 마우스가 올려져 있다면 페이드되지 않습니다."
L["The Copy Chat window now opens at the newest lines instead of the oldest."] = "대화 내용 복사 창을 열었을 때 가장 오래된 내용 대신 가장 최신 대화 줄부터 열립니다."
L["CD Ready and Glow (On CD) glows no longer cover a live proc or Active State Glow (also on trinkets, potions and spells added by Spell ID), and come back the moment it ends."] = "재사용 대기 완료 및 재사용 대기 중 반짝임이 활성화된 발동 효과나 사용 상태 반짝임을 가리지 않으며, 발동이 끝나는 즉시 다시 표시됩니다."
L["Cooldown State Effects now work on racials that Blizzard's Cooldown Manager tracks itself."] = "블리자드 재사용 대기시간 관리자가 자체 추적하는 종족 특성에도 재사용 대기 상태 효과가 정상 작동합니다."
L["Bar Glows on target debuffs (such as Freezing) light up right away, and At Stacks glows follow every stack change."] = "대상 약화 효과(동결 등)의 바 반짝임이 즉시 점등되며, '중첩 시' 반짝임이 모든 중첩 변경 사항을 정확히 따릅니다."
L["The per-spell settings menu no longer cuts off its last row."] = "주문별 설정 메뉴의 마지막 행이 잘려서 표시되던 문제를 수정했습니다."
L["A tracked trinket's buff placed on another bar now stays there after a reload or relog (add it to the bar once more if it already moved back)."] = "다른 바에 배치한 추적 장신구 강화 효과가 다시 불러오거나 재접속한 후에도 원래 자리에 정상 유지됩니다."
L["Custom spells from a talent you've swapped away from no longer stay on your bars, and return to their spot when you pick the talent again."] = "특성을 변경했을 때 미습득 특성의 사용자 지정 주문이 바에 남아있지 않고, 해당 특성을 다시 찍으면 원래 자리에 복귀합니다."
L["Profession blocks catch up on skill changes made in combat once it ends, and a block with no profession no longer leaves a gap on an auto-sized bar."] = "전투 중 발생한 전문 기술 숙련도 변화가 전투 종료 즉시 갱신되며, 전문 기술이 없는 블록이 자동 크기 바에서 빈 틈을 남기지 않습니다."
L["The micro menu no longer shows Achievements, PvP, Housing, Adventure Guide and Shop buttons, which do not exist there."] = "게임 메뉴에 해당 버전에 존재하지 않는 업적, PvP, 주택, 모험 안내서, 상점 단추가 표시되지 않습니다."
L["Clicking Optimize My FPS and Graphics in combat no longer offers a Restore when nothing was changed."] = "전투 중 'FPS 및 그래픽 최적화'를 클릭했을 때 변경 사항이 없음에도 복원 팝업이 뜨던 문제를 수정했습니다."
L["Popups that close when you click outside them (profile sync, Add Bar in Player Aura Bars, Add New in the Buff and Debuff Managers, Create Custom Buff Manager) now also do so the first time they open."] = "외부 클릭 시 닫히는 팝업창들(프로필 동기화, 오라 바 추가, 강화 효과/약화 효과 관리자 신규 추가 등)이 처음 열렸을 때도 외부 클릭으로 정상 닫힙니다."
L["Confirmation popups shown before the options window was opened (for example when leaving Unlock Mode right after a reload) are no longer drawn too large."] = "설정 창을 열기 전에 뜨는 확인 팝업창(UI를 다시 불러온 직후 잠금 해제 모드 종료 등)이 과도하게 크게 그려지던 문제를 수정했습니다."
L["Searching the options for range now finds Target Distance Text and the nameplate Distance to Target Text."] = "설정 검색창에 'range' 또는 '거리'를 검색하면 대상 거리 텍스트와 이름표 대상 거리 텍스트를 정확히 찾아냅니다."
L["The Auto Expand Less Common Settings and Enable Tutorial Tips options are gone: less common settings always start collapsed, and video guide badges show until you click them."] = "자주 쓰지 않는 설정 자동 확장 및 튜토리얼 팁 활성화 옵션이 제거되었습니다: 보조 설정은 항상 접힌 상태로 시작하고 동영상 가이드 배지는 클릭할 때까지 표시됩니다."
L["The reload popup that /rl and reload-needing settings open now also reloads when you press Enter."] = "/rl 및 다시 불러오기가 필요한 설정에서 열리는 확인창에서 Enter 키를 눌러도 다시 불러오기가 실행됩니다."
L["The Addon Buttons flyout now centers its buttons in the same square boxes as the button row (Button Backgrounds on) instead of gold rings."] = "애드온 단추 플라이아웃이 금색 고리 대신 단추 모음과 동일한 사각형 상자에 버튼을 중앙 정렬합니다 (단추 배경 켜짐)."
L["With the Gamepad interface style, the Friends button is hidden, since the game blocks opening the friends list from it."] = "게임 시스템이 게임패드 환경에서 친구 목록 열기를 차단하므로, 게임패드 스타일에서는 친구 버튼이 숨겨집니다."
L["Shields on enemy nameplates no longer shrink the health bar in combat; they draw over it the way the unit frames do."] = "전투 중 적 이름표의 보호막이 생명력 바 너비를 줄이지 않고 유닛 프레임처럼 바 위에 정상적으로 덧그려집니다."
L["Solid custom borders and the cast lockout icon's border no longer lose sides or flicker when Scale Target or Scale Casting Nameplate is above 100%."] = "대상 또는 시전 중 이름표 크기 비율이 100%를 초과할 때 단색 테두리와 시전 차단 아이콘 테두리의 일부가 잘리거나 깜빡이던 문제를 수정했습니다."
L["Custom Border on Spell Icon no longer draws a second border inside the cast bar while the icon is part of the bar."] = "주문 아이콘이 시전 바와 일체형일 때 주문 아이콘 사용자 지정 테두리가 바 내부에 이중으로 그려지지 않습니다."
L["Color Name by Reaction is now the name's Hostility / Class coloring, which also shows enemy players in their class colors."] = "'반응에 따른 이름 색상'이 '적대감/직업' 색상으로 개편되어 적 플레이어를 직업 색상으로 함께 표시합니다."
L["In the options preview, text and raid markers draw above the auras, and the name sits in front of or behind them as its Strata setting does on real nameplates."] = "설정 미리보기에서 글자와 징표가 오라 위에 그려지고, 이름은 실제 이름표의 레이어 설정을 정확히 따릅니다."
L["Enemy nameplates now show every buff by default (Enemy Buff Filter: Show All); pick Important or Only Dispellable to narrow them again."] = "적 이름표의 강화 효과 표시 기본값이 '모두 표시'로 변경되었습니다 (중요 또는 해제 가능만 선택하여 다시 좁힐 수 있음)."
L["Bars sorted by Expiration or Name now sort by that alone instead of putting your own auras first, and the options preview shows the icons in the chosen order."] = "만료 시간 또는 이름으로 정렬 시 자신의 오라를 강제로 앞에 두지 않고 해당 기준만으로 정렬하며, 미리보기에서도 동일 순서로 표시됩니다."
L["Announce Instance Reset no longer tells a party the reset failed; a party reset always succeeds."] = "인스턴스 초기화 알림이 파티 초기화 시 실패했다고 잘못 안내하던 문제를 수정했습니다."
L["The Raid Tools marker rows now read Target Markers and World Markers, so translated clients no longer label the ground marker row just World."] = "공격대 도구의 징표 행 명칭이 '대상 징표'와 '지면 징표'로 명확하게 구분되어 번역 클라이언트에서 지면 징표가 혼동되지 않도록 개선했습니다."
L["HoverCast on macOS now takes Command (Cmd) as a modifier, so Command bindings, including Command-clicks on your frames, work."] = "macOS 환경에서 마우스오버 시전이 Command(Cmd) 키를 정상 인식하여 프레임 Command-클릭 등 단축키 바인딩이 지원됩니다."
L["Tip of the Spear's stack count now always matches the buff on every class resource display (it could read a stack low after some spenders)."] = "모든 직업 자원 표시창에서 창끝 중첩 수가 실제 강화 효과와 항상 일치하도록 수정했습니다."
L["The Class Resource Bar now fills in right away when a zone change alters its maximum, instead of staying empty until your resource next changes."] = "지역 이동으로 최대 자원량이 변경되었을 때 다음 자원 변경을 기다리지 않고 직업 자원 바가 즉시 채워집니다."
L["Buff and debuff borders now line up with their icons at UI scales that are not pixel perfect."] = "픽셀 매칭이 완벽하지 않은 UI 비율에서도 강화 효과/약화 효과 테두리가 아이콘과 정확하게 정렬됩니다."
L["The power bar seam no longer overlaps the portrait separator where they meet, and Color Custom Borders also recolors the power and portrait separators."] = "자원 바 이음새가 초상화 구분선과 겹치지 않으며, '사용자 지정 테두리 색상 지정' 시 자원 및 초상화 구분선 색상도 함께 변경됩니다."
L["Show When Health Missing now works when the class resource bar is locked to the player frame."] = "직업 자원 바가 플레이어 프레임에 고정되어 있을 때도 '생명력 누락 시 표시'가 정상 작동합니다."
L["The options preview follows Power Fill Opacity with a bar texture, shows the Target of Target, Focus Target and Pet frames' own Border Size, and clicking its heal absorb and class resource parts opens their settings."] = "설정 미리보기가 자원 채우기 불투명도를 반영하고 보조 프레임 고유 테두리 크기를 보여주며, 치유 흡수 및 직업 자원 클릭 시 해당 설정이 열립니다."
L["Threat % shows on the target frame only by default (tick Show on Focus in its cog to keep it on the focus frame too), and can sit outside the target and focus frames (Outside Right / Outside Left), clear of the portrait."] = "위협 수준 %가 대상 프레임에만 기본 표시되며(톱니바퀴에서 주시대상 표시 선택 가능), 초상화를 가리지 않고 프레임 외부 좌/우에 배치할 수 있습니다."
L["Resizing the Battle Res, Bloodlust, cursor ring and Flight Timer displays keeps them under their mover instead of jumping back."] = "전투 부활, 피의 욕망, 커서 링 및 비행 타이머 크기 조절 시 위치가 튀지 않고 이동기 아래에 정확히 유지됩니다."
L["The fixed tooltip position, Battle Res, Bloodlust, Mythic+ Timer, Targeted Spell Bars and Target / Focus bars no longer keep a dragged position after Exit Without Saving."] = "'저장하지 않고 종료' 시 고정 툴팁, 전투 부활, 피의 욕망, 신화+ 타이머 등의 드래그 위치가 저장되지 않고 원래 위치로 복원됩니다."
L["Element Options on the XP, reputation, House Favor, micro menu and bag bars now opens their own settings instead of the Bar Display page."] = "경험치, 평판, 가문 호감도, 게임 메뉴, 가방 바의 '요소 설정' 클릭 시 단축바 표시 페이지 대신 해당 요소의 전용 설정이 바로 열립니다."
L["German, Korean, Traditional Chinese and Brazilian Portuguese translations updated for the latest options."] = "최신 옵션에 맞춰 한국어, 독일어, 번체 중국어 및 브라질 포르투갈어 번역이 업데이트되었습니다."
L["Target of Target and Bottom Text"] = "대상의 대상 및 하단 텍스트"
L["Any Core Text Position can now show the name of whoever the enemy is targeting, class colored for players. New Bottom Left and Bottom Right text slots sit under the health bar and drop below the cast bar while the enemy casts."] = "모든 기본 텍스트 위치에 적이 대상으로 잡고 있는 대상(플레이어는 직업 색상 적용)의 이름을 표시할 수 있습니다. 생명력 바 아래에 새로운 좌측 하단 및 우측 하단 텍스트 슬롯이 추가되며 적이 시전 중일 때는 시전 바 아래로 자동 이동합니다."
L["First Install Keeps Your Layout"] = "신규 설치 시 기존 레이아웃 유지"
L["A fresh install now starts from where your Blizzard frames already are, including the experience bar, micro menu and bags, with the gryphons at the outer ends of that row, instead of a fixed EllesmereUI layout. If you already use EllesmereUI, your current layout stays exactly as it is."] = "새로 설치 시 강제 고정된 EllesmereUI 레이아웃 대신 경험치 바, 게임 메뉴, 가방, 그리폰 장식 등 블리자드 기본 프레임 위치를 기반으로 시작합니다. 기존 사용자의 레이아웃은 그대로 유지됩니다."
L["Micro Menu and Bag Bar End Caps"] = "게임 메뉴 및 가방 바 장식 마감"
L["The micro menu and bag bar can show end caps like the action bars, and a fresh install moves Action Bar 1's end caps to the outer ends of any bars placed directly beside it"] = "게임 메뉴 및 가방 바에 행동 단축바와 같은 장식 마감을 표시할 수 있으며, 새로 설치 시 행동 단축바 1 옆에 배치된 바의 바깥쪽 끝으로 장식 마감이 자동 이동합니다"
L["Threat Meter Type"] = "위협 수준 미터기 유형"
L["Windows can show Forever Essentials' threat list as a Threat meter type, in the window's own style and with the Threat page's list settings"] = "창에 Forever Essentials의 위협 수준 목록을 미터기 전용 스타일 및 위협 페이지 설정과 함께 표시할 수 있습니다"
L["The Size setting's cog can scale the icons on the map, like Edit Mode's Icon Size"] = "'크기' 설정의 톱니바퀴에서 편집 모드의 아이콘 크기처럼 지도 위의 아이콘 크기 비율을 조절할 수 있습니다"
L["Level Text"] = "레벨 텍스트"
L["Level Position can show each member's level in front of their name or on its own spot (WoW Forever shows it by default)"] = "파티원의 레벨을 이름 앞이나 독립된 위치에 표시할 수 있습니다 (WoW Forever에서는 기본 활성화)"
L["Missing Buffs Choices"] = "누락된 강화 효과 선택"
L["Missing Buffs now covers only the buffs you can cast, and its cog picks which ones, Thorns and Paladin Blessings included (all on by default)"] = "누락된 강화 효과 알림이 플레이어가 시전할 수 있는 강화 효과만 선별 표시하며, 톱니바퀴에서 가시 및 성기사 축복을 포함해 표시할 항목을 선택할 수 있습니다 (모두 기본 켜짐)"
L["Raid and party names can show only the first or last word of a name, set at the top of the Name Size cog"] = "이름 크기 톱니바퀴 상단에서 공격대 및 파티원 이름의 첫 단어 또는 마지막 단어만 표시하도록 설정할 수 있습니다"
L["Call Totem Bar"] = "토템 소환 바"
L["Shamans can show Blizzard's call totem bar in the Totem Bar look and move it with Unlock Mode (off by default)"] = "주술사가 블리자드 토템 소환 바를 토템 바 스타일로 표시하고 잠금 해제 모드로 위치를 이동할 수 있습니다 (기본 꺼짐)"
L["Has Duration Filter"] = "지속시간 필터"
L["The player frame's Debuff Filter and the target and focus Buff Filter can hide permanent auras with Has Duration, and the target and focus Debuff Filter cog has it too"] = "플레이어 프레임 약화 효과 필터와 대상/주시대상 강화 효과/약화 효과 필터에서 '지속시간 있음' 옵션으로 영구 오라를 숨길 수 있습니다"
L["A bank whose free base slots were never opened now offers an Open Bank Slots button instead of showing an empty window."] = "기본 슬롯을 구입하지 않은 은행에서 빈 창 대신 '은행 슬롯 열기' 버튼을 제공합니다."
L["Items in your sixth bank bag and any after it now show in the bank window."] = "6번째 이후의 은행 가방에 있는 아이템도 은행 창에 정상 표시됩니다."
L["The Bonus Roll window's timer bar is visible again with the window skin on, in the same style as the loot roll timers."] = "창 스킨이 적용된 상태에서도 추가 주사위 굴림 창의 타이머 바가 일반 주사위 타이머와 동일한 스타일로 정상 표시됩니다."
L["On a fresh install the chat window now starts far enough from the screen edge to fit its sidebar."] = "새로 설치 시 대화창 사이드바가 화면 밖으로 벗어나지 않도록 가장자리에서 적절한 여백을 두고 배치됩니다."
L["Edit Mode no longer shows a selection box for Blizzard's hidden minimap."] = "편집 모드에서 블리자드의 숨겨진 미니맵 선택 상자가 나타나지 않습니다."
L["Auras in the top slot now sit above the Level text when Level is the Top Text."] = "레벨이 상단 텍스트일 때 상단 슬롯 오라가 레벨 텍스트 위에 알맞게 배치됩니다."
L["Clicking the Level or Health # text in the settings preview now scrolls to its text position, like the name and health %."] = "설정 미리보기에서 레벨 또는 생명력 # 텍스트를 클릭하면 이름 및 생명력 %처럼 해당 텍스트 위치 설정으로 바로 스크롤됩니다."
L["Text colors set by a spec-assigned nameplate preset now apply to the first nameplates after login, not only after the next settings change."] = "전문화 지정 이름표 프리셋의 글자 색상이 설정 변경 후뿐만 아니라 로그인 직후 첫 이름표에도 즉시 적용됩니다."
L["Blizzard's arrow under the nameplates of units behind your camera no longer shows."] = "카메라 뒤편에 있는 대상 이름표 아래에 뜨던 블리자드 화살표가 표시되지 않습니다."
L["Missing Buffs no longer marks group members who have the buff as missing during and after fights in dungeons and raids."] = "던전 및 공격대 전투 중/후에 이미 강화 효과를 받고 있는 파티원을 누락된 것으로 잘못 표시하던 문제를 수정했습니다."
L["The Totem Bar's Enabled Classes list no longer offers Death Knight, Monk, Demon Hunter or Evoker."] = "토템 바 활성화 직업 목록에 죽음의 기사, 수도사, 악마사냥꾼, 기원사가 표시되지 않습니다."
L["The target and focus cast bars no longer go missing from Unlock Mode when it is opened with a target or focus selected under the Blizzard, Classic or WoW Forever looks."] = "블리자드, 클래식, WoW Forever 스타일에서 대상/주시대상 선택 상태로 잠금 해제 모드를 열었을 때 시전 바가 사라지던 문제를 수정했습니다."
L["Brazilian Portuguese translations updated."] = "브라질 포르투갈어 번역이 업데이트되었습니다."
L["Match All on Indicators"] = "표시기 모든 조건 일치"
L["Debuff indicators can show only debuffs that match all their filters; everything else stays where it was"] = "약화 효과 표시기가 등록된 모든 필터 조건에 일치하는 약화 효과만 선별하여 표시할 수 있습니다"
L["Name Bar on Bottom"] = "하단 이름 바"
L["The Top Name Bar can sit at the bottom of the frame, under the health and power bars"] = "상단 이름 바를 생명력 및 자원 바 아래인 프레임 하단에 배치할 수 있습니다"
L["Raid and party frames show a glowing Fortitude, Mark of the Wild or Spirit icon on anyone missing it while your group can cast it"] = "파티/공격대에 해당 강화 효과 시전자가 있을 때 인내, 야생의 징표, 신비한 지능(또는 정신력)이 누락된 파티원 프레임에 반짝이는 아이콘을 표시합니다"
L["Edit Mode no longer shows selection boxes for Blizzard's hidden action bar end caps."] = "편집 모드에서 블리자드의 숨겨진 단축바 장식 마감 선택 상자가 나타나지 않습니다."
L["HoverCast can bind a specific spell rank: a lower rank picked from the spell grids casts exactly that rank on its own key, while the top rank keeps casting your highest rank."] = "마우스오버 시전에서 주문 격자의 하위 등급 주문을 전용 단축키에 지정하여 해당 등급을 정확히 시전할 수 있습니다 (최고 등급은 항상 최고 레벨 시전)."
L["Clicking the icon, spell text or duration text in the Cast Bar preview now jumps to the matching setting."] = "시전 바 미리보기에서 아이콘, 주문 텍스트, 지속시간 텍스트를 클릭하면 해당 설정 위치로 바로 이동합니다."
L["The Portrait Dragon's Frame Level now defaults to 2, so it sits over more of the frame."] = "초상화 용 테두리의 프레임 레벨 기본값이 2로 변경되어 프레임 위에 알맞게 배치됩니다."
L["Weapon imbues such as Rockbiter Weapon now show on the Player Aura Bars Buffs bar."] = "대지의 무기 등 주술사의 무기 마법부여 효과가 플레이어 오라 바의 강화 효과 바에 정상 표시됩니다."
L["End Caps on Any Bar"] = "모든 단축바 장식 마감"
L["End caps can go on any action bar, left, right or both, each with its own size and offsets. On the WoW Forever look any bar can also show the bar background."] = "행동 단축바의 왼쪽, 오른쪽 또는 양쪽 모두에 전용 크기 및 위치 조정이 가능한 장식 마감을 추가할 수 있습니다. WoW Forever 테마에서는 모든 바에 단축바 배경을 표시할 수도 있습니다."
L["Upgraded Flight Timer"] = "향상된 비행 타이머"
L["The flight timer now shows your route: a track between the two ends of the flight with each stop scrolling past as you reach it, plus an early landing button and adjustable height and end caps. It is now on by default."] = "비행 타이머가 비행 경로를 표시합니다: 출발지와 목적지 사이의 진행 상황과 각 경유지를 스크롤로 보여주며 조기 착륙 버튼, 높이 조절 및 장식 마감을 지원합니다 (기본 켜짐)."
L["Rearrange Bags"] = "가방 순서 재배치"
L["Drag a bag on the bag bar onto another slot to swap them; the bar now runs in Blizzard's order"] = "가방 바에서 가방을 드래그하여 다른 슬롯과 위치를 바꿀 수 있으며, 가방 바가 블리자드 기본 순서대로 정렬됩니다"
L["Micro Menu Tooltips"] = "게임 메뉴 툴팁"
L["Character always shows item level and stats; Social and Guild always list who is online"] = "캐릭터 버튼 툴팁에 아이템 레벨과 능력치를 항상 표시하며, 대인관계 및 길드 버튼에는 현재 접속자 목록을 표시합니다"
L["Friend Notes"] = "친구 메모 표시"
L["The Friends Online tooltip can show each friend's or guildmate's note (off by default)"] = "접속 중인 친구 툴팁에 친구 및 길드원의 메모를 함께 표시합니다 (기본 꺼짐)"
L["Hide Groups 5-8 in Mythic"] = "신화 난이도에서 5-8파티 숨기기"
L["A Show Groups option hides groups 5-8 inside a Mythic raid, where only groups 1-4 take part"] = "1-4파티만 참여하는 신화 공격대 인스턴스 내부에서 5-8파티 프레임을 자동으로 숨기는 옵션입니다"
L["Starter Buff Indicators"] = "기본 강화 효과 표시기 프리셋"
L["Defensives, Externals and Consumables in the center, your own core healing buffs top right"] = "생존기, 외부 지원기, 소모품을 중앙에 배치하고 주요 치유 강화 효과를 우측 상단에 배치하는 기본 프리셋을 제공합니다"
L["Regen Ticks"] = "마나 회복 주기 틱"
L["Mana Regen Spark can keep sweeping every 2 seconds while your mana regenerates"] = "마나가 회복되는 동안 마나 회복 불꽃(스파크)이 2초 주기 틱에 맞춰 계속 이동합니다"
L["Cast Icon Border"] = "시전 아이콘 테두리"
L["The cast icon can use the cast bar's border style, with an optional divider or wrap-around border"] = "시전 아이콘에 시전 바와 동일한 테두리 스타일을 적용하고, 구분선 또는 둘러싸는 테두리 옵션을 선택할 수 있습니다"
L["Class Zoom"] = "직업 초상화 확대"
L["Class-art portraits get a Class Zoom slider in the portrait zoom settings"] = "초상화 확대 설정에 직업 아트 초상화를 위한 전용 확대 슬라이더가 추가되었습니다"
L["Portrait Border Separator"] = "초상화 테두리 구분선"
L["Attached portraits can draw the border style's divider between the portrait and the bars"] = "프레임에 부착된 초상화와 바 사이에 테두리 스타일의 구분선을 그릴 수 있습니다"
L["Portrait Dragon"] = "초상화 용 장식"
L["The dragon has its own Portrait row and works with any portrait, attached or detached"] = "용 장식 전용 설정 행이 추가되어 부착형 및 분리형 초상화 모두에 적용할 수 있습니다"
L["Mana + Form Power"] = "마나 + 변신 자원 바"
L["Druids can keep Mana on the power bar with Energy or Rage in a second bar"] = "드루이드가 기본 자원 바에 마나를 유지하면서 기력 또는 분노를 보조 자원 바에 함께 표시할 수 있습니다"
L["Action bars, including the Stance Bar, now stay on screen after a UI Scale, resolution or window size change, and return to their saved spot when there is room again."] = "UI 비율, 해상도, 창 크기 변경 시 태세 바를 포함한 단축바가 화면 밖으로 벗어나지 않고 공간이 확보되면 저장된 위치로 복귀합니다."
L["Source of Magic now counts only your own cast, clears as soon as you cast it (even in combat), no longer flashes after loading screens, and reminds early by your Show Below settings."] = "마력의 원천이 자신의 시전만을 정확히 추적하여 시전 즉시 알림이 사라지고 로딩 화면 후 깜빡이지 않으며 설정된 기준에 맞춰 조기 알림을 제공합니다."
L["Elemental Orbit shamans can turn on an out-of-combat reminder for when no groupmate has their Earth Shield or it is about to run out."] = "원소의 궤도 특성을 찍은 주술사가 대지 보호막이 없거나 만료 직전일 때 전투 외 알림을 켤 수 있습니다."
L["The Great Vault shortcut now opens the vault without closing the character sheet, and a second click closes it."] = "위대한 금고 바로가기가 캐릭터 창을 닫지 않고 금고를 열며, 한 번 더 클릭하면 닫힙니다."
L["The flight timer now starts when you take off."] = "비행 타이머가 비행을 시작(이륙)하는 즉시 정상 작동합니다."
L["The Gamepad settings in Global Settings (hide action bars and the player cast bars while a controller is connected) are now off by default."] = "전체 설정의 게임패드 옵션(컨트롤러 연결 시 단축바 및 플레이어 시전 바 숨김)이 기본 비활성화로 변경되었습니다."
L["A UI Scale change made during combat is no longer undone by the game in the same fight."] = "전투 중 UI 비율을 변경해도 해당 전투 중 게임 시스템에 의해 변경 사항이 취소되지 않습니다."
L["Sound pickers (Chat whisper sound, Cooldown Manager bar sounds and others) show their speaker preview icon again."] = "소리 선택창(귓속말 알림음, 재사용 대기시간 관리자 알림음 등)에 스피커 미리듣기 아이콘이 정상 표시됩니다."
L["Popups that an addon opens from a button collected in the minimap button bag now draw above the bag and take clicks outside it."] = "미니맵 버튼 가방에 모인 버튼에서 애드온 팝업이 열릴 때 가방 창 위에 표시되며 외부 클릭을 정상적으로 처리합니다."
L["The Interrupted flash now also shows when a channeled or empowered cast is interrupted, on nameplates and on the Mythic+ target and focus cast bars."] = "채널링 또는 강화 주문이 차단되었을 때도 이름표 및 신화+ 대상/주시대상 시전 바에 '차단됨' 깜빡임 효과가 정상 표시됩니다."
L["Fixed a Lua error from the faction badge on full friendly nameplates when player names are hidden by the game (e.g. switching off Name Only)."] = "게임 시스템에 의해 플레이어 이름이 숨겨졌을 때 우호적 이름표의 진영 문장으로 인해 발생하던 Lua 오류를 수정했습니다."
L["Friendly nameplates shown by Blizzard no longer lose their widget bars, raid marker or interact icon, or show them on another nameplate, after reusing a frame from an enemy nameplate."] = "적 이름표 프레임을 재사용할 때 블리자드 아군 이름표의 위젯 바, 징표, 상호작용 아이콘이 사라지거나 다른 이름표에 나타나던 문제를 수정했습니다."
L["Enemy nameplates no longer keep Blizzard's hidden cast bar running underneath, which cuts background work in large caster pulls."] = "적 이름표 아래에서 블리자드 기본 시전 바가 백그라운드로 작동하지 않도록 차단하여 대규모 풀링 시 성능을 대폭 향상했습니다."
L["A moved Top Bar Event Text that the game re-anchors during combat now returns to your spot after the fight."] = "전투 중 게임 시스템이 위치를 재설정한 상단 바 이벤트 텍스트가 전투 종료 후 원래 사용자 지정 위치로 복귀합니다."
L["With the Gamepad interface style, the Shifter steps aside, so closing bags or windows opened from the radial menu no longer shows a blocked-action error and freezes the game."] = "게임패드 스타일에서 Shifter 이동 기능이 비활성화되어 링 메뉴에서 연 가방이나 창을 닫을 때 작업 차단 오류로 게임이 멈추지 않습니다."
L["Tracker sections added by other addons now get the EllesmereUI skin like Blizzard's own sections."] = "다른 애드온이 퀘스트 추적기에 추가한 섹션에도 블리자드 기본 섹션과 동일하게 EllesmereUI 스킨이 적용됩니다."
L["Party and raid frames now appear right away when you join a group or your party becomes a raid during combat, instead of after the fight."] = "전투 중 파티에 참여하거나 파티가 공격대로 전환되어도 전투 종료를 기다리지 않고 프레임이 즉시 나타납니다."
L["The Buffs tab now opens on All Specs."] = "강화 효과 탭이 기본적으로 '모든 전문화' 설정으로 열립니다."
L["Hide Power Bar if Resource no longer hides the Power Bar while the Class Resource is turned off, which also brings back the druid mana bar in Cat Form on WoW Forever."] = "직업 자원이 꺼져 있을 때 '자원 있으면 자원 바 숨김'이 작동하지 않아, WoW Forever 표범 변신 상태에서도 드루이드 마나 바가 정상 표시됩니다."
L["Spell Cost Prediction now shows on the Power Bar while you cast."] = "주문 시전 중 자원 바에 소모될 예상 자원량이 미리 표시됩니다."
L["The Power Bar Seam now joins the frame border on the Pixels border styles."] = "픽셀 테두리 스타일에서 자원 바 이음새가 프레임 테두리와 자연스럽게 연결됩니다."
L["The player power bar and its text now move smoothly as power regenerates or drains, in step with Blizzard's displays and the Resource Bars power bar, instead of updating every couple of seconds."] = "플레이어 자원 바 및 텍스트가 몇 초마다 뚝뚝 끊겨 갱신되지 않고 블리자드 표시처럼 부드럽게 실시간으로 채워지고 줄어듭니다."
L["Width-matched action bars and unit frames settle back into their saved spot after every fight, not only the first one of the session."] = "너비 맞춤이 적용된 단축바 및 유닛 프레임이 첫 전투뿐만 아니라 모든 전투가 끝난 후 항상 원래 저장된 위치로 복귀합니다."
L["Français"] = "프랑스어 (Français)"
L["Español (EU)"] = "스페인어 (유럽)"
