-- =========================================================================
-- 패치 노트 및 신규 기능 안내 (What's New / Patch Notes) - v9.6.2
-- =========================================================================
L["Important buffs can follow your cursor only while you are in combat, and show with your other reminders the rest of the time"] = "중요한 강화 효과가 전투 중에만 커서를 따라다니며, 그 외 시간에는 다른 알림들과 함께 기본 위치에 표시됩니다."
L["Not Needed Reminder Choice"] = "불필요 알림 표시 대상 선택"
L["Choose where each talent's 'Not Needed' reminder shows: never, this season's instances or every instance; one that was on now shows in this season's instances"] = "각 특성의 '불필요' 알림을 표시할 장소를 선택합니다: 표시 안 함, 이번 시즌 인스턴스 던전, 모든 인스턴스 던전 중 선택할 수 있으며 기존 활성 알림은 이번 시즌 인스턴스 던전으로 자동 전환됩니다"
L["Edit Talent Reminder Zones"] = "특성 알림 지역 편집"
L["Each talent reminder in the list has its own zone dropdown to change where it reminds you, with Delete Reminder at its top"] = "목록의 각 특성 알림에 자체 지역 드롭다운이 추가되어 알림을 받을 지역을 개별 변경할 수 있으며, 드롭다운 상단에서 알림을 삭제할 수 있습니다."
L["Talent reminders now remind in zones added to them later, and in the zone of a reminder made with an older version."] = "이후에 추가된 지역 및 이전 버전에서 생성된 알림의 지역에서도 특성 알림이 정상적으로 작동합니다."
L["Attach Important Buffs to Cursor no longer does work as you move your mouse while nothing is on the cursor."] = "커서에 표시할 효과가 없을 때는 마우스를 움직여도 '커서에 중요 강화 효과 표시' 기능이 불필요한 연산을 수행하지 않습니다."
L["Nameplates, Unit Frames and Action Bars do less work while you log in or reload the UI."] = "게임 접속 시 또는 UI를 다시 불러올 때 이름표, 유닛 프레임, 행동 단축바의 부하를 최적화했습니다."
L["Absorb text on a frame whose absorb bars are turned off now clears when a shield runs out on its own."] = "흡수 바가 꺼진 프레임에서 보호막이 자연 소멸할 때 흡수량 텍스트가 정상적으로 사라집니다."

-- =========================================================================
-- 패치 노트 및 신규 기능 안내 (What's New / Patch Notes) - v9.6.6
-- =========================================================================
-- 주요 기능 (Heroes)
L["Tracks your group's interrupts, even inside a key: a bar per member with their kick's cooldown, read from their spec and talents, and each kicker's icon on the enemy they kicked last. It is off until you turn it on in the Kick Tracker tab of Mythic+ Tools."] = "신화+ 쐐기돌 던전 내에서도 파티원의 차단 현황을 추적합니다. 파티원별 전문화와 특성을 반영한 차단 재사용 대기시간 바와 각 플레이어가 마지막으로 차단한 적 이름표 위에 차단자 아이콘을 표시합니다. 신화+ 도구의 차단 추적기 탭에서 활성화할 수 있습니다."
L["Shared Core Positions"] = "이름표 주요 위치 다중 배치"
L["Any elements can now share a Core Positions slot on your nameplates, side by side in the order you drag them into, such as the raid marker next to the crowd control icons. Each slot's cog gains an Element Spacing row, and existing setups look exactly as before."] = "이름표의 주요 위치 슬롯(상단, 좌측 등) 하나에 공격대 징표와 군중 제어 아이콘처럼 여러 요소를 드래그한 순서대로 나란히 함께 배치할 수 있습니다. 각 슬롯의 톱니바퀴에 요소 간격 설정이 추가되었으며, 기존 설정은 이전과 동일하게 유지됩니다."
L["Point Anchors"] = "포인트 기준점"
L["Unlock Mode can now anchor any point of an element to any point of another, a corner to a corner or an edge to an edge, and the two stay lined up when either resizes. Turn on Point Anchoring in Global Settings > General, then Anchor an element and pick its point and the target's."] = "잠금 해제 모드에서 한 요소의 특정 포인트를 다른 요소의 포인트에 고정할 수 있습니다(모서리와 모서리, 또는 가장자리와 가장자리). 어느 한쪽의 크기가 바뀌어도 정렬 상태가 유지됩니다. 전체 설정 > 일반에서 포인트 기준점을 켠 뒤, 요소를 고정하고 기준 포인트와 대상 포인트를 지정하세요."
L["Overlap Cycling"] = "겹친 프레임 순환 선택"
L["Scroll the wheel over overlapping frames in Unlock Mode to bring the one under your cursor to the front. On from the start with the plain wheel; choose a Shift, Ctrl or Alt modifier, or turn it off, in Global Settings > General."] = "잠금 해제 모드에서 여러 프레임이 겹쳐 있을 때 마우스 휠을 굴리면 커서 아래의 프레임들을 순서대로 맨 앞으로 가져옵니다. 기본적으로 마우스 휠 단독으로 작동하며, 전체 설정 > 일반에서 Shift, Ctrl, Alt 조합 키를 지정하거나 끌 수 있습니다."

-- 추가 기능 (Features)
L["A Move in Unlock Mode button beside each movable element's first settings section opens Unlock Mode with that element selected and flashed"] = "이동 가능한 각 요소의 첫 번째 설정 섹션 옆에 있는 '잠금 해제 모드에서 이동' 버튼을 클릭하면, 해당 요소가 선택되고 깜빡이는 상태로 잠금 해제 모드가 열립니다."
L["Page Previews"] = "페이지 미리보기"
L["The Kick Tracker, Cast Bars, Target/Focus Bars, GCD Bar, Totem Bar and XP Bar pages now preview their bars and icons at the top"] = "차단 추적기, 시전 바, 대상/주시 대상 바, GCD 바, 토템 바, 경험치 바 설정 페이지 상단에서 바와 아이콘을 미리 볼 수 있습니다."
L["Turn the spec icons on the group list's filled slots off to keep the game's own class and role icons"] = "파티 목록의 찬 슬롯에서 전문화 아이콘을 끄고 게임 기본 직업 및 역할 아이콘을 유지할 수 있습니다."
L["Channel Color Override"] = "정신 집중 시 색상 재정의"
L["Channel Color"] = "정신 집중 시 색상"
L["Channeled spells fill in their own color."] = "정신 집중 주문 시전 시 고유 색상으로 채웁니다."
L["This option can't be used while the Unit Frames player cast bar shows its icon on the portrait."] = "유닛 프레임 플레이어 시전 바가 초상화 위에 아이콘을 표시하는 동안에는 이 설정을 사용할 수 없습니다."
L["Channeled spells can fill the cast bar in their own color, set in its Fill Color cog"] = "채움 색상 톱니바퀴에서 색상을 지정하여 정신 집중 주문 시전 시 시전 바를 고유한 색상으로 채울 수 있습니다."
L["Spell Icon in Player Portrait"] = "플레이어 초상화에 주문 아이콘 표시"
L["The cast bar's spell icon can show over your player portrait while you cast"] = "주문을 시전하는 동안 시전 바의 주문 아이콘을 플레이어 초상화 위에 겹쳐 표시할 수 있습니다."
L["Extend Border Left and Right"] = "테두리 좌우 확장"
L["The power, class resource, cast and GCD bar borders can reach past the bar's left and right edges, like Extend Top and Bottom"] = "상하 확장과 마찬가지로 자원, 직업 자원, 시전 및 GCD 바의 테두리를 바의 좌우 끝 너머까지 확장할 수 있습니다."
L["The Health and Power bars can show while your health, energy, focus or mana is below full, even when their Visibility setting hides them"] = "가시성 설정에 의해 숨겨져 있더라도 생명력, 기력, 집중, 마나가 최대치 미만일 때 생명력 및 자원 바를 표시할 수 있습니다."
L["Aura Border Styles"] = "오라 테두리 모양"
L["Textured Pandemic Ring uses the aura's Border Size."] = "텍스처 팬데믹 링은 오라의 테두리 크기를 사용합니다."
L["This option requires a textured aura Border Style and a Border Size above 0."] = "이 설정은 텍스처 오라 테두리 모양과 0보다 큰 테두리 크기가 필요합니다."
L["This option requires a Pixels or Pixels Textured border above size 0."] = "이 설정은 0보다 큰 크기의 픽셀 또는 픽셀 텍스처 테두리가 필요합니다."
L["This option requires a textured border."] = "이 설정은 텍스처 테두리가 필요합니다."
L["This option requires an enabled textured border."] = "이 설정은 활성화된 텍스처 테두리가 필요합니다."
L["Buff and debuff icons can use any border style, an exact border size and border opacity, with optional textured dispel and pandemic rings"] = "강화 및 약화 효과 아이콘에 원하는 테두리 모양, 정확한 테두리 크기 및 불투명도를 설정할 수 있으며, 텍스처가 적용된 해제 및 팬데믹 링을 선택할 수 있습니다."
L["Each talent's 'Not Needed' reminder can show never, in this season's instances (the new default for ones that were on) or in every instance"] = "각 특성의 '불필요' 알림을 표시 안 함, 이번 시즌 인스턴스 던전(기존 활성 알림의 새 기본값), 모든 인스턴스 던전 중에서 선택하여 표시할 수 있습니다."
L["Stance Bar Hiding"] = "태세 바 숨김"
L["A per-spell Stance Bar option hides an icon in or outside Stealth, a form or a stance, so icons can swap with keys that cast something else there"] = "주문별 태세 바 옵션을 통해 은신, 형상 또는 태세 안팎에서 아이콘을 숨겨, 해당 자리에서 다른 주문을 시전하는 단축키와 교체되도록 할 수 있습니다."
L["Cooldown Manager Icons for Addons"] = "외부 애드온용 재사용 대기시간 관리자 아이콘"
L["Other addons can find the Cooldown Manager icons showing a spell, even one Blizzard's Cooldown Manager doesn't track, to highlight the next cast"] = "다른 외부 애드온이 블리자드 기본 재사용 대기시간 관리자가 추적하지 않는 주문을 포함하여, 재사용 대기시간 관리자 아이콘을 찾아 다음 시전할 기술을 강조할 수 있습니다."
L["Cooldown Manager Repopulate for Addons"] = "외부 애드온용 재사용 대기시간 관리자 재구성"
L["Profile installers that write Blizzard Cooldown Manager layouts can have the Cooldown Manager rebuild its bars from them after their reload"] = "블리자드 재사용 대기시간 관리자 레이아웃을 작성하는 프로필 설치기가 UI를 다시 불러온 후 해당 레이아웃을 기반으로 재사용 대기시간 관리자 바를 다시 구성하도록 요청할 수 있습니다."
L["Separators and Value Gradient"] = "구분선 및 수치 그래디언트"
L["Colors each value on a green to red scale."] = "각 수치를 녹색에서 빨간색 범위의 색상으로 표시합니다."
L["Colors each value from green to red as that player nears pulling aggro."] = "해당 플레이어가 어그로를 획득하기 직전까지 녹색에서 빨간색으로 수치 색상을 표시합니다."
L["Adds a divider between each icon and its bar."] = "각 아이콘과 바 사이에 구분선을 추가합니다."
L["Draws a divider under the header in the window border's style."] = "헤더 아래에 창 테두리 스타일의 구분선을 표시합니다."
L["Replaces each bar's border with a divider under it."] = "각 바의 테두리를 바 아래의 구분선으로 대체합니다."
L["Shows a white stripe on your own bar."] = "자신의 바에 흰색 줄무늬를 표시합니다."
L["Space between loot rows or Icon Tray tiles. Loot Toast adds room for its decorative frame."] = "획득 알림 줄 또는 아이콘 트레이 타일 사이의 간격입니다. 획득 토스트 사용 시 장식 프레임을 위한 공간이 추가됩니다."
L["fishing skill"] = "낚시 숙련도"
L["Pixels border separators between bars, values colored green to red from the top amount down, background textures, icon zoom and a marker on your bar"] = "바 사이의 픽셀 테두리 구분선, 최고 수치부터 녹색에서 빨간색으로 점진적으로 변하는 수치 색상, 배경 텍스처, 아이콘 확대, 내 바의 징표 표시 등을 지원합니다."
L["Right-click a quest in the quest tracker or quest log for a Wowhead link to copy, optionally in your game's language or opening at the comments"] = "퀘스트 추적기나 퀘스트 목록에서 퀘스트를 우클릭하여 복사할 수 있는 와우헤드 링크를 엽니다. 게임 언어로 보거나 댓글 탭으로 바로 열도록 설정할 수 있습니다."
L["Element Filter"] = "요소 필터"
L["A box on the Unlock Mode bar shows only the elements whose name contains every word you type, in English or your own language"] = "잠금 해제 모드 상단 바의 검색창에 입력한 단어가 포함된 요소만 표시합니다. 영어 또는 현재 설정된 언어로 검색할 수 있습니다."
L["Form Power Bar Settings"] = "폼 자원 바 설정"
L["A druid's Mana + Form Power bar has its own offsets and its own text format, position, size and color"] = "드루이드의 마나 + 폼 자원 바에 고유한 위치 오프셋과 텍스트 형식, 위치, 크기 및 색상 설정을 제공합니다."
L["Flight Timer Appearance"] = "비행 타이머 외형"
L["Any border style and size, a background texture and color, a Pixels stop separator, a spark at the end of the fill and an early exit button border"] = "다양한 테두리 모양 및 크기, 배경 텍스처 및 색상, 픽셀 정지 구분선, 바 끝의 스파크 효과, 조기 하차 버튼 테두리 등을 설정할 수 있습니다."
L["Loot Feed Appearance"] = "획득 알림 외형"
L["Any border style and size, a background texture, adjustable spacing and an optional Pixels separator beside the icon"] = "다양한 테두리 모양 및 크기, 배경 텍스처, 간격 조절, 아이콘 옆 픽셀 구분선 등을 설정할 수 있습니다."
L["Threat Meter Appearance"] = "위협 미터기 외형"
L["Icon zoom, Comic class icons, a background texture, Pixels separators, your bar's marker on or off, and values colored green to red as threat climbs"] = "아이콘 확대, 코믹 직업 아이콘, 배경 텍스처, 픽셀 구분선, 내 바의 징표 표시 여부, 위협 수준 상승에 따른 녹색~빨간색 수치 색상 등을 설정할 수 있습니다."
L["The world map shows the fishing skill a zone needs under its name, colored by your skill: red too low, yellow still loses fish, green loses none"] = "세계 지도 지역 이름 아래에 해당 지역에 필요한 낚시 숙련도를 표시합니다. 숙련도에 따라 색상이 지정됩니다(빨간색: 너무 낮음, 노란색: 낚시 실패 가능, 녹색: 100% 성공)."

-- 버그 수정 (Fixes)
L["Reminders for raid buffs a groupmate provides no longer take left clicks, since you cannot cast them; the click goes through to the game and middle-click still dismisses the reminder."] = "파티원이 제공하는 공격대 강화 효과 알림은 직접 시전할 수 없으므로 좌클릭을 가로채지 않고 게임 클라이언트로 통과시키며, 휠 클릭으로 알림을 닫을 수 있습니다."
L["Bulk Buy now opens on a shift-click for items a vendor sells one at a time, such as armor and weapons, which used to get no window."] = "방어구나 무기처럼 상인이 1개씩 판매하는 아이템도 Shift+클릭 시 대량 구매 창이 정상적으로 열립니다."
L["Copy Chat and chat tabs pulled out of the dock no longer cause a blocked-action error during combat."] = "전투 중 대화 복사 기능이나 도크에서 분리된 대화 탭으로 인해 동작 차단 오류가 발생하던 문제를 수정했습니다."
L["Add Custom Spell now refuses spells that are in the spell list, since their settings had no effect when added that way; to fix one added before, remove it and pick it from the list."] = "'사용자 지정 주문 추가' 시 이미 주문 목록에 존재하는 주문은 중복 등록을 거부합니다. 기존에 등록된 주문은 삭제 후 목록에서 직접 선택하세요."
L["The Add Custom Spell popup's messages no longer cover the Show Charges checkbox."] = "사용자 지정 주문 추가 팝업의 안내 메시지가 '충전 횟수 표시' 체크박스를 가리지 않도록 개선했습니다."
L["Dragging icons in the bar preview now works up and down on vertical bars, with the insert line across the gap, and the line matches the icons' height with the Cropped shape."] = "세로 바의 미리보기에서 아이콘을 상하로 드래그하여 배치할 수 있으며, 잘린 형태(Cropped) 설정 시 삽입선이 아이콘 높이에 맞게 표시됩니다."
L["The Add Custom Spell window now warns that Blizzard restrictions can keep custom spells from working fully."] = "사용자 지정 주문 추가 창에서 블리자드의 API 제약으로 인해 일부 기능이 제한될 수 있음을 안내합니다."
L["Scrolling a meter with the mouse wheel now lines the bars up again after reaching the end of the list."] = "마우스 휠로 미터기를 스크롤하여 목록 끝에 도달했을 때 바가 정상적으로 다시 정렬됩니다."
L["The threat meter no longer hides its bottom bar when the window is a pixel or two too short for it."] = "창 높이가 1~2픽셀 부족하더라도 위협 미터기의 맨 아래 바가 숨겨지지 않습니다."
L["The interrupt-ready color on cast bars now follows a warlock's real interrupt: Grimoire: Fel Ravager, which only summons, no longer counts as one."] = "시전 바의 차단 가능 색상이 흑마법사의 실제 차단 기술을 따릅니다. 소환 주문인 '흑마법서: 지옥 파괴자'는 차단 기술로 잘못 집계되지 않습니다."
L["The options window no longer opens during combat, as it could from a Data Bars block click or a request made just before the pull, which caused blocked-action errors."] = "데이터 바 클릭이나 풀링 직전 요청으로 인해 전투 중 설정 창이 열려 동작 차단 오류가 발생하던 현상을 방지했습니다."
L["The profile keybind window and the conditional overrides condition picker now close with the options window, so they can no longer hold your clicks or keys in combat."] = "설정 창을 닫을 때 프로필 단축키 창과 조건부 재정의 선택 창도 함께 닫히도록 하여, 전투 중 입력이 가려지는 문제를 해결했습니다."
L["Characters are now grouped and remembered by ruleset, Normal, PvP, Roleplaying or Hardcore, instead of a realm name, so the gold roster, spec memory, bag currency order and Cooldown Manager bar sizes no longer mix across rulesets."] = "캐릭터를 서버 이름 대신 일반, PvP, 롤플레잉, 하드코어 등 규칙 세트(Ruleset)별로 묶어 기억하여, 규칙 세트 간에 골드 현황, 전문화 기억, 가방 화폐 순서, 재사용 대기시간 관리자 바 크기 등이 섞이지 않습니다."
L["Cast Bars, Target/Focus Bars and Run Summary now follow a profile switch right away."] = "프로필 전환 시 시전 바, 대상/주시 대상 바, 쐐기 요약이 즉시 갱신됩니다."
L["Cast Bars (formerly Targeted Spell Bars) now show casts from enemies already on screen when you turn them on."] = "시전 바(구 대상 지정 주문 바)를 활성화했을 때 이미 화면에 있던 적의 시전도 즉시 감지하여 표시합니다."
L["The Mythic+ Timer tab now starts with an Enable Mythic+ Timer toggle, and its preview is the eye beside it instead of a Show Preview toggle."] = "신화+ 타이머 탭 상단에 '신화+ 타이머 활성화' 토글이 추가되었으며, 미리보기는 별도 토글 대신 옆의 눈 아이콘을 클릭하여 확인할 수 있습니다."
L["The Movement Alert's Burning Rush text now uses the alert font, outline and text size like the other alerts."] = "이동 알림의 '불타는 돌진' 텍스트가 다른 알림과 동일하게 알림 글꼴, 외곽선 및 글자 크기를 사용합니다."
L["Target arrows no longer make room for icons or auras that a Y offset has moved above or below them."] = "Y 오프셋으로 인해 대상 화살표 위나 아래로 이동한 아이콘 또는 오라로 인해 화살표에 불필요한 여백이 생기지 않습니다."
L["With the Full Sized spell icon, the target arrows and the auras beside the bar now move out past it during a cast instead of overlapping it."] = "전체 크기 주문 아이콘 사용 시, 시전 중 대상 화살표와 바 옆의 오라가 아이콘과 겹치지 않고 바깥쪽으로 알맞게 밀려납니다."
L["Pinging an ability no longer makes the ping marker on raid and party frames grow bigger or show an earlier ping's marker again."] = "기술 핑(Ping)을 찍었을 때 공격대 및 파티 프레임의 핑 징표가 비정상적으로 커지거나 이전 핑의 징표가 다시 나타나던 현상을 수정했습니다."
L["The Class, Power and Health Bars preview now includes the Arcane Soul helper for Mages, and plays it at its real spot on screen while the page is open."] = "직업, 자원 및 생명력 바 미리보기에 마법사용 비전 영혼 도우미가 포함되어, 설정 페이지가 열려 있는 동안 실제 화면 위치에서 미리보기가 재생됩니다."
L["Player Aura Bars tooltips no longer vanish when you move from one icon to the next with a negative Spacing or Row Spacing."] = "간격이나 줄 간격이 음수일 때 플레이어 오라 바의 한 아이콘에서 다음 아이콘으로 마우스를 옮겨도 툴팁이 사라지지 않습니다."
L["Boss frames now show the right name when the bosses change places mid-fight, such as when a new boss joins."] = "전투 중 새로운 우두머리가 합류하는 등 자리가 바뀔 때 우두머리 프레임에 올바른 이름이 정상 표시됩니다."
L["Dark Mode now applies to each frame on its own, with a toggle on the Main Frames and Mini Frames pages; Global Settings > Colors still switches every frame."] = "메인 프레임 및 미니 프레임 페이지의 토글을 통해 프레임별로 다크 모드를 개별 적용할 수 있으며, 전체 설정 > 색상에서는 기존처럼 모든 프레임을 일괄 전환할 수 있습니다."
L["The Target of Target and Focus Target frames now change the moment your target or focus switches who it is attacking, instead of up to half a second later."] = "대상이나 주시 대상이 공격 대상을 바꾸는 순간 대상의 대상 및 주시대상의 대상 프레임이 지연 없이 즉시 변경됩니다."
L["A druid's Mana + Form Power bar now sits just under the player frame on the WoW Forever, Blizzard Style and Classic WoW UI looks instead of hanging below it."] = "WoW Forever, 블리자드 스타일, 클래식 WoW UI 외형에서 드루이드의 마나 + 폼 자원 바가 플레이어 프레임 바로 아래에 밀착하여 배치됩니다."
L["Unlock Mode now comes back after combat even when another fight starts within half a second of the first one ending."] = "전투 종료 후 0.5초 이내에 다른 전투가 시작되더라도 전투가 모두 끝나면 잠금 해제 모드가 정상적으로 복원됩니다."
L["German, Korean, Traditional Chinese and Brazilian Portuguese translations updated for the latest options, and more tooltip, Damage Meters, minimap friends list and Raid & Party Frames labels now show in your language."] = "독일어, 한국어, 번체 중국어, 브라질 포르투갈어 번역이 최신 옵션에 맞추어 업데이트되었으며, 더 많은 툴팁과 데미지 미터기, 미니맵 친구 목록 및 공격대/파티 프레임 항목이 한국어로 표시됩니다."

-- =========================================================================
-- 패치 노트 및 신규 기능 안내 (What's New / Patch Notes) - v9.6.1
-- =========================================================================
L["Spell Groups"] = "주문 그룹"
L["One reminder for buffs that replace each other, like armors or aspects: it shows while none of the group's spells is active"] = "갑옷이나 상처럼 서로를 대체하는 강화 효과를 하나로 묶어 알립니다. 그룹 내 어떤 주문도 활성화되어 있지 않을 때 표시됩니다."
L["Party Condition"] = "파티 조건"
L["Conditional overrides can now apply while you are in a party (a group that is not a raid), inside instances or out"] = "인스턴스 내부 및 외부에서 공격대가 아닌 파티 상태일 때 조건부 재정의를 적용할 수 있습니다."
L["Each dungeon square in Premade Groups can show your best keystone level this season, colored by its score (Group Settings menu)"] = "파티 찾기의 각 던전 사각형에 이번 시즌 최고 쐐기돌 레벨을 평점 색상으로 표시할 수 있습니다(그룹 설정 메뉴)."
L["Quest Filter Button"] = "퀘스트 필터 버튼"
L["An optional button on the Quests header turns Filter Quests on and off"] = "퀘스트 헤더에 필터링 기능을 켜고 끌 수 있는 선택 버튼을 추가합니다."
L["New Name"] = "새 명칭"
L["Raid Frames is now called Raid & Party Frames, since it covers your party frames too; its main tab is now Raid"] = "공격대 프레임이 파티 프레임도 함께 관리하므로 이제 '공격대/파티 프레임'으로 명칭이 변경되며, 기본 탭 이름은 '공격대'가 됩니다."
L["Override List"] = "재정의 목록"
L["The Buff and Debuff Manager sidebars list the overrides that have their own manager; click one to edit it"] = "강화 및 약화 효과 관리자 사이드바에 자체 관리자를 가진 재정의 목록이 표시되며, 클릭하여 편집할 수 있습니다."
L["Casts that cannot be interrupted can fill the cast bar in their own color, set in its Fill Color cog"] = "차단할 수 없는 주문 시전 시 채움 색상 톱니바퀴에서 지정한 고유 색상으로 시전 바를 채울 수 있습니다."
L["Swing Timer Styles"] = "스윙 타이머 스타일"
L["The swing timer now follows your Resource Bars style, wearing the Blizzard, WoW Forever or Classic WoW UI frame like the other bars"] = "스윙 타이머가 자원 바 스타일을 따라 다른 바들과 마찬가지로 블리자드, WoW Forever, 클래식 WoW UI 프레임을 적용합니다."
L["Balance Mana (Always)"] = "조화 마나 (항상 표시)"
L["Balance Druids can keep the Power Bar on Mana in every form, Cat and Bear Form included, a new Power Type choice"] = "조화 드루이드가 표범 및 곰 변신을 포함한 모든 형상에서 자원 바를 마나로 유지할 수 있는 새로운 자원 유형 선택지입니다."
L["Bar Previews"] = "바 미리보기"
L["The Class, Power and Health Bars page now previews your power and health bars too, each with an eye to hide it"] = "직업, 자원 및 생명력 바 설정 페이지에서 자원 및 생명력 바도 함께 미리 볼 수 있으며, 눈 아이콘으로 각각 숨길 수 있습니다."
L["Enemy nameplate health and cast bar backgrounds can use the bar's own texture, tinted by the background color"] = "적 이름표 생명력 및 시전 바 배경에 배경 색상이 음영 처리된 바 고유의 텍스처를 적용할 수 있습니다."
L["Health, power and cast bar backgrounds can use the bar's own texture, tinted by the background color"] = "생명력, 자원 및 시전 바 배경에 배경 색상이 음영 처리된 바 고유의 텍스처를 적용할 수 있습니다."
L["Balance Astral Power"] = "조화 천공의 힘"
L["Balance Druids can show Astral Power on the player power bar in every form except Cat and Bear Form, a new Power Type choice"] = "조화 드루이드가 표범 및 곰 변신을 제외한 모든 형상에서 플레이어 자원 바에 천공의 힘을 표시할 수 있는 새로운 자원 유형 선택지입니다."
L["Attack, Shoot and Auto Shot buttons flash again while active, and stop flashing and lose their highlight as soon as they stop."] = "공격, 사격, 자동 사격 버튼이 활성 상태일 때 다시 깜빡이며, 공격을 멈추면 즉시 깜빡임과 강조 표시가 해제됩니다."
L["Your pet's Attack button stops flashing as soon as your pet stops attacking."] = "소환수가 공격을 멈추면 소환수의 공격 버튼 깜빡임이 즉시 중단됩니다."
L["Fixed combat errors that could stop logging out, the game menu and your action bar buttons from working until a reload."] = "UI를 다시 불러올 때까지 로그아웃, 게임 메뉴, 행동 단축바 버튼이 작동하지 않던 전투 오류를 수정했습니다."
L["Turning Use Blizzard's Rep Bars back on now asks for a reload, which keeps Blizzard's XP and reputation bars from slowing the game and causing errors in combat."] = "'블리자드 평판 바 사용'을 다시 켤 때 UI 다시 불러오기를 요청하여, 블리자드 경험치 및 평판 바로 인한 게임 지연과 전투 중 오류를 방지합니다."
L["Custom spell reminders no longer show for a buff you already have while the game is hiding aura details from addons."] = "게임 클라이언트가 애드온에 오라 세부 정보를 숨기는 동안 이미 보유한 강화 효과에 대해 사용자 지정 주문 알림이 중복 표시되지 않습니다."
L["The bag window stutters less when it opens, updates or you search, and the search now updates once you pause typing."] = "가방 창이 열리거나 갱신되거나 검색할 때의 끊김 현상을 완화했으며, 입력을 멈추었을 때 검색 결과가 갱신됩니다."
L["The Character Sheet's character model and item level, enchant and upgrade text no longer go missing behind the sheet's background."] = "캐릭터 창의 캐릭터 모델과 아이템 레벨, 마법부여, 강화 정보 텍스트가 창 배경 뒤로 가려지던 문제를 수정했습니다."
L["The Equipment Manager's set icon popup now matches the skinned Character Sheet."] = "장비 관리자의 세트 아이콘 팝업이 스킨이 적용된 캐릭터 창 스타일에 알맞게 일치됩니다."
L["Blizzard's swing timers and the other frames stacked above your action bars no longer move up the screen in combat when your cooldowns update."] = "행동 단축바 위에 배치된 블리자드 스윙 타이머 및 기타 프레임들이 전투 중 재사용 대기시간이 갱신될 때 화면 위로 밀려 올라가던 문제를 수정했습니다."
L["After an earlier fight, the meter now keeps filling when a teammate pulls before you or when you zone into a fight your group is already in."] = "이전 전투 이후 파티원이 먼저 풀링하거나 이미 교전 중인 지역에 진입해도 미터기가 정상적으로 계속 기록됩니다."
L["Spell History now lists the healthstones and potions you use."] = "주문 기록에 사용한 생명석과 물약이 표시됩니다."
L["Removed a brief freeze when combat ends, most noticeable after a boss dies."] = "우두머리 처치 직후 두드러지던 전투 종료 시의 순간적인 화면 멈춤 현상을 개선했습니다."
L["Cooldown Manager, Nameplates, Resource Bars, Unit Frames and Quality of Life's Movement Alert use less CPU in combat."] = "전투 중 재사용 대기시간 관리자, 이름표, 자원 바, 유닛 프레임, 이동 알림의 CPU 사용량을 최적화했습니다."
L["The leaver mark on a group member's icon in Premade Groups is no longer hidden under their spec or class icon."] = "파티 찾기에서 파티원 아이콘의 탈주 표시가 전문화나 직업 아이콘 아래에 가려지지 않습니다."
L["Addon buttons in the grouped flyout no longer turn dark after you click them."] = "미니맵 애드온 버튼 모아보기에서 버튼을 클릭한 후 어둡게 변하던 문제를 수정했습니다."
L["Stacking Speed and Top Screen Inset now keep your setting after a game restart."] = "게임 재시작 후에도 이름표 겹침 속도와 상단 여백 설정이 정상적으로 유지됩니다."
L["Health and cast bar background colors now update right away when you switch profiles."] = "프로필을 전환할 때 생명력 및 시전 바 배경 색상이 즉시 갱신됩니다."
L["The Honor Portrait faction icon now shows the unit's honor level badge inside it, as Blizzard's frames do."] = "명예 초상화 진영 아이콘 내부에 블리자드 기본 프레임과 마찬가지로 유닛의 명예 레벨 배지가 표시됩니다."
L["Hide Talking Head hides the speaker's 3D portrait again."] = "'말머리 숨기기' 사용 시 대화 상대의 3D 초상화도 함께 정상적으로 숨겨집니다."
L["The Movement Alert now plays your chosen sound when a movement spell is ready."] = "이동 기술의 재사용 대기시간이 완료되었을 때 이동 알림이 지정한 효과음을 재생합니다."
L["Changing form no longer makes the Movement Alert announce a spell that is still on cooldown."] = "변신 형태를 변경해도 아직 재사용 대기 중인 주문이 이동 알림에 잘못 안내되지 않습니다."
L["Quests added to the tracker no longer flash Blizzard's quest icon for a moment while Show Quest Icons is off."] = "'퀘스트 아이콘 표시'가 꺼져 있을 때 추적기에 추가된 퀘스트의 블리자드 퀘스트 아이콘이 순간적으로 깜빡이지 않습니다."
L["Click Casting no longer causes a brief freeze when a bound spell swaps, such as Holy Armaments."] = "신성한 무기처럼 지정된 주문이 바뀔 때 클릭 시전으로 인해 발생하던 순간적인 화면 멈춤을 해결했습니다."
L["The Buff Manager preview now follows each indicator's Show In setting, showing Raid Only and Party Only indicators only when it previews those frames."] = "강화 효과 관리자 미리보기가 각 표시기의 '표시 대상' 설정을 따라, 공격대 전용 및 파티 전용 표시기를 해당 프레임 미리보기에서만 표시합니다."
L["Hiding the Class Resource bar or its text in Moonkin Form (Enable/Disable per Form) now works."] = "달빛야수 변신 상태에서 직업 자원 바 및 텍스트 숨김 설정(변신별 활성화/비활성화)이 정상 작동합니다."
L["A cast bar's pushback now shows its added time in full beside the countdown, and repeated pushbacks add up correctly."] = "시전 지연 시 초읽기 옆에 추가 시간이 온전히 표시되며, 반복된 시전 지연 시간이 올바르게 합산됩니다."
L["The faction indicator's Honor Portrait style now shows the unit's honor level badge inside it, as Blizzard's frames do."] = "진영 표시기의 명예 초상화 스타일에 블리자드 기본 프레임과 마찬가지로 유닛의 명예 레벨 배지가 표시됩니다."
L["Spanish (Spain), German, Korean, Brazilian Portuguese and Traditional Chinese translations updated for the latest options."] = "스페인어, 독일어, 한국어, 브라질 포르투갈어 및 번체 중국어 번역이 최신 옵션에 맞추어 업데이트되었습니다."

-- =========================================================================
-- 패치 노트 및 신규 기능 안내 (What's New / Patch Notes) - v9.6
-- =========================================================================
L["Premade Groups Filters"] = "파티 찾기 필터"
L["Filter Premade Groups by dungeon, delve, raid boss, role and rating, see each group's specs and leader rating at a glance, and count your M+ applications. The module is off until you turn it on."] = "던전, 구렁, 공격대 우두머리, 역할 및 평점별로 파티를 필터링하고, 각 파티의 전문화 구성과 파티장 평점을 한눈에 확인하며, 신화+ 신청 현황을 집계합니다. 이 모듈은 직접 켤 때까지 꺼져 있습니다."
L["Merchant Bulk Buy"] = "상인 대량 구매"
L["Turn on Bulk Buy in the Merchant card of Window Skins, then shift-click a vendor item to buy any amount at once, with Max and +1 Stack buttons and the total cost shown before you buy."] = "창 스킨의 상인 카드에서 '대량 구매'를 켠 후, 상인 아이템을 Shift+클릭하여 원하는 수량을 한 번에 구매하세요. 구매 전 최대 수량 및 +1묶음 버튼과 총 소모 비용이 표시됩니다."
L["Under the Blizzard Style, Classic WoW UI and WoW Forever looks, the player, target and focus frames can hide their power bar so the health bar fills its space. Under these looks the power bar now always sits in the frame's own track."] = "블리자드 스타일, 클래식 WoW UI 및 WoW Forever 테마에서 플레이어, 대상, 주시 대상 프레임의 자원 바를 숨겨 생명력 바가 그 자리를 채우도록 할 수 있습니다. 해당 테마에서 자원 바는 이제 항상 프레임 자체 트랙 안에 배치됩니다."
L["Classic Windows"] = "클래식 창"
L["Your spellbook and talent keys can open the classic spellbook and talent window instead of Talents & Spellbook. The spellbook's tabs and pages work in combat, and talent points you spend count only once you press Learn."] = "마법책 및 특성 단축키를 눌렀을 때 통합 창 대신 클래식 마법책과 특성 창이 열리도록 설정할 수 있습니다. 마법책의 탭과 페이지는 전투 중에도 작동하며, 투자한 특성 포인트는 '배우기'를 눌러야만 확정됩니다."
L["Moonkin Form Reminder"] = "달빛야수 변신 알림"
L["Balance druids can turn on a reminder that shows in combat while they are out of Moonkin Form"] = "조화 드루이드가 전투 중 달빛야수 변신이 풀렸을 때 화면에 표시되는 알림을 켤 수 있습니다"
L["Item Level Colors"] = "아이템 레벨 색상"
L["Show Item Level is now Never, Default Colors or Custom Colored, with a color swatch for your own color"] = "'아이템 레벨 표시' 설정에 표시 안 함, 기본 색상, 사용자 지정 색상이 추가되었으며 원하는 색상을 팔레트에서 직접 지정할 수 있습니다"
L["A buff set to Show When Missing can also show for its last few seconds, as a reminder to refresh it before it drops"] = "'없을 때 표시'로 설정된 강화 효과가 완전히 끝나기 직전 몇 초 동안에도 화면에 나타나 미리 갱신할 수 있도록 알려줍니다"
L["Active Stance Icon"] = "활성 태세 아이콘"
L["An optional icon shows your active warrior stance, druid form, paladin aura or hunter aspect"] = "현재 활성화된 전사 태세, 드루이드 변신, 성기사 오라 또는 사냥꾼 상을 표시하는 아이콘 옵션입니다"
L["Your companion pet comes back after loading screens, flights and deaths, from your favorites or this character's own"] = "로딩 화면, 비행, 사망 후 계정 즐겨찾기 또는 이 캐릭터 고유의 즐겨찾기 애완동물이 자동으로 다시 소환됩니다"
L["A Fishing Key equips your pole, applies a lure, casts and reels in, a step per press, with optional double-click casting and a bobber indicator"] = "단축키 하나를 누를 때마다 낚싯대 착용, 미끼 사용, 낚싯줄 던지기, 낚아채기를 순서대로 수행하며, 더블 클릭 투척 및 찌 표시기 옵션을 제공합니다"
L["Herb and ore tooltips show the skill a node needs, colored by your chance to raise your skill there"] = "약초 및 광맥 툴팁에 필요한 채집 숙련도를 표시하며, 숙련도 상승 확률에 따라 색상으로 구분합니다"
L["Gold per Hour Tracker"] = "시간당 골드 추적기"
L["The Loot Feed can pin a row with your gold per hour and the session's total, counting looted coin and the value of looted items"] = "전리품 알림 피드 상단에 획득한 골드 및 전리품 가치를 합산하여 시간당 골드 획득량과 이번 세션 총 획득량을 고정 표시할 수 있습니다"
L["Junk Items on Low Bag Space"] = "가방 여유 공간 부족 시 잡동사니 창 표시"
L["The Junk Items window can show only when your bags are nearly full, below a free-slot threshold you choose"] = "가방의 빈 공간이 지정한 임계값 미만으로 부족할 때만 잡동사니 창이 자동으로 나타나도록 설정할 수 있습니다"
L["The world map can show boats, zeppelins, dungeon entrances, flight points and zone exits; click a marker to link it in chat"] = "세계 지도에 배, 비행선, 던전 입구, 비행 경로, 지역 이동 통로를 표시할 수 있으며, 징표를 클릭하여 대화창에 링크를 공유할 수 있습니다"
L["A money bag marks the quest reward choice that sells for the most gold"] = "퀘스트 보상 선택지 중 상점 판매가가 가장 높은 아이템에 돈주머니 아이콘을 표시합니다"
L["Hovering a zone on a continent map shows its level range, colored by difficulty"] = "대륙 단위 지도에서 지역 위에 마우스를 올리면 해당 지역의 적정 레벨 범위를 난이도별 색상으로 표시합니다"
L["World Map Fade"] = "세계 지도 투명화"
L["The world map can fade while you move, and the black behind the maximized map can be lightened so the game shows around it"] = "이동하는 동안 세계 지도를 반투명하게 흐리게 처리할 수 있으며, 최대화된 지도 배경의 검은 여백을 밝게 조절하여 주변 게임 화면을 볼 수 있습니다"
L["More Combat Text Options"] = "전투 텍스트 추가 옵션"
L["The Combat Text dropdown adds Absorb Shields, Target Effects and Others' Target Effects"] = "전투 텍스트 드롭다운 메뉴에 '흡수 보호막', '대상 효과', '타인의 대상 효과' 설정이 추가되었습니다"
L["With Important Cast Color on, an important cast can keep the Interruptible color while your interrupt is ready"] = "'중요 시전 색상' 사용 시, 내 차단 기술의 재사용 대기시간이 돌아와 있는 동안 중요 시전에 차단 가능 색상을 유지합니다"
L["Pandemic and Dispel Glow Styles"] = "팬데믹 및 해제 반짝임 스타일"
L["Pandemic Glow and Dispel Glow get their glow styles and settings back, with Blizzard's pandemic border kept as a style and still the default"] = "블리자드 기본 팬데믹 테두리를 기본 스타일로 유지하면서, 팬데믹 반짝임과 해제 반짝임에 다양한 반짝임 스타일 및 세부 설정이 복원되었습니다"
L["Hide Banners and Toasts"] = "현수막 및 알림창 숨김"
L["Hide Blizzard Elements can hide the big boss and event banners and Blizzard's loot, achievement and housing pop-ups"] = "'블리자드 요소 숨기기'를 통해 대형 우두머리 및 이벤트 현수막과 블리자드 기본 전리품, 업적, 하우징 팝업창을 숨길 수 있습니다"
L["Hide Blizzard Elements can silence the talking head's voice lines, with or without hiding the talking head"] = "'블리자드 요소 숨기기'를 통해 말머리 창 표시 여부와 관계없이 말머리의 음성 대사를 음소거할 수 있습니다"
L["The Secondary Stats block can show your off-hand hit chance (pick it in Choose Stats)"] = "보조 능력치 정보 블록에 보조무기 적중률을 표시할 수 있습니다 ('능력치 선택'에서 지정)"
L["Quest Sorting and Filters"] = "퀘스트 정렬 및 필터"
L["Sort, filter and auto-track your quests (experimental), color objectives by progress, and play a sound or tell your party as quests progress"] = "퀘스트를 정렬, 필터링 및 자동 추적(실험실 기능)하고, 진행 상황에 따라 목표에 색상을 입히며, 퀘스트 진행 시 효과음을 재생하거나 파티에 알릴 수 있습니다"
L["Buff icon indicators can show a colored border while the buff is in its refresh window"] = "강화 효과 아이콘 표시기에 효과 갱신 가능(팬데믹) 구간 동안 색상 테두리를 표시할 수 있습니다"
L["Salvation Reminder"] = "구원의 축복 알림"
L["Missing Buffs can remind Salvation on its own, now that it stacks with other blessings, on every group member but tanks"] = "구원의 축복이 다른 축복과 중첩됨에 따라, 누락된 강화 효과 알림에서 방어 전담을 제외한 모든 파티원에게 구원의 축복을 개별적으로 알릴 수 있습니다"
L["Bar backgrounds can use the bar's own texture, tinted by the background color, on the class, power and health bars, the cast bar and the GCD bar"] = "직업, 자원, 생명력 바와 시전 바, GCD 바 배경에 배경 색상이 음영 처리된 바 고유의 텍스처를 적용할 수 있습니다"
L["Swing Timer Movement Guide"] = "스윙 타이머 이동 가이드"
L["The swing timer shows when you can move and when to stand still for wand and Auto Shot shots, and colors rows by your attack's state"] = "스윙 타이머가 마법봉 사격 및 자동 사격 시 언제 움직일 수 있고 언제 멈춰야 하는지 안내하며, 공격 상태에 따라 각 줄의 색상을 변경합니다"
L["Swing Timer Spark"] = "스윙 타이머 이동선(Spark)"
L["The swing timer's spark can be wider, reach past the bar, and take its own color for each weapon"] = "스윙 타이머의 이동선(Spark) 너비를 넓히거나 바 바깥까지 확장할 수 있으며, 무기별로 고유한 색상을 지정할 수 있습니다"
L["Battle Shout reminders now count the whole raid, now that the shout reaches every raid member."] = "전투의 외침이 공격대원 전체에게 적용됨에 따라, 전투의 외침 알림이 공격대원 전원을 집계합니다."
L["The Extra Action Button's mover and settings are gone, now that the game no longer has an Extra Action Button."] = "게임 내에서 특수 능력 버튼(Extra Action Button)이 제거됨에 따라, 해당 버튼의 이동기 및 설정 항목이 정리되었습니다."
L["The skinned Character Sheet colors the pet stats' Combat section like Attack."] = "스킨이 적용된 캐릭터 창에서 소환수 능력치의 '전투' 섹션 색상이 '공격'과 동일하게 표시됩니다."
L["The skinned Talents window's spec tabs, top bar and search options arrow match the skin again after the game's new talent window art."] = "새로운 게임 기본 특성 창 디자인에 맞춰, 스킨이 적용된 특성 창의 전문화 탭, 상단 바, 검색 옵션 화살표가 자연스럽게 어우러지도록 수정했습니다."
L["While editing an override, you can now remove spells from a bar and drag them to reorder in the CDM Bars preview."] = "재정의(Override)를 편집하는 동안 CDM 바 미리보기에서 주문을 제거하거나 드래그하여 순서를 변경할 수 있습니다."
L["Hovering a death with no recap, or another player's row in combat, no longer shows the previous tooltip's target list."] = "전투 요약이 없는 사망 정보나 전투 중 다른 플레이어의 줄에 마우스를 올렸을 때 이전 툴팁의 대상 목록이 잘못 표시되던 문제를 수정했습니다."
L["Global search now finds the selected bar's settings, its blocks' settings included, without opening the Data Bars page first."] = "정보 바 페이지를 먼저 열지 않아도 전체 검색에서 선택된 바 및 블록의 설정을 즉시 검색할 수 있습니다."
L["The settings window now refreshes its pages in place, reusing what it has already built instead of building them again."] = "설정 창에서 페이지를 매번 새로 만들지 않고 기존 요소를 재사용하여 즉시 갱신되도록 성능을 최적화했습니다."
L["Cog popups no longer jump aside or stay open when a settings page redraws, previews keep following your changes after a tab switch, and buttons no longer look dimmer after you hover them."] = "설정 페이지가 다시 그려질 때 톱니바퀴 팝업이 튀거나 열린 채로 남지 않으며, 탭을 전환해도 미리보기가 정상 반영되고 마우스를 올린 버튼이 어두워 보이던 문제를 해결했습니다."
L["Raid Frames, Unit Frames, Nameplates, Resource Bars, Action Bars and Cooldown Manager use less CPU in combat."] = "공격대 프레임, 유닛 프레임, 이름표, 자원 바, 행동 단축바, 재사용 대기시간 관리자의 전투 중 CPU 사용량을 대폭 절감했습니다."
L["Animated glows on buff and debuff icons no longer use CPU while their icon is hidden."] = "강화 효과 및 약화 효과 아이콘이 숨겨져 있는 동안에는 애니메이션 반짝임 효과가 CPU를 소모하지 않도록 최적화했습니다."
L["A popup left open as combat starts no longer causes errors or holds back your key presses, and the Cooldown Manager's Edit Mode reload popup no longer stops later popups closing with Escape or a click outside."] = "전투 시작 시 열려 있던 팝업창으로 인해 오류가 발생하거나 키 입력이 무시되지 않으며, CDM 편집 모드 다시 불러오기 팝업 후 다른 팝업이 ESC나 외부 클릭으로 닫히지 않던 문제를 수정했습니다."
L["Typing /rl, reload buttons and settings that need a reload now reload right away, in combat too, with no extra popup."] = "/rl 입력, 다시 불러오기 버튼 및 재시작이 필요한 설정 변경 시 불필요한 확인 팝업 없이 전투 중에도 즉시 UI를 다시 불러옵니다."
L["The Forever Circle (and Blizzard Style's Circle) now wears the game's new header bar and buttons, with the day/night orb at its new spot, and Blizzard's new event link button stays on the minimap."] = "Forever 원형(및 블리자드 스타일 원형) 미니맵에 게임의 새로운 상단 바와 버튼이 적용되고 낮/밤 구체가 새 위치에 배치되며, 블리자드의 신규 이벤트 링크 버튼이 미니맵에 정상 유지됩니다."
L["Previewing the target and focus cast bars no longer shows an error."] = "대상 및 주시 대상 시전 바를 미리보기할 때 오류가 발생하던 문제를 수정했습니다."
L["Elite and rare badges now show on mobs seen for the first time, without needing a /reload."] = "처음 마주친 몬스터라도 UI 다시 불러오기(/reload) 없이 정예 및 희귀 배지가 즉시 정상 표시됩니다."
L["Blizzard's new arrow under the nameplates of units behind the camera is now hidden on retail too, as it already was on WoW Forever."] = "카메라 뒤편에 위치한 대상의 이름표 아래에 추가된 블리자드 기본 화살표 표시를 WoW Forever에 이어 본섭(리테일)에서도 숨깁니다."
L["The level box and its target border line up with the game's redrawn nameplates again."] = "새롭게 변경된 게임 기본 이름표에 맞춰 레벨 표시 상자와 대상 테두리 위치가 정확히 정렬됩니다."
L["Importing a profile's Edit Mode layout while using the Gamepad interface style keeps that layout's gamepad systems."] = "게임패드 인터페이스 스타일 사용 중 프로필의 편집 모드 레이아웃을 가져올 때 해당 레이아웃의 게임패드 시스템이 정상 유지됩니다."
L["The Shifter now moves the game's Options window too."] = "프레임 이동기(Shifter)를 통해 게임 기본 설정(설정) 창도 자유롭게 이동할 수 있습니다."
L["A hidden talking head no longer reappears later, for example when you leave Edit Mode."] = "숨겨진 말머리 창이 편집 모드를 종료하는 등의 상황에서 다시 화면에 나타나던 문제를 수정했습니다."
L["The Shifter now moves the pet stable and Legacy windows too."] = "프레임 이동기(Shifter)를 통해 야수 우리 및 유산 창도 이동할 수 있습니다."
L["The Full Preview shows the buffs your Buff Manager groups track, at their current size."] = "전체 미리보기에서 강화 효과 관리자 그룹이 추적하는 강화 효과를 실제 설정된 크기 그대로 표시합니다."
L["Under the Party Frames kit, the health and power bar shapes no longer change with the game's new frame art."] = "파티 프레임 키트 사용 시 게임의 새로운 프레임 아트가 적용되어도 생명력 및 자원 바 모양이 변형되지 않습니다."
L["Buff colors on the class resource bar no longer cause errors in raids that stopped the bar from updating (combo points looking like they were not generating)."] = "공격대에서 직업 자원 바의 강화 효과 색상으로 인해 오류가 발생하여 바 갱신이 멈추던(연계 점수가 생성되지 않는 것처럼 보이던) 현상을 수정했습니다."
L["The Call Totem Bar no longer slips back to Blizzard's spot when your bottom action bars re-stack."] = "하단 행동 단축바가 다시 정렬될 때 토템 소환 바가 블리자드 기본 위치로 되돌아가던 문제를 수정했습니다."
L["Settings pages with glow options no longer show an error in the standalone editions."] = "단독 실행(스탠드얼론) 버전에서 반짝임 옵션이 포함된 설정 페이지를 열 때 오류가 발생하던 문제를 수정했습니다."
L["With Show Icon on Portrait, the cast icon no longer covers the portrait's border, inner shadow and outer ring."] = "'초상화에 아이콘 표시' 사용 시 시전 아이콘이 초상화의 테두리, 내부 그림자 및 외부 링을 가리지 않도록 개선했습니다."
L["Under Blizzard Style with the portrait on the right, the Target of Target, Focus Target and pet frames' power bar no longer runs into the portrait ring."] = "초상화가 오른쪽에 위치한 블리자드 스타일에서 대상의 대상, 주시 대상의 대상 및 소환수 프레임의 자원 바가 초상화 링을 침범하지 않습니다."
L["Under the WoW Forever look, the bars, names, type strip, PvP crest and combo points line up with the game's redrawn unit frames again, and every bar fills its track right up to the bronze rim."] = "WoW Forever 테마에서 새롭게 변경된 유닛 프레임에 맞춰 바, 이름, 분류 선, PvP 문장 및 연계 점수가 다시 정확히 정렬되며 모든 바가 청동 테두리까지 빈틈없이 채워집니다."
L["Under Blizzard Style, the health, power and portrait shapes no longer change with the game's new frame art."] = "블리자드 스타일에서 게임의 새로운 프레임 아트가 적용되어도 생명력, 자원 및 초상화 모양이 변형되지 않습니다."
L["With your cast bar hidden for the Gamepad interface style, the game's own gamepad cast bar shows again (the Resource Bars cast bar too)."] = "게임패드 인터페이스 스타일에 맞춰 시전 바를 숨겼을 때 게임 기본 게임패드 시전 바가 다시 정상 표시됩니다 (자원 바 시전 바 포함)."
L["Escape in the Player Aura Bars Edit Filters window now closes that window instead of the whole settings window."] = "플레이어 오라 바 필터 편집 창에서 ESC 키를 누르면 전체 설정 창 대신 해당 필터 편집 창만 닫힙니다."
L["Turning a frame's Raid Marker back on shows the current marker right away, instead of after the next marker change."] = "프레임의 공격대 징표 표시를 다시 켰을 때 다음 징표 변경을 기다리지 않고 현재 징표를 즉시 화면에 표시합니다."
L["Spanish (Spain) translation added, and German, Korean, Brazilian Portuguese and Traditional Chinese translations updated for the latest options."] = "스페인어(스페인) 번역이 추가되었으며 독일어, 한국어, 브라질 포르투갈어 및 번체 중국어 번역이 최신 옵션에 맞추어 업데이트되었습니다."

L["Performance Patch"] = "성능 개선 패치"
L["CPU usage has been reduced across the suite, with the biggest gains in Nameplates, Chat, Action Bars, Resource Bars, Unit Frames, Cooldown Manager, and Spec Changes."] = "전체 모듈의 CPU 사용량이 대폭 감소하였으며, 특히 이름표, 대화창, 행동 단축바, 자원 바, 유닛 프레임, 재사용 대기시간 관리자 및 전문화 변경 시 성능이 눈에 띄게 향상되었습니다."
L["Fixed combat errors from Blizzard's hidden action buttons and the gamepad bars (blocked actions and secret value errors on cooldowns)."] = "블리자드의 숨겨진 액션 버튼 및 게임패드 단축바에서 발생하던 전투 중 오류(작업 차단 및 재사용 대기시간 비밀 값 오류)를 수정했습니다."
L["Fixed a stack overflow error on zone changes in sessions where the interface holds a very large number of frames."] = "프레임 수가 매우 많은 환경에서 지역 이동 시 발생하던 스택 오버플로 오류를 수정했습니다."
L["Shorten Equip Lines in Simplified Stats is now off by default; turn it on in Forever Essentials > General."] = "간소화된 능력치의 '착용 효과 문구 단축'이 기본 비활성화로 변경되었습니다. Forever Essentials > 일반에서 켤 수 있습니다."
L["Simplified Stats lists spell healing before spell damage, matching the item's own Equip line."] = "간소화된 능력치에서 아이템의 실제 착용 효과 순서에 맞춰 주문 치유량을 주문 공격력보다 먼저 표시합니다."
L["Pandemic Glow and Dispel Glow now draw Blizzard's own pandemic border instead of an animated glow. Pandemic Glow is a simple toggle, and the dispellable-buff border is Show Glow in the Enemy Buff Filter's settings."] = "팬데믹(지속시간 갱신) 반짝임 및 해제 반짝임이 애니메이션 발광 대신 블리자드 기본 팬데믹 테두리로 표시됩니다. 팬데믹 반짝임은 단순 켜기/끄기 토글 방식이며, 해제 가능 강화 효과 테두리는 적 강화 효과 필터 설정의 '반짝임 표시'로 설정합니다."
L["New Health # Short text, always one decimal (230.5K)."] = "항상 소수점 한 자리로 표시되는 새로운 생명력 단축 텍스트 '생명력 # 짧게'(예: 230.5K)가 추가되었습니다."
L["Text X/Y offsets reach twice as far, and the mini and boss frames' texts can color their level by difficulty."] = "글자 가로/세로 위치 조정 범위가 기존의 2배로 확장되었으며, 보조 및 우두머리 프레임 글자의 레벨 색상을 난이도에 따라 표시할 수 있습니다."
L["Your debuffs on enemy nameplates glow again while they are in their pandemic window, when a recast keeps the time left. The style, color and settings you had before come back, now with Default, Custom and Class color choices."] = "적 이름표의 약화 효과가 지속시간 손실 없이 재시전 가능한 팬데믹(Pandemic) 갱신 구간에 도달하면 다시 테두리가 반짝입니다. 이전 설정과 함께 기본, 사용자 지정, 직업 색상 선택 옵션이 제공됩니다."
L["Stacking Speed and Top Screen Inset"] = "이름표 겹침 속도 및 상단 여백"
L["Once you have updated to the 12.1.5 client, Nameplate Spacing has two new sliders for settings Blizzard brought back in this patch: how fast stacked nameplates slide into place, and how close nameplates can come to the top of the screen."] = "12.1.5 클라이언트로 업데이트 시 이름표 간격 설정에 블리자드가 복원한 2개의 새로운 슬라이더가 추가됩니다: 겹쳐진 이름표가 정렬되는 속도와 이름표가 화면 상단에 접근할 수 있는 최소 여백을 설정할 수 있습니다."
L["Macro Manager"] = "매크로 관리자"
L["The new Macros tab builds macros by click: commands, spells, targets and conditions line by line, with the live macro text that you can also edit directly. Save each one for your account or character, pick its icon and drag it onto your bars; turn it on at the top of the tab."] = "새로운 매크로 탭을 통해 명령어, 주문, 대상, 조건을 클릭으로 간편하게 작성할 수 있으며 실시간 매크로 문구를 직접 편집할 수도 있습니다. 계정 또는 캐릭터 전용으로 저장하고 아이콘을 선택해 단축바에 드래그하여 배치할 수 있습니다 (탭 상단에서 활성화)."
L["Pet Frame Auras"] = "소환수 프레임 오라"
L["The pet frame can now show its buffs and debuffs, with their own location, size and position, styled like the frame you pick in Copy Auras From."] = "소환수 프레임에 자체적인 위치, 크기 조정과 함께 강화 효과 및 약화 효과를 표시할 수 있으며, '오라 복사 기준'에서 선택한 프레임의 스타일을 그대로 따릅니다."
L["An optional Action Bar 1 setting makes next/previous page skip the pages your other enabled bars use, like Blizzard's paging"] = "행동 단축바 1의 다음/이전 페이지 전환 시, 블리자드 기본 페이징처럼 현재 활성화된 다른 단축바가 사용 중인 페이지 번호를 자동으로 건너뜁니다"
L["Berserker Stance Paging"] = "광폭 태세 페이징"
L["Warriors can now set a bar to page while in Berserker Stance"] = "전사가 광폭 태세 상태일 때 단축바 페이지가 자동으로 전환되도록 설정할 수 있습니다"
L["For Holy Paladins: during Mythic+ boss fights, your tank's raid frame shows a glowing red Beacon while they have your Beacon of Light or Faith"] = "신성 성기사용: 신화+ 우두머리 전투 중 방어 전담이 빛의 봉화 또는 신앙의 봉화를 보유하고 있으면 공격대 프레임에 붉게 빛나는 봉화 아이콘을 표시합니다"
L["An optional reminder when you have no food buff, counting every food including Grilled Squid, Nightfin Soup and the other raid foods"] = "음식 강화 효과가 없을 때 알려주는 알림 옵션으로 오징어 구이, 밤비늘열어 국 및 기타 모든 공격대 음식을 포함합니다"
L["Bind Type Search"] = "귀속 유형 검색"
L["Type BoP, BoE or WuE in the bag or bank search box to show only items with that bind type"] = "가방이나 은행 검색창에 BoP(획귀), BoE(착귀), WuE(장귀)를 입력하여 해당 귀속 유형의 아이템만 표시할 수 있습니다"
L["Hide Pinned Items from Their Categories"] = "고정 아이템 기존 카테고리에서 숨기기"
L["An option in the Pinned Items cog shows pinned items only in Pinned Items, not in their categories or Recent Items"] = "고정된 아이템 톱니바퀴의 옵션을 켜면 고정된 아이템이 원래 카테고리나 최근 획득 아이템 목록에 중복 표시되지 않고 '고정된 아이템'에만 나타납니다"
L["Open with Character Window"] = "캐릭터 창과 함께 가방 열기"
L["An optional setting opens your bags with the character window and closes them when you close it"] = "캐릭터 창을 열 때 가방을 함께 열고, 캐릭터 창을 닫을 때 가방도 함께 닫히도록 하는 옵션입니다"
L["Quick Actions"] = "빠른 작업"
L["An optional Bag Top Bar icon dims every item but those your spells work on, like Disenchant or Pick Lock; click one to cast it, or just Alt-click it"] = "가방 상단 바 아이콘으로 마력 추출, 자물쇠 따기 등 주문을 적용할 수 있는 아이템을 제외한 나머지를 어둡게 표시합니다. 아이템을 클릭하거나 Alt-클릭하여 시전할 수 있습니다"
L["Optional letters on character sheet slots, gear flyout items and socketed gems show each item's secondary stats, largest first"] = "캐릭터 창 장비 슬롯, 장비 교체 목록, 홈에 장착된 보석에 수치가 높은 순서대로 보조 능력치 문자를 표시하는 옵션입니다"
L["Chat Menu Button"] = "대화 메뉴 버튼"
L["An optional sidebar button (off by default) opens Blizzard's chat menu for chat types, emotes and your spoken language"] = "사이드바에 대화 유형, 감정 표현, 구사 언어를 선택할 수 있는 블리자드 대화 메뉴 버튼을 추가합니다 (기본값: 꺼짐)"
L["Empty Slot Talent Conditions"] = "빈 슬롯 특성 조건"
L["Empty slots on cooldown and utility bars can take Talent Conditions, so they only reserve space while the talents you pick are taken or not taken"] = "재사용 대기시간 및 유틸리티 바의 빈 슬롯에 특성 조건을 설정하여, 선택한 특성을 배웠거나 배우지 않았을 때만 공간을 차지하도록 할 수 있습니다"
L["Ignore Resource Cost"] = "자원 소모량 무시"
L["A per-spell option under Cooldown Saturation keeps an icon in full color while you lack the resource to cast it; out of range still tints it red"] = "재사용 대기 채도 설정의 주문별 옵션으로, 기술을 시전할 자원이 부족해도 아이콘을 원래 색상으로 유지합니다 (사거리 밖일 때는 여전히 붉은색 표시)"
L["Glows Combine With Hide Effects"] = "숨김 효과와 반짝임 동시 적용"
L["The Cooldown State glows are now + toggles in each spell's menu, so a glow can combine with Lower Alpha (On CD) or a Hidden effect"] = "재사용 대기 상태 반짝임이 각 주문 메뉴에서 개별 토글로 변경되어, 반짝임 효과를 '재사용 대기 중 투명도 낮춤' 또는 '숨김 효과'와 동시에 조합하여 적용할 수 있습니다"
L["Glow When Usable & Glow When Visible"] = "사용 가능 시 반짝임 & 표시 중 반짝임"
L["Bar Glows can light a button whenever its ability can be pressed, and buff icons can glow while shown, so a Show When Missing buff lights up"] = "바 반짝임을 통해 기술을 누를 수 있을 때마다 단추를 빛나게 할 수 있으며, 강화 효과 아이콘이 표시되는 동안 반짝이게 하여 '누락 시 표시' 강화 효과를 강조할 수 있습니다"
L["An optional window lists your cheapest gray and Junk Marker items by vendor value; Ctrl + Left Click deletes a stack, Middle Click hides an item"] = "상점 판매가가 가장 저렴한 회색 아이템과 잡동사니 지정 아이템을 목록으로 보여주는 창입니다. Ctrl + 좌클릭으로 묶음 삭제, 휠클릭으로 아이템을 숨길 수 있습니다"
L["Simplified Stats"] = "간소화된 능력치"
L["Item tooltips now show Equip: and Set: stats as short lines like +52 Spell Power, with optional stat colors and a merged Spell Power line"] = "아이템 툴팁의 착용 효과: 및 세트: 능력치를 '+52 주문력'처럼 짧은 한 줄로 표시하며, 능력치 색상 옵션 및 주문력 통합 표시를 지원합니다"
L["The world map can show the areas you have not explored yet, tinted in a color you pick so they stand apart"] = "세계 지도에서 아직 탐험하지 않은 미탐험 지역을 선택한 색상으로 음영 처리하여 쉽게 구분할 수 있도록 표시합니다"
L["Choose Which Corners Round"] = "둥글게 만들 모서리 선택"
L["The Corner Radius cog can round only the corners you pick, and a detached power bar or a nameplate's cast bar can round as one shape with its frame"] = "모서리 곡률 톱니바퀴에서 원하는 모서리만 선택하여 둥글게 만들 수 있으며, 분리된 자원 바나 이름표 시전 바를 프레임과 하나의 일체형 모양으로 둥글게 처리할 수 있습니다"
L["Current / Max Text"] = "현재 / 최대 텍스트"
L["Health and power text can show current / maximum values, Classic-style, on unit frames, nameplates and Resource Bars"] = "유닛 프레임, 이름표 및 자원 바에서 생명력과 자원 텍스트를 클래식 스타일의 현재값 / 최대값 형태로 표시할 수 있습니다"
L["EUI Legends Spotlight"] = "EUI 명예의 전당 추천 표시"
L["EUI Legends moved to its own sidebar page below Profiles & Presets, and now spotlights the Seasonal Legend and the All-Time Legend"] = "EUI 명예의 전당이 '프로필 & 프리셋' 아래 전용 사이드바 페이지로 이동하였으며, 이번 시즌 명예의 전당 및 역대 명예의 전당 헌액자를 조명합니다"
L["Module Resets in Global Settings"] = "전체 설정 내 모듈 초기화"
L["The Reset buttons on module pages moved to Global Settings: Reset EUI Module Settings resets one module, or ALL of EUI, after you type Confirm"] = "각 모듈 페이지의 초기화 버튼이 전체 설정으로 통합되었습니다: '확인'을 입력한 후 단일 모듈 또는 EUI 전체 설정을 초기화할 수 있습니다"
L["Border Styles"] = "테두리 스타일"
L["On the WoW Forever look, Chat and Damage Meters can pick Slim, Slim Textured or Heavy Bronze borders, and the Minimap is now a bronze Forever Square"] = "WoW Forever 테마에서 대화창과 데미지 미터기에 얇은 청동, 얇은 질감 청동, 굵은 청동 테두리를 선택할 수 있으며, 미니맵은 청동 Forever 사각형으로 표시됩니다"
L["Blizzard Style Square"] = "블리자드 스타일 사각 미니맵"
L["Blizzard Style's minimap is now a thin bronze square with the zone name in its title bar; its Circle matches WoW Forever's round one"] = "블리자드 스타일 미니맵이 제목 표시줄에 지역 이름이 표시되는 얇은 청동 사각형으로 바뀌며, 원형 선택 시 WoW Forever의 둥근 미니맵과 일치합니다"
L["Always Threat Colors"] = "항상 위협 수준 색상 표시"
L["Show Threat Colors adds Always, which shows them even when you play solo with no pet out; the old Always is now called Group or Pet"] = "위협 색상 표시에 '항상' 옵션이 추가되어 소환수 없이 솔로 플레이할 때도 위협 색상이 표시됩니다 (기존의 '항상'은 이제 '파티 또는 소환수'로 명칭 변경)"
L["Aura Tooltips"] = "오라 툴팁"
L["An optional Show Buff / Debuff Tooltips setting shows a spell's tooltip when you hover its icon on a nameplate"] = "이름표의 강화/약화 효과 아이콘에 마우스를 올렸을 때 해당 주문의 툴팁을 표시하는 옵션입니다"
L["The optional /way command (also /euiway) turns coordinates, zone names or map IDs into map pin links and announces when you reach a pin"] = "좌표, 지역 이름, 지도 ID를 지도 핀 링크로 변환하고 핀에 도착했을 때 알림을 제공하는 /way (또는 /euiway) 명령어 옵션입니다"
L["Potion Ready and Unspent Talents Alerts"] = "물약 준비 및 미사용 특성 알림"
L["Quality of Life's new ALERTS section adds a Potion Ready alert and an Unspent Talents alert beside the Combat Alert, all on one movable anchor"] = "편의 기능(QoL)의 새로운 '알림' 섹션에 전투 알림과 함께 물약 준비 알림 및 미사용 특성 알림이 추가되었으며, 하나의 이동식 고정 위치에서 함께 관리됩니다"
L["With a Pixels border, Compact Mode joins your party or raid frames into one bordered block, and Grid Mode joins the raid groups into one grid"] = "픽셀 테두리 사용 시 압축 모드로 파티 및 공격대 프레임을 하나의 테두리 블록으로 합치고, 격자 모드로 공격대 그룹을 단일 격자로 정돈합니다"
L["Show Tank, Healer or DPS as colored text instead of the role icon, with a color for each role"] = "역할 아이콘 대신 방어 전담, 치유 전담, 공격 전담을 각 역할별 색상이 적용된 텍스트로 표시합니다"
L["Matching Power and Name Bar Dividers"] = "자원 및 이름 바 구분선 통일"
L["With the Pixels border styles, the power bar's Divider or Border can match the frame border, and the Top Name Bar can show a matching divider"] = "픽셀 테두리 스타일 사용 시 자원 바의 구분선 또는 테두리를 프레임 테두리와 일치시키고, 상단 이름 바에도 통일된 구분선을 표시할 수 있습니다"
L["Pet Growth Direction"] = "소환수 프레임 확장 방향"
L["Pet frames set to Free Move can now grow down, up, right or left, instead of always following your party or raid frames"] = "자유 이동으로 설정된 소환수 프레임이 파티/공격대 프레임 방향을 강제로 따르지 않고 아래, 위, 오른쪽, 왼쪽 중 원하는 방향으로 확장될 수 있습니다"
L["Blessing Priority Lists"] = "축복 우선순위 목록"
L["The Tank, Healer and DPS blessings in Missing Buffs are drag-to-order priority lists, with per-class exceptions for members who need a different one"] = "누락된 강화 효과의 방어, 치유, 공격 전담 축복을 드래그하여 우선순위를 지정할 수 있으며, 다른 축복이 필요한 파티원을 위한 직업별 예외 설정도 지원합니다"
L["Per-Spec Hash Lines"] = "전문화별 기준선"
L["The Health and Power bars can show their own hash lines for each spec or talent, set in their new Threshold & Hash Lines editor"] = "생명력 및 자원 바에 새로운 '임계값 및 기준선' 편집기에서 전문화 또는 특성별로 고유한 기준선을 설정하여 표시할 수 있습니다"
L["The player cast bar can show the rank of the spell you are casting, such as Frostbolt (Rank 4)"] = "플레이어 시전 바에 '얼음 화살 (4등급)'처럼 현재 시전 중인 주문의 등급을 표시할 수 있습니다"
L["With the Important or Own debuff filter, important debuffs from others get their own limit under Max Count"] = "'중요' 또는 '자신의 약화 효과' 필터 사용 시 타인이 건 중요 약화 효과에 대해 '최대 개수' 내에서 별도의 한도를 적용할 수 있습니다"
L["With Always Show Buttons off, the pet bar now shows up when you summon your pet in combat instead of staying hidden until combat ends."] = "'버튼 항상 표시'가 꺼져 있을 때, 전투 중 소환수를 소환해도 전투가 끝날 때까지 숨겨져 있지 않고 소환수 바가 즉시 정상 표시됩니다."
L["The pet bar's Attack button now stops flashing once your pet stops attacking, as it does on Blizzard's bar, instead of flashing on after combat."] = "소환수가 공격을 멈추면 블리자드 기본 단축바처럼 소환수 바의 공격 버튼 깜빡임이 즉시 멈추도록 수정했습니다."
L["The vehicle exit button now stays where you place it in Edit Mode instead of moving back to the main action bar after a reload."] = "탈것/차량 내리기 버튼이 UI를 다시 불러온 후 기본 단축바로 되돌아가지 않고 편집 모드에서 배치한 위치를 정확히 유지합니다."
L["Fixed a niche issue where the Extra Action Button could disappear until the end of a fight when Blizzard rearranged its bottom-of-screen frames mid-combat; it now stays usable at Blizzard's spot until combat ends."] = "전투 중 블리자드가 화면 하단 프레임을 재배치할 때 특수 능력 버튼(Extra Action Button)이 사라지던 문제를 수정하여 전투 종료 시까지 정상적으로 사용할 수 있도록 했습니다."
L["Unlock Mode no longer shows a mover for the Extra Action Button while its visibility is set to Never, like the other bars."] = "다른 단축바와 마찬가지로 특수 능력 버튼의 표시 설정이 '표시 안 함'일 때는 잠금 해제 모드에서 이동기를 표시하지 않습니다."
L["With the Gamepad interface style, the action bar extras for the spellbook, the macro window, Quick Keybind, the spell flyout and bar paging now step aside to avoid blocked-action errors."] = "게임패드 인터페이스 스타일 사용 시 마법책, 매크로 창, 빠른 단축키 지정, 주문 플라이아웃 및 바 페이징 단축바 부가 기능이 작업 차단 오류를 방지하도록 비활성화됩니다."
L["Under Blizzard Style, the micro menu and bag bar no longer sit inside WoW Forever's bronze frame, matching the rest of the look."] = "블리자드 스타일 사용 시 게임 메뉴와 가방 바가 WoW Forever 청동 프레임 안에 배치되지 않고 전체 테마 스타일에 알맞게 일치됩니다."
L["The AuraBuff Reminders settings now say up front that the module is for out-of-combat buff and consumable reminders, and link to the Cooldown Manager's Buffs bar for in-combat and rotational auras."] = "AuraBuff Reminders 설정에 이 모듈이 전투 외 강화 효과 및 소모품 알림 전용임을 명시하고, 전투 중 및 딜사이클 오라는 재사용 대기시간 관리자의 강화 효과 바로 연결되도록 링크를 추가했습니다."
L["The gold tooltips of the bag window and the Data Bars Gold block now read one shared list of your characters' gold, so their amounts and totals match."] = "가방 창의 골드 툴팁과 정보 바의 골드 블록이 캐릭터 골드 공유 목록을 함께 참조하여 보유량과 합계가 정확히 일치합니다."
L["Gold Tracking and History is now one account-wide switch, also on the Data Bars Gold block, and Data Bars no longer records your characters' gold while it is off."] = "골드 추적 및 내역이 정보 바 골드 블록을 포함한 전체 계정 통합 단일 스위치로 변경되었으며, 꺼져 있을 때는 골드 내역을 기록하지 않습니다."
L["A tooltip whose fixed position is linked to a screen edge in Unlock Mode no longer jumps up and back while you hover unit frames or action buttons."] = "잠금 해제 모드에서 화면 가장자리에 고정된 툴팁이 유닛 프레임이나 단축 버튼 위에 마우스를 올릴 때 위아래로 튀던 현상을 수정했습니다."
L["Chat bubbles from speakers who start off screen are now styled once they come into view, and a styled bubble stays styled when you turn away and back."] = "화면 밖에서 시작된 말풍선이 화면 안으로 들어왔을 때 스타일이 정상 적용되며, 시야를 돌렸다가 다시 봐도 스타일이 유지됩니다."
L["The loot roll timer bar is no longer hidden behind the skinned loot roll window."] = "전리품 주사위 굴림 타이머 바가 스킨이 적용된 주사위 창 뒤에 가려지던 문제를 수정했습니다."
L["The merchant quantity box now fits both lines for items sold in bundles, centers a single count, and keeps its look when you shift-click another item while it is open."] = "상점 수량 입력창이 묶음 판매 아이템의 두 줄 문구를 알맞게 표시하고 단일 수량을 중앙 정렬하며, 열린 상태에서 다른 아이템을 Shift-클릭해도 디자인이 유지됩니다."
L["The inspect window's item text toggle now only shows on the Character tab."] = "살펴보기 창의 아이템 텍스트 표시 토글이 '캐릭터' 탭에서만 표시되도록 수정했습니다."
L["The character sheet's Equipment tab now matches the other tabs: its buttons and scroll bar are skinned instead of Blizzard's red buttons, and the buttons and gear set list fill the full column width."] = "캐릭터 창의 장비 관리 탭이 다른 탭들과 통일되었습니다: 블리자드 붉은색 버튼 대신 스킨이 적용된 버튼과 스크롤바가 적용되며 열 전체 너비를 채웁니다."
L["The character sheet's gear flyout now matches the skinned sheet instead of showing Blizzard's parchment and round icon borders."] = "캐릭터 창의 장비 교체 목록이 블리자드 양피지와 둥근 테두리 대신 통일된 스킨 디자인으로 깔끔하게 표시됩니다."
L["The character sheet and inspect window now show an upgraded or catalyzed item's real item level instead of its base level."] = "캐릭터 창 및 살펴보기 창에서 강화 또는 촉매 변환된 장비의 기본 아이템 레벨 대신 실제 아이템 레벨을 정확히 표시합니다."
L["Character sheet and inspect window item labels read before an item's data has loaded now fill in once it arrives instead of staying blank or showing a missing enchant."] = "아이템 정보를 불러오기 전에 캐릭터 창과 살펴보기 창을 열었을 때 공백으로 남거나 마법부여 누락으로 뜨지 않고 데이터 수신 즉시 정확하게 갱신됩니다."
L["A slot emptied while the character sheet was closed no longer keeps the removed item's labels after you change a sheet setting."] = "캐릭터 창이 닫힌 상태에서 장비를 벗었을 때, 창 설정을 변경한 후에도 벗은 아이템의 정보 텍스트가 남아 있던 문제를 수정했습니다."
L["The character sheet's item level, upgrade track and enchant text, and the inspect window's enchant names, now follow Disable Slug Outline."] = "캐릭터 창의 아이템 레벨, 강화 단계 및 마법부여 글자와 살펴보기 창의 마법부여 이름이 'Slug 외곽선 끄기' 설정을 정확히 따릅니다."
L["The character sheet no longer shows a gray bar across the top of the character model after the latest game update."] = "최신 게임 업데이트 이후 캐릭터 창의 캐릭터 모델 상단에 회색 바가 나타나던 현상을 수정했습니다."
L["The inspect window's new PvP tab no longer opens blank, and the item level and slot labels stay on the character tab instead of floating over the PvP and Guild tabs."] = "살펴보기 창의 새로운 PvP 탭이 빈 상태로 열리지 않으며, 아이템 레벨과 슬롯 정보가 PvP 및 길드 탭 위에 겹쳐 떠 있지 않고 캐릭터 탭에만 유지됩니다."
L["The Looking For Group window's new Voice Chat dropdown is now skinned."] = "파티 찾기 창의 신규 음성 대화 드롭다운에 스킨이 정상 적용됩니다."
L["Up and Down now also recall the addon slash commands you typed, like /eui, not only messages."] = "대화 입력창에서 위/아래 방향키를 누를 때 일반 메시지뿐만 아니라 /eui 등 입력했던 애드온 슬래시 명령어도 불러올 수 있습니다."
L["Tracking Bars now show a tracked buff or target debuff the moment it starts, even from a proc or in Mythic+, instead of waiting for your next cast."] = "추적 바가 다음 기술 시전을 기다리지 않고 발동 효과나 신화+ 등에서 추적 중인 강화 효과/약화 효과가 활성화되는 즉시 화면에 표시합니다."
L["Hidden (Outside Form/Stance) now hides Druid caster spells such as Moonfire, Rebirth and the Restoration heals in forms they cannot be cast in, unless a talent or proc allows it."] = "'숨김 (변신/태세 외)'이 특성이나 발동 효과로 허용되지 않는 한, 해당 변신 상태에서 시전할 수 없는 드루이드 주문(달빛섬광, 환생, 회복 치유 주문 등)을 정상적으로 숨깁니다."
L["Spells set to Hidden (CD Ready) no longer flash onto the bar for a moment as a global cooldown ends."] = "'숨김 (재사용 대기 완료)'으로 설정된 주문이 전역 재사용 대기시간(GCD)이 끝날 때 단축바에 순간적으로 깜빡이며 나타나던 문제를 수정했습니다."
L["Group loot rolls no longer get pushed off screen or to random heights; they now sit clear of your action bars, Cooldown Manager bars and Tracking Bars."] = "파티 전리품 주사위 창이 화면 밖이나 엉뚱한 높이로 밀려나지 않고 행동 단축바, 재사용 대기시간 관리자 바, 추적 바와 겹치지 않게 정렬됩니다."
L["The talking head, the encounter bar and Blizzard's other frames stacked above your action bars no longer get pushed up or off screen while tracked buffs are showing."] = "추적 중인 강화 효과가 표시되는 동안 단축바 위에 위치한 말머리, 우두머리 전투 바 등의 블리자드 기본 프레임이 위로 밀려나거나 화면 밖으로 벗어나지 않습니다."
L["Saving Edit Mode with an Essential or Utility viewer snapped to another frame no longer anchors that viewer to an EllesmereUI bar in the saved layout."] = "핵심 또는 유틸리티 뷰어를 다른 프레임에 스냅한 상태로 편집 모드를 저장할 때, 저장된 레이아웃에서 해당 뷰어가 EllesmereUI 바에 잘못 고정되던 문제를 수정했습니다."
L["With a Pixels or Pixels Textured border, the cooldown swipe now stays under the border line, so its rounded corners and bottom edge no longer disappear while a cooldown runs."] = "픽셀 또는 픽셀 질감 테두리 사용 시 재사용 대기 스와이프 애니메이션이 테두리 선 아래에 유지되어, 쿨다운 작동 중 둥근 모서리와 하단 가장자리가 사라지지 않습니다."
L["Bar Glows now stay with the ability they were set on, so a stance or form swap no longer moves a glow onto a different ability."] = "바 반짝임이 설정된 원래 기술에 정확히 고정되어, 태세나 변신을 변경해도 다른 기술로 반짝임이 잘못 옮겨가지 않습니다."
L["Picking Lower Alpha (On CD) with Apply to This Spell now asks for its opacity, as clicking it does, instead of setting 50%."] = "'이 주문에 적용'으로 '투명도 낮춤 (재사용 대기 중)'을 선택할 때 임의로 50%가 지정되지 않고 직접 투명도를 입력할 수 있도록 팝업이 뜹니다."
L["Lifebloom's pandemic glow on Tracking Bars now starts exactly when a refresh would keep its remaining time, talents that lengthen that window included, instead of always at 30% of its duration."] = "추적 바에서 피어나는 생명의 팬데믹(지속시간 갱신) 반짝임이 고정 30%가 아니라 지속시간을 연장하는 특성을 포함하여 갱신 시 잔여 시간이 손실되지 않는 정확한 타이밍에 시작됩니다."
L["Hovering an icon in the bar preview now shows its spell name and that clicking it opens its alert settings."] = "바 미리보기의 아이콘에 마우스를 올리면 주문 이름과 함께 클릭하여 알림 설정을 열 수 있다는 안내를 표시합니다."
L["The Racial slot now tracks the right racial for Humans, Night Elves, Trolls and Skyborne."] = "종족 특성 슬롯이 인간, 나이트 엘프, 트롤 및 스카이본의 올바른 종족 특성을 정확히 추적합니다."
L["Force English Units now follows the profile you switch to instead of keeping the previous profile's setting."] = "'영문 단위 강제' 설정이 이전 프로필의 값을 유지하지 않고 새로 전환한 프로필의 설정을 정확히 따릅니다."
L["Blocks on a bar made from a starter template, and blocks you add, now show at their real widths in the preview strip right away."] = "시작 템플릿으로 생성된 바의 블록 및 새로 추가한 블록이 미리보기 바에서 즉시 실제 너비로 표시됩니다."
L["The threat meter's Not While Tanking now ignores Bear Form and Defensive Stance while someone in your group has the tank role."] = "파티에 방어 전담 역할을 가진 파티원이 있을 때 위협 수준 미터기의 '탱킹 중 제외'가 곰 변신 및 방어 태세를 탱커로 오인하지 않고 정상 제외합니다."
L["Reduced memory use across the whole EllesmereUI suite."] = "EllesmereUI 전체 모듈의 메모리 사용량을 대폭 최적화했습니다."
L["Odd sizes of the Pixels and Pixels Textured borders no longer sit further out than the next even size."] = "픽셀 및 픽셀 질감 테두리의 홀수 크기가 다음 짝수 크기보다 바깥쪽으로 벗어나 표시되던 문제를 수정했습니다."
L["Turning off Hide Blizzard Party Panel during combat now brings the panel back once combat ends, and turning it off no longer shows an empty panel tab while you are solo."] = "전투 중 '블리자드 파티 패널 숨기기'를 끄면 전투 종료 시 패널이 복원되며, 솔로 플레이 시 빈 패널 탭이 나타나지 않습니다."
L["The Cooldown Manager, Action Bars, Raid Frames and Unit Frames no longer interfere with Edit Mode's own updates, which could cause blocked-action errors or unsnap frames you had snapped to Blizzard's party, raid or boss frames."] = "재사용 대기시간 관리자, 행동 단축바, 공격대 및 유닛 프레임이 편집 모드의 자체 업데이트와 충돌하여 작업 차단 오류를 일으키거나 블리자드 프레임에 스냅된 배치가 풀리던 문제를 해결했습니다."
L["Macro Factory buttons now update the moment a macro is created or deleted, and changes made to spec macros during combat (such as Show Tooltip) are applied when combat ends."] = "매크로 제작소 단추가 매크로 생성/삭제 즉시 갱신되며, 전투 중 변경된 전문화 매크로 설정(툴팁 표시 등)은 전투 종료 시 안전하게 적용됩니다."
L["A confirmation popup that is open when the accent color changes, such as on an automatic spec profile switch, now stays open in the new color instead of closing."] = "자동 전문화 프로필 전환 등으로 강조 색상이 변경될 때 열려 있던 확인 팝업창이 닫히지 않고 새 색상으로 유지됩니다."
L["Full-account profile exports no longer include your characters' gold balances."] = "전체 계정 프로필 내보내기 시 캐릭터의 골드 보유량이 내보내기 데이터에 포함되지 않습니다."
L["Greyed-out buttons in the settings, such as Apply Template on the Glows page, now explain on hover why they are unavailable."] = "반짝임 페이지의 '템플릿 적용' 등 설정 창의 비활성화된 버튼에 마우스를 올리면 사용할 수 없는 이유가 툴팁으로 설명됩니다."
L["The icons beside Unlock Mode, Global Settings, Patch Notes and Profiles & Presets in the options sidebar are no longer slightly squashed."] = "설정 사이드바의 잠금 해제 모드, 전체 설정, 패치 노트, 프로필 & 프리셋 옆의 아이콘이 찌그러져 보이던 현상을 개선했습니다."
L["The donor named at the top right of the options window is now most often the Seasonal or All-Time Legend, then their #2 and #3, then the rest of the all-time donors."] = "설정 창 우측 상단에 표시되는 후원자 이름이 시즌/역대 명예의 전당 헌액자, 2~3위 후원자, 기타 역대 후원자 순서로 균형 있게 표시됩니다."
L["Global search now finds the settings on almost every options page without opening that page first."] = "전체 검색 기능이 해당 옵션 페이지를 미리 열어보지 않아도 거의 모든 페이지의 설정 항목을 즉시 찾아냅니다."
L["Settings links, such as global search results, now highlight the exact setting instead of an earlier one whose name contains it."] = "전체 검색 결과 등 설정 바로가기 링크를 클릭했을 때 이름이 일부 겹치는 다른 설정 대신 정확한 설정 항목을 강조 표시합니다."
L["Patch Notes cards for a module you have turned off are no longer clickable, so they no longer show a Lua error or jump the page back to the top."] = "비활성화한 모듈의 패치 노트 카드는 클릭되지 않도록 변경하여, Lua 오류가 발생하거나 페이지가 맨 위로 튀는 현상을 방지했습니다."
L["A settings page that was reset while the settings window was closed (for example by a profile change) now rebuilds when the window opens instead of showing an empty page."] = "설정 창이 닫힌 상태에서 프로필 변경 등으로 설정이 초기화되었을 때 창을 열면 빈 페이지가 뜨지 않고 정상적으로 다시 빌드됩니다."
L["Changing the Window Scale right after a settings page rebuilt itself now re-aligns that page's borders correctly."] = "설정 페이지가 다시 빌드된 직후 창 크기 비율을 변경해도 해당 페이지의 테두리가 올바르게 정렬됩니다."
L["Opening an add-on page that has no tabs no longer breaks the other settings pages, which could then show outside or on top of the settings window."] = "탭이 없는 애드온 설정 페이지를 열었을 때 다른 설정 페이지가 설정 창 바깥으로 삐져나오거나 겹쳐 깨지던 문제를 수정했습니다."
L["A settings page that runs into an error while building no longer leaves the settings window in a broken state until a reload."] = "설정 페이지 빌드 중 오류가 발생해도 UI를 다시 불러오기 전까지 전체 설정 창이 망가진 상태로 방치되지 않도록 안전장치를 추가했습니다."
L["A setting that makes its own page rebuild while that page is still building no longer leaves a half-built copy of the page on screen."] = "페이지 빌드 중 다시 빌드를 트리거하는 옵션으로 인해 화면에 반쯤 생성된 페이지 잔상이 남던 문제를 수정했습니다."
L["A settings page that rebuilds while one of its sliders is being dragged no longer leaves slider tooltips, Shift + mouse wheel window scaling and some live preview updates switched off until a reload."] = "슬라이더를 드래그하는 도중 페이지가 다시 빌드되어 슬라이더 툴팁, Shift+마우스 휠 창 크기 조절 등이 먹통이 되던 문제를 수정했습니다."
L["Consumable reminders, the character sheet's item details and Great Vault item levels keep working now that Blizzard has removed its old item functions."] = "블리자드가 기존 구형 아이템 API를 제거한 12.1.5 패치 이후에도 소모품 알림, 캐릭터 창 아이템 세부 정보, 위대한 금고 아이템 레벨이 정상 작동하도록 업데이트했습니다."
L["Buff and debuff rows you have turned off on unit frames, raid frames, nameplates and Player Aura Bars no longer do any work when auras change."] = "유닛 프레임, 공격대 프레임, 이름표 및 플레이어 오라 바에서 꺼둔 강화 효과/약화 효과 줄이 오라 변경 시 불필요한 백그라운드 연산을 하지 않도록 최적화했습니다."
L["On the WoW Forever look, Chat, Damage Meters and the threat meter draw Blizzard's latest weathered bronze line cleanly (Slim Textured), and the older flat line is the Slim border style."] = "WoW Forever 테마에서 대화창, 데미지 미터기 및 위협 수준 미터기가 블리자드의 세련된 질감 청동 선(얇은 질감)을 깔끔하게 그리며, 기존 단색 선은 '얇은 테두리' 스타일로 유지됩니다."
L["The WoW Forever look's slim bronze borders on Chat, Damage Meters, the threat meter and the XP bar now have clean angled corners that match the action bars."] = "WoW Forever 테마의 대화창, 데미지 미터기, 위협 미터기 및 경험치 바의 얇은 청동 테두리가 단축바와 어울리도록 깔끔한 사선 각진 모서리로 다듬어졌습니다."
L["Cast bars now find every class's interrupt in all its ranks, so the interrupt-ready color and kick tick work for Shamans, Druids and Warriors, with Shield Bash, Pummel and Feral Charge following your stance or form."] = "시전 바가 모든 직업 및 등급의 차단기를 완벽 인식하여, 주술사, 드루이드, 전사에게도 차단 준비 색상과 틱 표시가 지원되며 방패 가격, 자루 공격, 야성의 돌진이 태세/변신에 맞게 작동합니다."
L["The Threat % text on unit frames and nameplates can now be moved up to 300 in any direction with its X and Y Offset sliders, up from 100."] = "유닛 프레임 및 이름표의 위협 수준 % 텍스트 위치 슬라이더 조정 범위가 기존 100에서 최대 300으로 확장되었습니다."
L["Blizzard's Toggle Minimap key now keeps the map hidden until you press it again, instead of the map coming back when you change targets, leave combat, switch profiles or toggle the damage meters."] = "블리자드의 미니맵 토글 단축키를 눌렀을 때 대상 변경, 전투 종료, 프로필 전환 등으로 미니맵이 다시 나타나지 않고 단축키를 다시 누를 때까지 숨김 상태가 유지됩니다."
L["Objective split times and their comparisons now survive leaving and re-entering the dungeon during a key, a reload no longer changes their comparisons, and split times from an abandoned or crashed key no longer carry over into your next key."] = "쐐기돌 진행 중 던전을 나갔다 재입장해도 목표 구간별 기록과 비교 수치가 유지되며, 포기하거나 튕긴 쐐기돌의 기록이 다음 쐐기돌로 넘어가지 않습니다."
L["A finished key's timer color now matches its result, also for keys finished close to the limit or after a reload."] = "완료된 쐐기돌 타이머 색상이 실제 클리어 결과(단수)와 정확히 일치하도록 수정되었습니다."
L["Enemy players in battlegrounds and arenas now show their class color on the health bar even with Blizzard's enemy nameplate class colors turned off, as they do in the open world."] = "전장 및 투기장에서 블리자드 적 이름표 직업 색상이 꺼져 있어도 야외 필드처럼 생명력 바에 직업 색상이 정상 표시됩니다."
L["Pixels and Pixels Textured custom borders no longer flicker a thin gap against the health bar while the plate moves."] = "이름표가 이동할 때 생명력 바와 테두리 사이에 미세한 틈이 깜빡이던 현상을 수정했습니다."
L["Objective gauges above friendly NPCs now show while Show Friendly NPC Nameplates is on."] = "'우호적 NPC 이름표 표시'가 켜져 있을 때 NPC 상단의 퀘스트 목표 게이지가 정상 표시됩니다."
L["After a duel, your opponent's name shows again right away instead of only once you look away and back."] = "결투 종료 후 다른 곳을 보지 않아도 상대방의 이름이 즉시 다시 표시됩니다."
L["The Elite/Rare Indicator in Core Positions now also works on the WoW Forever look, where it starts unchecked."] = "기본 위치 설정의 정예/희귀 표시 기능이 WoW Forever 스타일에서도 정상 작동합니다 (기본값: 꺼짐)."
L["At a Window Scale other than 100%, the Grow, Strata and other dropdowns in the Display page cogs now open at the right size the first time too."] = "창 크기 비율이 100%가 아닐 때도 표시 페이지 설정의 확장 방향, 프레임 레이어 등 드롭다운이 처음부터 올바른 크기로 열립니다."
L["The nameplate preview no longer stretches or pushes the class resource out of view at a large Class Resource Y Offset; it shows the offset as a small number instead."] = "이름표 미리보기에서 직업 자원 세로 위치를 크게 조정해도 자원이 늘어나거나 시야 밖으로 밀리지 않고 위치 수치를 작은 숫자로 표시합니다."
L["Threat colors now also show for damage dealers and healers playing solo with a pet out, so you can see which mobs your pet is holding."] = "딜러나 힐러가 소환수를 꺼내고 솔로 플레이할 때도 위협 색상이 표시되어 소환수가 어떤 몬스터의 어그로를 잡고 있는지 확인할 수 있습니다."
L["Threat colors now treat you as the tank in Bear Form, Dire Bear Form, Defensive Stance or with Righteous Fury up while nobody in your group has the tank role, so tanks see tank colors solo too."] = "파티에 방어 전담이 없거나 솔로 플레이 중일 때 곰 변신, 광포한 곰 변신, 방어 태세, 정의의 격노 상태라면 플레이어를 방어 전담으로 인식하여 위협 색상을 표시합니다."
L["The Upgrade Calculator now keeps your +80 / -80 crest adjustments after a reload, and Update at Upgrader clears them."] = "강화 계산기의 +80 / -80 문장 조정값이 UI를 다시 불러온 후에도 유지되며, 강화 NPC 확인 시 초기화됩니다."
L["Moving the loot windows (Group Loot, Bonus Roll, Alert Toasts) no longer risks blocked-action errors when rolls appear, and turning a mover off or resetting it puts its window back right away."] = "전리품 획득 창 이동 기능 사용 시 주사위 굴림 창이 뜰 때 발생하던 작업 차단 오류를 방지하고 이동기 끄기 또는 초기화 시 즉시 원래 위치로 복귀합니다."
L["Turning off Move Top Bar Event Text in Unlock Mode, or resetting its mover, now puts the text back in its usual spot right away instead of after a reload."] = "잠금 해제 모드에서 상단 바 이벤트 텍스트 이동을 끄거나 초기화할 때 다시 불러올 필요 없이 즉시 원래 위치로 복귀합니다."
L["Switching profiles now updates the Battle Res and Bloodlust icons right away (synced profiles keep their own icon positions), and resetting Quality of Life now also resets them, the /keys popup and the LFG Reminder."] = "프로필 전환 시 전투 부활 및 피의 욕망 아이콘이 즉시 갱신되며, 편의 기능(QoL) 초기화 시 해당 아이콘들과 /keys 팝업, 파티 찾기 알림도 함께 초기화됩니다."
L["Hide Error Messages now lets every error on its keep list show (being dead, a dead pet, dungeon kick votes and pickpocketing), and turning it off now applies after a reload."] = "오류 메시지 숨기기 사용 시에도 유지 목록의 중요 오류(사망, 소환수 사망, 던전 추방 투표, 훔치기)는 정상 표시되며, 옵션 끄기는 UI를 다시 불러온 후 적용됩니다."
L["The Shifter now moves the new friends window and the Looking For Group window."] = "Shifter 이동 기능이 새로운 친구 목록 창과 파티 찾기 창도 정상적으로 이동시킵니다."
L["A tracker hidden by the Mythic+ timer no longer keeps processing quest updates in the background, and Auto Accept / Auto Turn In Quests keep working while the tracker is hidden in raids and arenas."] = "신화+ 타이머로 인해 추적기가 숨겨졌을 때 백그라운드 퀘스트 처리를 중단하여 성능을 높이고, 레이드 및 투기장에서 추적기가 숨겨져 있어도 퀘스트 자동 수락/완료 기능은 정상 작동합니다."
L["Action menus no longer come back empty after a reload when the Quickdraw settings page was opened before visiting another settings page, and the error this could show is gone."] = "Quickdraw 설정 페이지를 열람한 후 UI를 다시 불러왔을 때 액션 메뉴가 빈 상태로 표시되거나 오류가 발생하던 문제를 수정했습니다."
L["The Buff Manager's Defensives filter now includes Primordial Bond for Shamans."] = "강화 효과 관리자의 생존기 필터에 주술사의 태고의 유대가 포함됩니다."
L["Buff Manager indicators now follow a conditional or spec override's size and layout when it swaps in, instead of keeping the old size or drawing off their corner."] = "강화 효과 관리자 표시기가 조건부/전문화 오버라이드 전환 시 이전 크기를 유지하거나 위치를 벗어나지 않고 변경된 크기와 레이아웃을 정확히 따릅니다."
L["Healer Mana now shows the new group once combat ends when someone joins or leaves mid-fight while the raid and party frames are hidden, instead of keeping the old one."] = "공격대/파티 프레임이 숨겨진 상태에서 전투 중 파티원이 나가거나 들어왔을 때, 전투가 종료되면 힐러 마나 표시가 새로운 파티 구성으로 즉시 갱신됩니다."
L["After using the options search, changes on the raid frames page no longer land in the party frames' settings."] = "옵션 검색 후 공격대 프레임 페이지에서 설정을 변경했을 때 파티 프레임 설정에 적용되던 문제를 수정했습니다."
L["Changing the absorb style, color or opacity with rounded corners no longer causes a Lua error."] = "모서리 둥글게 설정이 켜진 상태에서 흡수 보호막 스타일, 색상 또는 불투명도를 변경할 때 발생하던 Lua 오류를 수정했습니다."
L["Role icons set to Show Behind Border now draw under textured frame borders too."] = "'테두리 뒤에 표시'로 설정된 역할 아이콘이 텍스처 프레임 테두리 아래에도 정상적으로 그려집니다."
L["Frame Spacing and Group Spacing, and the party Frame Spacing, now go below -1 at every UI scale, so frames with 2 px borders can share one border line."] = "모든 UI 비율에서 프레임 및 그룹 간격을 -1 미만으로 설정할 수 있어 2px 테두리 프레임이 하나의 테두리 선을 공유할 수 있습니다."
L["The Click Casting icon grids no longer leave stray or stacked divider lines after switching between Spells, Macros and Items, and Quickbind's divider lines no longer get brighter with every binding."] = "클릭 시전 창에서 주문, 매크로, 아이템 전환 시 구분선이 겹치거나 잔상이 남던 문제를 수정했습니다."
L["The eye icon tip on the Frames page no longer stacks a new copy every time the page refreshes, so a single Okay dismisses it and no leftover copy stays on screen over other pages."] = "프레임 페이지의 눈 아이콘 팁이 새로고침 시 중복 생성되지 않고 한 번의 확인으로 깔끔하게 닫힙니다."
L["Group members whose role the game keeps hidden from addons no longer risk Lua errors."] = "게임 시스템이 애드온에 역할을 숨긴 파티원이 있을 때 발생하던 Lua 오류 위험을 제거했습니다."
L["Role icons now show for group members whose role the game keeps hidden from addons."] = "게임 시스템이 애드온에 역할을 숨긴 파티원에게도 역할 아이콘이 정상 표시됩니다."
L["Missing Buffs no longer reminds you to bless a member who already carries one of your blessings, since a paladin keeps only one blessing on each target."] = "성기사는 대상당 하나의 축복만 유지할 수 있으므로, 이미 축복을 받고 있는 파티원에게는 누락된 강화 효과 알림이 중복 표시되지 않습니다."
L["Group members with no assigned role now follow your DPS blessing list in Missing Buffs instead of always showing Kings, since many groups never set roles."] = "역할이 지정되지 않은 파티원에게 무조건 왕의 축복을 띄우는 대신 공격 전담 축복 우선순위 목록을 따르도록 개선했습니다."
L["The GCD bar now hides as soon as a short global cooldown ends in instanced combat, and in every fight on WoW Forever, instead of lingering (Rogues, Feral Druids and hasted characters)."] = "도적, 야성 드루이드 등 글쿨이 짧은 캐릭터의 GCD 바가 지연 없이 글쿨 종료 즉시 숨겨집니다."
L["In instanced combat, and in every fight on WoW Forever, the GCD bar no longer shows up again after a hard cast finishes or after a spell that does not trigger the global cooldown, such as an interrupt."] = "시전 완료 후 또는 차단 등 글쿨을 유발하지 않는 기술 시전 후 GCD 바가 다시 나타나던 현상을 수정했습니다."
L["Channel tick marks on the cast bar are now correct for Penance, with or without Castigation, and on WoW Forever for every rank of Mind Flay and Penance."] = "시전 바의 정신 채널링 틱 표시가 회개 및 정신의 채찍의 모든 레벨에서 정확하게 표시됩니다."
L["Hash lines turned off and back on now reappear right away instead of after a reload."] = "기준선을 껐다 켤 때 UI를 다시 불러올 필요 없이 즉시 다시 나타납니다."
L["The mouse wheel over a short Threshold & Hash Lines list now scrolls the settings page instead of doing nothing."] = "짧은 임계값 및 기준선 목록 위에서 마우스 휠을 굴렸을 때 설정 페이지 전체가 정상적으로 스크롤됩니다."
L["Druid Power Bars that still carry per-form thresholds from the old Advanced mode now use the spec thresholds and hash lines you add, in any form without a per-form entry."] = "구 고급 모드의 변신별 임계값을 가지고 있던 드루이드 자원 바가 새로 추가한 전문화 임계값과 기준선을 정확히 반영합니다."
L["Elements linked above or below the Power Bar now move clear of the druid's Mana Bar while Shapeshifted instead of being covered by it."] = "자원 바 상하단에 연결된 요소들이 드루이드의 변신 중 마나 바에 가려지지 않고 깔끔하게 비켜납니다."
L["Putting buffs and debuffs on the same spot now moves the other row out of the way instead of turning it off or drawing both on top of each other."] = "강화 효과와 약화 효과를 같은 위치에 배치할 때 서로 겹치거나 꺼지지 않고 다른 행이 자동으로 밀려나 정렬됩니다."
L["Buff and debuff rows you have turned off no longer slow down login."] = "비활성화한 강화 효과 및 약화 효과 줄이 게임 로그인 속도를 지연시키지 않도록 최적화했습니다."
L["Switching Class Resource between the Blizzard style and another style no longer makes Resource Bars' Blizzard Class Resource Art jump under the player frame when your cast bar shows or hides, or leaves the Blizzard bar overlapping your cast bar while you cast."] = "블리자드 스타일 직업 자원 전환 시 시전 바 작동에 따라 자원 아트 위치가 튀거나 겹치던 문제를 수정했습니다."
L["The Mini Frames and Boss Frames previews no longer leave an empty gap below them after switching units or changing a setting while the Main Frames preview hint is still showing."] = "메인 프레임 미리보기 힌트가 표시되는 동안 보조 및 우두머리 프레임 미리보기 아래에 빈 공간이 남던 문제를 수정했습니다."
L["Bottom-anchored player buffs and debuffs now sit below the Resource Bars docked under the player frame instead of overlapping them; if you had moved them down by hand, reset their Y offset."] = "플레이어 프레임 하단에 도킹된 자원 바 아래로 강화 효과/약화 효과가 겹치지 않고 알맞게 정렬됩니다 (수동으로 내렸던 경우 세로 위치를 초기화하세요)."
L["Player Aura Bars icons with a custom Icon Shape no longer zoom far into the spell; the shape now shows the whole icon at your Icon Zoom, as on the action bars."] = "플레이어 오라 바에 사용자 지정 아이콘 모양을 사용할 때 아이콘이 과도하게 확대되지 않고 단축바처럼 전체 아이콘을 정확히 표시합니다."
L["Combo points on the unit frames, the target nameplate and Resource Bars now update when your points move to a new target."] = "대상을 변경할 때 유닛 프레임, 대상 이름표 및 자원 바의 연계 점수가 즉시 갱신됩니다."
L["An edit made while Unlock Mode is still opening, such as a width match, now asks to be saved when you exit instead of being kept without a prompt."] = "잠금 해제 모드가 열리는 동안 변경한 내용(너비 맞춤 등)도 종료 시 저장 여부를 정상적으로 확인합니다."
L["Exiting after combat interrupted it no longer asks to save changes you never made."] = "전투로 인해 잠금 해제 모드가 중단된 후 종료할 때 변경하지 않은 내용에 대해 저장 확인창이 뜨지 않습니다."
L["Reopening an element's cog menu after closing it mid-edit no longer leaves your keyboard typing into a hidden box."] = "설정 편집 중 톱니바퀴 메뉴를 닫았다가 다시 열었을 때 키보드 입력이 숨겨진 입력창에 고정되던 문제를 수정했습니다."
L["Exit Without Saving now fully restores pet fallback anchors, so the element keeps moving when your pet is summoned or dismissed."] = "'저장하지 않고 종료' 시 소환수 대체 고정 위치를 완벽하게 복원합니다."
L["Brazilian Portuguese, French, German, Korean, Simplified Chinese and Traditional Chinese translations updated for the latest options, and the Raid Frames Free Move labels now show in your language."] = "최신 옵션에 맞춰 한국어를 포함한 다국어 번역이 업데이트되었으며, 공격대 프레임의 자유 이동 라벨이 한국어로 표시됩니다."

