L["This option requires Rotate Bar Text or Rotate Divider Labels."] = "이 옵션은 '바 텍스트 회전' 또는 '구분선 라벨 회전'이 켜져 있어야 합니다."
L["This option requires Rotate Bar Text."] = "이 옵션은 '바 텍스트 회전'이 켜져 있어야 합니다."
