L["Top Right Text"] = "우측 상단 텍스트"
L["Vertical Text"] = "세로 텍스트"
L["What this text shows."] = "이 텍스트가 표시할 내용입니다."
L["Which ends of the bar show the gryphons or wyverns."] = "단축바의 어느 쪽 끝에 그리핀 또는 와이번을 표시할지 선택합니다."
L["Which ends of the bar show the gryphons."] = "단축바의 어느 쪽 끝에 그리핀을 표시할지 선택합니다."
L["XP per Hour"] = "시간당 경험치"
L["(the source is always included)"] = "(원본은 항상 포함됨)"
L["Apply Height to all "] = "모든 바에 높이 적용 "
L["Apply Width to all "] = "모든 바에 너비 적용 "
L["Background Padding"] = "배경 여백"
L["CDM Font"] = "CDM 글꼴"
L["CDM Outline"] = "CDM 외곽선"
L["CDM: "] = "CDM: "
L["Cooldown Manager Bars"] = "재사용 대기시간 관리자 바"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "EllesmereUI가 이 변경 사항을 편집 모드 배치에 저장할 수 없어 수동으로 설정해야 합니다. 설정하는 동안 재사용 대기시간 관리자를 꺼야 합니다. 블리자드의 재사용 대기시간 뷰어를 숨기며, 숨겨진 뷰어는 편집 모드에서 선택할 수 없기 때문입니다.\n\n1. EllesmereUI 재사용 대기시간 관리자 비활성화 (아래 단추).\n2. 게임 메뉴에서 편집 모드 열기.\n3. 각 재사용 대기시간 관리자 뷰어를 선택하고 가시성을 '항상'으로 설정.\n4. 추적 중인 강화 효과 및 추적 바에서 '비활성 시 숨기기' 체크.\n5. 배치를 저장하고 편집 모드 종료.\n6. EllesmereUI 재사용 대기시간 관리자 다시 활성화."
L["Text Outline"] = "텍스트 외곽선"
L["This option requires the Blackout glow type"] = "이 옵션은 암전(Blackout) 반짝임 유형이 필요합니다"
L["WoW Forever has no other specs to copy this bar to"] = "WoW Forever에는 이 바를 복사할 다른 전문화가 없습니다"
L["+ Add Combo"] = "+ 연계 추가"
L["+ Add Debuff"] = "+ 약화 효과 추가"
L["Already in use. Use the arrows to reorder."] = "이미 사용 중입니다. 화살표를 사용하여 순서를 재정렬하세요."
L["Class Colored Health Bar"] = "직업 색상 생명력 바"
L["Combos win over single debuffs; higher in the list wins."] = "단일 약화 효과보다 연계가 우선하며, 목록에서 더 위에 있는 항목이 우선합니다."
L["Custom Border on Aura Icons"] = "오라 아이콘에 사용자 지정 테두리"
L["Custom Border on Spell Icon"] = "주문 아이콘에 사용자 지정 테두리"
L["Elite and rare marks. Always in the same slot as the Quest Indicator."] = "정예 및 희귀 표시입니다. 항상 퀘스트 표시기와 동일한 슬롯에 위치합니다."
L["Enter the debuff's spell ID."] = "약화 효과의 주문 ID를 입력하세요."
L["Every text is already shown."] = "모든 텍스트가 이미 표시되어 있습니다."
L["Higher in the list wins when several are up."] = "여러 항목이 활성화된 경우 목록에서 더 위에 있는 항목이 우선합니다."
L["Marks mobs for your active quests. Always in the same slot as the Elite/Rare Indicator."] = "진행 중인 퀘스트 몬스터를 표시합니다. 항상 정예/희귀 표시기와 동일한 슬롯에 위치합니다."
L["Only Debuffs with Crowd Control, or the Elite/Rare and Quest Indicators with Faction, can share a slot."] = "군중 제어 효과가 있는 약화 효과, 또는 진영 표시가 있는 정예/희귀 및 퀘스트 표시기만 슬롯을 공유할 수 있습니다."
L["Quest Indicator"] = "퀘스트 표시기"
L["Icon Borders"] = "아이콘 테두리"
L["Show Level Box"] = "레벨 상자 표시"
L["Show Seam Line"] = "접합선 표시"
L["Size of the quest objective text. The same setting as the cog next to Replace Quest Icon with Objective."] = "퀘스트 목표 텍스트의 크기입니다. '퀘스트 아이콘을 목표로 대체' 옆의 톱니바퀴 설정과 동일합니다."
L["Target Border Effects"] = "대상 테두리 효과"
