L["Recolor the bar while a spell is castable (usable and off cooldown). The first castable spell in the list wins, so order = priority. Overrides threshold coloring while active; an active tracked buff from Buff Colors takes priority.\nFor an ability that turns into another spell while active, enter the original spell's ID: its current form is checked."] = "주문을 시전할 수 있을 때(사용 가능하고 재사용 대기시간이 아닐 때) 바의 색상을 변경합니다. 목록의 첫 번째 시전 가능 주문이 우선 적용되므로 순서가 우선순위가 됩니다. 활성화 시 한계점 색상보다 우선하며, 강화 효과 색상에서 추적 중인 활성 강화 효과가 가장 높은 우선순위를 갖습니다.\n활성화 중 다른 주문으로 변환되는 기술의 경우 원래 주문의 ID를 입력하세요. 현재 형상이 확인됩니다."
