L["Smallest on-screen size a reskinned bar is drawn at.\n\nWidget bars on a nameplate inherit that nameplate's scale, so they come out tiny on small units. Below this size the bar is scaled up instead, text and all.\n\nSet to 0 to mirror Blizzard's size exactly."] = "스킨이 적용된 바가 화면에 그려지는 최소 크기입니다.\n\n이름표의 위젯 바는 해당 이름표의 크기 비율을 상속받으므로 작은 유닛에서는 매우 작게 표시됩니다. 이 크기보다 작아지면 텍스트를 포함한 전체 바를 확대하여 그립니다.\n\n블리자드의 원래 크기와 정확히 일치시키려면 0으로 설정하세요."
