L["The Social window frame, border, title bar, Battle.net bar, search boxes, filter dropdowns and buttons, and the friend tiles with class icons, class-colored names and region icons. The side tab icons stay untouched."] = "소셜 창 프레임, 테두리, 제목 표시줄, 배틀넷 바, 검색창, 필터 드롭다운 및 버튼, 그리고 직업 아이콘, 직업 색상 이름, 지역 아이콘이 포함된 친구 타일에 스킨을 적용합니다. 측면 탭 아이콘은 변경되지 않습니다."
