L["This option requires Move Timer Inside Bar to be disabled"] = "이 옵션은 '타이머를 바 내부로 이동'이 비활성화되어 있어야 합니다."
L["This option requires Show Objective Times or a Split Compare mode"] = "이 옵션은 '목표 시간 표시' 또는 '구간 비교' 모드가 필요합니다."
L["This option requires Show Timer Bar or Apply to Forces Bar to be enabled"] = "이 옵션은 '타이머 바 표시' 또는 '적 병력 바에 적용'이 켜져 있어야 합니다."
L["This option requires Show Timer Bar or Show Enemy Forces to be enabled"] = "이 옵션은 '타이머 바 표시' 또는 '적 병력 표시'가 켜져 있어야 합니다."
L["The Friends List window skin draws this border (Blizzard Skins+ > Window Skins)."] = "친구 목록 창 스킨이 이 테두리를 그립니다 (블리자드 스킨+ > 창 스킨)."
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "아무것도 사용하지 않고 열려 있는 메뉴를 닫습니다. ESC 키도 항상 동일하게 작동합니다. 모든 메뉴가 하나의 키를 공유하며, 메뉴가 열려 있을 때만 선점됩니다 (그 외 시간에는 마우스 버튼이 원래 기능대로 작동)."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span. A nest reaches over the plain entries it passes, and they only give up their angles while it is open."] = "하위 중첩 메뉴가 호(원호)를 따라 항목을 펼치는 범위입니다. '제한'은 양쪽의 다음 하위 메뉴와 겹치지 않게 거리를 유지하여 둘이 서로 겹쳐 그려지지 않도록 합니다. '초과 허용'은 최대 하위 메뉴 범위 전체를 사용합니다. 하위 메뉴는 지나치는 일반 항목 위로 펼쳐지며, 일반 항목은 하위 메뉴가 열려 있는 동안에만 자신의 각도 공간을 양보합니다."
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "하위 메뉴 항목이 펼쳐질 수 있는 최대 각도입니다. 한 링 안에 들어가는 동안에는 동일한 링에 유지되며, 초과하는 항목은 더 바깥쪽의 두 번째 링으로 배치됩니다."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "'메뉴 열기 토글'로 메뉴가 열려 있는 동안 마우스 커서가 가리키고 있는 항목을 사용합니다. 모든 메뉴가 하나의 키를 공유하며, 메뉴가 열려 있을 때만 선점됩니다 (그 외 시간에는 마우스 버튼이 원래 기능대로 작동)."
