L["EUI was installed before it kept a record of your original settings, so the settings it still manages go back to the game's defaults."] = "EUI가 기존 게임 설정을 기록하기 전에 설치되었으므로, EUI가 관리하던 설정들이 게임의 기본 설정값으로 되돌아갑니다."
L["Every profile on this account is deleted. Export any profile you want to keep first."] = "이 계정의 모든 프로필이 삭제됩니다. 보관하려는 프로필이 있다면 먼저 내보내기를 진행하세요."
