L["Puts back the game settings EUI changed, such as nameplate, action bar, chat and tooltip options, and turns EUI off for every character, then reloads the UI."] = "이름표, 행동 단축바, 대화창 및 툴팁 옵션 등 EUI가 변경한 게임 내 설정을 복원하고, 모든 캐릭터에서 EUI를 비활성화한 후 UI를 다시 로드합니다."
