L["To keep its settings safe, EllesmereUI now gives other addons their own section in the panel instead of letting them change its pages. The addons below haven't caught up yet, so those changes are hidden until they're updated. Everything else works as usual."] = "설정을 안전하게 보호하기 위해, EllesmereUI는 이제 다른 애드온이 기존 페이지를 수정하도록 허용하는 대신 패널 내에 전용 섹션을 제공합니다. 아래 애드온들은 아직 이 변경 사항을 지원하지 않으므로 업데이트될 때까지 해당 변경 내용이 숨겨집니다. 그 외의 모든 기능은 정상 작동합니다."
L["Uninstall & Reload"] = "제거 및 다시 불러오기"
