L["\nPick a gem from the list to socket it."] = "\n목록에서 장착할 보석을 선택하세요."
L["\n|cff66ccffDrag to reorder.\nRight-click to change action.\nMiddle-click to remove.\nDrop an action here to replace it.|r"] = "\n|cff66ccff드래그하여 순서 변경.\n우클릭하여 동작 변경.\n가운데 클릭으로 제거.\n여기에 동작을 끌어다 놓아 교체.|r"
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile."] = "\"%1$s\" 프로필이 저장되었으나, 현재 전문화에 지정된 프로필이 있어 불러올 수 없습니다."
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile. Switch specs or remove the spec assignment to use it."] = "\"%1$s\" 프로필이 저장되었으나, 현재 전문화에 지정된 프로필이 있어 불러올 수 없습니다. 사용하려면 전문화를 변경하거나 전문화 프로필 지정을 해제하세요."
L["%1$s is bound to \"%2$s\". Binding it to \"%3$s\" will leave that unbound."] = "%1$s 키가 이미 \"%2$s\"에 지정되어 있습니다. \"%3$s\"에 지정하면 기존 지정이 해제됩니다."
L["A preset named \"%1$s\" already exists."] = "\"%1$s\" 프리셋이 이미 존재합니다."
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "\"%1$s\" 프로필이 이미 존재합니다. 다른 이름을 사용하세요."
L["Add \"%1$s\" to every spec? It will be copied to each of your specs that doesn't already have it."] = "모든 전문화에 \"%1$s\" 바를 추가하시겠습니까? 해당 바가 없는 모든 전문화에 복사됩니다."
L["Add an action\n|cff66ccffLeft-click to pick an action from a list.\nYou can also drop an action from the cursor here.|r"] = "동작 추가\n|cff66ccff좌클릭하여 목록에서 동작 선택.\n커서로 동작을 끌어다 놓을 수도 있습니다.|r"
L["Are you sure you want to delete \"%1$s\"?"] = "정말로 \"%1$s\" 항목을 삭제하시겠습니까?"
L["CDM buttons can have their glow and active states\nset per icon or synced to the bar. Click a button\nto show its settings."] = "CDM 버튼은 아이콘별로 반짝임 및 활성 상태를 설정하거나\n바 전체와 동기화할 수 있습니다. 버튼을 클릭하면\n설정이 표시됩니다."
L["Categories can be dragged\nto reorder them."] = "카테고리를 드래그하여\n순서를 변경할 수 있습니다."
L["Click this eye icon to preview live\nhealth bar effects like absorbs and healing."] = "이 눈 아이콘을 클릭하면 보호막 및 치유 효과 등\n생명력 바 실시간 효과를 미리 볼 수 있습니다."
L["Colors are shared globally from the \"%1$s\" profile.\nSwitch to it (or set Pull Colors From to this profile) to edit."] = "색상은 \"%1$s\" 프로필에서 전역으로 공유됩니다.\n편집하려면 해당 프로필로 전환하거나 '색상 가져오기 대상'을 이 프로필로 설정하세요."
L["Coordinates\nDisabled"] = "좌표\n비활성화됨"
L["Coordinates\nEnabled"] = "좌표\n활성화됨"
L["Cursor Light\nDisabled"] = "커서 강조 조명\n비활성화됨"
L["Cursor Light\nEnabled"] = "커서 강조 조명\n활성화됨"
L["Dark Overlays\nDisabled"] = "다크 오버레이\n비활성화됨"
L["Dark Overlays\nEnabled"] = "다크 오버레이\n활성화됨"
L["Delete \"%1$s\" for ALL specs? Bars keep their current positions."] = "모든 전문화에서 \"%1$s\" 바를 삭제하시겠습니까? 각 바는 현재 위치를 유지합니다."
L["Delete \"%1$s\"?"] = "\"%1$s\" 프로필을 삭제하시겠습니까?"
L["Detailed information is\nsecret while in combat"] = "전투 중에는 세부 정보를\n확인할 수 없습니다"
L["Elements cannot be anchored to\n%1$s"] = "요소를 %1$s에\n고정할 수 없습니다"
L["Elements cannot size match to\n%1$s"] = "요소의 크기를 %1$s에\n맞출 수 없습니다"
L["Enter a new name for \"%1$s\":"] = "\"%1$s\"의 새 이름을 입력하세요:"
L["Hover Top Bar\nDisabled"] = "상단 바 마우스오버\n비활성화됨"
L["Hover Top Bar\nEnabled"] = "상단 바 마우스오버\n활성화됨"
L["Left-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "좌클릭하여 단축키를 설정한 후 아무 키를 누르거나\n마우스 버튼을 클릭하여 지정하세요.\nEsc 키로 취소할 수 있으며, 우클릭 시 단축키가 해제됩니다."
L["Left-click to set a keybind.\nRight-click to unbind."] = "좌클릭하여 단축키를 설정합니다.\n우클릭 시 단축키가 해제됩니다."
L["Left-click to set keybind.\nRight-click to clear."] = "좌클릭하여 단축키 설정.\n우클릭하여 지우기."
L["Please disable the addon \"Clique\" to use this feature."] = "이 기능을 사용하려면 \"Clique\" 애드온을 비활성화하세요."
L["Remove \"%1$s\" from every other spec? The bar in this spec is kept."] = "다른 모든 전문화에서 \"%1$s\" 바를 제거하시겠습니까? 현재 전문화의 바는 유지됩니다."
L["Snap Elements\nDisabled"] = "요소 자동 맞춤(스냅)\n비활성화됨"
L["Snap Elements\nEnabled"] = "요소 자동 맞춤(스냅)\n활성화됨"
L["This Action Bar is also used as the Moonkin Form bar.\nChanging spells on a Druid for this bar will also change them on your Moonkin Form bar."] = "이 행동 단축바는 달빛야수 변신 바로도 사용됩니다.\n드루이드에서 이 바의 주문을 변경하면 달빛야수 변신 바의 주문도 함께 변경됩니다."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "블리자드 재사용 대기시간 관리자(CDM)에서 추적하는 주문 자체는 변경할 수 없습니다.\n여기서 선택한 전문화의 블리자드 CDM 배치도 함께 공유하는 것을 권장합니다."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "위치 잠금 해제 모드의 세부 설정을 제어할 수 있는 곳입니다.\n\n드래그나 방향키(+Shift)로 요소를 이동할 수 있습니다.\n모든 요소에 기준 고정, 높이 일치, 너비 일치를 적용할 수 있습니다.\n자동 맞춤(스냅)은 가장 가까운 요소를 기준으로 작동하지만,\n우클릭이나 설정 아이콘을 통해 특정 요소에만 맞출 수도 있습니다."
L["Type \"%s\" to enable:"] = "활성화하려면 \"%s\"을(를) 입력하세요:"
L["Unlock Mode is where you can adjust\npositioning for all the elements of EllesmereUI"] = "잠금 해제 모드에서는 EllesmereUI의\n모든 요소 배치를 조절할 수 있습니다"
L["|cffff6060[EllesmereUI]|r A profile named \"%1$s\" already exists."] = "|cffff6060[EllesmereUI]|r \"%1$s\" 이름을 가진 프로필이 이미 존재합니다."
L["|cffff6060[EllesmereUI]|r Cannot rename to \"Default\"."] = "|cffff6060[EllesmereUI]|r \"Default\"(기본)로는 이름을 변경할 수 없습니다."
L["Raid Frames"]       = "공격대/파티 프레임"
L["Copy Raid & Party Filters"] = "공격대/파티 필터 복사"
L["Allows free camera movement while holding and dragging right mouse button over raid and party frames. Right-click tap still opens the unit menu."] = "공격대/파티 프레임 위에서 마우스 오른쪽 버튼을 누른 채 드래그하는 동안 카메라를 자유롭게 움직일 수 있도록 허용합니다. 마우스 오른쪽 버튼을 짧게 클릭하면 기존처럼 개체 메뉴가 열립니다."
L["Party (in a group, not a raid)"] = "파티 (파티 중, 공격대 아님)"
L["Blizzard's XP and reputation bars return after a UI reload."] = "UI를 다시 불러오면 블리자드 경험치 및 평판 바가 돌아옵니다."
L["Nameplate Icon"] = "이름표 아이콘"
L["Dismiss this warning"] = "이 경고 닫기"

